	["/eui camp [status | panel | announce | ask | share | finds]"] = "/eui camp [status | panel | announce | ask | share | finds]",
	["/eui chat mute <channel>; <name>, unmute <channel>; <name>, filters, mutes, colors, alerts, alert <word>"] = "/eui chat mute <channel>; <name>, unmute <channel>; <name>, filters, mutes, colors, alerts, alert <word>",
	["/eui clickcast changes or removes these clicks."] = "/eui clickcast ændrer eller fjerner disse klik.",
	["/eui farm [start | pause | stop | reset | history]"] = "/eui farm [start | pause | stop | reset | history]",
	["/eui gather [list | clear | clear all | export [all] | import | send <party | guild | name> [all] | show]"] = "/eui gather [list | clear | clear all | export [all] | import | send <party | guild | name> [all] | show]", -- l10n: keep
	["/eui routes opens every dungeon with its packs, bosses and a suggested route; plan and share your own. Press M inside to see the floor."] = "/eui routes åbner alle dungeons med deres packs, bosser og en foreslået rute; planlæg og del dine egne. Tryk M inde i dungeonet for at se etagen.",
	["0 fits the icons to the font and frame."] = "0 tilpasser ikonerne til skrifttypen og rammen.",
	["0 fits the icons to the frame height."] = "0 tilpasser ikonerne til rammens højde.",
	["0 fits the marker to the font and frame."] = "0 tilpasser markøren til skrifttypen og rammen.",
	["03:04 PM"] = "03:04 PM",
	["1 hour"] = "1 time",
	["1 hour 5 minutes"] = "1 time 5 minutter",
	["1 hr"] = "1 t.",
	["1 hr 5 mins"] = "1 t. 5 min.",
	["1 min"] = "1 min.",
	["1 minute"] = "1 minut",
	["1 px borders"] = "1 px kanter",
	["1 px borders around the window and each bar."] = "1 px kanter rundt om vinduet og hver bjælke.",
	["1 sec"] = "1 sek.",
	["1 second"] = "1 sekund",
	["1 to 3 or the bar: pick a tower. Click: build or train. Right-click: sell. Space: next wave. P: pause."] = "1 til 3 eller bjælken: vælg et tårn. Klik: byg eller træn. Højreklik: sælg. Mellemrum: næste bølge. P: pause.",
	["1 to 9 pick the numbered choice or reward while the panel shows. Off: those keys stay on your action bars."] = "1 til 9 vælger det nummererede valg eller den nummererede belønning mens panelet vises. Fra: tasterne bruges stadig til dine handlingslinjer.",
	["1 whisper"] = "1 hviskebesked",
	["10 questions"] = "10 spørgsmål",
	["10 x 10"] = "10 x 10",
	["100% is normal running speed."] = "100% er normal løbehastighed.",
	["110 % (melee)"] = "110 % (nærkamp)",
	["12 hour"] = "12-timers",
	["130 % (ranged)"] = "130 % (afstand)",
	["16 cards"] = "16 kort",
	["16 x 16, 40 mines"] = "16 x 16, 40 miner",
	["1h 5m"] = "1t 5m",
	["200 px list with title, level and background."] = "Liste på 200 px med titel, level og baggrund.",
	["2004 nostalgia: the game's own sounds and a gold fantasy font, no banner."] = "2004-nostalgi: spillets egne lyde og en gylden fantasy-skrifttype, intet banner.",
	["220 px bars with the icon left and the time right."] = "Bjælker på 220 px med ikonet til venstre og tiden til højre.",
	["24 cards"] = "24 kort",
	["24 h"] = "24 t",
	["24 hour"] = "24-timers",
	["24-hour or 12-hour time is set once for every EldoUI clock, on the General page (Clock and durability)."] = "24- eller 12-timersformat indstilles én gang for alle EldoUI-ure på siden Generelt (Ur og holdbarhed).",
	["25 questions"] = "25 spørgsmål",
	["277 px power bar with pips on top, the current value and the spell cost while casting."] = "Ressourcebjælke på 277 px med pips øverst, den nuværende værdi og evnens pris mens du caster.",
	["28 px icons without the glow, faded until the mouse is on the bar."] = "28 px ikoner uden glød, tonet ud indtil musen er på bjælken.",
	["29 mana every 5 sec"] = "29 mana hvert 5. sek.",
	["3 px between bars and the largest text, easy to read at a glance."] = "3 px mellem bjælkerne og den største tekst, let at læse med et hurtigt blik.",
	["3 x 3"] = "3 x 3",
	["30 px icons in a row, glow while a buff is missing."] = "30 px ikoner på en række, glød mens en buff mangler.",
	["30 px icons stacked top to bottom."] = "30 px ikoner stablet oppefra og ned.",
	["30 x 16, 99 mines"] = "30 x 16, 99 miner",
	["32 px buffs in rows of 12 with time under them, 40 px debuffs below."] = "Buffs på 32 px i rækker på 12 og tiden under dem, debuffs på 40 px nedenunder.",
	["36 cards"] = "36 kort",
	["36 px buttons with 2 px gaps on the three main rows, and smaller text."] = "Knapper på 36 px med 2 px afstand på de tre hovedrækker, og mindre tekst.",
	["36 px icons with a swipe and the time on them; missing auras show faded."] = "Ikoner på 36 px med swipe og tiden på dem; manglende auraer vises nedtonet.",
	["4 px between bars, larger text."] = "4 px mellem bjælkerne, større tekst.",
	["4 runes"] = "4 runer",
	["4 x 4"] = "4 x 4",
	["4.5 under 10 s"] = "4.5 under 10 s",
	["440 x 200 with 13 pt text and the edit box below."] = "440 x 200 med 13 pt tekst og tekstfeltet nedenunder.",
	["480 x 380 for busy guilds, with saved history."] = "480 x 380 til travle guilds, med gemt historik.",
	["5 x 5"] = "5 x 5",
	["5% of a level as rested XP"] = "5% af et level som udhvilet XP",
	["52 px buttons on the three main rows and bigger text, for big screens."] = "Knapper på 52 px på de tre hovedrækker og større tekst, til store skærme.",
	["557 x 282, accent underline on the active tab, edit box over the tabs."] = "557 x 282, accentunderstregning på den aktive fane, tekstfeltet over fanerne.",
	["557 x 300 with 16 pt outlined text."] = "557 x 300 med 16 pt tekst med kontur.",
	["6 runes"] = "6 runer",
	["6 x 6"] = "6 x 6",
	["64 px icon that pops in, holds for a moment and fades."] = "Ikon på 64 px der popper frem, bliver stående et øjeblik og tones ud.",
	["7 x 7"] = "7 x 7",
	["700 x 260 for long lines."] = "700 x 260 til lange linjer.",
	["8 x 8"] = "8 x 8",
	["9 x 9"] = "9 x 9",
	["9 x 9, 10 mines"] = "9 x 9, 10 miner",
	[":) :D ;) :( :P <3 and other text smileys show as emoji when they stand alone, so addresses and times like 12:30 stay as they are. What you send is not changed."] = ":) :D ;) :( :P <3 og andre tekstsmileys vises som emojis når de står alene, så adresser og klokkeslæt som 12:30 forbliver som de er. Det du sender, ændres ikke.",
	["<%s> is already muted."] = "<%s> er allerede dæmpet.",
	["<%s> is muted."] = "<%s> er dæmpet.",
	["<%s> is no longer muted."] = "<%s> er ikke længere dæmpet.",
	["<%s> is not muted."] = "<%s> er ikke dæmpet.",
	["<id>  play a sound from the media library (eldo:Tada, kit:READY_CHECK, lsm:Air Horn)"] = "<id>  afspil en lyd fra mediebiblioteket (eldo:Tada, kit:READY_CHECK, lsm:Air Horn)",
	["<spell> | off  print each charge that comes back for one of your spells"] = "<spell> | off  skriv hver ladning der kommer tilbage for en af dine evner",
	["<text>  search the items of all your characters"] = "<text>  søg i alle dine karakterers genstande",
	["<text>  search the selected chat window"] = "<text>  søg i det valgte chatvindue",
	["[2. Trade - City] becomes [2] or [Trade], [Guild] becomes [G]."] = "[2. Trade - City] bliver til [2] eller [Trade], [Guild] bliver til [G].",
	["[challenges | probe | export | import | config | on | off]  the Legacy Planner: plan Legacy points (never spends them), browse challenges, or print what the client answers"] = "[challenges | probe | export | import | config | on | off]  Legacy-planlæggeren: planlæg Legacy-point (bruger dem aldrig), gennemse udfordringer eller skriv hvad klienten svarer",
	["[clear]  battleground widgets and map points (the last 20 kept until /reload writes them)"] = "[clear]  battleground-widgets og kortpunkter (de sidste 20 bevares indtil /reload skriver dem)",
	["[conflicts | layouts | forget]  Edit Mode and EldoUI: conflicts, saved layouts, forget saved layouts"] = "[conflicts | layouts | forget]  Edit Mode og EldoUI: konflikter, gemte layouts, glem gemte layouts",
	["[dungeon | import]  the dungeon map with packs and routes; a name opens that dungeon"] = "[dungeon | import]  dungeonkortet med packs og ruter; et navn åbner det pågældende dungeon",
	["[Friend]: gg :) that was fun :tada: see you at 12:30 <3"] = "[Ven]: gg :) det var sjovt :tada: ses kl. 12:30 <3",
	["[G] %s"] = "[G] %s",
	["[list | clear [all] | export [all] | import | send <who> [all] | show]  the herb, ore, treasure and fishing nodes you have gathered"] = "[list | clear [all] | export [all] | import | send <who> [all] | show]  dine indsamlede nodes: urter, malm, skatte og fiskestimer", -- l10n: keep
	["[log | add | count | stats | pvp | options | on | off]  run log and hourly instance count"] = "[log | add | count | stats | pvp | options | on | off]  runlog og instanstælling pr. time",
	["[mode | log | reset]  fishing mode and the catch log"] = "[mode | log | reset]  fisketilstand og fangstloggen",
	["[mute <guild> | unmute <guild> | hidden]  muted guilds in chat (no word opens the list)"] = "[mute <guild> | unmute <guild> | hidden]  dæmpede guilds i chatten (uden ord åbnes listen)",
	["[on | off | focus | target]  EldoUI threat meter"] = "[on | off | focus | target]  EldoUI-aggromåler",
	["[on | off | search <text> | agenda | log | size]  the Alts window with all your characters"] = "[on | off | search <text> | agenda | log | size]  Alts-vinduet med alle dine karakterer",
	["[on|off]  EldoUI crosshair at the screen center"] = "[on|off]  EldoUI-sigtekors midt på skærmen",
	["[on|off]  EldoUI cursor ring"] = "[on|off]  EldoUI-markørring",
	["[party | raid10 | raid20 | raid25 | raid40]  show or hide test party and raid frames"] = "[party | raid10 | raid20 | raid25 | raid40]  vis eller skjul testrammer for gruppe og raid",
	["[settings | import | capture]  Cooldown Manager: EldoUI options, Blizzard's settings, import or capture this spec's set"] = "[settings | import | capture]  Cooldown Manager: EldoUI-indstillinger, Blizzards indstillinger, importer eller indfang denne specs sæt",
	["[setup | undo | apply | test]  Deadly Boss Mods: EldoUI profile, switch back, re-apply, test timers"] = "[setup | undo | apply | test]  Deadly Boss Mods: EldoUI-profil, skift tilbage, anvend igen, test nedtællinger",
	["[show | hide | guides]  the Eldostar guide window, or the guide list in the Journal"] = "[show | hide | guides]  Eldostars guidevindue eller guidelisten i journalen", -- l10n: keep
	["[show | tab | hide] [2]  show the Info Bar, fold it to a small tab or hide it (2: the second bar)"] = "[show | tab | hide] [2]  vis Infobjælken, fold den sammen til en lille fane eller skjul den (2: den anden bjælke)",
	["[sound|font|statusbar] [filter]  list the media library"] = "[sound|font|statusbar] [filter]  vis mediebiblioteket",
	["[start | pause | stop | reset | history]  the farming session bar and its history"] = "[start | pause | stop | reset | history]  bjælken for farmingsessioner og dens historik",
	["[status | panel | announce | ask | share | finds]  campfire buffs, the camp panel, a one-line camp announce and the camp finder"] = "[status | panel | announce | ask | share | finds]  lejrbålsbuffs, lejrpanelet, en lejrannoncering på én linje og lejrsøgeren",
	["[test [theme] [seconds] [fail] | dump]  cast bar effects: open the page, play a test cast on every enabled cast bar, or list your spellbook with spell IDs"] = "[test [theme] [seconds] [fail] | dump]  castbar-effekter: åbn siden, afspil et testcast på alle castbars der er slået til, eller vis din evnebog med evne-ID'er",
	["[test dungeon | raid | pull | stop]  the Encounter Timeline page, or a test fight"] = "[test dungeon | raid | pull | stop]  siden Encounter-tidslinje eller en testkamp",
	["[test|move]  Combat Text settings, sample lines in every area, or move the scroll areas"] = "[test|move]  indstillinger for Kamptekst, prøvelinjer i alle områder eller flyt rulleområderne",
	["[toggle | reset]  Blizzard's damage meter: show/hide it, or clear its fights"] = "[toggle | reset]  Blizzards skademåler: vis/skjul den, eller ryd dens kampe",
	["A !EUR1! string of this route to copy and paste to others."] = "En !EUR1!-streng af ruten som du kan kopiere og dele med andre.",
	["A \"Reset\" button for the leader is on the Raid Tools bar (Group > Raid Tools > Reset instances, off by default)."] = "En \"Nulstil\"-knap til lederen findes på Raidværktøjer-bjælken (Gruppe > Raidværktøjer > Nulstil instanser, slået fra som standard).",
	["A bar counting down to the gates opening."] = "En bjælke der tæller ned til portene åbner.",
	["A bar for each base, tower or graveyard being taken, in the attacker's color. Uses the game's own time when the map reports one."] = "En bjælke for hver base, hvert tårn eller hver kirkegård der indtages, i angriberens farve. Bruger spillets egen tid når kortet oplyser en.",
	["A bar for main-hand swings."] = "En bjælke for slag med main hand.",
	["A bar for off-hand swings."] = "En bjælke for slag med off hand.",
	["A bar for ranged and wand shots."] = "En bjælke for ranged- og wand-skud.",
	["A bar per queue with the game's estimated wait. It shows \"-\" once the estimate has passed."] = "En bjælke pr. kø med spillets anslåede ventetid. Den viser \"-\" når estimatet er overskredet.",
	["a basilisk"] = "en basilisk",
	["A bigger counter and typing line."] = "En større tæller og skrivelinje.",
	["A bigger game window for a high resolution or a far screen."] = "Et større spilvindue til en høj opløsning eller en skærm langt væk.",
	["A bright line along the edge of the swipe."] = "En lys linje langs kanten af swipen.",
	["A bronze frame and bronze names, to match the WoW Forever art style."] = "En bronzeramme og bronzenavne, så de passer til grafikstilen WoW Forever.",
	["A buff of yours that changes a spell glows on that spell's buttons while you have it, such as Maelstrom Weapon on Lightning Bolt. Its look is on the Glows page (Spell cues: buff)."] = "Når en af dine buffs ændrer en evne, gløder evnens knapper mens du har buffen, fx Maelstrom Weapon på Lightning Bolt. Udseendet findes på siden Glød (Spell cues: buff).",
	["A built-in section: the game's item types fill it. Your own categories come first, then the built-in sections; drop an item on its title to keep it here."] = "Et indbygget afsnit: spillets genstandstyper fylder det. Dine egne kategorier kommer først, derefter de indbyggede afsnit; slip en genstand på dets titel for at beholde den her.",
	["A burst of guild join, leave, online and offline lines shows as one line per kind, such as \"5 more came online: Name, Name ...\". Point at [all] for every name. Off by default."] = "En byge af guildlinjer om medlemmer der melder sig ind, melder sig ud, logger på eller logger af, vises som én linje pr. type, fx \"5 flere kom online: Name, Name ...\". Peg på [alle] for at se alle navne. Slået fra som standard.",
	["A button for a mount: the best mount item in your bags, or a mount from your collection (right-click picks which)."] = "En knap til en mount: den bedste mountgenstand i dine tasker eller en mount fra din samling (højreklik vælger hvilken).",
	["A button for bandages."] = "En knap til bandager.",
	["A button for drinks."] = "En knap til drikke.",
	["A button for food."] = "En knap til mad.",
	["A button for healing potions."] = "En knap til healing potions.",
	["A button for healthstones."] = "En knap til Healthstones.",
	["A button for mana potions."] = "En knap til mana potions.",
	["A button for your conjured mana gem, with its cooldown. It stays on the bar while you carry none, so you see when to conjure one."] = "En knap til din fremmanede mana gem med dens cooldown. Den bliver på linjen selv når du ikke har nogen, så du kan se hvornår du skal fremmane en.",
	["A button for your Hearthstone, with its cooldown."] = "En knap til din Hearthstone med dens cooldown.",
	["A button glows while the effect it put on you or your target lasts, such as a damage or heal over time, a shield or a seal. Its look is on the Glows page (Spell cues: your effect)."] = "En knap gløder mens den effekt den har lagt på dig eller dit mål varer, fx skade eller heal over tid, et skjold eller et seal. Udseendet findes på siden Glød (Spell cues: din effekt).",
	["A calm screen with your character, zone, away time and whispers while you are marked Away."] = "En rolig skærm med din karakter, zone, tid væk og hviskebeskeder mens du er markeret som AFK.",
	["A camera distance per situation; the first that applies wins, in the order below. Otherwise the camera goes back to your own distance."] = "En kameraafstand pr. situation; den første der gælder, vinder, i rækkefølgen nedenfor. Ellers går kameraet tilbage til din egen afstand.",
	["A capture must be taken."] = "Et slag skal tages.",
	["A card in the alert lane when someone dies. The game decides which deaths it announces (its own Hardcore death alert setting: guild or all)."] = "Et kort i advarselsbanen når nogen dør. Spillet bestemmer hvilke dødsfald det annoncerer (dets egen indstilling for Hardcore-dødsadvarsler: guild eller alle).",
	["A character name the menu lists first as Banker when that player can take the item."] = "Et karakternavn som menuen viser først som Bankier når den spiller kan få genstanden.",
	["A character name the menu lists first as Disenchanter when that player can take the item."] = "Et karakternavn som menuen viser først som Disenchanter når den spiller kan få genstanden.",
	["A chat line when Edit Mode opens and a frame is placed by both EldoUI and Edit Mode."] = "En chatlinje når Edit Mode åbnes og en ramme placeres af både EldoUI og Edit Mode.",
	["A check lists each slot with a lower rank in chat (only you see it): where it is, its rank and the highest rank you know."] = "Et tjek viser hver plads med en lavere rang i chatten (kun du ser det): hvor den er, dens rang og den højeste rang du kender.",
	["A Check ranks button on the spellbook page: left-click lists and lights up the lower ranks, right-click shows the changes to apply."] = "En Tjek evnerang-knap på evnebogssiden: venstreklik viser evnerne i lavere rang og lyser dem op, højreklik viser de ændringer du kan anvende.",
	["A class icon before each name."] = "Et klasseikon foran hvert navn.",
	["A class or role icon on the frame's top right corner. Round in the Blizzard and Classic skins, square in Modern (Layout and style > Appearance)."] = "Et klasse- eller rolleikon i rammens øverste højre hjørne. Rundt i Blizzard- og Classic-skinnet, firkantet i Modern (Layout og stil > Udseende).",
	["A class spell's icon and four names: which one is it?"] = "Ikonet for en klassebesværgelse og fire navne: hvilken er det?",
	["A clock swipe over the big icon as the time runs out."] = "En urlignende swipe over det store ikon mens tiden løber ud.",
	["A color for the whole bar from a stack count up. Later ranges win."] = "En farve til hele bjælken fra et bestemt antal stakke og op. Senere intervaller har forrang.",
	["A color of its own once the bar is full."] = "En egen farve når bjælken er fuld.",
	["A color per chat type (say, guild, party ...) and per joined channel. Channels keep their color when their number changes."] = "En farve pr. chattype (sig, guild, gruppe ...) og pr. kanal du er med i. Kanaler beholder deres farve når deres nummer ændres.",
	["A color per pip"] = "En farve pr. pip",
	["A colored border on buttons that hold an item you are wearing (trinkets, for example)."] = "En farvet kant på knapper med en genstand du har på (for eksempel trinkets).",
	["A column at the side of the screen."] = "En kolonne i siden af skærmen.",
	["A Copy button on the chat's side rail: the selected window as plain text."] = "En Kopier-knap på chattens sidebjælke: det valgte vindue som ren tekst.",
	["a crocolisk"] = "en krokodille",
	["A cross"] = "Et kors",
	["A crown"] = "En krone",
	["A daily limit to count against as well. Forever has none."] = "Også en daglig grænse at tælle op mod. Forever har ingen.",
	["A dark box behind each bar."] = "En mørk boks bag hver bjælke.",
	["A dialog view for quest and gossip NPCs: big readable text, numbered choices, Space to go on and Esc to leave."] = "En dialogvisning for quest- og samtale-NPC'er: stor læsevenlig tekst, nummererede valg, Space for at gå videre og Esc for at afslutte.",
	["a dragon"] = "en drage",
	["A draw."] = "Uafgjort.",
	["A farming session bar: time, looted gold, item value and XP, each per hour, with sessions saved per zone."] = "En bjælke for farmingsessioner: tid, lootet guld, genstandsværdi og XP, hver pr. time, med sessioner gemt pr. zone.",
	["A few seconds after login, prints a chat line for each character with mail that is returned or deleted soon, on every realm."] = "Et par sekunder efter login skrives en chatlinje for hver karakter med post der snart sendes retur eller slettes, på alle realms.",
	["A few seconds after login, prints a chat line for each character with running auctions who has not visited the auction house for a while."] = "Et par sekunder efter login skrives en chatlinje for hver karakter med aktive auktioner som ikke har besøgt auktionshuset i et stykke tid.",
	["A Find button on the chat's side rail that searches the selected window."] = "En Søg-knap på chattens sidebjælke der søger i det valgte vindue.",
	["A fish"] = "En fisk",
	["A fixed amount"] = "Et fast beløb",
	["A flash when the game lights up a spell, and your buffs on the spells they change. Nothing is guessed or cast for you."] = "Et blink når spillet lyser en evne op, og dine buffs på de evner de ændrer. Intet gættes eller castes for dig.",
	["A flat EldoUI border behind every icon."] = "En flad EldoUI-kant bag hvert ikon.",
	["A friend comes online"] = "En ven logger på",
	["A full panel in your art style, bronze under WoW Forever."] = "Et fuldt panel i din grafikstil, bronze under WoW Forever.",
	["A full scan is possible again in %d min."] = "En fuld scanning er mulig igen om %d min.",
	["A gem"] = "En ædelsten",
	["A glow around the pulse icon. Its look is on the Glows page (Cooldown pulse)."] = "En glød omkring pulsikonet. Udseendet findes på siden Glød (Cooldown-puls).",
	["A glow on the big icon from the danger time. Its look is on the Glows page (Encounter Timeline)."] = "En glød på det store ikon fra faretiden. Dens udseende findes på siden Glød (Encounter-tidslinje).",
	["A glow round the bar during the cast, in the theme color. Its style is set on the Glows page."] = "En glød om bjælken under castet i temaets farve. Dens stil indstilles på siden Glød.",
	["A glow while a member has an aura the game marks as a boss aura. Style and color on the Glows page."] = "En glød mens et medlem har en aura som spillet markerer som en bossaura. Stil og farve findes på siden Glød.",
	["a gnoll"] = "en gnoll",
	["A goblet"] = "Et bæger",
	["A green arrow on items that beat what you wear (Upgrades module)."] = "En grøn pil på genstande der er bedre end det du har på (modulet Opgraderinger).",
	["A group member levels up"] = "Et gruppemedlem stiger i level",
	["a harpy"] = "en harpy",
	["A heart"] = "Et hjerte",
	["A house"] = "Et hus",
	["a hydra"] = "en hydra",
	["A key"] = "En nøgle",
	["a kobold"] = "en kobold",
	["A large 96 px icon with a longer hold, hard to miss."] = "Et stort ikon på 96 px der bliver stående længere, svært at overse.",
	["A large search line with the screen dimmed behind it."] = "En stor søgelinje med skærmen nedtonet bagved.",
	["A line at the moment the hourly count drops below the limit again."] = "En linje i det øjeblik tællingen pr. time igen kommer under grænsen.",
	["A line that shows while a value is low. The game works out when; EldoUI only draws the line. No sound. Off by default."] = "En linje der vises mens en værdi er lav. Spillet afgør hvornår; EldoUI tegner kun linjen. Ingen lyd. Slået fra som standard.",
	["A line that shows while your health is below the percent on the Warnings tab. The game works out when; EldoUI only draws it. No sound."] = "En linje der vises mens dit liv er under procentsatsen på fanen Advarsler. Spillet afgør hvornår; EldoUI tegner den bare. Ingen lyd.",
	["A line that shows while your mana is below the percent on the Warnings tab. No sound."] = "En linje der vises mens din mana er under procentsatsen på fanen Advarsler. Ingen lyd.",
	["A line that shows while your pet's health is below the percent on the Warnings tab. No sound."] = "En linje der vises mens dit pets liv er under procentsatsen på fanen Advarsler. Ingen lyd.",
	["A line when an entry turns out to be the same run as the one before."] = "En linje når et besøg viser sig at være samme run som det før.",
	["A line when you enter a battleground or arena, which never counts toward the limit."] = "En linje når du går ind i et battleground eller en arena; de tæller aldrig med i grænsen.",
	["A line where you would take aggro: 110 % of the tank's threat in melee, 130 % at range (Blizzard's rule)."] = "En linje der hvor du ville tage aggro: 110 % af tankens aggro i nærkamp, 130 % på afstand (Blizzards regel).",
	["A line with the hourly count when you enter a dungeon, with links to the log and to remove the entry."] = "En linje med tællingen pr. time når du går ind i et dungeon, med links til loggen og til at fjerne posten.",
	["A lock on an item"] = "En lås på en genstand",
	["A look sets how the bars look, never where they sit. Pick one per talent group to switch with your talents; save your own into slot A or B."] = "Et udseende bestemmer hvordan bjælkerne ser ud, aldrig hvor de sidder. Vælg ét pr. talentgruppe for at skifte med dine talenter; gem dit eget på plads A eller B.",
	["A macro conditional that replaces when these frames show, for example \"[group:raid] show; hide\". End it with show or hide. Empty = EldoUI's own rule."] = "En makrobetingelse der erstatter hvornår disse rammer vises, for eksempel \"[group:raid] show; hide\". Afslut med show eller hide. Tomt = EldoUI's egen regel.", -- l10n: keep
	["A mark on item buttons and a tooltip line that say whether you have an item's appearance, and set progress in the Loot Guide."] = "Et mærke på genstandsknapper og en tooltiplinje som fortæller om du har en genstands udseende, og fremskridt for sæt i Loot Guide.",
	["A marker for every pack of mobs, from the Classic spawn data."] = "En markør for hver pack af mobs fra Classic-spawndataene.",
	["A message closed with Escape, or open during a loading screen, comes back with Ctrl+Shift+Z for this long. Secure commands (/cast and the like) are never kept."] = "En besked der lukkes med Escape eller er åben under en indlæsningsskærm, kommer tilbage med Ctrl+Shift+Z i så lang tid. Sikre kommandoer (/cast og lignende) gemmes aldrig.",
	["A mill: take one of the Horde's pieces."] = "En mølle: tag en af Hordens brikker.",
	["A month of lockout resets, cooldowns, calendar events, mail and auctions for your characters."] = "En måned med lockout-resets, cooldowns, kalenderbegivenheder, post og auktioner for dine karakterer.",
	["A moon"] = "En måne",
	["A mover for BigWigs' messages. BigWigs can't follow it live: send the anchors again after you move it."] = "Et flyttefelt til BigWigs' beskeder. BigWigs kan ikke følge det live: send ankerpunkterne igen når du har flyttet det.",
	["A mover for BigWigs' pull and encounter countdown, right above your character in every layout. Like the messages, BigWigs gets its spot when you send the anchors."] = "Et flyttefelt til BigWigs' pull- og encounter-nedtælling, lige over din karakter i alle layouts. Ligesom beskederne får BigWigs sin plads når du sender ankerpunkterne.",
	["a murloc"] = "en murloc",
	["A mushroom"] = "En svamp",
	["A name for the search. The same name again replaces it."] = "Et navn til søgningen. Samme navn igen erstatter den.",
	["A name for this group, shown in the Group list above."] = "Et navn til gruppen, vist i gruppelisten ovenfor.",
	["A name for this panel, shown in the list above."] = "Et navn til dette panel, vist i listen ovenfor.",
	["A narrow box with small rows and no second line."] = "En smal boks med små rækker og ingen anden linje.",
	["A narrow panel with small text, all of it at once."] = "Et smalt panel med lille tekst, det hele på én gang.",
	["A new horizontal panel with three slots (clock, gold, durability) at the top of the screen. Change it below."] = "Et nyt vandret panel med tre pladser (ur, guld, holdbarhed) øverst på skærmen. Tilpas det nedenfor.",
	["A new panel in Dashboard display: durability, bag space, your tracked currencies, the reputation you watch and your professions, each as a row with a bar. Change its rows below."] = "Et nyt panel i visningen Dashboard: holdbarhed, taskeplads, dine sporede valutaer, det omdømme du følger, og dine fag, hver som en række med en bjælke. Tilpas rækkerne nedenfor.",
	["A new vertical panel with eight character stats picked for your class. In combat the game hides some stats; they show a dash until the fight ends."] = "Et nyt lodret panel med otte karakterstats valgt til din klasse. I kamp skjuler spillet nogle stats; de viser en streg indtil kampen slutter.",
	["A note before your camp buffs run out, and one when they end while you are still near a fire."] = "En besked før dine lejrbuffs udløber, og en når de slutter mens du stadig er tæt på et bål.",
	["A note when the session's gold plus item value reaches this much."] = "En besked når sessionens guld plus genstandsværdi når dette beløb.",
	["A notice with a Show button when someone in your group sends you a route."] = "En besked med knappen Vis når nogen i din gruppe sender dig en rute.",
	["A panel behind the text in your art style."] = "Et panel bag teksten i din grafikstil.",
	["A percentage"] = "En procentdel",
	["A phrase matches only as a whole word: \"gold\" hides \"buy gold\" but not \"goldfish\"."] = "En frase matcher kun som et helt ord: \"gold\" skjuler \"buy gold\", men ikke \"goldfish\".",
	["A picture behind the chat text: a background from EldoUI's media list (SharedMedia packs add more), or your own file."] = "Et billede bag chatteksten: en baggrund fra EldoUI's medieliste (SharedMedia-pakker tilføjer flere) eller din egen fil.",
	["A picture on the left of each party frame. A member out of view or offline shows the 2D portrait instead of the model."] = "Et billede til venstre på hver grupperamme. Et medlem der er ude af syne eller offline, viser 2D-portrættet i stedet for modellen.",
	["A Planner button on Blizzard's Legacy window that opens this planner beside it."] = "En Planlægger-knap på Blizzards Legacy-vindue der åbner denne planlægger ved siden af.",
	["A potion"] = "En eliksir",
	["A profession skill rises"] = "Dit skill i et fag stiger",
	["A quest link's tooltip says which of your characters have the quest, are ready to turn it in or completed it."] = "Tooltippen for et questlink viser hvilke af dine karakterer der har questen, er klar til at aflevere den eller har fuldført den.",
	["A quest or recipe of yours needs this item, so EldoUI's junk selling and Move these leave it alone."] = "En af dine quests eller opskrifter skal bruge denne genstand, så EldoUI's salg af skrald og Flyt disse lader den være.",
	["A rare catch!"] = "En sjælden fangst!",
	["A ready-made set of the text settings below. Changing one of them turns this to Custom. Bars with their own text settings (Bars tab) keep those."] = "Et færdigt sæt af tekstindstillingerne nedenfor. Hvis du ændrer en af dem, skifter dette til Brugerdefineret. Linjer med egne tekstindstillinger (fanen Bjælker) beholder dem.",
	["A recipe, or the item it makes. Empty shows every shared recipe."] = "En opskrift eller den genstand den laver. Tom viser alle delte opskrifter.",
	["A red \"Binds when picked up\" line on items that bind when you win them."] = "En rød linje \"Bindes ved opsamling\" på genstande der bindes når du vinder dem.",
	["A reputation standing rises"] = "Du når et nyt omdømmetrin",
	["A ring that follows the mouse cursor."] = "En ring der følger musemarkøren.",
	["A route from your group"] = "En rute fra din gruppe",
	["A route keeps at most %d arrows."] = "En rute kan højst have %d pile.",
	["A route keeps at most %d lines."] = "En rute kan højst have %d linjer.",
	["A route keeps at most %d notes."] = "En rute kan højst have %d noter.",
	["A row of filters above the Overview: faction, level, fully rested, mail and lockouts."] = "En række filtre over fanen Oversigt: fraktion, level, fuldt udhvilet, post og lockouts.",
	["A row of your bags (or bank tabs) under the search box: click one to hide or show its slots, drag bags in and out, right-click for the game's bag options."] = "En række med dine tasker (eller bankfaner) under søgefeltet: klik på en for at skjule eller vise dens pladser, træk tasker ind og ud, og højreklik for spillets taskeindstillinger.",
	["A sample cast with the theme: it fills, gets pushed back once, then finishes or is interrupted, in turn."] = "Et prøvecast med temaet: det fyldes, skubbes tilbage én gang og bliver så skiftevis færdigt eller afbrudt.",
	["A sample essential row in its icon size, spacing, zoom, borders and keybinds."] = "Et eksempel på den essentielle række med ikonstørrelse, afstand, zoom, kanter og genvejstaster.",
	["A sample line with your emoji settings, and whether the emoji folder is ready."] = "En eksempellinje med dine emojiindstillinger og om emojimappen er klar.",
	["A sample of the timeline in your current look, the boss mod the timers come from and what reached the timeline this session."] = "Et eksempel på tidslinjen i dit nuværende udseende, den bossmod nedtællingerne kommer fra, og hvad der har nået tidslinjen i denne session.",
	["A sample party in your party frames' size, growth and colors."] = "En eksempelgruppe i dine grupperammers størrelse, vækstretning og farver.",
	["A second bar with its own datatexts. It sits in the top edge of the chat window, or on its own mover."] = "En ekstra bjælke med egne datatekster. Den sidder i chatvinduets øverste kant eller på sit eget flyttefelt.",
	["A second color from a higher stack count up."] = "En anden farve fra et højere antal stakke og op.",
	["A second column with each tank's target."] = "En ekstra kolonne med hver tanks mål.",
	["A second gain of the same item, money or faction while its row is still shown adds to that row instead of opening a new one."] = "Får du den samme genstand, flere penge eller mere omdømme hos samme fraktion mens rækken stadig vises, lægges det til rækken i stedet for at åbne en ny.",
	["A second line under the name with where the item is worn and what kind it is."] = "En linje mere under navnet med hvor genstanden bæres, og hvad slags den er.",
	["A second panel on the right for chosen kinds of messages, such as loot, so the main chat stays readable."] = "Et ekstra panel til højre for udvalgte beskedtyper, fx loot, så hovedchatten forbliver læsbar.",
	["A see-through page in the heading font, text at reading pace, no model."] = "En gennemsigtig side i overskriftsskrifttypen, tekst i læsetempo, ingen model.",
	["A see-through panel behind the counters."] = "Et gennemsigtigt panel bag tællerne.",
	["A see-through panel behind the list."] = "Et gennemsigtigt panel bag listen.",
	["A session counts looted gold, items and their worth, and XP, also per hour. Stop saves it in the session history. Also: /eui farm."] = "En session tæller lootet guld, genstande og deres værdi samt XP, også pr. time. Stop gemmer den i sessionshistorikken. Også: /eui farm.",
	["A shield"] = "Et skjold",
	["A shine sweeping over the filled part of the bar."] = "En glans der fejer hen over den fyldte del af bjælken.",
	["A short bar after a flag capture until the flags return (Warsong Gulch)."] = "En kort bjælke efter en flagerobring indtil flagene vender tilbage (Warsong Gulch).",
	["A short card or row for each item, money, reputation, currency and skill-up you gain."] = "Et kort eller en række for hver genstand, pengesum, omdømmeændring, valuta og skillup du får.",
	["A short line when combat ends."] = "En kort linje når kampen slutter.",
	["A short line when combat starts."] = "En kort linje når kampen starter.",
	["A short note naming a camp buff when you gain it."] = "En kort besked der nævner en lejrbuff når du får den.",
	["A short note under or after the result (the settings page, a macro's kind, a stack size)."] = "En kort note under eller efter resultatet (indstillingssiden, makroens type, en stakstørrelse).",
	["A short notice at the mailbox, the auction house and the trade window while the game reports Self-Found for this character."] = "En kort besked ved postkassen, auktionshuset og byttevinduet mens spillet melder Self-Found for denne karakter.",
	["A short orange pulse when a cast is pushed back or a channel changes."] = "En kort orange puls når et cast skubbes tilbage eller en channel ændrer sig.",
	["A short streak of light behind the spark."] = "En kort lysstribe bag gnisten.",
	["A short text on or next to the icon: plain words or text tags, such as [cd:name], [cd:key] or [power:percent]. Empty shows nothing."] = "En kort tekst på eller ved siden af ikonet: almindelige ord eller teksttags som [cd:name], [cd:key] eller [power:percent]. Tom viser intet.",
	["A short word at the bottom: New, Look or Have."] = "Et kort ord nederst: Nyt, Udseende eller Har.",
	["A side"] = "En side",
	["A slot is free again: %d/%d this hour (estimate)."] = "En plads er ledig igen: %d/%d denne time (skøn).",
	["A small 44 px icon without name that fades quickly."] = "Et lille ikon på 44 px uden navn som hurtigt tones ud.",
	["A small arrow at the bar's right end: click folds the bar to a tab, right-click hides it."] = "En lille pil i bjælkens højre ende: klik folder bjælken sammen til en fane, højreklik skjuler den.",
	["A small arrow in the corner of a chat window while it is scrolled up; it turns accent when new lines arrive. Shift + mouse wheel jumps to the top or bottom."] = "En lille pil i hjørnet af et chatvindue mens det er rullet op; den skifter til accentfarve når nye linjer kommer. Shift + musehjul hopper til toppen eller bunden.",
	["A small bar with your food, drink, potions, bandage, healthstone, Hearthstone and mount, with counts and cooldowns. One click uses one."] = "En lille linje med din mad, drikke, potions, bandage, Healthstone, Hearthstone og mount, med antal og cooldowns. Ét klik bruger én.",
	["A small box behind the time."] = "En lille boks bag tiden.",
	["A small button in the title that posts the items' links to chat when you click it, highest quality first. It shows when there is something to link and a chat to post to."] = "En lille knap i titlen der skriver genstandenes links i chatten når du klikker på den, højeste kvalitet først. Den vises når der er noget at linke og en chat at skrive i.",
	["A small button in the title that takes every item when you click it."] = "En lille knap i titlen der tager alle genstande når du klikker på den.",
	["A small card with the next pulls of your route inside a dungeon. Check pulls off with Done; the next pull is lit on the map. Move it with /eui move."] = "Et lille kort med de næste pulls på din rute inde i et dungeon. Sæt flueben ved pulls med Færdig; det næste pull lyser op på kortet. Flyt det med /eui move.",
	["A small check, question mark or cross in the top right corner."] = "Et lille flueben, spørgsmålstegn eller kryds i øverste højre hjørne.",
	["A small class or race icon (the game's own art) in front of player names. The gear sets their size, offset and where they show."] = "Et lille klasse- eller raceikon (spillets egen grafik) foran spillernavne. Tandhjulet indstiller deres størrelse, forskydning og hvor de vises.",
	["A small colored square in the top right corner."] = "En lille farvet firkant i øverste højre hjørne.",
	["A small eye in the top-left corner fades the slots and stats so only the model shows. Click again, or close the window, to bring them back."] = "Et lille øje i øverste venstre hjørne toner pladserne og stats ud, så kun modellen vises. Klik igen, eller luk vinduet, for at få dem tilbage.",
	["A small Games box shows while you fly a flight path. Click it to open the games; right-click puts it away for this flight."] = "En lille Spil-boks vises mens du flyver en flyverute. Klik på den for at åbne spillene; højreklik lægger den væk på denne flyvning.",
	["A small list of hostile players seen on nameplates, with class color, level and how long ago."] = "En lille liste over fjendtlige spillere fra nameplates med klassefarve, level og hvor længe siden du så dem.",
	["A small lock on items an open quest needs, items that start a quest you haven't done, and recipes one of your characters can still learn. On by default."] = "En lille lås på genstande som en åben quest har brug for, genstande der starter en quest du ikke har klaret, og opskrifter som en af dine karakterer stadig kan lære. Slået til som standard.",
	["A small mark after a quest link: a tick when you have done the quest, the quest icon when it is in your quest log. Nothing when neither or unknown."] = "Et lille mærke efter et questlink: et flueben når du har klaret questen, questikonet når den er i din questlog. Intet når ingen af delene gælder eller det er ukendt.",
	["A small numbered tag on every pull of the route."] = "Et lille nummereret mærke på hvert pull i ruten.",
	["A small panel with your camp buffs and their timers. Move it in move mode (Camp Panel)."] = "Et lille panel med dine lejrbuffs og deres nedtællinger. Flyt det i flyttetilstand (Lejrpanel).",
	["A small red mark on enchantable slots whose item carries no enchant, and a line in the tooltip. Read from the item link."] = "Et lille rødt mærke på pladser der kan enchantes og har en genstand uden enchant, og en linje i tooltippen. Læses fra genstandslinket.",
	["A small timer with the length of your current fight."] = "Et lille ur med længden af din nuværende kamp.",
	["A small window with one bar per group member on your target's threat table."] = "Et lille vindue med én bjælke pr. gruppemedlem på dit måls aggrotabel.",
	["A smaller game window and a box without the time left."] = "Et mindre spilvindue og en boks uden tiden der er tilbage.",
	["A smile"] = "Et smil",
	["A soft dark shadow around the icon."] = "En blød, mørk skygge omkring ikonet.",
	["A soft glow on a buff or poison icon while it is missing (out of combat; the game hides auras from addons in combat)."] = "En blød glød på et buff- eller giftikon mens det mangler (uden for kamp; spillet skjuler auraer for addons i kamp).",
	["A soft shadow under the chat text, so it reads on bright ground."] = "En blød skygge under chatteksten, så den kan læses på lys baggrund.",
	["A sound when a new card or row appears; several at once play it once. Fanfare's loot sounds are separate."] = "En lyd når et nyt kort eller en ny række vises; flere på én gang spiller den kun én gang. Fanfares lyde for loot er for sig.",
	["A sound when someone else writes in guild, party, raid or another channel. None by default."] = "En lyd når en anden skriver i guild, gruppe, raid eller en anden kanal. Ingen som standard.",
	["A sound with the goal note. None for silence."] = "En lyd sammen med målbeskeden. Vælg Ingen for at slå lyden fra.",
	["A sound with the slot-free line."] = "En lyd sammen med linjen om ledig plads.",
	["A sound with the warning. None for silence."] = "En lyd med advarslen. Vælg Ingen for at slå lyden fra.",
	["A spark crosses the mana bar during the 5 seconds after you cast a spell that costs mana (spirit regeneration is paused meanwhile)."] = "En gnist krydser manabjælken i de 5 sekunder efter at du har castet en evne der koster mana (regenerering fra Spirit er sat på pause imens).",
	["A spell name or ID (shift-click a spell link works too). Cooldown bars also take an item as item:ID."] = "Et evnenavn eller ID (Shift-klik på et evnelink virker også). Cooldownbjælker tager også en genstand som item:ID.",
	["A spell you cast lately, or one you pinned. Cast the spell once to see it here, or type its ID below."] = "En evne du har castet for nylig, eller en du har fastgjort. Cast evnen én gang for at se den her, eller skriv dens ID nedenfor.",
	["A spell you learn goes to its key on bars 1 to 3; a talent spell relearned after a talent reset returns to its old button. Offer asks first; Automatically places it out of combat. Empty buttons only."] = "En evne du lærer, kommer på sin tast på linje 1 til 3; en talentevne du lærer igen efter at have nulstillet dine talenter, kommer tilbage på sin gamle knap. Tilbyd spørger først; Automatisk sætter den på uden for kamp. Kun tomme knapper.",
	["A standing bar that fills upwards; width is its length and height its thickness."] = "En stående bjælke der fyldes opad; bredden er dens længde og højden dens tykkelse.",
	["A step whose goals are all done moves on to the next one. Off: Next moves on."] = "Et trin hvor alle mål er klaret, går videre til det næste. Fra: Næste går videre.",
	["A sticky line when your combo points are full."] = "En fast linje når dine combopoints er fulde.",
	["A string of the draft (or the selected profile) to share."] = "En streng af kladden (eller den valgte profil) til deling.",
	["A string with every node on every map."] = "En streng med alle nodes på alle kort.",
	["A string with the nodes of the map you are on, to copy and give to a friend."] = "En streng med nodes fra det kort du er på. Kopier den, og giv den til en ven.",
	["A summon is pending, accepted or declined."] = "En summon venter, er accepteret eller afvist.",
	["A sword"] = "Et sværd",
	["A tab that flashes (a whisper in another tab) brings the strip back, so you never miss it."] = "En fane der blinker (et hvisk i en anden fane), henter fanelinjen frem igen, så du aldrig går glip af det.",
	["A tab that gets a whisper while you look at another tab flashes (the game's alert, in the EldoUI look). Off: it stays still. Skin switch."] = "En fane der får et hvisk mens du ser på en anden fane, blinker (spillets advarsel i EldoUI-udseende). Fra: den forbliver stille. Skin-kontakt.",
	["A thin bar that runs down during the global cooldown after each spell, from the game's own cooldown."] = "En tynd bjælke der løber ned under den globale cooldown efter hver evne, ud fra spillets egen cooldown.",
	["A thin cross at the center of the screen."] = "Et tyndt kors midt på skærmen.",
	["A thin cross at the center of the screen. The range tint shows the game's own in-range answer for a spell as a color."] = "Et tyndt kors midt på skærmen. Rækkeviddefarven viser spillets eget svar på om en evne er inden for rækkevidde.",
	["A thin dark edge around each bar, so it shows on bright ground."] = "En tynd mørk kant om hver bjælke, så den kan ses på lys baggrund.",
	["A thin gap between the cells of a board."] = "Et tyndt mellemrum mellem felterne på et bræt.",
	["A thin mana bar while you are in bear or cat form; the power bar shows the form's rage or energy."] = "En tynd manabjælke mens du er i Bear Form eller Cat Form; ressourcebjælken viser formens rage eller energi.",
	["A thin mark at every tick step, so you can read the distance."] = "En tynd streg for hvert trin, så du kan aflæse afstanden.",
	["A third color from a higher stack count up."] = "En tredje farve fra et højere antal stakke og op.",
	["A tick each second for the soonest event and a final sound at zero. Off by default, because DBM and BigWigs can count down too."] = "Et tik hvert sekund for den nærmeste hændelse og en slutlyd ved nul. Slået fra som standard fordi DBM og BigWigs også kan tælle ned.",
	["A timeline bar that shows the timers DBM or BigWigs publish, plus the pull countdown, as icons moving toward now."] = "En tidslinjebjælke der viser nedtællingerne fra DBM eller BigWigs plus pull-nedtællingen som ikoner der bevæger sig mod nu.",
	["A tracking bar whose spell the game lights up (a proc or a reactive spell). Only the game's own spell alert starts it."] = "En sporingsbjælke hvis evne spillet lyser op (en proc eller en reaktiv evne). Kun spillets egen evneadvarsel starter den.",
	["A tree"] = "Et træ",
	["A warning when you become flagged for PvP yourself."] = "En advarsel når du selv bliver flagget til PvP.",
	["A warning when your target is flagged for PvP and attacking it (a player or a guard) or healing and buffing it (a player) would flag you too."] = "En advarsel når dit mål er flagget til PvP, og du også ville blive flagget ved at angribe det (en spiller eller en vagt) eller heale og buffe det (en spiller).",
	["a waypoint to this camp"] = "et waypoint til denne lejr",
	["A wide panel with the model and a darker screen behind it."] = "Et bredt panel med modellen og en mørkere skærm bagved.",
	["A wide, flat bar with short single-line rows."] = "En bred, flad bjælke med korte rækker på én linje.",
	["A wishlist item drops"] = "En genstand fra ønskelisten dropper",
	["A word shown on the bar while the spell is ready (for example Ready). Empty shows nothing."] = "Et ord der vises på bjælken mens evnen er klar (for eksempel Klar). Tom viser intet.",
	["A zone or a city and the map of its continent: click where it lies."] = "En zone eller en by og kortet over dens kontinent: klik der hvor den ligger.",
	["Abandon %s"] = "Opgiv %s",
	["Above or below the bar; pick below for a bar along the top edge."] = "Over eller under bjælken; vælg under til en bjælke langs den øverste kant.",
	["Above the bar"] = "Over bjælken",
	["Above the chat"] = "Over chatten",
	["Above the damage meter"] = "Over skademåleren",
	["Above the damage meter needs the damage meter's Move switch; otherwise the timer uses its own mover (EldoUI_CombatTimer)."] = "Over skademåleren kræver skademålerens Flyt-kontakt; ellers bruger uret sit eget flyttefelt (EldoUI_CombatTimer).",
	["Above the debuffs"] = "Over debuffene",
	["above the guide"] = "over guiden",
	["above the guide (RestedXP's default)"] = "over guiden (RestedXP's standard)",
	["Above the icon"] = "Over ikonet",
	["Absorb"] = "Absorb",
	["Accent"] = "Accentfarve",
	["Accent background"] = "Accentbaggrund",
	["Accent bar"] = "Accentbjælke",
	["Accent border on the member you have targeted."] = "Kant i accentfarven på det medlem du har som mål.",
	["Accent borders and headers with an accent gradient behind the model."] = "Kanter og overskrifter i accentfarve med en accentgradient bag modellen.",
	["Accent color in combat"] = "Accentfarve i kamp",
	["Accent shades"] = "Accentnuancer",
	["Accent text only"] = "Kun accenttekst",
	["Accent underline"] = "Accentunderstregning",
	["Accent-tinted column headers"] = "Kolonneoverskrifter i accentfarve",
	["Accept %s"] = "Tag %s",
	["Account"] = "Konto",
	["Account bank"] = "Kontobank",
	["Account bank page %d"] = "Kontobankens side %d",
	["Account macro"] = "Kontomakro",
	["Account: %s"] = "Konto: %s",
	["Achievement earned"] = "Achievement opnået",
	["Action Bar %d"] = "Handlingslinje %d",
	["Action bar bag buttons"] = "Taskeknapper på handlingslinjen",
	["Action Bars"] = "Handlingslinjer",
	["Action buttons that still hold a lower rank of a spell you know at a higher rank (Action Bars, Spell ranks)."] = "Handlingsknapper der stadig har en lavere rang af en evne som du kender i en højere rang (Handlingslinjer, Evnerang).",
	["Action: %s"] = "Handling: %s",
	["Actions"] = "Handlinger",
	["Active"] = "Aktiv",
	["Active DBM profile: %s"] = "Aktiv DBM-profil: %s",
	["Active Edit Mode layout: %s"] = "Aktivt Edit Mode-layout: %s",
	["Active Edit Mode layout: %s (positions per layout are off)"] = "Aktivt Edit Mode-layout: %s (placeringer pr. layout er slået fra)",
	["Active tab"] = "Aktiv fane",
	["Acts for you"] = "Handler på dine vegne",
	["Acts for you when turned on: when the game auto loots, takes every item at once instead of one by one. Works with either window. Off by default: turn it on here or in the installer."] = "Handler for dig når den er slået til: når spillet auto-looter, tages alle genstande på én gang i stedet for én ad gangen. Virker med begge vinduer. Slået fra som standard: slå den til her eller i opsætningsguiden.",
	["Acts for you when you click it; off by default. At the bank, mail, trade or a vendor, a button by the search box moves up to 12 searched items per click. Quest, recipe and never-sell items stay."] = "Handler på dine vegne når du klikker på den; slået fra som standard. Ved banken, posten, byttevinduet eller en købmand flytter en knap ved søgefeltet op til 12 søgte genstande pr. klik. Questgenstande, opskrifter og genstande du aldrig vil sælge, bliver liggende.",
	["Acts for you: declines duel requests from members of the guilds you muted, out of combat, and says who in chat. Change it later under Chat."] = "Handler på dine vegne: afviser duelanmodninger fra medlemmer af de guilds du har dæmpet, uden for kamp, og skriver i chatten hvem det var. Ændr det senere under Chat.",
	["Acts for you: declines group invites from members of the guilds you muted, out of combat, and says who in chat. Change it later under Chat."] = "Handler på dine vegne: afviser gruppeinvitationer fra medlemmer af de guilds du har dæmpet, uden for kamp, og skriver i chatten hvem det var. Ændr det senere under Chat.",
	["Add a dashboard"] = "Tilføj et dashboard",
	["Add a panel"] = "Tilføj et panel",
	["Add a rank"] = "Tilføj et rangtrin",
	["add a rank to the draft"] = "tilføj et rangtrin til kladden",
	["Add a stats panel"] = "Tilføj et statspanel",
	["Add an item"] = "Tilføj en genstand",
	["Add area"] = "Tilføj område",
	["Add bar"] = "Tilføj bjælke",
	["Add my main cooldown row"] = "Tilføj min hovedrække af cooldowns",
	["Add or remove columns. The styles on the Alts page set a good mix."] = "Tilføj eller fjern kolonner. Stilene på siden Alts giver en god blanding.",
	["Add or remove counters"] = "Tilføj eller fjern tællere",
	["Add spells from"] = "Tilføj evner fra",
	["Add spells or items in the Icons row above, or drag icons here in move mode."] = "Tilføj evner eller genstande i rækken Ikoner ovenfor, eller træk ikoner hertil i flyttetilstand.",
	["add to Favorites"] = "tilføj til Favoritter",
	["Add to list"] = "Føj til liste",
	["Add to the selected list"] = "Føj til den valgte liste",
	["Add up repeats"] = "Læg gentagelser sammen",
	["Added \"%s\" to %s."] = "\"%s\" er føjet til %s.",
	["Added \"%s\"."] = "\"%s\" er tilføjet.",
	["Added %d spells from your main cooldown row."] = { one = "%d evne fra din hovedrække af cooldowns er tilføjet.", other = "%d evner fra din hovedrække af cooldowns er tilføjet." },
	["Added in the draft"] = "Tilføjet i kladden",
	["Added."] = "Tilføjet.",
	["Addon Lua memory"] = "Lua-hukommelse for addons",
	["Addon memory"] = "Addonhukommelse",
	["Addon messages are paused here. Try again when the fight or match is over."] = "Addonbeskeder er sat på pause her. Prøv igen når kampen eller matchen er slut.",
	["Adds"] = "Adds",
	["Adds \"Announce the last reset\" to the Instances datatext menu, the reset line and the Raid Tools Reset button. Each click sends one line to group chat."] = "Tilføjer \"Meld det seneste reset\" til menuen i Instanser-datateksten, resetlinjen og Nulstil-knappen i Raidværktøjer. Hvert klik sender én linje til gruppechatten.",
	["Adds \"Appearance: collected / not collected\" to item tooltips, also at the auction house."] = "Tilføjer \"Udseende: i samlingen / ikke i samlingen\" til tooltips for genstande, også i auktionshuset.",
	["Adds \"Post to group\" and \"Post to guild\" to the log's right-click menu and lets /eui instances stats party send the newest run. Each post is one click."] = "Tilføjer \"Del i gruppen\" og \"Del i guilden\" til loggens højreklikmenu og lader /eui instances stats party sende det nyeste run. Hver deling er ét klik.",
	["Adds \"×3\" to joined lines. When the game keeps the numbers hidden, the newest number shows with the count."] = "Tilføjer \"×3\" til sammenlagte linjer. Når spillet holder tallene skjult, vises det nyeste tal med antallet.",
	["Adds a scroll area of your own (up to four), with its own mover. Send events to it on the Events tab."] = "Tilføjer et eget rulleområde (op til fire) med sit eget flyttefelt. Send hændelser til det på fanen Hændelser.",
	["Adds an \"EldoUI\" theme (EldoUI colors, accent and font) to RestedXP's theme list. Pick it in RestedXP's settings. Takes effect after a reload."] = "Tilføjer et \"EldoUI\"-tema (EldoUI-farver, accent og skrifttype) til RestedXP's temaliste. Vælg det i RestedXP's indstillinger. Træder i kraft efter en genindlæsning.",
	["Adds an empty group with its own mover (Cooldown Group N in move mode)."] = "Tilføjer en tom gruppe med sit eget flyttefelt (Cooldown-gruppe N i flyttetilstand).",
	["Adds every spell of your main cooldown row (Cooldown Manager > Own rows) to the list."] = "Tilføjer alle evner fra din hovedrække af cooldowns (Cooldown Manager > Egne rækker) til listen.",
	["Adds how many of the item you now carry."] = "Tilføjer hvor mange du nu har af genstanden.",
	["Adds Send my alts and Ask the guild buttons to the Guild tab, to swap your characters' names, classes and levels with guild members who use EldoUI. Nothing is sent without your click."] = "Tilføjer knapperne Send mine alts og Spørg guilden til fanen Guild, så du kan udveksle dine karakterers navne, klasser og levels med guildmedlemmer der bruger EldoUI. Intet sendes uden dit klik.",
	["Adds Send my recipes and Ask the guild buttons to the Crafters tab, to swap known recipes with guild members who use EldoUI. Nothing is sent without your click. Off by default."] = "Tilføjer knapperne Send mine opskrifter og Spørg guilden til fanen Craftere, så du kan udveksle kendte opskrifter med guildmedlemmer der bruger EldoUI. Intet sendes uden dit klik. Slået fra som standard.",
	["Adds Shopping List, Quick Sell and Cancel Undercut tabs to the auction house. Every post, purchase, cancel and search is one click of yours."] = "Tilføjer fanerne Indkøbsliste, Hurtigt salg og Annuller undercut i auktionshuset. Hver gang du lægger op, køber, annullerer eller søger, er det ét klik fra dig.",
	["Adds the count in the guild banks you have opened (cached per guild)."] = "Tilføjer antallet i de guildbanker du har åbnet (gemt pr. guild).",
	["Adds the search term to the selected shopping list."] = "Føjer søgeordet til den valgte indkøbsliste.",
	["Adds what all copies on your characters sell for to the tooltip's value line."] = "Tilføjer salgsværdien af alle eksemplarer på dine karakterer til tooltippens værdilinje.",
	["Adds your other characters' amounts to currency tooltips."] = "Tilføjer dine andre karakterers beholdning til valuta-tooltips.",
	["Adept"] = "Øvet",
	["Advanced: macro conditions and page numbers, for example \"[mod:shift] 2; [form:1] 7\". Checked before the modifier paging."] = "Avanceret: makrobetingelser og sidenumre, for eksempel \"[mod:shift] 2; [form:1] 7\". Tjekkes før sideskift med ændringstast.",
	["Advanced: macro conditions ending in show or hide, for example \"[mod:shift] show; hide\". When filled they replace the Show rule. The bar always hides in pet battles."] = "Avanceret: makrobetingelser der ender på show eller hide, for eksempel \"[mod:shift] show; hide\". Når de er udfyldt, erstatter de Vis-reglen. Linjen skjules altid i petkampe.", -- l10n: keep
	["Advanced: macro conditions ending in show or hide; when filled they replace the Show rule. The bar only ever shows when you have stances or forms."] = "Avanceret: makrobetingelser der ender på show eller hide; når de er udfyldt, erstatter de Vis-reglen. Linjen vises kun når du har stances eller forms.", -- l10n: keep
	["Advanced: macro conditions ending in show or hide; when filled they replace the Show rule. The bar only ever shows while you have a pet with a bar."] = "Avanceret: makrobetingelser der ender på show eller hide; når de er udfyldt, erstatter de Vis-reglen. Linjen vises kun mens du har et pet med en linje.", -- l10n: keep
	["Adventure"] = "Adventure",
	["AFK screen"] = "AFK-skærm",
	["AFK Screen"] = "AFK-skærm",
	["AFK text"] = "AFK-tekst",
	["After a set time"] = "Efter en fast tid",
	["After firing, the trigger waits this long before it can fire again."] = "Når udløseren er gået af, venter den så længe før den kan gå af igen.",
	["After which queen of the ancient night elves is Azshara named?"] = "Hvilken dronning blandt de gamle natelvere er Azshara opkaldt efter?",
	["After you applied the layout's corner: a layout on the other side of the screen moves Questie's grow corner along. A corner you pick in Questie yourself stays."] = "Når du har anvendt layoutets hjørne: et layout i den anden side af skærmen flytter Questies væksthjørne med. Et hjørne som du selv vælger i Questie, bliver.",
	["After you die, a card with a Tell the guild button. One click writes one line about your death in guild chat; nothing is sent without it."] = "Når du er død: et kort med knappen Fortæl guilden. Ét klik skriver én linje om din død i guildchatten; intet sendes uden det.",
	["After you give an item, posts the item and the player's name to your group. Off by default."] = "Når du har givet en genstand væk, skriver den genstanden og spillerens navn i din gruppe. Slået fra som standard.",
	["After you learn a new rank, the old one stays on your bars. EldoUI can offer to move those buttons to the new rank, or move them for you."] = "Når du lærer en ny rang, bliver den gamle på dine linjer. EldoUI kan tilbyde at flytte de knapper til den nye rang eller flytte dem for dig.",
	["After you learn a new spell rank, and once at login when lower ranks are on your bars, ask whether to show the changes. Nothing moves until you press Apply in that preview."] = "Når du lærer en ny evnerang, og én gang ved login når der er lavere rang på dine linjer, spørger EldoUI om du vil se ændringerne. Intet flyttes før du trykker Anvend i forhåndsvisningen.",
	["After you leave"] = "Når du går ud",
	["After you roll, the bar shows your choice and stays until the game's loot history names the winner, or everyone passed. Without a result it leaves when the roll's time is up."] = "Når du har rullet, viser bjælken dit valg og bliver, til spillets loothistorik viser vinderen, eller alle passede. Uden et resultat forsvinder den når rullets tid er gået.",
	["After you send a line in %s, the edit box stays there for the next line. Off: it goes back to the last sticky chat type."] = "Når du har sendt en linje i %s, bliver tekstfeltet der til næste linje. Fra: det går tilbage til den sidste faste chattype.",
	["Again!"] = "Igen!",
	["Against your build: %s"] = "I forhold til dit build: %s",
	["agenda"] = "agenda",
	["Agenda"] = "Agenda",
	["Agenda reminder details"] = "Detaljer for agendapåmindelser",
	["Agenda reminders"] = "Agendapåmindelser",
	["Agi"] = "Agi",
	["Agility"] = "Agility",
	["AH"] = "AH",
	["Aid"] = "Aid",
	["Aim with the mouse or Left and Right. Click, Space or Up: shoot. P: pause."] = "Sigt med musen eller Venstre og Højre. Klik, Mellemrum eller Op: skyd. P: pause.",
	["Air Hockey"] = "Airhockey",
	["Airy"] = "Airy",
	["Alarm when something hits you while you are marked AFK."] = "Alarm når noget rammer dig mens du er markeret som AFK.",
	["Alert for"] = "Advarsel for",
	["Alert keywords"] = "Nøgleord for advarsler",
	["Alert on my name"] = "Advarsel ved mit navn",
	["Alerts and Banners settings"] = "Indstillinger for Advarsler og bannere",
	["Alerts and filters"] = "Advarsler og filtre",
	["Alerts tab"] = "Alerts-fane",
	["Alerts tab off"] = "Alerts-fanen er slået fra",
	["Alerts tab ready"] = "Alerts-fanen er klar",
	["Alerts tab status"] = "Status for Alerts-fanen",
	["all"] = "alle",
	["all %d: "] = "alle %d: ",
	["All addons"] = "Alle addons",
	["All bags and the bank in EldoUI windows with categories and a bag bar, item counts across your characters, search with filters, offline viewing and a Blizzard skin mode."] = "Alle tasker og banken i EldoUI-vinduer med kategorier og taskelinje, antal genstande på tværs af dine karakterer, søgning med filtre, offlinevisning og en Blizzard-skintilstand.",
	["All buttons of the bar in one column."] = "Alle linjens knapper i én kolonne.",
	["All buttons of the bar in one row."] = "Alle linjens knapper i én række.",
	["All characters"] = "Alle karakterer",
	["All chat except your own lines"] = "Al chat undtagen dine egne linjer",
	["All game colors"] = "Alle spilfarver",
	["All games"] = "Alle spil",
	["All guides"] = "Alle guides",
	["All home"] = "Alle hjem",
	["All kinds, icons on the world map and minimap."] = "Alle typer, ikoner på verdenskortet og minikortet.",
	["All off"] = "Alle fra",
	["All on"] = "Alle til",
	["All particles"] = "Alle partikler",
	["All realms"] = "Alle realms",
	["All tabs"] = "Alle faner",
	["All trees"] = "Alle træer",
	["All triggers and settings of this module."] = "Alle udløsere og indstillinger i dette modul.",
	["All white"] = "Alt hvidt",
	["All zones"] = "Alle zoner",
	["Alliance %d, Horde %d"] = "Alliancen %d, Horden %d",
	["Alliance (you)"] = "Alliancen (dig)",
	["Allow posting stats"] = "Tillad at dele statistik",
	["Allow sending nodes"] = "Tillad afsendelse af nodes",
	["Along the way"] = "Undervejs",
	["Also darken the icon while the target is out of range."] = "Gør også ikonet mørkere mens målet er uden for rækkevidde.",
	["Also draws every pack, patrol and your route on that map. Off keeps the map readable; the Dungeons window always shows them for planning."] = "Tegner også hver pack, patrulje og din rute på kortet. Slået fra holder kortet læsbart; Dungeonvinduet viser dem altid til planlægning.",
	["Also for warriors and rogues"] = "Også for warriors og rogues",
	["Also forget its EldoUI settings"] = "Glem også dens EldoUI-indstillinger",
	["Also forget their EldoUI settings"] = "Glem også deres EldoUI-indstillinger",
	["Also in a party"] = "Også i en gruppe",
	["Also in instances"] = "Også i instanser",
	["Also light up and list macros that show or name a lower rank. A macro changes only when you click its Update button in the macro editor (/eui macros)."] = "Lys også makroer op der viser eller nævner en lavere rang, og vis dem på listen. En makro ændres kun når du klikker på dens Opdater-knap i makroeditoren (/eui macros).",
	["Also light up buttons of Bartender4, ElvUI and Dominos. Blizzard's own bars follow Blizzard UI > Action button look: Improve."] = "Lys også knapper op i Bartender4, ElvUI og Dominos. Blizzards egne linjer følger Blizzard-UI > Handlingsknappernes udseende: Forbedr.",
	["Also list the clicks that open the frame's menu."] = "Vis også de klik der åbner rammens menu.",
	["Also list the raid's main assists."] = "Vis også raidets main assists.",
	["Also outside dungeons"] = "Også uden for dungeons",
	["Also play the sound each time a charge of a spell with charges comes back, not only when the first one does."] = "Afspil også lyden hver gang en ladning af en evne med ladninger kommer tilbage, ikke kun når den første gør.",
	["Also show defensives others cast on the member."] = "Vis også defensive evner som andre caster på medlemmet.",
	["Also show mana, rage and energy gains, in the mana color."] = "Vis også gevinster af mana, rage og energi i manafarven.",
	["Also show the cues on buttons of other bar addons. Blizzard's own bars follow Blizzard UI > Action button look: Improve."] = "Vis også cues på knapper fra andre handlingslinje-addons. Blizzards egne linjer følger Blizzard-UI > Handlingsknappernes udseende: Forbedr.",
	["Also show your combo points under your target's nameplate."] = "Vis også dine combopoints under dit måls nameplate.",
	["Also show your gold as a counter."] = "Vis også dit guld som en tæller.",
	["Also shows plate numbers in a party or raid, where they include your group's hits."] = "Viser også tal på nameplates i en gruppe eller et raid. Der omfatter tallene også din gruppes hits.",
	["Also with loot toasts"] = "Også med pop op-beskeder om loot",
	["Alt list of %s"] = "Altliste for %s",
	["Alt lists guild members sent you, or that you imported."] = "Altlister som guildmedlemmer har sendt dig, eller som du har importeret.",
	["Alt shows"] = "Med Alt nede",
	["Alt+F"] = "Alt+F",
	["Alt+Space"] = "Alt+Space",
	["Alt, every action you know, disenchant up to rare."] = "Alt-tasten, alle handlinger du kender, disenchant op til Rare.",
	["Alt-click a name to invite"] = "Alt-klik på et navn for at invitere",
	["Alt-click a player's name in chat to send one group invite. Not in combat. Other clicks on names work as before. Off by default."] = "Alt-klik på en spillers navn i chatten for at sende én gruppeinvitation. Ikke i kamp. Andre klik på navne virker som før. Slået fra som standard.",
	["Alt-click a slot: every slot with the same item flashes in the bag and bank windows. Nothing else happens with the item."] = "Alt-klik på en plads: alle pladser med samme genstand blinker i taske- og bankvinduet. Der sker ikke andet med genstanden.",
	["Alt-click shows the same item"] = "Alt-klik viser samme genstand",
	["Alts"] = "Alts",
	["Alts and bank"] = "Alts og bank",
	["Alts datatext shows"] = "Alts-datateksten viser",
	["Alts window"] = "Alts-vindue",
	["Alts: could be stored on"] = "Alts: kan opbevares hos",
	["Alts: currencies"] = "Alts: valuta",
	["Alts: quests"] = "Alts: quests",
	["Alts: recipes"] = "Alts: opskrifter",
	["Always all"] = "Altid alle",
	["Always EldoUI's"] = "Altid EldoUI's",
	["Always keep Blizzard's"] = "Behold altid Blizzards",
	["Always show"] = "Vis altid",
	["Always show the Errors button"] = "Vis altid Fejl-knappen",
	["Always shows quest items, whatever their quality."] = "Viser altid questgenstande uanset kvalitet.",
	["Always sticky"] = "Altid fast",
	["Always, or only while you hold Shift. Tooltip > Info area > Alts and bank sets the same thing (also Ctrl, Alt or Never); the one you changed last applies."] = "Altid eller kun mens du holder Shift nede. Tooltip > Infoområde > Alts og bank indstiller det samme (også Ctrl, Alt eller Aldrig); den du ændrede sidst, gælder.",
	["Ammo"] = "Ammo",
	["Ammo %d"] = "Ammunition %d",
	["Ammo count that turns red and triggers the warning."] = "Mængden af ammunition hvor tallet bliver rødt og advarslen udløses.",
	["Ammo warning"] = "Ammo-advarsel",
	["An action button while its effect on you or your target lasts: a damage or heal over time, a shield, a seal (Action Bars, Spell cues)."] = "En handlingsknap mens dens effekt på dig eller dit mål varer: skade eller heal over tid, et skjold, et seal (Handlingslinjer, Spell cues).",
	["An allow list from the Aura filters page. Its spells come after the ones typed above."] = "En tilladelsesliste fra siden Aurafiltre. Dens evner kommer efter dem der er skrevet ovenfor.",
	["An Alts window with every character you play: level, gold, gear, professions, mail, quests, reputation and lockouts, with search across all of them. Off while another alts addon is loaded."] = "Et Alts-vindue med alle de karakterer du spiller: level, guld, udstyr, fag, post, quests, omdømme og lockouts, med søgning på tværs af dem alle. Slået fra mens en anden alt-addon er indlæst.",
	["An arrow"] = "En pil",
	["An estimate of who reaches the score limit first and the final score, from the score at the top of the screen (Arathi Basin, Darkspear Islands)."] = "Et estimat af hvem der når pointgrænsen først, og slutresultatet, ud fra stillingen øverst på skærmen (Arathi Basin, Darkspear Islands).",
	["An extra sound when someone whispers you (also Battle.net whispers). The game's own whisper sound still plays. Instant Messages plays this same sound, so a whisper sounds once."] = "En ekstra lyd når nogen hvisker til dig (også Battle.net-hvisk). Spillets egen hviskelyd spiller stadig. Hurtigbeskeder spiller den samme lyd, så et hvisk kun lyder én gang.",
	["An inner ring fills while you cast or channel."] = "En indre ring fyldes mens du caster eller channeler en evne.",
	["An item name, an item ID, or the bag search words: q:rare, t:cloth, ilvl>20, boe, bop, quest, junk. Put - before a word to exclude it and | between alternatives."] = "Et genstandsnavn, et genstands-ID eller taskesøgeordene: q:rare, t:cloth, ilvl>20, boe, bop, quest, junk. Sæt - foran et ord for at udelukke det og | mellem alternativer.",
	["An upkeep icon of the class bar while its buff or poison is missing (out of combat)."] = "Et ikon på klassebjælken mens buffen eller giften mangler (uden for kamp).",
	["Anchors"] = "Ankerpunkter",
	["And: items both words find"] = "Og: genstande som begge ord finder",
	["Angled"] = "Skrå",
	["Angler"] = "Angler",
	["Announce"] = "Annoncer",
	["Announce reset"] = "Meld reset",
	["Announce the last reset"] = "Meld det seneste reset",
	["Announce the winner"] = "Meld vinderen",
	["Announce this camp"] = "Annoncer denne lejr",
	["Announce to"] = "Annoncer i",
	["Announce to the group"] = "Meld til gruppen",
	["Another picture for the icon: a texture file ID or path. Empty uses the spell's or item's own icon."] = "Et andet billede til ikonet: et teksturfil-ID eller en sti. Tom bruger evnens eller genstandens eget ikon.",
	["Another text on or next to the icon, written like Label 1. Empty shows nothing."] = "Endnu en tekst på eller ved siden af ikonet, skrevet som Etiket 1. Tom viser intet.",
	["Any enemy"] = "Enhver fjende",
	["Any enemy: the member has threat on something. Your target: the member's threat state on what you have targeted, as the game reports it. The border itself is on the Effects tab."] = "Enhver fjende: medlemmet har aggro på et eller andet. Dit mål: medlemmets aggrostatus over for dit mål ifølge spillet. Selve kanten findes på fanen Effekter.",
