	["Arm width"] = "Armbredde",
	["Armor"] = "Armor",
	["Armor and weapons up to the quality cap below. Needs Enchanting."] = "Rustning og våben op til kvalitetsgrænsen nedenfor. Kræver Enchanting.",
	["Arrange cooldown icons in your own groups. Off keeps the fixed rows."] = "Arranger cooldownikoner i dine egne grupper. Fra beholder de faste rækker.",
	["Arrange the items with the settings below. Off keeps Blizzard's layout from Edit Mode."] = "Arranger elementerne med indstillingerne nedenfor. Fra: Blizzards layout fra Edit Mode bevares.",
	["Arrow keys move the cursor"] = "Piletaster flytter markøren",
	["Arrow keys or WASD, or click a side of the board: slide. P: pause."] = "Piletaster eller WASD, eller klik på en side af brættet: skub. P: pause.",
	["Arrow keys or WASD: hop. P: pause."] = "Piletaster eller WASD: hop. P: pause.",
	["Arrow keys or WASD: turn. P: pause."] = "Piletaster eller WASD: drej. P: pause.",
	["Arrow keys or WASD: walk. P: pause."] = "Piletaster eller WASD: gå. P: pause.",
	["Arrow keys, WASD or a click beside you: walk and push. U: back. R: again. P: pause."] = "Piletaster, WASD eller et klik ved siden af dig: gå og skub. U: tilbage. R: forfra. P: pause.",
	["Arrow keys, WASD or a click: move. P: pause."] = "Piletaster, WASD eller et klik: bevæg dig. P: pause.",
	["Arrows and bullets."] = "Pile og kugler.",
	["As group leader, each reset sends the instance names to group members who run EldoUI, as an addon message (never in a battleground)."] = "Når du er gruppeleder, sender EldoUI ved hvert reset instansnavnene som en addonbesked til gruppemedlemmer der kører EldoUI (aldrig i et battleground).",
	["As issue"] = "Som issue",
	["As many columns as fit: level, XP, rested, gold, played, item level, durability, lockouts, bags, mail, professions and last seen."] = "Så mange kolonner der er plads til: level, XP, udhvilet, guld, spilletid, item level, holdbarhed, lockouts, tasker, post, fag og sidst set.",
	["As of each character's last auction house visit."] = "Fra hver karakters seneste besøg i auktionshuset.",
	["As set on the Glows page"] = "Som indstillet på siden Glød",
	["Ascending"] = "Stigende",
	["Ask"] = "Spørg",
	["Ask and share camps"] = "Spørg efter og del lejre",
	["Ask and share camps is unchecked on the Camp Helper page (%s)."] = "\"Spørg efter og del lejre\" er uden flueben på siden Lejrhjælper (%s).",
	["Ask and share with"] = "Spørg og del med",
	["Ask for a camp"] = "Spørg efter en lejr",
	["Ask for played time at login"] = "Spørg efter spilletid ved login",
	["Ask me"] = "Spørg mig",
	["Ask me: while you know a fire, a toast lets you send it with one click. Never: requests are ignored."] = "Spørg mig: mens du kender et bål, lader en pop op-besked dig sende det med ét klik. Aldrig: forespørgsler ignoreres.",
	["ask the game for your total time (also shown in chat)"] = "spørg spillet om din samlede spilletid (vises også i chatten)",
	["Ask your guild or group for a camp and share yours, with members who use EldoUI. Nothing is sent until you click Ask or Share, and nothing is answered for you."] = "Spørg din guild eller gruppe efter en lejr, og del din egen med medlemmer der bruger EldoUI. Intet sendes før du klikker på Spørg eller Del, og intet besvares for dig.",
	["asked for your alt list"] = "bad om din altliste",
	["asked for your recipe list"] = "bad om din opskriftsliste",
	["Asked your group for a camp. Members who use EldoUI choose whether to answer."] = "Du har spurgt din gruppe efter en lejr. Medlemmer der bruger EldoUI, vælger selv om de vil svare.",
	["Asked your guild for a camp. Members who use EldoUI choose whether to answer."] = "Du har spurgt din guild efter en lejr. Medlemmer der bruger EldoUI, vælger selv om de vil svare.",
	["Asked your guild for their alt lists. Answers show in the Guild tab."] = "Bad din guild om deres altlister. Svarene vises på fanen Guild.",
	["Asked your guild for their recipe lists. Answers show in the Crafters tab."] = "Bad din guild om deres opskriftslister. Svarene vises på fanen Craftere.",
	["Asks BigWigs, in its own popup, to switch to an \"EldoUI - <layout>\" profile with its bars, messages and countdown on EldoUI's movers. Declining changes nothing."] = "Beder BigWigs om at skifte til en \"EldoUI - <layout>\"-profil (i BigWigs' eget pop op-vindue) med bjælker, beskeder og nedtælling på EldoUI's flyttefelter. Siger du nej, ændres intet.",
	["Asks for played time right after a level-up, so the level log has the exact value instead of an estimate from the login read."] = "Spørger efter spilletid lige efter et nyt level, så levelloggen får den nøjagtige værdi i stedet for et estimat ud fra aflæsningen ved login.",
	["Asks guild members who use EldoUI and share their alts to send you their list. Their answer needs their click too."] = "Beder om altlisten fra guildmedlemmer der bruger EldoUI og deler deres alts. Svaret kræver også et klik fra dem.",
	["Asks guild members who use EldoUI and share their recipes to send you their list. Their answer needs their click too."] = "Beder om opskriftslisten fra guildmedlemmer der bruger EldoUI og deler deres opskrifter. Svaret kræver også et klik fra dem.",
	["Asks once, then removes the character picked above."] = "Spørger én gang og fjerner derefter den karakter der er valgt ovenfor.",
	["Asks the auction house once for every listing and saves the lowest price of each item. Blizzard allows one full scan every 15 minutes."] = "Beder auktionshuset om alle opslag på én gang og gemmer den laveste pris for hver genstand. Blizzard tillader én fuld scanning hvert 15. minut.",
	["Asks the server for your played time a few seconds after login, so the window can show and total it."] = "Spørger serveren om din spilletid et par sekunder efter login, så vinduet kan vise den og lægge den sammen.",
	["Asks your guild or group for a camp now. Members who use EldoUI choose whether to answer."] = "Spørger din guild eller gruppe efter en lejr nu. Medlemmer der bruger EldoUI, vælger selv om de vil svare.",
	["Asks your guild or group for a camp. Members who use EldoUI choose whether to answer."] = "Spørger din guild eller gruppe efter en lejr. Medlemmer der bruger EldoUI, vælger selv om de vil svare.",
