	["Assign to"] = "Tildel til",
	["Assist"] = "Assister",
	["Assisted Highlight (the rotation helper) is off on WoW: Forever, so there is no option for it."] = "Assisted Highlight (rotationshjælperen) er slået fra i WoW: Forever, så der er ingen indstilling til den.",
