	["At the level cap the window waits until you start a guide: from the Journal's Guides page, Open the guide list below or /eui eldostar."] = "Ved levelgrænsen venter vinduet til du starter en guide: fra journalens Guides-side, Åbn guidelisten herunder eller /eui eldostar.",
