	["Aura: a buff or debuff's time left or stacks. Cooldown: drains while the spell or item is on cooldown. Charges: one segment per charge."] = "Aura: en buffs eller debuffs resterende tid eller stakke. Cooldown: tømmes mens evnen eller genstanden har cooldown. Ladninger: ét segment pr. ladning.",
	["Auras"] = "Auraer",
