	["Auto (EldoUI, Blizzard if it fails)"] = "Auto (EldoUI, Blizzard hvis det fejler)",
	["Auto uses EldoUI's frames and switches to Blizzard's frames if the client's group headers don't work. Skinned needs the Skin switch for party and raid frames on the Blizzard UI page."] = "Auto bruger EldoUI's rammer og skifter til Blizzards rammer hvis klientens gruppeheadere ikke virker. Valget Med skin kræver Skin-kontakten for gruppe- og raidrammer på Blizzard-UI-siden.",
	["auto uses the item, achievement or situation icon. Or a file ID or Interface\\Icons\\ path."] = "auto bruger ikonet for genstanden, achievementet eller situationen. Eller et fil-id eller en sti i Interface\\Icons\\.",
