	["BAGS FULL"] = "FULDE TASKER",
	["bags only"] = "kun tasker",
	["Bags switched off. Blizzard's bags come fully back after a reload."] = "Tasker er slået fra. Blizzards tasker kommer helt tilbage efter en genindlæsning.",
	["Bags, Bank, Mail, Equipped and Auctions separately. Off shows one number per character."] = "Tasker, Bank, Post, Båret og Auktioner hver for sig. Når den er slået fra, vises ét tal pr. karakter.",
	["Balanced rows, coin icons and accent headers."] = "Afbalancerede rækker, møntikoner og overskrifter i accentfarve.",
	["Balls: %d"] = "Bolde: %d",
	["Bandage"] = "Bandage",
	["bank"] = "bank",
	["Bank"] = "Bank",
