	["Bank mark"] = "Bankmærke",
	["Bank mark you gave the character (right-click a name)."] = "Bankmærke du har givet karakteren (højreklik på et navn).",
	["bank only"] = "kun bank",
	["Bank tab %d"] = "Bankfane %d",
	["Bank tabs are bought in order at the bank: the next one shows a plus."] = "Bankfaner købes i rækkefølge i banken: den næste viser et plus.",
	["Bank view"] = "Bankvisning",
	["Banker"] = "Bankier",
