	["Bar"] = "Bjælke",
	["Bar %d"] = "Linje %d",
	["Bar %d (hidden)"] = "Linje %d (skjult)",
	["Bar %d (off)"] = "Linje %d (fra)",
	["Bar 1"] = "Linje 1",
	["Bar 1 shows the actions of vehicles, override bars and possessed units, like Blizzard's main bar, and stays shown in vehicles. Always on while EldoUI hides Blizzard's override bar."] = "Linje 1 viser handlingerne for køretøjer, overstyringslinjer og enheder du kontrollerer, ligesom Blizzards hovedlinje, og forbliver synlig i køretøjer. Altid slået til mens EldoUI skjuler Blizzards overstyringslinje.",
	["Bar 1 shows vehicle actions"] = "Linje 1 viser køretøjshandlinger",
	["Bar 1 switches page with stance, form and stealth, like Blizzard's main bar."] = "Linje 1 skifter side med stance, form og stealth, ligesom Blizzards hovedlinje.",
	["Bar 1: Blizzard's override and vehicle bar is hidden and EldoUI's bar 1 shows the vehicle's actions (needs the Hide switch of Vehicle bars and bar 1 on). Blizzard's: its own skinned vehicle bar shows."] = "Linje 1: Blizzards overstyrings- og køretøjslinje skjules, og EldoUI's linje 1 viser køretøjets handlinger (kræver at Skjul-kontakten for Køretøjslinjer og linje 1 er slået til). Blizzards: dens egen køretøjslinje med skin vises.",
	["Bar and log"] = "Linje og log",
	["Bar area height"] = "Højde på bjælkeområde",
	["Bar area width"] = "Bredde på bjælkeområde",
	["Bar colors"] = "Bjælkefarver",
	["Bar fill"] = "Bjælkefyld",
	["Bar icons"] = "Bjælkeikoner",
	["Bar length along the travel direction. The layouts set it; a longer bar may cover the boss frames."] = "Bjælkens længde i bevægelsesretningen. Layoutene sætter den; en længere bjælke kan dække bossrammerne.",
	["Bar shown"] = "Bjælkevisning",
	["Bar size across the travel direction. Above 40 it leaves the space the layouts keep free."] = "Bjælkens tykkelse på tværs af bevægelsesretningen. Over 40 går den ud over den plads layoutene holder fri.",
	["Bar texture during the cast. EldoUI bars only; Blizzard's bars keep theirs."] = "Bjælkens tekstur under castet. Kun EldoUI-bjælker; Blizzards bjælker beholder deres egen.",
	["Barnyard"] = "Barnyard",
	["Bars 1 to 3 and the gamepad bars"] = "Linje 1 til 3 og gamepadlinjerne",
	["Bars 1 to 3 take the keys and spells of your key set. Bar 4 and up stay yours; Fill bars 4 and 5 only uses empty buttons."] = "Linje 1 til 3 får tasterne og evnerne fra dit tastesæt. Linje 4 og opefter forbliver dine; Fyld linje 4 og 5 bruger kun tomme knapper.",
	["Bars 4 and 5"] = "Linje 4 og 5",
	["Bars move to the \"soon\" area 10 seconds before they end for tanks, 8 for healers and 7 for damage dealers, and the bar count suits the role."] = "Bjælker flyttes til området \"snart\" 10 sekunder før de slutter for tanks, 8 for healere og 7 for DPS'ere, og antallet af bjælker passer til rollen.",
	["Bars show from the first swing in combat and hide when combat ends."] = "Bjælkerne vises fra første slag i kamp og skjules når kampen slutter.",
	["Bars touch each other, small text."] = "Bjælkerne rører hinanden, lille tekst.",
	["Bars whose Show rule is \"Mouse over\" appear together: hovering one of them shows all of them, the pet and stance bars too. Off: each bar fades in on its own."] = "Linjer hvis Vis-regel er \"Musen over\", vises sammen: når du holder musen over en af dem, vises de alle, også pet- og stance-linjerne. Fra: hver linje toner ind for sig.",
	["Bars you build for one spell each: an aura's time left or stacks, a spell's or item's cooldown, or its charges. They hang under the cooldown rows; the game fills every bar."] = "Bjælker du bygger til én evne hver: en auras resterende tid eller stakke, en evnes eller genstands cooldown eller dens ladninger. Bjælkerne hænger under cooldownrækkerne; spillet fylder hver bjælke.",
	["Base captures"] = "Erobring af baser",
	["Basic campfire"] = "Basic-lejrbål",
	["Battle"] = "Kamp",
	["Battle begins"] = "Kampen begynder",
	["Battle start"] = "Kampstart",
	["Battleground ends"] = "Battleground slutter",
	["Battleground entered"] = "Gik ind i battleground",
	["Battleground probe dumps removed."] = "Probe-dumps for battlegrounds er fjernet.",
