	["Battleground Timers"] = "Battleground-nedtællinger",
	["Battlegrounds never count toward the hourly limit."] = "Battlegrounds tæller aldrig med i grænsen pr. time.",
	["Battlegrounds with the result and honor. They never count."] = "Battlegrounds med resultat og ære. De tæller aldrig med.",
	["Became rested"] = "Du bliver udhvilet",
	["Begin a session by itself when you loot money or an item and none is running. Off: start it with a click."] = "Start automatisk en session når du looter penge eller en genstand, og ingen session kører. Slået fra: start den med et klik.",
	["Below the bags"] = "Under taskerne",
	["Below the bar"] = "Under bjælken",
	["Below the chat"] = "Under chatten",
	["Below the debuffs"] = "Under debuffene",
	["Below the frame, from the left"] = "Under rammen, fra venstre",
	["Below the frame, from the right"] = "Under rammen, fra højre",
	["Below the vendor price"] = "Under købmandsprisen",
	["Bend"] = "Bøjning",
	["Beside the icons"] = "Ved siden af ikonerne",
	["Beside the slot"] = "Ved siden af pladsen",
	["Beside the slot puts the number next to the icon, on the side facing the model."] = "\"Ved siden af pladsen\" sætter tallet ved ikonet, på den side der vender mod modellen.",
	["Best done in a group of %d."] = "Bedst i en gruppe på %d.",
	["Best done in a group."] = "Bedst i en gruppe.",
	["Best for your level"] = "Bedst til dit level",
	["Best here"] = "Bedst her",
	["Best hour"] = "Bedste time",
	["Best ilvl"] = "Bedste ilvl",
	["Best in bags"] = "Bedste i taskerne",
	["Best scores"] = "Bedste scorer",
	["Best: %s"] = "Bedste: %s",
	["Better items than this never get the disenchant button, so a stray click can't destroy them."] = "Genstande over denne kvalitet får aldrig disenchant-knappen, så et forkert klik ikke kan ødelægge dem.",
	["BG"] = "BG",
	["Bid"] = "Bud",
	["Bids"] = "Bud",
	["Big"] = "Big",
	["Big 38 px icons, easy to hit."] = "Store 38 px ikoner, nemme at ramme.",
	["Big 40 px buffs and 52 px debuffs, your own buffs first, colored time that blinks in the last 5 seconds."] = "Store buffs på 40 px og debuffs på 52 px, dine egne buffs først, farvet tid der blinker de sidste 5 sekunder.",
	["Big 48 px icons with the time under them; missing auras show faded."] = "Store ikoner på 48 px med tiden under dem; manglende auraer vises nedtonet.",
	["Big 56 px essential icons for a cooldown-centered HUD."] = "Store 56 px essentielle ikoner til en HUD med cooldowns i centrum.",
	["Big arcing numbers on both sides of your character, the classic scrolling look."] = "Store tal i buer på begge sider af din karakter, det klassiske rullende udseende.",
	["Big buttons with their names."] = "Store knapper med deres navne.",
	["Big defensive"] = "Stor defensiv",
	["Big icon"] = "Stort ikon",
	["Big icons shown at once. More than one makes the timeline longer, away from the bar, and may reach the frames next to it."] = "Antal store ikoner vist på én gang. Mere end ét gør tidslinjen længere, væk fra bjælken, og kan nå rammerne ved siden af.",
	["Big item levels, red tint on worn gear, missing-enchant marks."] = "Store item levels, rød farvetone på slidt udstyr, mærker for manglende enchant.",
	["Big markers and a thick line, easy to read on a big screen."] = "Store markører og en tyk linje, let at læse på en stor skærm.",
	["Big rows and roll bars for high resolutions."] = "Store rækker og lootrulbjælker til skærme med høj opløsning.",
	["Big rows and text that read well from a distance."] = "Store rækker og tekst der er let at læse på afstand.",
	["Big text"] = "Stor tekst",
	["Big text and clock, whispers and chat hidden."] = "Stor tekst og ur, hviskebeskeder og chat skjult.",
	["Big text in a wide panel, easy to read from a distance."] = "Stor tekst i et bredt panel, let at læse på afstand.",
	["Big tiles in rows of five, sorted by role, health growing upward, power only on healers, your heals over time and every heal and shield on the way."] = "Store felter i rækker på fem, sorteret efter rolle, liv der vokser opad, ressource kun på healere, dine heals over tid og alle heals og skjolde på vej.",
	["Bigger 30 px icons and 14 pt text in a column."] = "Større 30 px ikoner og 14 pt tekst i en kolonne.",
	["Bigger red markers with the boss's number in kill order."] = "Større røde markører med bossens nummer i drabsrækkefølge.",
	["Bigger text and bars for big screens or sitting far away."] = "Større tekst og bjælker til store skærme eller lang afstand til skærmen.",
	["Bigger text and roomier boxes, easy to read from afar."] = "Større tekst og rummeligere bokse, nemme at læse på afstand.",
	["Bigger text for big screens or sitting back."] = "Større tekst til store skærme eller når du sidder langt fra skærmen.",
	["BigWigs"] = "BigWigs",
	["BigWigs %s"] = "BigWigs %s",
	["BigWigs already uses %s."] = "BigWigs bruger allerede %s.",
	["BigWigs anchors left unchanged."] = "BigWigs' ankerpunkter er uændrede.",
	["BigWigs bars now follow the EldoUI movers. Move them with /eui move."] = "BigWigs' bjælker følger nu EldoUI-flyttefelterne. Flyt dem med /eui move.",
	["BigWigs has no profile called %s any more."] = "BigWigs har ikke længere en profil der hedder %s.",
	["BigWigs integration"] = "BigWigs-integration",
	["BigWigs is back on %s."] = "BigWigs bruger %s igen.",
	["BigWigs is not loaded, or this integration is off."] = "BigWigs er ikke indlæst, eller denne integration er slået fra.",
	["BigWigs messages mover"] = "Flyttefelt til BigWigs-beskeder",
	["BigWigs only"] = "Kun BigWigs",
	["BigWigs refused the anchors: %s"] = "BigWigs afviste ankerpunkterne: %s",
	["BigWigs' bars get EldoUI's thin border, texture and font, with the accent on bars about to end. Bar colors and sounds stay as set in BigWigs."] = "BigWigs' bjælker får EldoUI's tynde kant, tekstur og skrifttype, med accentfarve på bjælker der snart slutter. Bjælkefarver og lyde forbliver som indstillet i BigWigs.",
	["BigWigs: hide its normal bars in BigWigs' own Bars options if you want only the timeline."] = "BigWigs: skjul dens normale bjælker i BigWigs' egne Bars-indstillinger hvis du kun vil have tidslinjen.",
	["Bind keys"] = "Tildel taster",
	["Bind spells and macros to clicks on party, raid and unit frames, and see every binding in the frame's tooltip."] = "Bind evner og makroer til klik på gruppe-, raid- og unitframes, og se alle bindinger i rammens tooltip.",
	["Bind spells and macros to clicks, modifier clicks, keys or the mouse wheel on party, raid and unit frames. Saved per class."] = "Bind evner og makroer til klik, klik med ændringstast, taster eller musehjulet på gruppe-, raid- og unitframes. Gemmes pr. klasse.",
	["Bind tag"] = "Bindingsmærke",
	["Bindings"] = "Bindinger",
	["Bindings and tips only on party and raid frames."] = "Bindinger og tips kun på gruppe- og raidrammer.",
	["Bindings change after combat."] = "Bindingerne ændres efter kampen.",
	["Bindings for %s"] = "Bindinger for %s",
	["Bindings for %s, talent group %s"] = "Bindinger for %s, talentgruppe %s",
	["Bindings on every frame, keys and wheel on hover, tips for the modifier you hold."] = "Bindinger på alle rammer, taster og hjul under musen, tips for den ændringstast du holder nede.",
	["Bindings work, the tooltip stays clean."] = "Bindingerne virker; tooltippen forbliver ren.",
	["Binds when picked up"] = "Bindes ved opsamling",
	["Blackrock Mountain lies between which two zones?"] = "Mellem hvilke to zoner ligger Blackrock Mountain?",
	["Blacksmith"] = "Blacksmith",
	["Blend"] = "Blanding",
	["Blend the fill towards a second color at the growing edge."] = "Bland fyldet hen mod en anden farve ved den voksende kant.",
	["Blessing of Kings"] = "Blessing of Kings",
	["Blessing of Might"] = "Blessing of Might",
	["Blessing of Wisdom"] = "Blessing of Wisdom",
	["Blessing plan"] = "Velsignelsesplan",
	["Blessing Plan"] = "Velsignelsesplan",
	["Blessing plan from %s: %s"] = "Velsignelsesplan fra %s: %s",
	["Blessing plan posted in chat."] = "Velsignelsesplanen er skrevet i chatten.",
	["Blessing plan sent to the group."] = "Velsignelsesplanen er sendt til gruppen.",
	["Blessing plan: %s"] = "Velsignelsesplan: %s",
	["Blessings for %s: %s"] = "Velsignelser til %s: %s",
	["Blink when expiring"] = "Blink når den udløber",
	["Blizzard art"] = "Blizzard-grafik",
	["Blizzard art keeps Blizzard's bar textures."] = "Blizzard-grafik beholder Blizzards bjælketeksturer.",
	["Blizzard art keeps Blizzard's fill textures; the others use the texture below."] = "Blizzard-grafik beholder Blizzards fyldteksturer; de andre bruger teksturen nedenfor.",
	["Blizzard bank"] = "Blizzard-bank",
	["Blizzard class background"] = "Blizzards klassebaggrund",
	["Blizzard combat text"] = "Blizzards kamptekst",
	["Blizzard decides what the meter counts. Its own settings (Edit Mode and the window's cog menu) still apply."] = "Blizzard bestemmer hvad måleren tæller. Dens egne indstillinger (Edit Mode og vinduets tandhjulsmenu) gælder stadig.",
	["Blizzard draws these into an anchor on the frame; EldoUI never sees them."] = "Blizzard tegner dem i et ankerpunkt på rammen; EldoUI ser dem aldrig.",
	["Blizzard frames that EldoUI hides or replaces can't be grabbed in Edit Mode, nor the empty Blizzard bar left behind when EldoUI carries the micro menu or bag buttons. Drag EldoUI's own box instead."] = "Blizzard-rammer som EldoUI skjuler eller erstatter, kan ikke gribes i Edit Mode, heller ikke den tomme Blizzard-linje der bliver tilbage når EldoUI står for mikromenuen eller taskeknapperne. Træk i EldoUI's egen boks i stedet.",
	["Blizzard frames whose position EldoUI sets get a label, so you know an Edit Mode drag won't stick."] = "Blizzard-rammer hvis placering EldoUI sætter, får et mærke, så du ved at et træk i Edit Mode ikke holder.",
	["Blizzard frames whose position EldoUI sets get a label: dragging them in Edit Mode won't stick."] = "Blizzard-rammer hvis placering EldoUI sætter, får et mærke: træk i dem i Edit Mode holder ikke.",
	["Blizzard frames, skinned"] = "Blizzard-rammer med skin",
	["Blizzard frames, untouched"] = "Blizzard-rammer, urørte",
	["Blizzard gold"] = "Blizzard-guld",
	["Blizzard import string for the first Legacy tree: %s"] = "Blizzard-importstreng for det første Legacy-træ: %s",
	["Blizzard party and raid switches"] = "Blizzard-kontakter for gruppe og raid",
	["Blizzard roll frame scale"] = "Skala for Blizzards rulrammer",
	["Blizzard setting"] = "Blizzard-indstilling",
	["Blizzard window scale"] = "Skala for Blizzard-vinduet",
	["Blizzard's action bars come fully back after a reload."] = "Blizzards handlingslinjer kommer helt tilbage efter en genindlæsning.",
	["Blizzard's auction window. Its size, dragging and resets are on the Move windows page; where it opens is its mover in move mode."] = "Blizzards auktionsvindue. Størrelse, trækning og nulstilling findes på siden Flyt vinduer; hvor det åbner, styres af dets flyttefelt i flyttetilstand.",
	["Blizzard's bag windows"] = "Blizzards taskevinduer",
	["Blizzard's bar"] = "Blizzards linje",
	["Blizzard's bars under your character (Edit Mode: Personal Resource Display). Skin restyles it instead."] = "Blizzards bjælker under din karakter (Edit Mode: Personal Resource Display). Skin giver dem et nyt udseende i stedet.",
	["Blizzard's breath, fatigue and feign death bars stay hidden."] = "Blizzards bjælker for åndedræt, udmattelse og Feign Death forbliver skjult.",
	["Blizzard's bright tip at the end of each buff bar."] = "Blizzards lyse spids for enden af hver buffbjælke.",
	["Blizzard's Buy tab"] = "Blizzards købsfane",
	["Blizzard's cast bars too"] = "Også Blizzards castbars",
	["Blizzard's class background with quality borders only."] = "Blizzards klassebaggrund og kun kvalitetskanter.",
	["Blizzard's compact raid frame proportions, two groups per column, power bars only on healers."] = "Proportionerne fra Blizzards kompakte raidrammer, to grupper pr. kolonne, ressourcebjælker kun på healere.",
	["Blizzard's Cooldown Manager isn't available on this character."] = "Blizzards Cooldown Manager er ikke tilgængelig på denne karakter.",
	["Blizzard's Cooldown Manager isn't loaded."] = "Blizzards Cooldown Manager er ikke indlæst.",
	["Blizzard's Cooldown Manager settings open after combat."] = "Blizzards indstillinger for Cooldown Manager åbnes efter kampen.",
	["Blizzard's Cooldown Manager shows no spells here, so EldoUI's own cooldown rows take its place. They stay empty until you pick your spells for the Main and Utility rows in /eui cooldownmanager."] = "Blizzards Cooldown Manager viser ingen evner her, så EldoUI's egne cooldownrækker træder i stedet. De er tomme indtil du vælger dine evner til Hovedrækken og Utility-rækken i /eui cooldownmanager.",
	["Blizzard's countdown numbers on the icon."] = "Blizzards nedtællingstal på ikonet.",
	["Blizzard's damage meter isn't available on this character."] = "Blizzards skademåler er ikke tilgængelig på denne karakter.",
	["Blizzard's damage numbers are on too, so each hit shows twice. Turn on \"Let EldoUI change this\" on the Blizzard combat text tab."] = "Blizzards skadetal er også slået til, så hvert hit vises to gange. Slå \"Lad EldoUI ændre dette\" til på fanen Blizzards kamptekst.",
	["Blizzard's Edit Mode for Blizzard's frames only; EldoUI's frames move with /eui move."] = "Blizzards Edit Mode kun til Blizzards rammer; EldoUI's rammer flyttes med /eui move.",
	["Blizzard's floating combat text is hidden (Blizzard combat text tab)."] = "Blizzards svævende kamptekst er skjult (fanen Blizzards kamptekst).",
	["Blizzard's frames"] = "Blizzards rammer",
	["Blizzard's Legacy window"] = "Blizzards Legacy-vindue",
	["Blizzard's loot history gets the EldoUI look with the Skin switch, and remembers where you drag it with the Move switch."] = "Blizzards loothistorik får EldoUI-udseendet med kontakten Skin, og med kontakten Flyt husker den hvor du trækker den hen.",
	["Blizzard's main-hand swing bar stays hidden."] = "Blizzards swingbjælke for main hand forbliver skjult.",
	["Blizzard's numbers over enemies"] = "Blizzards tal over fjender",
	["Blizzard's off-hand swing bar stays hidden."] = "Blizzards swingbjælke for off hand forbliver skjult.",
	["Blizzard's option %s. \"Blizzard setting\" follows the game's options, but hides it while hit numbers on plates are on, so a hit shows once."] = "Blizzards indstilling %s. \"Blizzard-indstilling\" følger spillets indstillinger, men skjuler den mens hittal på nameplates er slået til, så et hit kun vises én gang.",
	["Blizzard's option %s. \"Blizzard setting\" leaves it as you set it in the game's options."] = "Blizzards indstilling %s. \"Blizzard-indstilling\" lader den være som du har sat den i spillets indstillinger.",
	["Blizzard's option to clear the meter when you enter a new instance (CVar damageMeterResetOnNewInstance)."] = "Blizzards indstilling for at rydde måleren når du går ind i en ny instans (CVar damageMeterResetOnNewInstance).",
	["Blizzard's own"] = "Blizzards egen",
	["Blizzard's own bar %d. Hide when replaced: hidden while this EldoUI bar is on and the Replace switch is on. Keep: it stays. Hide: always hidden (needs the Hide switch)."] = "Blizzards egen linje %d. Skjul når EldoUI erstatter den: skjult mens denne EldoUI-linje er slået til og Erstat-kontakten er slået til. Behold: den bliver. Skjul: altid skjult (kræver Skjul-kontakten).",
	["Blizzard's own combat text options. \"Blizzard setting\" keeps your value from Blizzard's options; Blizzard default puts your values back."] = "Blizzards egne indstillinger for kamptekst. \"Blizzard-indstilling\" beholder din værdi fra Blizzards indstillinger; Blizzard-standard sætter dine værdier tilbage.",
	["Blizzard's own countdown with the big numbers (battleground gates, pull countdown). Skin, move or hide it under Blizzard UI > Combat HUD > Start countdown."] = "Blizzards egen nedtælling med de store tal (battleground-porte, pull-nedtælling). Skin, flyt eller skjul den under Blizzard-UI > Combat HUD > Startnedtælling.",
	["Blizzard's own damage and healing numbers over targets: your own hits, from the game."] = "Blizzards egne skade- og helingstal over mål: dine egne hits, fra spillet.",
	["Blizzard's own loot and roll frames in the EldoUI look."] = "Blizzards egne loot- og rulrammer i EldoUI-udseendet.",
	["Blizzard's own option for coloring names by class in every channel."] = "Blizzards egen indstilling for at farve navne efter klasse i alle kanaler.",
	["Blizzard's own swing timer shows when Interface > Combat > Swing Timer is on. Its Edit Mode visibility still applies."] = "Blizzards egen swingtimer vises når Interface > Combat > Swing Timer er slået til. Dens synlighed i Edit Mode gælder stadig.",
	["Blizzard's own timestamp setting (Social options)."] = "Blizzards egen indstilling for tidsstempler (indstillingerne under Social).",
	["Blizzard's party and raid frames too"] = "Også Blizzards gruppe- og raidrammer",
	["Blizzard's quest timer stays hidden."] = "Blizzards questnedtælling forbliver skjult.",
	["Blizzard's raid manager on the left edge. Hidden keeps markers and ready check in EldoUI's Raid Tools. Needs the raid frames switch on the Blizzard UI page; Skinned also needs its Skin switch."] = "Blizzards raidmanager ved venstre kant. Skjult beholder markører og klar-tjek i EldoUI's Raidværktøjer. Kræver raidrammekontakten på Blizzard-UI-siden; valget Med skin kræver også dens Skin-kontakt.",
	["Blizzard's ranged swing bar stays hidden."] = "Blizzards swingbjælke for ranged forbliver skjult.",
	["Blizzard's roll frames are hidden and EldoUI's roll bars are off, so loot rolls are not shown. Type %s for EldoUI's bars."] = "Blizzards rulrammer er skjult, og EldoUI's rulbjælker er slået fra, så lootrul vises ikke. Skriv %s for EldoUI's bjælker.",
	["Blizzard's roll frames, Blizzard's in the EldoUI look, or EldoUI's roll bars. Going back from EldoUI's bars takes effect after a reload."] = "Blizzards rulrammer, Blizzards i EldoUI-udseendet eller EldoUI's rulbjælker. Et skift tilbage fra EldoUI's bjælker træder i kraft efter en genindlæsning.",
	["Blizzard's setting"] = "Blizzards indstilling",
	["Blizzard's setting follows the game's own class color option. Class colors colors every player by class even when that option is off."] = "Blizzards indstilling følger spillets egen klassefarveindstilling. Klassefarver farver hver spiller efter klasse, også når den indstilling er slået fra.",
	["Blizzard's settings"] = "Blizzards indstillinger",
	["Blizzard's start countdown"] = "Blizzards startnedtælling",
	["Blizzard's totem timers (the totem bar for placing totems is under Action Bars)."] = "Blizzards totemnedtællinger (totemlinjen til at sætte totems står under Handlingslinjer).",
	["Blizzard's vehicle bar"] = "Blizzards køretøjslinje",
	["Blizzard's window, Blizzard's window in the EldoUI look, or EldoUI's own quality-colored window."] = "Blizzards vindue, Blizzards vindue i EldoUI-udseendet eller EldoUI's eget vindue farvet efter kvalitet.",
	["Blizzard's windows (skin and move)"] = "Blizzards vinduer (skin og flyt)",
	["Blizzard's, EldoUI skin"] = "Blizzards, EldoUI-skin",
	["Blizzard, EldoUI skin"] = "Blizzard, EldoUI-skin",
	["Blizzard, skinned"] = "Blizzard, med skin",
	["Blizzard: the game's bags, untouched. Skin: the game's bags in the EldoUI look. EldoUI window: one window with categories, offline view and more."] = "Blizzard: spillets tasker, urørte. Skin: spillets tasker i EldoUI-udseendet. EldoUI-vindue: ét vindue med kategorier, offlinevisning og mere.",
	["Blizzard: the game's bank, untouched. Skin: the game's bank in the EldoUI look. EldoUI window: the bank in the bag window's style, with offline view."] = "Blizzard: spillets bank, urørt. Skin: spillets bank i EldoUI-udseendet. EldoUI-vindue: banken i taskevinduets stil med offlinevisning.",
	["Blizzard_LegacySystem loaded: %s, LegacySystemFrame: %s"] = "Blizzard_LegacySystem indlæst: %s, LegacySystemFrame: %s",
