	["Boss mod uses the color DBM or BigWigs gives the timer type. Accent uses your accent color. None keeps the plain border."] = "Bossmod bruger den farve DBM eller BigWigs giver nedtællingstypen. Accentfarve bruger din accentfarve. Ingen beholder den almindelige kant.",
