	["Change color as the time runs out: aura bars color their time text, cooldown bars their fill. The game does the math."] = "Skift farve efterhånden som tiden løber ud: aurabjælker farver deres tidstekst, cooldownbjælker deres fyld. Spillet står for beregningen.",
	["change filter"] = "skift filter",
	["Change the bar color above chosen values: the part of the bar past each value takes that value's color, e.g. energy past 40 turns orange."] = "Skift bjælkens farve over valgte værdier: den del af bjælken der ligger over hver værdi, får den værdis farve, fx bliver energi over 40 orange.",
	["Change the key out of combat."] = "Skift tasten uden for kamp.",
	["Change this route on the map: add and take out pulls, write notes, draw arrows and lines. A suggested route is copied as yours first."] = "Ret ruten på kortet: tilføj og fjern pulls, skriv noter, og tegn pile og linjer. En foreslået rute kopieres først som din egen.",
	["Changed by EldoUI for this character. Undo puts the earlier values back."] = "Ændret af EldoUI for denne karakter. Fortryd sætter de tidligere værdier tilbage.",
	["Changed by EldoUI in the %s profile \"%s\". Undo puts the earlier values back."] = "Ændret af EldoUI i %s-profilen \"%s\". Fortryd sætter de tidligere værdier tilbage.",
	["Changed in the draft"] = "Ændret i kladden",
	["Changes"] = "Ændringer",
	["Changes only"] = "Kun ændringer",
	["Changes Questie's own \"grow from\" corner to the layout's side of the screen, so a growing tracker stays on screen. EldoUI asks first; Undo puts the old corner back."] = "Ændrer Questies eget hjørne for vækstretning til layoutets side af skærmen, så en voksende tracker bliver på skærmen. EldoUI spørger først; Fortryd sætter det gamle hjørne tilbage.",
	["Changes RestedXP's \"Current step frame anchor\" to Bottom, so the current step shows under the guide. EldoUI asks first and shows which RestedXP profile changes. Undo puts the old value back."] = "Ændrer RestedXP's ankerpunkt for kortet med det aktuelle trin til Bottom, så det aktuelle trin vises under guiden. EldoUI spørger først og viser hvilken RestedXP-profil der ændres. Fortryd sætter den gamle værdi tilbage.",
