	["Clears every remembered recipe."] = "Rydder alle huskede opskrifter.",
	["Clears the plan of every paladin listed here."] = "Rydder planen for alle Paladins på listen her.",
	["Clears this character's place in the guide in use and starts it from its first step."] = "Rydder denne karakters plads i guiden der er i brug, og starter den fra første trin.",
	["Click a brazier, or arrow keys and Space. P: pause."] = "Klik på et fyrfad, eller brug piletasterne og mellemrum. P: pause.",
	["Click a burrow, or the number keys as on a number pad. P: pause."] = "Klik på et hul eller brug taltasterne som på et numerisk tastatur. P: pause.",
	["Click a card to turn it. Arrow keys and Space work too."] = "Klik på et kort for at vende det. Piletaster og mellemrum virker også.",
	["Click a card, then where it goes. Right-click or double-click: send home. Space: draw. U: undo. A: all home."] = "Klik et kort og så hvor det skal hen. Højreklik eller dobbeltklik: send hjem. Mellemrum: træk. U: fortryd. A: alle hjem.",
	["Click a cart, then where it goes. Arrow keys slide it, Space picks the next. U: undo. R: start over."] = "Klik på en vogn og så hvor den skal hen. Piletasterne skubber den, Mellemrum vælger den næste. U: fortryd. R: start forfra.",
	["Click a color to change it. Game puts the game's own color back. Numbered channels keep their color when their number changes."] = "Klik på en farve for at ændre den. Spil sætter spillets egen farve tilbage. Nummererede kanaler beholder deres farve når deres nummer ændres.",
	["Click a column, or Left, Right and Space (or 1 to 7). P: pause."] = "Klik på en søjle, eller brug venstre, højre og mellemrum (eller 1 til 7). P: pause.",
	["Click a line to try it in the search box."] = "Klik på en linje for at prøve den i søgefeltet.",
	["Click a name or press 1 to 4. P: pause."] = "Klik på et navn eller tryk 1 til 4. P: pause.",
	["Click a note, arrow or line to delete it."] = "Klik på en note, en pil eller en linje for at slette den.",
	["Click a pack: it becomes the next pull, or comes out of the route when it is in it. Shift-click: it joins the pull picked in the list."] = "Klik på en pack: den bliver det næste pull, eller den tages ud af ruten hvis den allerede er med. Shift-klik: den kommer med i det pull der er valgt i listen.",
	["Click a piece in line with the gap, or the arrow keys. P: pause."] = "Klik på en brik på linje med hullet, eller brug piletasterne. P: pause.",
	["Click a piece, then where it goes. P: pause."] = "Klik på en brik og så hvor den skal hen. P: pause.",
	["Click a piece, then where it goes. U: take back. P: pause."] = "Klik på en brik og så hvor den skal hen. U: fortryd. P: pause.",
	["Click a point to place; click a piece, then where it goes. P: pause."] = "Klik på et punkt for at sætte en brik; klik på en brik og så hvor den skal hen. P: pause.",
	["Click a profession to see its recipes."] = "Klik på et fag for at se dets opskrifter.",
	["Click a route to keep it or dismiss it. Nothing is added to your routes until you keep one."] = "Klik på en rute for at beholde eller afvise den. Intet føjes til dine ruter før du beholder en.",
	["Click a route to open it on the map. Right-click for rename, export and delete."] = "Klik på en rute for at åbne den på kortet. Højreklik for at omdøbe, eksportere og slette.",
	["Click a rune, then move the pointer to draw. Arrow keys and Space work too. P: pause."] = "Klik på en rune, og flyt markøren for at tegne. Piletasterne og Mellemrum virker også. P: pause.",
	["Click a rune, then the empty hole it jumps to. Arrow keys and Space work too. U: undo. P: pause."] = "Klik på en rune og så det tomme hul, den hopper til. Piletasterne og Mellemrum virker også. U: fortryd. P: pause.",
	["Click a square of the Horde's waters. R: new fleet before the first shot. P: pause."] = "Klik på et felt i Hordens farvand. R: ny flåde før første skud. P: pause.",
	["Click a square to pick a blessing."] = "Klik på et felt for at vælge en velsignelse.",
	["Click a square with a dot. P: pause."] = "Klik på et felt med en prik. P: pause.",
	["Click a stone, then a number key or the runes below. Backspace clears. P: pause."] = "Klik på en sten og så en taltast eller runerne nedenfor. Backspace sletter. P: pause.",
	["Click a word's first letter."] = "Klik på et ords første bogstav.",
	["Click again"] = "Klik igen",
	["Click an answer or press 1 to 4. P: pause."] = "Klik på et svar eller tryk 1 til 4. P: pause.",
	["Click an empty square. P: pause."] = "Klik på et tomt felt. P: pause.",
	["Click between two posts to set a fence."] = "Klik mellem to pæle for at sætte et hegn.",
	["Click between two posts. P: pause."] = "Klik mellem to pæle. P: pause.",
	["Click Casting"] = "Klikkast",
	["Click dice to keep them, roll again, or pick a box."] = "Klik på terninger for at beholde dem, slå igen eller vælg en rubrik.",
	["Click here with a mouse button, or hover and press a key"] = "Klik her med en museknap, eller hold musen over og tryk på en tast",
	["Click one of your pits, or 1 to 6. P: pause."] = "Klik på en af dine gruber, eller 1 til 6. P: pause.",
	["Click or press %d"] = "Klik eller tryk %d",
	["Click or press Esc to close. Moving clears Away."] = "Klik eller tryk på Esc for at lukke. Når du bevæger dig, fjernes AFK-status.",
	["Click Refresh to load your auctions."] = "Klik på Opdater for at indlæse dine auktioner.",
	["Click the first and the last letter of a word. Arrow keys and Space work too. P: pause."] = "Klik på et ords første og sidste bogstav. Piletasterne og Mellemrum virker også. P: pause.",
	["Click the map to write a note there. Click a note to change its text; an empty text deletes it."] = "Klik på kortet for at skrive en note der. Klik på en note for at ændre dens tekst; en tom tekst sletter den.",
	["Click the map where the place lies. P: pause."] = "Klik på kortet der hvor stedet ligger. P: pause.",
	["Click the runes, or their number keys. P: pause."] = "Klik på runerne eller deres taltaster. P: pause.",
	["Click to check this off when it is done. Click again to uncheck it."] = "Klik for at sætte flueben når det er klaret. Klik igen for at fjerne fluebenet.",
	["Click to copy"] = "Klik for at kopiere",
	["Click to go on with this guide where you left it. Right-click to start it over."] = "Klik for at fortsætte med guiden hvor du slap. Højreklik for at starte den forfra.",
	["Click to search for \"%s\"."] = "Klik for at søge efter \"%s\".",
	["Click to start this guide."] = "Klik for at starte guiden.",
	["Click two crests side by side to swap them. Arrow keys and Space work too."] = "Klik på to emblemer ved siden af hinanden for at bytte dem. Piletaster og mellemrum virker også.",
	["Click two free tiles with the same icon. H: a hint. P: pause."] = "Klik på to frie brikker med samme ikon. H: et hint. P: pause.",
	["Click, then press the key that casts Fishing in fishing mode. Esc cancels."] = "Klik, og tryk så på den tast der kaster snøren i fisketilstand. Esc annullerer.",
	["Click, then press the key. Shift, Ctrl and Alt work too."] = "Klik, og tryk så på tasten. Shift, Ctrl og Alt virker også.",
	["Click-casting is on"] = "Klikkast er slået til",
	["Click-through"] = "Klik igennem",
	["Click: fill. Right-click or X: cross out. Arrow keys and Space work too. P: pause."] = "Klik: udfyld. Højreklik eller X: sæt kryds. Piletaster og mellemrum virker også. P: pause.",
	["Click: open the games. Right-click: put the box away for this flight. Drag: move it."] = "Klik: åbn spillene. Højreklik: læg boksen væk på denne flyvning. Træk: flyt den.",
	["Click: open. Right-click or F: flag. Arrow keys and Space work too."] = "Klik: åbn. Højreklik eller F: sæt flag. Piletaster og mellemrum virker også.",
	["Click: the next board size or level. Each one keeps its own best."] = "Klik: næste brætstørrelse eller sværhedsgrad. Hver har sin egen bedste score.",
	["Clickable links"] = "Klikbare links",
	["Clicks work again after combat."] = "Klik virker igen efter kamp.",
	["Clock and date"] = "Ur og dato",
	["Clock shows"] = "Uret viser",
	["Clock, gold, FPS and latency only, on a 24 px bar."] = "Kun ur, guld, FPS og latens, på en bjælke på 24 px.",
	["Close bags with it"] = "Luk taskerne samtidig",
	["Close gaps"] = "Luk huller",
	["Close lines of Horde stones between yours to turn them; most stones wins."] = "Indeslut rækker af Hordens sten mellem dine for at vende dem; flest sten vinder.",
	["Close matches"] = "Tætte match",
	["Close the copy box after Ctrl+C"] = "Luk kopifeltet efter Ctrl+C",
	["Close the editor. Your route is saved as you go."] = "Luk editoren. Din rute gemmes løbende.",
	["Close the games when you land"] = "Luk spillene når du lander",
	["Close the roll window after"] = "Luk rulvinduet efter",
	["Close to pulling aggro"] = "Tæt på at tage aggro",
	["Closer at NPCs, indoors and in cities, further out on a mount."] = "Tættere på ved NPC'er, indendørs og i byer, længere ude på en mount.",
	["Closes the bags again when the %s window closes, if it opened them."] = "Hvis vinduet (%s) åbnede taskerne, lukker det dem igen når det lukkes.",
	["Coin and darken"] = "Mønt og mørkere",
	["Coin icon"] = "Møntikon",
	["Coin Merge"] = "Møntfletning",
	["Coins you looted (the money change when no loot line could be read). Never posted to chat."] = "Mønter du har lootet (pengeændringen når ingen lootlinje kunne læses). Deles aldrig i chatten.",
	["Collect %s"] = "Saml %s",
	["collected"] = "i samlingen",
	["collected (from another item)"] = "i samlingen (fra en anden genstand)",
	["Collector"] = "Collector",
	["Color at most stacks"] = "Farve ved flest stakke",
	["Color border by type"] = "Farv kant efter type",
	["Color by health"] = "Farv efter liv",
	["Color by time left"] = "Farv efter resterende tid",
	["Color near the end"] = "Farve nær slutningen",
	["Color of a matched keyword."] = "Farve på et matchet nøgleord.",
	["Color of all pips at maximum combo points."] = "Farve på alle pips ved maks. combopoints.",
	["Color of Alliance bars."] = "Farve på Alliance-bjælker.",
	["Color of charges and item counts."] = "Farve på ladninger og antal genstande.",
	["Color of clickable links."] = "Farve på klikbare links.",
	["Color of cooldowns about to end."] = "Farve på cooldowns der snart slutter.",
	["Color of cooldowns of a minute or more."] = "Farve på cooldowns på et minut eller mere.",
	["Color of cooldowns under a minute."] = "Farve på cooldowns under et minut.",
	["Color of damage numbers."] = "Farve på skadetal.",
	["Color of dodge, parry, miss and other words."] = "Farve på dodge, parry, miss og andre ord.",
	["Color of each bar. Threat status uses the game's yellow, orange and red."] = "Farven på hver bjælke. Aggrostatus bruger spillets gule, orange og røde farve.",
	["Color of EldoUI's timestamps."] = "Farve på EldoUI's tidsstempler.",
	["Color of every item level number."] = "Farven på alle item level-tal.",
	["Color of every other bar: time to enter, battle start, time left."] = "Farve på alle andre bjælker: tid til at gå ind, kampstart, tid tilbage.",
	["Color of healing numbers."] = "Farve på helingstal.",
	["Color of Horde bars."] = "Farve på Horde-bjælker.",
	["Color of macro names."] = "Farve på makronavne.",
	["Color of new notes, arrows and lines"] = "Farve på nye noter, pile og linjer",
	["Color of plain values. Warnings keep their own colors (yellow, red)."] = "Farve på almindelige værdier. Advarsler beholder deres egne farver (gul, rød).",
	["Color of queue bars."] = "Farve på købjælker.",
	["Color of section titles in the stats and side panels."] = "Farve på afsnitstitler i stats- og sidepanelerne.",
	["Color of the bar of the player who has aggro."] = "Farven på bjælken for den spiller der har aggro.",
	["Color of the bar past this value."] = "Bjælkens farve over denne værdi.",
	["Color of the bar's edges lighting up as it fills."] = "Farven på bjælkens kanter der lyser op mens den fyldes.",
	["Color of the border around each equipped item."] = "Farve på kanten om hver genstand du har på.",
	["Color of the breath bar when you are under water."] = "Farven på åndedrætsbjælken når du er under vand.",
	["Color of the buff bars."] = "Buffbjælkernes farve.",
	["Color of the buff squares."] = "Farve på buffkvadraterne.",
	["Color of the cast sweep."] = "Farven på castfyldet.",
	["Color of the charge or item count."] = "Farven på antallet af ladninger eller genstande.",
	["Color of the dark cooldown swipe."] = "Farven på den mørke cooldown-swipe.",
	["Color of the death timer bar, when the game shows one."] = "Farven på dødsnedtællingens bjælke når spillet viser en.",
	["Color of the fatigue bar in deep water."] = "Farven på udmattelsesbjælken i dybt vand.",
	["Color of the feign death bar."] = "Farven på Feign Death-bjælken.",
	["Color of the fifth combo point."] = "Farve på det femte combopoint.",
	["Color of the fill particles."] = "Farven på fyldpartiklerne.",
	["Color of the fill: the resource's own color (blue mana, red rage, yellow energy), your class color or one you pick."] = "Fyldets farve: ressourcens egen farve (blå mana, rød rage, gul energi), din klassefarve eller en du vælger.",
	["Color of the filled part."] = "Farven på den fyldte del.",
	["Color of the first combo point."] = "Farve på det første combopoint.",
	["Color of the flash and falling particles when a cast is interrupted."] = "Farven på blinket og de faldende partikler når et cast afbrydes.",
	["Color of the flash when a cast completes."] = "Farven på blinket når et cast fuldføres.",
	["Color of the flash."] = "Blinkets farve.",
	["Color of the flashing whisper tab."] = "Farve på den blinkende hviskefane.",
	["Color of the four bars."] = "Farven på de fire bjælker.",
	["Color of the fourth combo point."] = "Farve på det fjerde combopoint.",
	["Color of the keybind text (out of range may tint it, Buttons tab)."] = "Farve på genvejstastteksten (\"Uden for rækkevidde\" på fanen Knapper kan farve den).",
	["Color of the keybind text."] = "Genvejstasttekstens farve.",
	["Color of the labels (\"Dur\", \"Gold\" and so on)."] = "Farve på etiketterne (\"Holdb.\", \"Guld\" og så videre).",
	["Color of the mark when the buff's own icon isn't known."] = "Farve på mærket når buffens eget ikon ikke kendes.",
	["Color of the pull aggro line."] = "Farven på aggrogrænsen.",
	["Color of the ring and the GCD sweep."] = "Farven på ringen og GCD-fyldet.",
	["Color of the second combo point."] = "Farve på det andet combopoint.",
	["Color of the section titles."] = "Farve på afsnitstitlerne.",
	["Color of the shine."] = "Farven på glansen.",
	["Color of the slot item levels."] = "Farve på pladsernes item levels.",
	["Color of the spark and its trail."] = "Farven på gnisten og dens spor.",
	["Color of the spell cost overlay."] = "Farve på overlaget for evnens pris.",
	["Color of the text. Item quality fits loot, accent fits your own progress."] = "Tekstens farve. Genstandskvalitet passer til loot, accentfarve til dine egne fremskridt.",
	["Color of the third combo point."] = "Farve på det tredje combopoint.",
	["Color of the threshold lines."] = "Farve på tærskellinjerne.",
	["Color of the tick marks."] = "Farve på skalastregerne.",
	["Color of your own bar."] = "Farven på din egen bjælke.",
	["Color per bar"] = "Farve pr. bjælke",
	["Color per timer"] = "Farve pr. nedtælling",
	["Color range 1"] = "Farveinterval 1",
	["Color range 2"] = "Farveinterval 2",
	["Color range 3"] = "Farveinterval 3",
	["Color ranges"] = "Farveintervaller",
	["Color ranges and tick marks go on the power bar. Turn the power bar on (Bars tab) to use them."] = "Farveintervaller og skalastreger sidder på ressourcebjælken. Slå ressourcebjælken til (fanen Bjælker) for at bruge dem.",
	["Color the bars by magic, curse, disease, poison or bleed (the game picks the color), or use the accent color."] = "Farv bjælkerne efter magi, forbandelse, sygdom, gift eller blødning (spillet vælger farven), eller brug accentfarven.",
	["Color the icon while you can't cast it, like action buttons without enough mana."] = "Farv ikonet mens du ikke kan caste det, ligesom handlingsknapper uden nok mana.",
	["Color the pet bar border by the happiness the game reports for your pet (green, yellow, red)."] = "Farv petlinjens kant efter den tilfredshed som spillet rapporterer for dit pet (grøn, gul, rød).",
	["Color when full"] = "Farve når fuld",
	["Color while the target is out of range."] = "Farve mens målet er uden for rækkevidde.",
	["Color-blind safe pieces, lines between cells, creature models and the time left on the box."] = "Farveblind-sikre brikker, streger mellem felterne, væsenmodeller og tiden der er tilbage på boksen.",
	["Colored corner"] = "Farvet hjørne",
	["Colored dots"] = "Farvede prikker",
	["Colored squares"] = "Farvede kvadrater",
	["Colors damage by its magic school when the game says which school it was."] = "Farver skade efter dens magiske skole når spillet oplyser hvilken skole det var.",
	["Colors the slot border with the game's item quality color."] = "Farver pladsens kant med spillets kvalitetsfarve for genstanden.",
	["Column and group headers in a dark tint of the accent color."] = "Kolonne- og gruppeoverskrifter i en mørk nuance af accentfarven.",
	["Columns (or rows) at most. With 5 units per column and Group sorting this is the number of groups side by side."] = "Det højeste antal kolonner (eller rækker). Med 5 enheder pr. kolonne og sortering efter gruppe er det antallet af grupper side om side.",
	["Columns first"] = "Kolonner først",
	["Combat Text"] = "Kamptekst",
	["Combat text in the theme font (or the font below)."] = "Kamptekst i temaets skrifttype (eller skrifttypen nedenfor).",
	["Combat Text: %s"] = "Kamptekst: %s",
	["Combat time"] = "Kamptid",
	["Combat Timer"] = "Kampur",
	["Combat timer"] = "Kampur",
	["Combo points for rogues and druids in cat form. Turn off to keep only Blizzard's."] = "Combopoints for Rogues og for Druids i Cat Form. Slå fra for kun at beholde Blizzards.",
	["Combo points full"] = "Fulde combopoints",
	["Combo points, energy or rage, and your mana always below them as a second bar, e.g. a feral druid."] = "Combopoints, energi eller rage, og din mana altid under dem som en ekstra bjælke, fx til en feral Druid.",
	["Comma-separated names that stay plain, for example names that are also common words."] = "Kommaseparerede navne der forbliver uden farve, fx navne der også er almindelige ord.",
	["Common"] = "Common",
	["common"] = "Common",
	["Community guides, release %s."] = "Fællesskabets guides, udgave %s.",
	["Community leveling guides for Eldostar: the one in use, the next one and every guide for your character."] = "Fællesskabets levelingguides til Eldostar: den der er i brug, den næste og alle guides til din karakter.",
	["Community leveling guides, step by step in the Eldostar window."] = "Fællesskabets levelingguides, trin for trin i Eldostar-vinduet.",
	["Compact bar"] = "Kompakt linje",
	["Compact boxes for EldoUI's frames inside Edit Mode, without names, labels or side panel."] = "Kompakte bokse til EldoUI's rammer i Edit Mode uden navne, mærker eller sidepanel.",
	["Compact boxes, no snapping, 1-pixel nudges: place every EldoUI frame by hand."] = "Kompakte bokse, ingen fastgørelse, skub på 1 pixel: placer hver EldoUI-ramme i hånden.",
	["Compact see-through EldoUI frame around a 360 x 180 Details window."] = "Kompakt gennemsigtig EldoUI-ramme om et Details-vindue på 360 x 180.",
	["Compact view"] = "Kompakt visning",
	["Complete %s"] = "Gennemfør %s",
	["Complete quest"] = "Fuldfør quest",
	["Completed by"] = "Fuldført af",
	["Conflicts"] = "Konflikter",
	["Conjure a mana gem to fill this button."] = "Fremman en mana gem for at fylde denne knap.",
	["Conjured first"] = "Fremmanet først",
	["Constants.LegacyConsts: faction %s, currency %s, trees %s / %s / %s"] = "Constants.LegacyConsts: fraktion %s, valuta %s, træer %s / %s / %s",
	["Constants.LegacyConsts: missing. This client has no Legacy system."] = "Constants.LegacyConsts: mangler. Denne klient har intet Legacy-system.",
	["Consumable Bar"] = "Forbrugslinje",
	["Consumables"] = "Forbrugsvarer",
	["Content filters"] = "Indholdsfiltre",
	["Cook"] = "Cook",
	["Cooking skill."] = "Skill i Cooking.",
	["Cooldown"] = "Cooldown",
	["Cooldown Group %d"] = "Cooldown-gruppe %d",
	["Cooldown Icon: %s"] = "Cooldownikon: %s",
	["Cooldown Pulse"] = "Cooldown-puls",
	["Cooldown ready"] = "Cooldown klar",
	["Cooldown row icons glow while their spell's buff is on you or its debuff is on your target, as the game reports it. Off by default."] = "Ikoner i cooldownrækker gløder mens deres evnes buff er på dig eller dens debuff er på dit mål, efter hvad spillet melder. Slået fra som standard.",
	["Cooldown rows: aura active"] = "Cooldownrækker: aura aktiv",
	["Cooldown rows: proc"] = "Cooldownrækker: proc",
	["Cooldown rows: ready"] = "Cooldownrækker: klar",
	["Cooldown swipe (all rows)"] = "Cooldown-swipe (alle rækker)",
	["Cooldown swipe with numbers on the icon and a thin time bar under it."] = "Cooldown-swipe med tal på ikonet og en tynd tidsbjælke under det.",
	["Cooldowns"] = "Cooldowns",
	["Cooldowns shorter than this in total (seconds) show no numbers, so the global cooldown stays quiet. The game checks the length; EldoUI never reads it."] = "Cooldowns der i alt er kortere end dette (sekunder), viser ingen tal, så den globale cooldown forbliver stille. Spillet tjekker længden; EldoUI læser den aldrig.",
	["Cooldowns: Buff Bars"] = "Cooldowns: buffbjælker",
	["Cooldowns: Buff Icons"] = "Cooldowns: buffikoner",
	["Cooldowns: Essential"] = "Cooldowns: essentielle",
	["Cooldowns: Items"] = "Cooldowns: genstande",
	["Cooldowns: Mobility"] = "Cooldowns: mobilitet",
	["Cooldowns: Trinkets"] = "Cooldowns: trinkets",
	["Cooldowns: Utility"] = "Cooldowns: Utility",
	["Coordinate precision"] = "Koordinatpræcision",
	["Copied!"] = "Kopieret!",
	["Copies another area's look onto this one, with a preview of what changes first. Its name, on/off switch and position stay."] = "Kopierer et andet områdes udseende over på dette med en forhåndsvisning af ændringerne først. Navn, til/fra-knap og placering bevares.",
	["Copies every setting of another bar to this one after a preview, or applies this bar's settings to all bars. Its switch and position stay. Right-click a row to set only that row everywhere."] = "Kopierer alle indstillinger fra en anden linje til denne efter en forhåndsvisning, eller anvender denne linjes indstillinger på alle linjer. Dens kontakt og placering bevares. Højreklik på en række for kun at sætte den række overalt.",
	["Copies the selected profile into the draft. Your Legacy points don't change."] = "Kopierer den valgte profil ind i kladden. Dine Legacy-point ændres ikke.",
	["Copy a suggested route on the Map tab, or import a route string someone shared."] = "Kopier en foreslået rute på fanen Kort, eller importer en rutestreng som andre har delt.",
	["Copy as my route"] = "Kopier som min rute",
	["Copy as my route to change labels and colors"] = "Kopier som min rute for at ændre etiketter og farver",
	["Copy bindings"] = "Kopier bindinger",
	["Copy button"] = "Kopier-knap",
	["Copy chat"] = "Kopier chat",
	["Copy line"] = "Kopier linje",
	["Copy link"] = "Kopier link",
	["Copy link (to insert it, open the chat first)"] = "Kopier link (åbn chatten først for at indsætte det)",
	["Copy list"] = "Kopier liste",
	["Copy matches to an Alerts tab"] = "Kopier match til en Alerts-fane",
	["Copy my build"] = "Kopier mit build",
	["Copy results"] = "Kopier resultater",
	["Copy right panel"] = "Kopier højre panel",
	["Copy search results"] = "Kopier søgeresultater",
	["Copy the class list"] = "Kopier klasselisten",
	["Copy the look of another bar onto this one (size, colors, texture, icon, text, stacks), with a preview of what changes first. What it tracks and its switch stay as they are."] = "Kopier udseendet fra en anden bjælke over på denne (størrelse, farver, tekstur, ikon, tekst, stakke), med en forhåndsvisning af ændringerne først. Det den sporer, og dens til/fra-knap bevares.",
	["Copy the look of another group onto this one (icons or bars, size, growth, timers, missing auras), with a preview of what changes first. Its name, switch, unit, spells and visibility stay as they are."] = "Kopier udseendet fra en anden gruppe over på denne (ikoner eller bjælker, størrelse, vækstretning, nedtællinger, manglende auraer) med en forhåndsvisning af ændringerne først. Navn, kontakt, enhed, evner og synlighed forbliver som de er.",
	["Copy the other talent group"] = "Kopier den anden talentgruppe",
	["Copy the size, growth, bars, texts, icons and auras of another section onto this one, with a preview of what changes first. On/off, raid size and who is listed stay as they are."] = "Kopier størrelse, vækstretning, bjælker, tekster, ikoner og auraer fra et andet afsnit over på dette med en forhåndsvisning af ændringerne først. Til/fra, raidstørrelse og hvem der vises, forbliver som de er.",
	["Copy the slots, look and place of another panel onto this one, with a preview of what changes first. Its name, Shown switch and position stay as they are."] = "Kopier pladserne, udseendet og placeringen fra et andet panel over på dette, og se først en forhåndsvisning af ændringerne. Dets navn, kontakten Vist og placeringen forbliver som de er.",
	["Copy this run as one line of text."] = "Kopier dette run som én linje tekst.",
	["Copy this string and give it to a friend. They paste it in /eui import."] = "Kopier denne streng, og giv den til en ven. Vennen indsætter den i /eui import.",
	["Copy this trigger."] = "Kopier denne udløser.",
	["Copy to the search box"] = "Kopier til søgefeltet",
