	["Corner or edge the icons start from, or one row under the frame (leave room with Spacing)."] = "Det hjørne eller den kant ikonerne starter fra, eller én række under rammen (giv plads med Afstand).",
	["Corner the first button sits in and the direction the rest follow."] = "Hjørnet som den første knap sidder i, og retningen som resten følger.",
