	["Counts your dungeon entries against the hourly limit (5 per hour, shared by your characters) and logs every run. The count is an estimate."] = "Tæller dine dungeonbesøg op mod grænsen pr. time (5 pr. time, delt mellem dine karakterer) og logger hvert run. Tællingen er et skøn.",
