	["DBM and BigWigs"] = "DBM og BigWigs",
	["DBM bar opacity"] = "Opacitet for DBM-bjælker",
	["DBM did not switch to the EldoUI profile; nothing was changed."] = "DBM skiftede ikke til EldoUI-profilen; intet blev ændret.",
	["DBM does not accept the EldoUI font on this client; DBM keeps its own font."] = "DBM accepterer ikke EldoUI-skrifttypen på denne klient; DBM beholder sin egen skrifttype.",
	["DBM is set up when the fight is over."] = "DBM sættes op når kampen er slut.",
	["DBM is still loading"] = "DBM indlæses stadig",
	["DBM is still loading. Try again in a moment."] = "DBM indlæses stadig. Prøv igen om et øjeblik.",
	["DBM keeps its own look and chat; EldoUI only places its frames with the layout."] = "DBM beholder sit eget udseende og sin egen chat; EldoUI placerer kun dens rammer efter layoutet.",
	["DBM only"] = "Kun DBM",
	["DBM stops copying warnings into chat and flashes the screen only for urgent ones (move, run away). Cast alerts stay on. Off puts DBM's own values back."] = "DBM holder op med at kopiere advarsler til chatten og blinker kun skærmen ved de akutte (flyt dig, løb væk). Cast-advarsler forbliver slået til. Fra: DBM's egne værdier kommer tilbage.",
	["DBM uses the profile %s now. Your own profile (%s) is kept: switch back any time on this page or with /eui dbm undo."] = "DBM bruger nu profilen %s. Din egen profil (%s) bevares: skift tilbage når som helst på denne side eller med /eui dbm undo.",
	["DBM uses the profile you had before the setup again. The EldoUI profiles stay in DBM's list, so setting up again is one click."] = "DBM bruger igen den profil du havde før opsætningen. EldoUI-profilerne bliver i DBM's liste, så det kun kræver ét klik at sætte op igen.",
	["DBM uses your profile %s again. The EldoUI profiles are kept for later."] = "DBM bruger igen din profil %s. EldoUI-profilerne gemmes til senere.",
	["DBM's timers, warnings and info frame follow the layout's boss mod spots while its EldoUI profile is in use. Unchecked, DBM keeps its own spots."] = "DBM's timere, advarsler og infoboks følger layoutets pladser til bossmods mens DBM's EldoUI-profil er i brug. Uden flueben beholder DBM sine egne pladser.",
	["DBM's timers, warnings, info and range frames go to your layout's boss-mod movers, again after each layout click or drag (never during a fight)."] = "DBM's nedtællinger, advarsler, info- og rækkevidderammer flyttes til dit layouts bossmod-flyttefelter, og det sker igen efter hvert layoutvalg eller træk (aldrig under en kamp).",
	["DBM's version, the DBM profile in use and what EldoUI does with it."] = "DBM's version, den aktive DBM-profil og hvad EldoUI gør med den.",
	["DBM-PvP is loaded and shows its own capture and score bars, so these bars stand back; queue and start bars stay. Turn this on to show them anyway."] = "DBM-PvP er indlæst og viser sine egne bjælker for erobringer og stilling, så disse bjælker træder tilbage; kø- og startbjælkerne vises stadig. Slå dette til for at vise dem alligevel.",
	["Deadly Boss Mods"] = "Deadly Boss Mods",
	["Deadly Boss Mods is not loaded"] = "Deadly Boss Mods er ikke indlæst",
	["Deadly Boss Mods is not loaded."] = "Deadly Boss Mods er ikke indlæst.",
	["Deadly Boss Mods with an EldoUI touch: its own DBM profile per layout, timers and warnings placed by the layout, the EldoUI look and quiet chat. Your DBM profile, sounds and boss settings stay yours."] = "Deadly Boss Mods med et EldoUI-præg: en egen DBM-profil pr. layout, nedtællinger og advarsler placeret af layoutet, EldoUI-udseendet og stille chat. Din DBM-profil, dine lyde og dine bossindstillinger forbliver dine.",
