	["Disenchanter"] = "Disenchanter",
	["Disenchanting"] = "Disenchanting",
	["Dismiss"] = "Afvis",
	["Dispellable debuff highlight"] = "Fremhævning af debuffs der kan dispelles",
	["Distance"] = "Afstand",
	["Distance %d, gold %d"] = "Afstand %d, guld %d",
	["Do this step"] = "Klar dette trin",
	["dock"] = "dock",
	["Dock"] = "Dokning",
	["Docked panels take the width of the chat window (right of its side buttons) or of the minimap."] = "Dokkede paneler får samme bredde som chatvinduet (til højre for dets sideknapper) eller minikortet.",
	["Dodge"] = "Dodge",
	["Dodge, parry, miss"] = "Dodge, parry, miss",
	["Does not stack with %s"] = "Stakker ikke med %s",
	["Don't record this character"] = "Registrer ikke denne karakter",
	["Don't show on flights"] = "Vis ikke under flyvning",
	["Don't Stand in the Fire"] = "Stå ikke i ilden",
	["done"] = "færdig",
	["Done %s"] = "Fuldført %s",
	["Done on the route card."] = "Markeret som færdig på rutekortet.",
	["Dot"] = "Prik",
	["Dot size"] = "Prikstørrelse",
	["Dots"] = "Prikker",
	["Double right-click casts"] = "Dobbelt højreklik kaster snøren",
	["Double-click"] = "Dobbeltklik",
	["Down (columns)"] = "Ned (kolonner)",
	["Down (newest at the top)"] = "Ned (nyeste øverst)",
	["Download / upload"] = "Download/upload",
	["DPS (damage meter)"] = "DPS (skademåler)",
	["draft %d"] = "kladde %d",
	["Drag a spell or macro onto the text box, or type a spell name. Macro text starts with /, for example /cast [@mouseover] Renew. Right-click the action button to go back. The game's own Click Casting wins on the same click."] = "Træk en evne eller makro hen på tekstfeltet, eller skriv navnet på en evne. Makrotekst starter med /, for eksempel /cast [@mouseover] Renew. Højreklik på handlingsknappen for at bladre baglæns. Spillets eget klikkast har forrang ved samme klik.",
	["Drag handles in move mode"] = "Trækhåndtag i flyttetilstand",
	["Drag icons between groups, or onto empty screen as free icons."] = "Træk ikoner mellem grupper eller ud på tom skærm som frie ikoner.",
	["Drag the big text where you want it."] = "Træk den store tekst derhen hvor du vil have den.",
	["Drag to change the area's width and height. The opposite corner stays put."] = "Træk for at ændre områdets bredde og højde. Det modsatte hjørne bliver hvor det er.",
	["Drag to move. Right-click resets it to the layout position."] = "Træk for at flytte. Højreklik nulstiller den til layoutets placering.",
	["Dragging, the mouse wheel scale and the reset of the character window are on the Move windows page, with every other Blizzard window."] = "Du kan trække, skalere med musehjulet og nulstille karaktervinduet på siden Flyt vinduer, ligesom alle andre Blizzard-vinduer.",
	["Drake"] = "Drake",
	["Draw"] = "Tegn",
	["Draw a background behind the panel. Off leaves only the text, which can be hard to read on a bright minimap."] = "Tegn en baggrund bag panelet. Slået fra ses kun teksten, og den kan være svær at læse på et lyst minikort.",
	["Draw a bright edge along the cooldown swipe."] = "Tegn en lys kant langs cooldownens swipe.",
	["Draw an EldoUI panel behind the bar."] = "Tegn et EldoUI-panel bag linjen.",
	["Draw one"] = "Træk ét",
	["Draw the bar's dark background and border. Off leaves only the text."] = "Tegn bjælkens mørke baggrund og kant. Slået fra ses kun teksten.",
	["Draw the packs and the picked route on the Loot Guide's dungeon map too. Its own boss markers stay."] = "Tegn også packs og den valgte rute på Loot Guides dungeonkort. Dets egne bossmarkører bevares.",
	["Draw the path of each patrolling pack as a thin line."] = "Tegn patruljeruten for hver pack som en tynd linje.",
	["Draw the thin border around the panel."] = "Tegn den tynde kant rundt om panelet.",
	["Draw three"] = "Træk tre",
	["Drawn by"] = "Tegnet af",
	["Draws an EldoUI panel (art style, border and colors from the General page) around the Details windows."] = "Tegner et EldoUI-panel (grafikstil, kant og farver fra siden Generelt) om Details-vinduerne.",
	["Drink"] = "Drikke",
	["Drink, mana potion, health potion and healthstone, potions first."] = "Drikke, mana potion, health potion og Healthstone, potions først.",
	["Drop Alliance banners against the Horde; four in a row wins."] = "Slip Alliancens bannere mod Horden; fire på stribe vinder.",
	["Drop an item on the section's title in the bag window."] = "Slip en genstand på afsnittets titel i taskevinduet.",
	["Drop the EldoUI positions saved for Edit Mode layouts; the current positions stay."] = "Fjern EldoUI-placeringerne gemt til Edit Mode-layouts; de nuværende placeringer bevares.",
	["Druid mana"] = "Druid-mana",
	["Druid mana bar height."] = "Højde på Druid-manabjælken.",
	["Druid mana in forms"] = "Druid-mana i dyreformer",
	["Druid or Primalist"] = "Druid eller Primalist",
	["DUEL"] = "DUEL",
	["Duel declined"] = "Duel afvist",
	["Duel request"] = "Duelanmodning",
	["Duel requests from members of muted guilds are declined, and one chat line names who and which guild. Not in combat. This acts for you. Off by default."] = "Duelanmodninger fra medlemmer af dæmpede guilds afvises, og en chatlinje nævner hvem og hvilken guild. Ikke i kamp. Dette handler på dine vegne. Slået fra som standard.",
	["Dungeon"] = "Dungeon",
	["Dungeon boss"] = "Dungeonboss",
	["Dungeon data could not load"] = "Dungeondataene kunne ikke indlæses",
	["Dungeon data is not installed"] = "Dungeondataene er ikke installeret",
	["Dungeon data is switched off"] = "Dungeondataene er slået fra",
	["Dungeon data is too old"] = "Dungeondataene er for gamle",
	["Dungeon data loads out of combat"] = "Dungeondataene indlæses uden for kamp",
	["Dungeon difficulty"] = "Sværhedsgrad for dungeons",
	["Dungeon entered"] = "Gik ind i dungeon",
	["Dungeon map on the world map"] = "Dungeonkort på verdenskortet",
	["Dungeon route"] = "Dungeonrute",
	["Dungeon route: %s"] = "Dungeonrute: %s",
	["Dungeon routes"] = "Dungeonruter",
	["Dungeon Routes"] = "Dungeonruter",
	["Dungeon Routes: \"%s\" added to %s."] = "Dungeonruter: \"%s\" føjet til %s.",
	["Dungeon Routes: no dungeon called \"%s\"."] = "Dungeonruter: intet dungeon hedder \"%s\".",
	["Dungeon Routes: the route was not added (%s)."] = "Dungeonruter: ruten blev ikke tilføjet (%s).",
	["Dungeon Routes: there is no such route to export."] = "Dungeonruter: der er ingen sådan rute at eksportere.",
	["Dungeon runs. These count toward the hourly limit."] = "Dungeonruns. De tæller med i grænsen pr. time.",
	["Dungeons window"] = "Dungeonvinduet",
	["Duplicate"] = "Dupliker",
	["Dur"] = "Holdb.",
	["Dur."] = "Holdb.",
	["Durability"] = "Holdbarhed",
	["Durability colors"] = "Farver for holdbarhed",
	["Durability of the equipped gear (average)."] = "Holdbarhed på det udstyr der er taget på (gennemsnit).",
	["Duration"] = "Varighed",
	["Durations"] = "Varigheder",
	["During which festival do the innkeepers hand out treats?"] = "Under hvilken festival deler kroværterne godter ud?",
	["During which festival do you honor the elders with coins of ancestry?"] = "Under hvilken festival ærer du de ældste med forfædremønter?",
	["During which festival does Greatfather Winter visit?"] = "Under hvilken festival kommer Greatfather Winter på besøg?",
	["Durotar is named after which orc?"] = "Hvilken ork er Durotar opkaldt efter?",
	["Dwarven Crates"] = "Dværgens kasser",
	["e.g. t:herb or q>=rare"] = "f.eks. t:herb eller q>=rare",
	["Each aura as a timer bar with its name and time, one under the other."] = "Hver aura som en tidsbjælke med navn og tid, den ene under den anden.",
	["Each bar follows one spell: an aura's time or stacks, a cooldown or charges. Aura bars work for your buffs and your debuffs on enemies."] = "Hver bjælke følger én evne: en auras tid eller stakke, en cooldown eller ladninger. Aurabjælker virker for dine buffs og dine debuffs på fjender.",
	["Each button holds an item of its kind from your bags; click to use, right-click to pick one. Buttons change only out of combat."] = "Hver knap rummer en genstand af sin type fra dine tasker; klik for at bruge den, højreklik for at vælge en. Knapperne skifter kun uden for kamp.",
	["Each character keeps one point per day from now on, and the gold at each level-up from the level log."] = "Hver karakter gemmer fra nu af ét punkt pr. dag samt guldet ved hvert nyt level fra levelloggen.",
	["Each character records its level, gold, gear, bags, professions, quests and lockouts when you log in. Open the Alts window with /eui alts."] = "Hver karakter registrerer sit level, guld, udstyr, tasker, fag, quests og lockouts når du logger ind. Åbn Alts-vinduet med /eui alts.",
	["Each character records itself when you log in on it. Right-click a character for groups, bank marks and Forget. Values with ~ are estimates for characters that are offline."] = "Hver karakter registrerer sig selv når du logger ind på den. Højreklik på en karakter for grupper, bankmærker og Glem. Værdier med ~ er estimater for karakterer der er offline.",
	["Each character's bags, bank, gear, mail and gold are kept. Search with words or filters (q:rare, ilvl>50); /eui find searches them all."] = "Hver karakters tasker, bank, udstyr, post og guld gemmes. Søg med ord eller filtre (q:rare, ilvl>50); /eui find søger i dem alle.",
	["Each character: quests in the log, ready to turn in, dailies since the daily reset, completed quests."] = "Hver karakter: quests i loggen, klar til aflevering, dailies siden det daglige reset og fuldførte quests.",
	["Each Edit Mode layout keeps its own EldoUI frame positions."] = "Hvert Edit Mode-layout beholder sine egne placeringer af EldoUI-rammer.",
	["Each Edit Mode layout keeps its own EldoUI frame positions. Switching layouts in Edit Mode moves EldoUI's frames too."] = "Hvert Edit Mode-layout beholder sine egne placeringer af EldoUI-rammer. Skifter du layout i Edit Mode, flyttes EldoUI's rammer også.",
	["Each level a character gained: when, where, how long it took, kills and quests."] = "Hvert level en karakter har opnået: tidspunkt, sted, varighed, drab og quests.",
	["Each level-up from now on adds a row: the time, zone, how long the level took, kills and quests."] = "Hvert nyt level fra nu af tilføjer en række: tidspunkt, zone, levelets varighed, drab og quests.",
	["Each mark shows only what the game reports for the item; with all of them off the rows show the name alone."] = "Hvert mærke viser kun hvad spillet oplyser om genstanden; når alle er slået fra, viser rækkerne kun navnet.",
	["Each panel group gets the EldoUI panel, flat bars and accent headers."] = "Hver panelgruppe får EldoUI-panelet, flade bjælker og overskrifter i accentfarve.",
	["Each particle gets a color between this and the second color."] = "Hver partikel får en farve mellem denne og den anden farve.",
	["Each section keeps its own out-of-range opacity (Bars, on its tab)."] = "Hvert afsnit beholder sin egen opacitet uden for rækkevidde (Bjælker, på sin fane).",
	["Each slot's item and item level per character, as of its last login."] = "Genstand og item level i hver plads pr. karakter, fra dens seneste login.",
	["Each talent group (dual spec) keeps its own list. A talent group starts as a copy of your class list; the class list itself stays saved and comes back when this is off."] = "Hver talentgruppe (dual spec) har sin egen liste. En talentgruppe starter som en kopi af din klasseliste; selve klasselisten forbliver gemt og kommer tilbage når indstillingen er slået fra.",
	["Each talent group keeps its own groups, free icons and free icon spots. The icon looks stay shared."] = "Hver talentgruppe beholder sine egne grupper, frie ikoner og pladser til frie ikoner. Ikonernes udseende forbliver fælles.",
	["Each touch turns a brazier and its neighbors; light them all."] = "Hvert tryk vender et fyrfad og dets naboer; tænd dem alle.",
	["Earn %s"] = "Opnå %s",
	["Eastern Kingdoms"] = "Eastern Kingdoms",
	["Easy"] = "Let",
	["Eat, grow and keep clear of the walls and your tail."] = "Spis, voks og hold dig fri af væggene og din hale.",
	["Edge color"] = "Kantfarve",
	["Edge only"] = "Kun kant",
	["Edge particles"] = "Kantpartikler",
	["Edit bindings"] = "Rediger bindinger",
	["edit box"] = "tekstfelt",
	["Edit box height"] = "Tekstfeltets højde",
	["Edit box position"] = "Tekstfeltets placering",
	["Edit box text size"] = "Tekststørrelse i tekstfeltet",
	["Edit categories"] = "Rediger kategorier",
	["Edit category"] = "Rediger kategori",
	["Edit chat colors"] = "Rediger chatfarver",
	["Edit keywords"] = "Rediger nøgleord",
	["Edit Mode"] = "Edit Mode",
	["Edit Mode and EldoUI agree: no frame is placed by both."] = "Edit Mode og EldoUI er enige: ingen ramme placeres af begge.",
	["Edit Mode brings EldoUI's move tools along, so Blizzard's and EldoUI's frames are placed in one go. /eui move has the same tools."] = "Edit Mode tager EldoUI's flytteværktøjer med, så Blizzards og EldoUI's rammer placeres i én omgang. /eui move har de samme værktøjer.",
	["Edit Mode layout %s: EldoUI frames moved to their spots for it."] = "Edit Mode-layout %s: EldoUI-rammerne er flyttet til deres pladser i layoutet.",
	["Edit opens the editor: click packs to add or take out pulls, drag pulls in the list, write notes and draw arrows or lines on the map. Send to group shares a route with your party with one click."] = "Rediger åbner editoren: klik på packs for at tilføje eller fjerne pulls, træk pulls i listen, skriv noter, og tegn pile eller linjer på kortet. Send til gruppen deler en rute med din gruppe med ét klik.",
	["Edit panel"] = "Rediger panel",
	["Edit the list"] = "Rediger listen",
	["Edit the list of guilds whose members' lines are hidden (up to 50). Also right-click a player and pick Mute their guild, or /eui chatguild."] = "Rediger listen over guilds hvis medlemmers linjer skjules (op til 50). Du kan også højreklikke på en spiller og vælge Dæmp deres guild eller bruge /eui chatguild.",
	["Edit the list of words and phrases that hide a line (up to 50), and test a line against it. Also /eui chat filters."] = "Rediger listen over ord og fraser der skjuler en linje (op til 50), og test en linje mod den. Også /eui chat filters.",
	["Effects on other targets"] = "Effekter på andre mål",
	["Effects on your target"] = "Effekter på dit mål",
	["Eight flat action bars, pet and stance bars, cooldown numbers, proc glow and fade rules."] = "Otte flade handlingslinjer, pet- og stance-linjer, cooldowntal, procglød og toningsregler.",
	["Eldostar"] = "Eldostar",
	["Eldostar guide"] = "Eldostar-guide",
	["Eldostar is switched off on the Modules page, so no guide shows."] = "Eldostar er slået fra på siden Moduler, så ingen guide vises.",
	["Eldostar is your guide."] = "Eldostar er din guide.",
	["Eldostar is your guide. RestedXP stays on and keeps its own spot: EldoUI does not place it."] = "Eldostar er din guide. RestedXP forbliver slået til og beholder sin egen plads: EldoUI placerer den ikke.",
	["Eldostar, EldoUI's own guide window."] = "Eldostar, EldoUI's eget guidevindue.",
	["EldoUI accent pulse"] = "EldoUI-accentpuls",
	["EldoUI actions"] = "EldoUI-handlinger",
	["EldoUI and Edit Mode"] = "EldoUI og Edit Mode",
	["EldoUI bar"] = "EldoUI-linje",
	["EldoUI bar style"] = "EldoUI-bjælkestil",
	["EldoUI bar: the pet bar buttons in an EldoUI frame you can move, resize and fade (needs the Replace switch). Blizzard's bar: left as it is. Hidden: needs the Hide switch."] = "EldoUI-linje: petlinjens knapper i en EldoUI-ramme som du kan flytte, ændre størrelse på og tone ud (kræver Erstat-kontakten). Blizzards linje: bliver som den er. Skjult: kræver Skjul-kontakten.",
	["EldoUI bar: the stance bar buttons in an EldoUI frame you can move, resize and fade (needs the Replace switch). Blizzard's bar: left as it is. Hidden: needs the Hide switch."] = "EldoUI-linje: stance-linjens knapper i en EldoUI-ramme som du kan flytte, ændre størrelse på og tone ud (kræver Erstat-kontakten). Blizzards linje: bliver som den er. Skjult: kræver Skjul-kontakten.",
	["EldoUI buffs"] = "EldoUI-buffs",
	["EldoUI Cancel Undercut"] = "EldoUI Annuller undercut",
	["EldoUI changes Blizzard's party and raid frames only as allowed on the Blizzard UI page. Off there keeps them as Blizzard made them."] = "EldoUI ændrer kun Blizzards gruppe- og raidrammer som tilladt på Blizzard-UI-siden. Er den slået fra dér, forbliver de som Blizzard lavede dem.",
	["EldoUI changes it"] = "EldoUI ændrer den",
	["EldoUI combo points"] = "EldoUI-combopoints",
	["EldoUI command"] = "EldoUI-kommando",
	["EldoUI cooldown text"] = "EldoUI's cooldowntekst",
	["EldoUI could not move a spell rank on your action bars and stops upgrading them automatically until you log in again."] = "EldoUI kunne ikke flytte en evnerang på dine handlingslinjer og holder op med at opgradere dem automatisk indtil du logger ind igen.",
	["EldoUI debuffs"] = "EldoUI-debuffs",
	["EldoUI Fishing"] = "EldoUI Fiskeri",
	["EldoUI font, bar texture, 1 px border, backdrop and accent on DBM's timer bars, and the EldoUI font on warnings and the info frame. Off: DBM's own look comes back."] = "EldoUI-skrifttype, bjælketekstur, 1 px kant, baggrund og accent på DBM's tidsbjælker og EldoUI-skrifttypen på advarsler og inforammen. Fra: DBM's eget udseende kommer tilbage.",
	["EldoUI format"] = "EldoUI-format",
	["EldoUI format: seconds, minutes and hours with colors and tenths at the end. Game setting: follows Options > Action Bars > Show cooldown numbers. Off: no numbers."] = "EldoUI-format: sekunder, minutter og timer med farver og tiendedele til sidst. Spillets indstilling: følger Options > Action Bars > Show cooldown numbers. Fra: ingen tal.",
	["EldoUI frame"] = "EldoUI-ramme",
	["EldoUI frames"] = "EldoUI-rammer",
	["EldoUI handles this viewer"] = "EldoUI håndterer denne visning",
	["EldoUI has no map for this place yet. The pulls of its route are listed on the right."] = "EldoUI har endnu intet kort over dette sted. Rutens pulls står i listen til højre.",
	["EldoUI has no record of Guidelime's earlier spot, so the window stays where it is. Guidelime's own Reset position button moves it."] = "EldoUI har ingen registrering af Guidelimes tidligere placering, så vinduet bliver hvor det er. Guidelimes egen knap Reset position flytter det.",
	["EldoUI has nothing to undo here."] = "EldoUI har intet at fortryde her.",
	["EldoUI hides or replaces:"] = "EldoUI skjuler eller erstatter:",
	["EldoUI holds none of your camera settings."] = "EldoUI styrer ingen af dine kameraindstillinger.",
	["EldoUI layout"] = "EldoUI-layout",
	["EldoUI leaves Details, RestedXP, BigWigs and Questie exactly as they are."] = "EldoUI lader Details, RestedXP, BigWigs og Questie være præcis som de er.",
	["EldoUI line"] = "EldoUI-linje",
	["EldoUI look"] = "EldoUI-udseende",
	["EldoUI look for the character window"] = "EldoUI-udseende til karaktervinduet",
	["EldoUI look on DBM's bars and texts; DBM keeps its own positions."] = "EldoUI-udseende på DBM's bjælker og tekster; DBM beholder sine egne placeringer.",
	["EldoUI look: flat bars, theme font and texture, a see-through box behind each window."] = "EldoUI-udseende: flade bjælker, temaskrifttype og -tekstur, en gennemsigtig boks bag hvert vindue.",
	["EldoUI look: font, bar texture, 1 px border, backdrop and accent"] = "EldoUI-udseende: skrifttype, bjælketekstur, 1 px kant, baggrund og accent",
	["EldoUI module"] = "EldoUI-modul",
	["EldoUI mover"] = "EldoUI-flyttefelt",
	["EldoUI movers, attach points and the icon grid below. Off keeps Blizzard's Edit Mode position and layout."] = "EldoUI-flyttefelter, tilknytningspunkter og ikongitteret nedenfor. Fra: Blizzards placering og layout fra Edit Mode bevares.",
	["EldoUI never changes DBM's sounds, voices, comms, raid icons, pull timer or boss settings. Timer area sizes are on the Integrations page."] = "EldoUI ændrer aldrig DBM's lyde, stemmer, kommunikation, raidikoner, pull-nedtælling eller bossindstillinger. Størrelserne på nedtællingsområderne findes på siden Integrationer.",
	["EldoUI never releases your spirit for you: the buttons only work when you click them. The death popup is skinned with the dialogs."] = "EldoUI trykker aldrig på Release Spirit for dig: knapperne virker kun når du selv klikker på dem. Pop op-vinduet ved død får skin sammen med dialogerne.",
	["EldoUI options"] = "EldoUI-indstillinger",
	["EldoUI panel for the death recap, flat ghost button."] = "EldoUI-panel til dødsoversigten, flad spøgelsesknap.",
	["EldoUI panel next to Edit Mode"] = "EldoUI-panel ved siden af Edit Mode",
	["EldoUI places this"] = "EldoUI placerer denne",
	["EldoUI places:"] = "EldoUI placerer:",
	["EldoUI Quick Sell"] = "EldoUI Hurtigt salg",
	["EldoUI sets nothing in its DBM profile; switch back to your own profile on this page."] = "EldoUI sætter intet i sin DBM-profil; skift tilbage til din egen profil på denne side.",
	["EldoUI settings page"] = "EldoUI-indstillingsside",
	["EldoUI settings re-applied to the DBM profile %s (%d settings)."] = "EldoUI-indstillinger anvendt igen på DBM-profilen %s (%d indstillinger).",
	["EldoUI Shopping List"] = "EldoUI Indkøbsliste",
	["EldoUI shows \"Name the Title\" and the level, specialization and class in class color, all as the game reports them."] = "EldoUI viser navnet med titel samt level, spec og klasse i klassefarve, alt sammen som spillet angiver det.",
	["EldoUI shows your combat text now. Hide Blizzard's own text around your character? Your damage numbers over enemies stay."] = "EldoUI viser nu din kamptekst. Vil du skjule Blizzards egen tekst omkring din karakter? Dine skadetal over fjender bevares.",
	["EldoUI skin"] = "EldoUI-skin",
	["EldoUI skin dresses the game's guild bank window (Bank switch with Skin on). EldoUI window shows the guild bank in EldoUI's own window, on the Guild bank mover."] = "EldoUI-skin klæder spillets guildbankvindue (Bank-kontakten med Skin slået til). EldoUI-vindue viser guildbanken i EldoUI's eget vindue på Guildbank-flyttefeltet.",
	["EldoUI skins and places Blizzard's death recap window. Off leaves it to Blizzard."] = "EldoUI giver Blizzards vindue med dødsoversigten skin og placering. Fra: Blizzard styrer det.",
	["EldoUI skins and places the breath, fatigue and feign death bars. Off leaves them to Blizzard."] = "EldoUI giver bjælkerne for åndedræt, udmattelse og Feign Death skin og placering. Fra: Blizzard styrer dem.",
	["EldoUI skins and places the ghost button. Off leaves it to Blizzard."] = "EldoUI giver spøgelsesknappen skin og placering. Fra: Blizzard styrer den.",
	["EldoUI skins the quest timer and moves it out of the objective tracker onto its own mover. Off leaves it to Blizzard."] = "EldoUI giver questnedtællingen skin og flytter den ud af mål- og questtrackeren over på et eget flyttefelt. Fra: Blizzard styrer den.",
	["EldoUI theme"] = "EldoUI-tema",
	["EldoUI theme: pick it in RestedXP's theme list."] = "EldoUI-tema: vælg det i RestedXP's temaliste.",
	["EldoUI timestamps"] = "EldoUI-tidsstempler",
	["EldoUI unit frames too"] = "Også EldoUI's unitframes",
	["EldoUI window"] = "EldoUI-vindue",
	["EldoUI windows and a compact loot feed of everything you gain, repeats added up."] = "EldoUI-vinduer og et kompakt lootfeed med alt du får, gentagelser lagt sammen.",
	["EldoUI windows without toasts."] = "EldoUI-vinduer uden pop op-beskeder.",
	["EldoUI's auction tabs"] = "EldoUI's auktionsfaner",
	["EldoUI's DBM setup needs an update for DBM %s (%d settings skipped)."] = "EldoUI's DBM-opsætning skal opdateres til DBM %s (%d indstillinger sprunget over).",
	["EldoUI's Edit Mode settings: snapping, nudge step, conflicts and style presets."] = "EldoUI's Edit Mode-indstillinger: fastgørelse, skubbetrin, konflikter og stilpresets.",
	["EldoUI's frames can be dragged inside Blizzard's Edit Mode."] = "EldoUI's rammer kan trækkes i Blizzards Edit Mode.",
	["EldoUI's frames get a box you can drag, like Blizzard's."] = "EldoUI's rammer får en boks du kan trække i, ligesom Blizzards.",
	["EldoUI's frames inside Blizzard's Edit Mode, positions per Edit Mode layout, and warnings when both place the same frame."] = "EldoUI's rammer i Blizzards Edit Mode, placeringer pr. Edit Mode-layout og advarsler når begge placerer den samme ramme.",
	["EldoUI's frames move here too: drag a box, or click it for exact X and Y."] = "EldoUI's rammer flyttes også her: træk i en boks, eller klik på den for præcis X og Y.",
	["EldoUI's frames move here too: drag them like Blizzard's, with EldoUI's move panel beside Edit Mode's window."] = "EldoUI's rammer flyttes også her: træk dem ligesom Blizzards, med EldoUI's flyttepanel ved siden af Edit Modes vindue.",
	["EldoUI's frames, panel and labels inside Blizzard's Edit Mode; snaps to grid and frames."] = "EldoUI's rammer, panel og mærker i Blizzards Edit Mode; fastgøres til gitter og rammer.",
	["EldoUI's group frames, and Blizzard's when their Improve switch is on."] = "EldoUI's grupperammer, og Blizzards når deres Forbedr-kontakt er slået til.",
	["EldoUI's loot window at the mouse, roll bars, toasts from Uncommon."] = "EldoUI's lootvindue ved musen, rulbjælker, pop op-beskeder fra Uncommon.",
	["EldoUI's movable leave-vehicle button. Shown while you can leave a vehicle or a flight path early. Automatic: only when Blizzard's button is hidden with its bar."] = "EldoUI's flytbare knap til at forlade køretøjer. Vises når du kan forlade et køretøj eller en flyverute før tid. Automatisk: kun når Blizzards knap er skjult sammen med dens linje.",
	["EldoUI's move mode opens with Edit Mode: its panel beside Edit Mode's window, with search, exact X and Y, lock, attach, match size and test frames. Off: compact boxes with a small X and Y dialog."] = "EldoUI's flyttetilstand åbnes sammen med Edit Mode: dens panel ved siden af Edit Modes vindue med søgning, præcis X og Y, lås, tilknyt, tilpas størrelse og testrammer. Fra: kompakte bokse med en lille X- og Y-dialog.",
	["EldoUI's move mode opens with Edit Mode: its panel beside this window, with search, exact X and Y, lock, attach, match size and test frames. Off: compact boxes with a small X and Y dialog."] = "EldoUI's flyttetilstand åbnes sammen med Edit Mode: dens panel ved siden af dette vindue med søgning, præcis X og Y, lås, tilknyt, tilpas størrelse og testrammer. Fra: kompakte bokse med en lille X- og Y-dialog.",
	["EldoUI's Nameplates module is off: the numbers hang on Blizzard's plates."] = "EldoUI's modul Nameplates er slået fra: tallene hænger på Blizzards nameplates.",
	["EldoUI's own"] = "EldoUI's eget",
	["EldoUI's own cast bars get effects. For a unit whose EldoUI cast bar is off, Blizzard's own cast bar gets them instead."] = "EldoUI's egne castbars får effekter. For en enhed hvis EldoUI-castbar er slået fra, får Blizzards egen castbar dem i stedet.",
	["EldoUI's own cooldown rows. The game draws each cooldown; EldoUI picks what shows and where. Their glows are on the Glows page."] = "EldoUI's egne cooldownrækker. Spillet tegner hver cooldown; EldoUI vælger hvad der vises og hvor. Rækkernes glød findes på siden Glød.",
	["EldoUI's own display"] = "EldoUI's egen visning",
	["EldoUI's own leveling guide: community guides step by step in an EldoUI window on the layout's guide spot, with goals that tick from your quest log, bags and level, and one waypoint to the next goal."] = "EldoUI's egen levelingguide: fællesskabets guides trin for trin i et EldoUI-vindue på layoutets guideplads, med mål der får flueben ud fra din questlog, dine tasker og dit level, og ét waypoint til det næste mål.",
	["EldoUI's own leveling guide: community guides, step by step, on the layout's guide spot. The guides are in English."] = "EldoUI's egen levelingguide: fællesskabets guides, trin for trin, på layoutets guideplads. Guiderne er på engelsk.",
	["EldoUI's own ring around the mouse cursor. The GCD and cast sweeps are drawn by the game from its own timers."] = "EldoUI's egen ring om musemarkøren. GCD- og castfyldet tegnes af spillet ud fra dets egne nedtællinger.",
	["EldoUI's own scrolling combat text in the scroll areas: damage and healing you take, notifications, loot and gains."] = "EldoUI's egen rullende kamptekst i rulleområderne: skade og heling du modtager, notifikationer, loot og gevinster.",
	["EldoUI's own swing bars with titles and time, GCD ring on the cursor."] = "EldoUI's egne swingbjælker med titler og tid, GCD-ring ved markøren.",
	["EldoUI's scrolling text instead of Blizzard's text around your character, while EldoUI's is on. Your damage numbers over enemies stay."] = "EldoUI's rullende tekst i stedet for Blizzards tekst omkring din karakter mens EldoUI's er slået til. Dine skadetal over fjender bevares.",
	["EldoUI's settings (each opens the options search on it) and the game settings browser."] = "EldoUI's indstillinger (hver åbner indstillingssøgningen på den) og spillets indstillingsbrowser.",
	["EldoUI's swing bars, drawn from the game's swing event, with the movers and settings of the Swing timer tab. Hide Blizzard's bars there."] = "EldoUI's swingbjælker, tegnet ud fra spillets swing-hændelse, med flyttefelterne og indstillingerne fra fanen Swingtimer. Skjul Blizzards bjælker der.",
	["EldoUI's thin line"] = "EldoUI's tynde linje",
	["EldoUI's unit frames."] = "EldoUI's unitframes.",
	["EldoUI: %d action slots hold a lower rank of %s. Look at the changes before they happen?"] = { one = "EldoUI: %d handlingsplads har en lavere rang af %s. Vil du se ændringen før den sker?", other = "EldoUI: %d handlingspladser har en lavere rang af %s. Vil du se ændringerne før de sker?" },
	["EldoUI: gear sets change only out of combat."] = "EldoUI: udstyrssæt skiftes kun uden for kamp.",
	["EldoUI: name, title, class color"] = "EldoUI: navn, titel, klassefarve",
	["EldoUI_Emoji could not load (%s)."] = "EldoUI_Emoji kunne ikke indlæses (%s).",
	["EldoUI_Emoji does not match this EldoUI version. Update both folders."] = "EldoUI_Emoji passer ikke til denne EldoUI-version. Opdater begge mapper.",
	["EldoUI_Emoji is switched off in the addon list."] = "EldoUI_Emoji er slået fra i addonlisten.",
	["EldoUI_Emoji loads when emoji are on and you are out of combat."] = "EldoUI_Emoji indlæses når emojis er slået til og du er uden for kamp.",
	["EldoUI_GuideData is switched off in the game's addon list. Turn it on there and reload."] = "EldoUI_GuideData er slået fra i spillets addonliste. Slå den til der og genindlæs.",
	["Elemental Storm"] = "Elementstorm",
	["elite"] = "elite",
	["Ember"] = "Gløde",
	["Emoji"] = "Emoji",
	["Emoji and :shortcodes: such as :smile: show as pictures in chat. Needs the Blizzard UI switch Improve. Emoji graphics: Twemoji, CC-BY 4.0."] = "Emojis og :kortkoder: som :smile: vises som billeder i chatten. Kræver Blizzard-UI-kontakten Forbedr. Emojigrafik: Twemoji, CC-BY 4.0.",
	["Emoji characters and :shortcodes: in chat lines show as pictures, and the edit box gets a smiley button for the picker. Hover an emoji in chat for its name and shortcode."] = "Emojitegn og :kortkoder: i chatlinjer vises som billeder, og tekstfeltet får en smileyknap til vælgeren. Hold musen over en emoji i chatten for at se dens navn og kortkode.",
	["Emoji don't go into slash commands."] = "Emojis kommer ikke med i skråstregskommandoer.",
	["Emoji ready: %d emoji, Twemoji %s, %.1f MB in memory."] = "Emoji klar: %d emojis, Twemoji %s, %.1f MB i hukommelsen.",
	["Emoji ready: %d emoji, Twemoji %s."] = "Emoji klar: %d emojis, Twemoji %s.",
	["Emoji size"] = "Emojistørrelse",
	["Emoji that come in skin tones use this one."] = "Emojis der findes i flere hudtoner, bruger denne.",
	["Emoji you pick show up here."] = "Emojis du vælger, vises her.",
	["Emotes of your target (\"... becomes enraged!\"). Skipped while the game keeps chat hidden."] = "Emotes fra dit mål (\"... becomes enraged!\"). Springes over mens spillet holder chatten skjult.",
	["Emphasized area height"] = "Højde på fremhævet område",
	["Emphasized area width"] = "Bredde på fremhævet område",
	["Empties as time runs out"] = "Tømmes efterhånden som tiden løber ud",
	["Empties the draft. Your Legacy points don't change."] = "Tømmer kladden. Dine Legacy-point ændres ikke.",
	["Empties the list (asks first)."] = "Tømmer listen (spørger først).",
	["Empties the log."] = "Tømmer loggen.",
	["Empties the Recent row of the picker for this character."] = "Tømmer rækken Seneste i vælgeren for denne karakter.",
	["Empties the run log for every character, after a confirmation."] = "Tømmer runloggen for alle karakterer efter en bekræftelse.",
	["Empties the search box each time the bag or bank window closes, so the next open shows every item."] = "Tømmer søgefeltet hver gang taske- eller bankvinduet lukker, så vinduet viser alle genstande næste gang det åbnes.",
	["Empty slots of herb, enchanting and other special bags get a green border."] = "Tomme pladser i urte-, enchanting- og andre specialtasker får en grøn kant.",
	["Empty space between the center and each bar."] = "Tom plads mellem midten og hver bjælke.",
	["Empty the draft? Your Legacy points don't change."] = "Vil du tømme kladden? Dine Legacy-point ændres ikke.",
	["Empty: add a search or drop items on its title"] = "Tom: tilføj en søgning eller slip genstande på dens titel",
	["Enchanter"] = "Enchanter",
