	["Enlarges timers and keeps long timers hidden at the times that suit your role: tank 10 s and 60 s, healer 8 s and 90 s, damage 7 s and 45 s."] = "Forstørrer nedtællinger og holder lange nedtællinger skjult på de tidspunkter der passer til din rolle: tank 10 s og 60 s, healer 8 s og 90 s, DPS 7 s og 45 s.",
	["Enter"] = "Enter",
