	["Equip"] = "Tag på",
	["equip (out of combat)"] = "tag på (uden for kamp)",
	["Equip a fishing pole to start fishing mode."] = "Tag en fiskestang på for at starte fisketilstand.",
	["equip a set (out of combat)"] = "tag et sæt på (uden for kamp)",
	["Equip your pole"] = "Tag din fiskestang på",
	["Equipment"] = "Udstyr",
	["Equipped"] = "Båret",
	["Equipped color"] = "Farve for båret udstyr",
	["Equipped item border"] = "Kant for båret udstyr",
	["Erase"] = "Visk ud",
	["error"] = "fejl",
	["Error"] = "Fejl",
	["Error as GitHub issue"] = "Fejl som GitHub-issue",
	["Errors and help"] = "Fejl og hjælp",
	["Esc"] = "Esc",
	["Esc cancels."] = "Esc annullerer.",
	["Essential row"] = "Essentiel række",
	["Estimate from the current score: who reaches the limit first, and the final score."] = "Estimat ud fra den aktuelle stilling: hvem der når grænsen først, og slutresultatet.",
	["Estimate rested XP"] = "Anslå udhvilet XP",
	["estimated"] = "anslået",
	["Estimated time until the rested bar is full."] = "Anslået tid til udhvilet XP er fyldt op.",
	["Evade"] = "Evade",
	["Events"] = "Hændelser",
	["Events beyond the window wait in a small grid at the far end."] = "Hændelser uden for vinduet venter i et lille gitter i den fjerne ende.",
	["Every alarm on with the chicken alarm, an oh no and a squeaky toy, and the flash."] = "Alle alarmer slået til med hønsealarmen, et \"oh no\", et pibende legetøj og blinket.",
	["Every alarm on, EldoUI's alarm, chime and warning tones, and the red edge flash."] = "Alle alarmer slået til, EldoUI's alarm-, klokke- og advarselstoner og det røde blink i skærmkanten.",
	["Every announced death"] = "Alle annoncerede dødsfald",
	["Every bar I use"] = "Alle linjer jeg bruger",
	["Every bar in the EldoUI accent color; the faction shows on the icon border."] = "Alle bjælker i EldoUI's accentfarve; fraktionen vises på ikonets kant.",
	["Every bar in the stack glides to its new value instead of jumping. The game animates the bar itself."] = "Alle bjælker i stakken glider til den nye værdi i stedet for at hoppe. Spillet animerer selv bjælken.",
	["Every button goes back to the automatic pick, the mount button too."] = "Alle knapper går tilbage til det automatiske valg, også mountknappen.",
	["Every button stays on screen, grayed out when empty, the Hearthstone and mount too."] = "Alle knapper bliver på skærmen, nedtonet når de er tomme, også Hearthstone og mount.",
	["Every character"] = "Alle karakterer",
	["Every character's mail with the days left, running auctions and bids."] = "Alle karakterers post med dage tilbage, aktive auktioner og bud.",
	["Every character's professions with skill, recipes and cooldowns, and the recipe list of each."] = "Alle karakterers fag med skill, opskrifter og cooldowns samt opskriftslisten for hvert fag.",
	["Every character's saved instances with boss progress and the time to reset."] = "Alle karakterers gemte instanser med bossfremskridt og tid til reset.",
	["Every class but the shaman: one bar with the buffs you keep up (live, faded while missing), your key cooldowns and the reagents you spend. Click casts; right-click picks the spell and rank."] = "Alle klasser undtagen shaman: én bjælke med de buffs du holder oppe (live, tonet ud mens de mangler), dine vigtige cooldowns og de reagenser du bruger. Klik caster; højreklik vælger evne og rang.",
	["Every Classic dungeon with its packs (count on the marker, gold ring: elite), patrol paths, bosses (red, in kill order) and a route of numbered pulls."] = "Alle Classic-dungeons med deres packs (antal på markøren, guldring: elite), patruljeruter, bosser (røde, i drabsrækkefølge) og en rute af nummererede pulls.",
	["Every counter on its own mover instead of one strip. Place them in move mode."] = "Hver tæller på sit eget flyttefelt i stedet for én stribe. Placer dem i flyttetilstand.",
	["Every counter on its own mover, to place anywhere."] = "Hver tæller på sit eget flyttefelt, så de kan placeres hvor som helst.",
	["Every critical hit your target takes, from anyone."] = "Alle kritiske hits dit mål tager, fra alle.",
	["Every currency these characters hold."] = "Alle valutaer disse karakterer har.",
	["Every datatext on a 24 px bar, gray labels and white values."] = "Alle datatekster på en bjælke på 24 px med grå etiketter og hvide værdier.",
	["Every datatext on the info bar."] = "Alle datatekster på infobjælken.",
	["Every datatext, labels in your class color and white values."] = "Alle datatekster med etiketter i din klassefarve og hvide værdier.",
	["Every death in the log."] = "Alle dødsfald i loggen.",
	["Every detail: counts, elites, patrols, numbers and a medium line."] = "Alle detaljer: antal, elitemobs, patruljer, numre og en mellemtyk linje.",
	["Every dungeon, raid and battleground you entered, newest first."] = "Alle dungeons, raids og battlegrounds du er gået ind i, nyeste først.",
	["Every enemy plate"] = "Alle fjendtlige nameplates",
	["Every game setting (CVar)"] = "Alle spilindstillinger (CVar)",
	["Every goal is done."] = "Alle mål er klaret.",
	["Every guide in the guide data."] = "Alle guides i guidedataene.",
	["Every herb, ore, chest and fishing pool you gather shows on the world map and minimap; finds close together are one node. Also: /eui gather."] = "Alle urter, malmårer, kister og fiskestimer du indsamler, vises på verdenskortet og minikortet; fund tæt på hinanden er én node. Også: /eui gather.",
	["Every hit your target takes, from anyone. The game doesn't say who hit, so this is not only your damage."] = "Alle hits dit mål tager, fra alle. Spillet siger ikke hvem der ramte, så det er ikke kun din skade.",
	["Every icon border in your accent color, for a calm one-color bar."] = "Alle ikonkanter i din accentfarve for en rolig, ensfarvet bjælke.",
	["Every integration on: layouts place the windows, Details gets the EldoUI frame and size, RestedXP offers the EldoUI theme."] = "Alle integrationer slået til: layouts placerer vinduerne, Details får EldoUI-rammen og -størrelsen, RestedXP tilbyder EldoUI-temaet.",
	["Every item can get an action again."] = "Alle genstande kan få en handling igen.",
	["Every Legacy Challenge."] = "Alle Legacy-udfordringer.",
	["Every Legacy tree."] = "Alle Legacy-træer.",
	["Every line with a keyword is also copied into an Alerts chat tab, with time, source and a clickable name, also from channels no tab shows. The tab flashes on new lines. Off by default."] = "Hver linje med et nøgleord kopieres også til en Alerts-chatfane med tid, kilde og et klikbart navn, også fra kanaler som ingen fane viser. Fanen blinker ved nye linjer. Slået fra som standard.",
	["Every notice and every stat in the summary. Sharing stays off."] = "Alle meddelelser og al statistik i oversigten. Deling forbliver slået fra.",
	["Every pip in your class color, or each pip in its own color (set below)."] = "Alle pips i din klassefarve, eller hvert pip i sin egen farve (vælges herunder).",
	["Every pip turns one color when all your combo points are filled, so a finisher at five points stands out."] = "Alle pips skifter til én farve når alle dine combopoints er fyldt, så en finisher på fem point skiller sig ud.",
	["Every quest in the logs once, with the characters that have it. * = ready to turn in."] = "Hver quest i loggene én gang med de karakterer der har den. * = klar til aflevering.",
	["Every run, newest first."] = "Alle runs, nyeste først.",
	["Every rune once in each row, column and block."] = "Hver rune én gang i hver række, kolonne og blok.",
	["Every running auction with its bid, buyout and time left."] = "Alle aktive auktioner med bud, buyout og resterende tid.",
	["Every saved mail with sender, items, gold and the time until it is returned or deleted."] = "Alle gemte breve med afsender, genstande, guld og tiden til de sendes retur eller slettes.",
	["Every school in its own theme; other units arcane. Rising motes, light lines."] = "Hver skole i sit eget tema; andre enheder i Arkan. Opstigende fnug, lyslinjer.",
	["Every spell on your action bars already uses its highest rank."] = "Alle evner på dine handlingslinjer bruger allerede deres højeste rang.",
	["Everyone"] = "Alle",
	["Everything else"] = "Alt andet",
	["Everything is selected. Press Ctrl+C and share it. It holds your own categories and the order of the sections."] = "Alt er markeret. Tryk Ctrl+C og del det. Det indeholder dine egne kategorier og rækkefølgen af afsnittene.",
	["Everything saved about the character: level, gold, played, rested, professions, lockouts, mail and stats."] = "Alt der er gemt om karakteren: level, guld, spilletid, udhvilet, fag, lockouts, post og stats.",
	["Exact played time at each level"] = "Nøjagtig spilletid ved hvert level",
	["Exact words only"] = "Kun præcise ord",
	["Expected winner"] = "Forventet vinder",
	["Expected worth of the materials from disenchanting a green, blue or purple item, at your saved auction prices. Shows only once you have prices for those materials."] = "Forventet værdi af materialerne når du disenchanter en grøn, blå eller lilla genstand, ud fra dine gemte auktionspriser. Vises først når du har priser for disse materialer.",
	["Experience divided by the time inside."] = "Erfaring divideret med tiden inde.",
	["Experience from kills, from the game's chat line."] = "Erfaring fra drab, fra spillets chatlinje.",
	["Experience from kills, quests and exploring, added up in one row."] = "Erfaring fra drab, quests og udforskning, lagt sammen i én række.",
	["Experience gained inside."] = "Erfaring optjent derinde.",
	["Experience through the current level."] = "Erfaring i det nuværende level.",
	["Experience, XP per hour, kills and runs to the next level after each run."] = "Erfaring, XP pr. time, drab og runs til næste level efter hvert run.",
	["Expert"] = "Ekspert",
	["Expert campfire"] = "Expert-lejrbål",
	["Explore %s"] = "Udforsk %s",
	["Explorer"] = "Explorer",
	["Export all"] = "Eksporter alle",
	["Export every trigger and setting as a text string, or import one. Triggers hold no code, only picks from the same lists."] = "Eksporter alle udløsere og indstillinger som en tekststreng, eller importer en. Udløsere indeholder ingen kode, kun valg fra de samme lister.",
	["Export Fanfare"] = "Eksporter Fanfare",
	["Export this zone"] = "Eksporter denne zone",
	["External defensives too"] = "Også eksterne defensive evner",
	["Extra attacks"] = "Ekstra angreb",
	["Extra attacks you gain, from the game's own combat text feed."] = "Ekstra angreb du får, fra spillets eget kamptekstfeed.",
	["Extra bars"] = "Ekstra bjælker",
	["Extra space between chat lines, in pixels (skin switch). Game keeps the game's spacing."] = "Ekstra afstand mellem chatlinjer i pixels (Skin-kontakt). Spil beholder spillets afstand.",
	["Extra text"] = "Ekstra tekst",
	["Extra text position"] = "Placering af ekstra tekst",
	["Eye button (show only the model)"] = "Øjeknap (vis kun modellen)",
	["Faction"] = "Fraktion",
	["faction %d"] = "fraktion %d",
	["Faction colors"] = "Fraktionsfarver",
