	["Final sound"] = "Slutlyd",
	["Find"] = "Søg",
	["Find a name, zone or cause. Press Enter; an empty search shows all."] = "Find et navn, en zone eller en årsag. Tryk Enter; en tom søgning viser alle.",
	["Find an item on any of your characters: bags, bank, gear, mail, auctions and guild banks."] = "Find en genstand på en hvilken som helst af dine karakterer: tasker, bank, udstyr, post, auktioner og guildbanker.",
	["Find and sink the hidden Horde fleet before it sinks yours."] = "Find og sænk Hordens skjulte flåde før den sænker din.",
	["Find on the chat's side rail (or /eui chatsearch) lists matching lines. Click a result to scroll to it; Copy results gives them as text."] = "Søg på chattens sidebjælke (eller /eui chatsearch) viser linjer der matcher. Klik på et resultat for at rulle til det; Kopier resultater giver dem som tekst.",
	["Find the hidden five-letter word in six guesses, in English or in Danish."] = "Find det skjulte ord på fem bogstaver i seks gæt, på engelsk eller dansk.",
