	["Flat boxes"] = "Flade bokse",
	["Flat boxes, or flat tabs with an accent underline on the open one."] = "Flade bokse, eller flade faner med en understregning i accentfarve på den åbne.",
	["Flat bubbles, none in instances, no raid bubbles."] = "Flade talebobler, ingen i instanser og ingen for raidchat.",
	["Flat dark window: name and title header, item level beside each slot with gem and enchant marks, a large accent item level, foldable stat sections and underlined tabs (tabs after a reload)."] = "Fladt mørkt vindue: overskrift med navn og titel, item level ved hver plads med mærker for gems og enchant, et stort item level i accentfarve, stats-afsnit der kan foldes sammen, og understregede faner (faner efter en genindlæsning).",
	["Flat EldoUI speech bubbles with the EldoUI font, and control over which bubbles show, also in instances."] = "Flade EldoUI-talebobler med EldoUI's skrifttype og styring af hvilke talebobler der vises, også i instanser.",
	["Flat pips as wide as the bars, or round dots on an arc above them."] = "Flade pips lige så brede som bjælkerne, eller runde prikker i en bue over dem.",
