	["Fold stat sections"] = "Fold stats-afsnit sammen",
	["fold the bar to a small tab"] = "fold bjælken sammen til en lille fane",
	["Fold the bar to a small tab at its right end (hover the tab to see the bar, click it to open) or hide it. Frames placed against the bar stay where they are. Also /eui infobar and a key binding."] = "Fold bjælken sammen til en lille fane i dens højre ende (hold musen over fanen for at se bjælken, klik på den for at åbne), eller skjul den. Rammer der er placeret op ad bjælken, bliver hvor de er. Også /eui infobar og en genvejstast.",
	["Folded"] = "Foldet",
	["Folded to a tab"] = "Foldet sammen til en fane",
	["Follow the plate"] = "Følg nameplaten",
	["Font for the big text. Triggers can pick their own."] = "Skrifttype til den store tekst. Udløsere kan vælge deres egen.",
	["Font for this trigger. Module default uses the General tab's font."] = "Skrifttype til denne udløser. Modulstandard bruger skrifttypen fra fanen Generelt.",
	["Font of Blizzard's combat text around your character."] = "Skrifttype til Blizzards kamptekst omkring din karakter.",
	["Font of critical hits and other sticky lines. Default: the UI font."] = "Skrifttype til kritiske hits og andre faste linjer. Standard: UI-skrifttypen.",
	["Font of names and values."] = "Skrifttype for navne og værdier.",
	["Font of names, values and the window header."] = "Skrifttype for navne, værdier og vinduets overskrift.",
	["Font of normal lines. Default: the UI font."] = "Skrifttype til normale linjer. Standard: UI-skrifttypen.",
	["Font of the bar texts. Theme font follows the Fonts and text page."] = "Skrifttype for bjælketeksterne. Temaskrifttype følger siden Skrifttyper og tekst.",
	["Font of the countdown, charges, stacks, bar texts and keybinds."] = "Skrifttype for nedtælling, ladninger, stakke, bjælketekster og genvejstaster.",
	["Font of the effect name and the time."] = "Skrifttype for effektens navn og tiden.",
	["Font of the feedback text."] = "Skrifttype til feedbackteksten.",
	["Font of the numbers and names. Theme font follows General."] = "Skrifttype for tal og navne. Temaskrifttype følger Generelt.",
	["Font of the time."] = "Skrifttype for tiden.",
	["Font of the timer texts."] = "Skrifttype for nedtællingsteksterne.",
	["Font of the title and time."] = "Skrifttype for titel og tid.",
	["Font of this area. Default: the general font."] = "Skrifttype til dette område. Standard: den generelle skrifttype.",
	["Font size of Blizzard's combat text. Game keeps Blizzard's size."] = "Skriftstørrelse på Blizzards kamptekst. Værdien Game beholder Blizzards størrelse.",
	["Font size of charges and stacks."] = "Skriftstørrelse for ladninger og stakke.",
	["Font size of the charges left (poisons, stones) on the icon."] = "Skriftstørrelse for de resterende ladninger (gifte, sten) på ikonet.",
	["Font size of the cooldown countdown."] = "Skriftstørrelse for cooldown-nedtællingen.",
	["Font size of the effect name. Game keeps Blizzard's size."] = "Skriftstørrelse for effektens navn. Spil beholder Blizzards størrelse.",
	["Font size of the health text."] = "Skriftstørrelse for livsteksten.",
	["Font size of the keybind text."] = "Skriftstørrelse for genvejstastteksten.",
	["Font size of the power text."] = "Skriftstørrelse for ressourceteksten.",
	["Font size of the remaining time."] = "Skriftstørrelse for den resterende tid.",
	["Font size of the stack count."] = "Skriftstørrelse for stakantallet.",
	["Font size of the text."] = "Skriftstørrelse for teksten.",
	["Font size of the time left under each enchant icon."] = "Skriftstørrelse for den resterende tid under hvert enchant-ikon.",
	["Font size of the time left."] = "Skriftstørrelse for den resterende tid.",
	["Font size of the time left. Game keeps Blizzard's size."] = "Skriftstørrelse for den resterende tid. Spil beholder Blizzards størrelse.",
	["Food"] = "Mad",
	["Food and drink first"] = "Mad og drikke først",
	["Food and drink that give Well Fed or another buff are left out of the automatic pick, so they are not used up as plain food or drink. Right-click the button to pick one."] = "Mad og drikke der giver Well Fed eller en anden buff, udelades fra det automatiske valg, så de ikke bruges op som almindelig mad eller drikke. Højreklik på knappen for at vælge en.",
	["Food, drink, potions, bandage and healthstone, empty ones hidden, 32 px."] = "Mad, drikke, potions, bandage og Healthstone, tomme skjult, 32 px.",
	["Food, health potion, bandage and healthstone, potions first."] = "Mad, health potion, bandage og Healthstone, potions først.",
	["Food, potions, scrolls, bandages and the like."] = "Mad, potions, skriftruller, bandager og lignende.",
	["For Blizzard frames whose Move switch is off, Edit Mode decides where they sit. EldoUI reports any frame that is anchored to an EldoUI frame anyway."] = "For Blizzard-rammer hvis Flyt-kontakt er slået fra, bestemmer Edit Mode hvor de sidder. EldoUI melder enhver ramme der alligevel er forankret til en EldoUI-ramme.",
	["For breath, fatigue and AFK alarms and the Test buttons. Aura alarms are sound only, because the game plays them."] = "Til alarmer for åndedræt, udmattelse og AFK og til Test-knapperne. Auraalarmer er kun lyd: spillet afspiller dem selv.",
	["For buffs on the left side of the screen: rows fill to the right."] = "Til buffs i venstre side af skærmen: rækkerne fyldes mod højre.",
	["For Class resources in Blizzard UI. Hide and Replace hide what is checked here; Move puts the totem timers on their own mover."] = "Til Klasseressourcer i Blizzard-UI. Skjul og Erstat skjuler det der har flueben her; Flyt sætter totemnedtællingerne på deres eget flyttefelt.",
	["For Hardcore characters: a log of announced deaths, death alerts, a Tell the guild card after your own death, PvP-flag warnings and Self-Found reminders."] = "Til Hardcore-karakterer: en log over annoncerede dødsfald, dødsadvarsler, et Fortæl guilden-kort efter din egen død, PvP-flagadvarsler og Self-Found-påmindelser.",
	["For items you can craft: what the reagents cost at your saved auction or vendor prices, and the profit at the item's auction price. Needs Remember recipes (Crafting, below)."] = "For genstande du kan crafte: hvad reagenserne koster efter dine gemte auktions- eller købmandspriser, og fortjenesten ved genstandens auktionspris. Kræver Husk opskrifter (Crafting, nedenfor).",
	["For Player buffs and debuffs in Blizzard UI. Move puts Blizzard's frames on EldoUI's movers; Improve shows the time left."] = "Til Spillerens buffs og debuffs i Blizzard-UI. Flyt sætter Blizzards rammer på EldoUI's flyttefelter; Forbedr viser den resterende tid.",
	["For the compact boxes: edges snap to Edit Mode's grid (when it is shown, else EldoUI's grid) and to other EldoUI frames. The full move tools use Snap in their own panel. Hold Alt to place freely."] = "For de kompakte bokse: kanter fastgøres til Edit Modes gitter (når det vises, ellers EldoUI's gitter) og til andre EldoUI-rammer. De fulde flytteværktøjer bruger Fastgør i deres eget panel. Hold Alt nede for at placere frit.",
	["For this character"] = "Til denne karakter",
	["Forever bronze"] = "Forever bronze",
	["Forget"] = "Glem",
