	["Gear the character wears."] = "Udstyr karakteren har på.",
	["Gear, recipes and other items this character can't use yet (level, skill, class or armor type) get a red icon, as the game's tooltip shows in red."] = "Udstyr, opskrifter og andre genstande denne karakter ikke kan bruge endnu (level, færdighed, klasse eller rustningstype) får et rødt ikon, ligesom spillets tooltip viser dem med rødt.",
