	["Give"] = "Giv",
	["Give %s to %s?"] = "Giv %s til %s?",
	["Give a channel and a player name, for example Trade and Name-Realm."] = "Angiv en kanal og et spillernavn, fx Trade og Navn-Realm.",
	["Give menu"] = "Uddelingsmenu",
	["Give one spell or item its own sound, speech or glow. Module default uses the settings on the Pulse tab."] = "Giv en enkelt evne eller genstand sin egen lyd, tale eller glød. Modulstandard bruger indstillingerne på fanen Puls.",
	["Give spell flyout buttons the EldoUI look. Blizzard's flyout follows the Skin switch of Action button look."] = "Giv flyoutknapperne for evner EldoUI-udseendet. Blizzards flyout følger Skin-kontakten for Handlingsknappernes udseende.",
	["Give this bar its own keybind, count and macro text (the gear). Off: the bar uses the Text tab."] = "Giv denne linje sin egen genvejstast-, antals- og makrotekst (tandhjulet). Fra: linjen bruger fanen Tekst.",
	["Give this group its own visibility rule. Off: a group made from a fixed row follows that row, any other group follows the main row."] = "Giv denne gruppe sin egen synlighedsregel. Fra: en gruppe der er lavet ud fra en fast række, følger den række, og alle andre grupper følger hovedrækken.",
	["Give this icon's shadow its own strength and size. Off follows Frame shadows on Global settings > Textures."] = "Giv dette ikons skygge sin egen styrke og størrelse. Fra følger Rammeskygger under Globale indstillinger > Teksturer.",
	["Give your route another name."] = "Giv din rute et andet navn.",
	["Gives BigWigs' bars, messages and countdown a spot in the layout. BigWigs asks in its own window before it takes them. Unchecked, EldoUI leaves BigWigs alone."] = "Giver BigWigs' bjælker, beskeder og nedtælling en plads i layoutet. BigWigs spørger i sit eget vindue før den tager dem i brug. Uden flueben lader EldoUI BigWigs være.",
	["Gives the selected profile another name."] = "Giver den valgte profil et andet navn.",
