	["Global cooldown"] = "Global cooldown",
	["Global cooldown bar"] = "Bjælke for global cooldown",
	["Glow around the pulse icon for this entry, or not."] = "Glød omkring pulsikonet for denne post, eller ej.",
	["Glow on a party or raid frame while the member has a debuff you (or your group) can dispel. Switch it on under Party and Raid > Indicators."] = "Glød på en gruppe- eller raidramme mens medlemmet har en debuff som du (eller din gruppe) kan dispelle. Slå den til under Gruppe og raid > Indikatorer.",
	["Glow on a party or raid frame while the member has an aura the game marks as a boss aura. Switch it on under Party and Raid > Indicators."] = "Glød på en gruppe- eller raidramme mens medlemmet har en aura som spillet markerer som en bossaura. Slå den til under Gruppe og raid > Indikatorer.",
	["Glow on boss auras"] = "Glød ved bossauraer",
