	["Glowing particles light up what is behind them; solid ones cover it."] = "Glødende partikler lyser op i det der er bag dem; uigennemsigtige partikler dækker det.",
	["Glows round a themed cast bar while it casts (Cast Bar Effects, Glow while casting). The color comes from the theme."] = "Glød om en castbar med tema mens den caster (Castbar-effekter, Glød under cast). Farven kommer fra temaet.",
