	["Height of the tab strip and the tabs in it."] = "Højden på fanelinjen og fanerne i den.",
	["Height of this bar."] = "Højde på denne bjælke.",
	["Height of window 1 including its title bar, when \"Set the window size\" is on."] = "Højden på vindue 1 inklusive titellinjen når \"Angiv vinduesstørrelsen\" er slået til.",
	["Height of window 2 including its title bar, when it is placed and sized by EldoUI."] = "Højden på vindue 2 inklusive titellinjen når EldoUI placerer det og bestemmer størrelsen.",
	["Herbalism"] = "Herbalism",
	["Herbalist"] = "Herbalist",
	["Herbs"] = "Urter",
	["hidden"] = "skjult",
	["Hidden (use Raid Tools)"] = "Skjult (brug Raidværktøjer)",
	["Hidden in the window."] = "Skjult i vinduet.",
	["Hidden lines"] = "Skjulte linjer",
	["Hidden right now (shown while you move it)."] = "Skjult lige nu (vises mens du flytter den).",
	["Hidden while the Blizzard UI switch Hide is on for chat windows."] = "Skjult mens Blizzard-UI-kontakten Skjul er slået til for chatvinduer.",
	["Hidden while the element's Hide switch is on."] = "Skjult mens elementets Skjul-kontakt er slået til.",
	["hidden, %d found"] = "skjult, %d fundet",
	["Hide (follows the Hide switch)"] = "Skjul (følger Skjul-kontakten)",
	["Hide a button while you carry nothing for it (the mana gem stays)."] = "Skjul en knap mens du ikke har noget til den (mana gem-knappen bliver).",
	["Hide background art"] = "Skjul baggrundsgrafik",
	["Hide below this total"] = "Skjul under dette antal i alt",
	["Hide Blizzard's"] = "Skjul Blizzards",
	["Hide Blizzard's combo points"] = "Skjul Blizzards combopoints",
	["Hide Blizzard's druid mana bar"] = "Skjul Blizzards Druid-manabjælke",
	["Hide Cyrillic lines"] = "Skjul kyrilliske linjer",
	["Hide death recap"] = "Skjul dødsoversigt",
	["Hide EldoUI's action bars while the game's gamepad interface is on, so the controller HUD takes over."] = "Skjul EldoUI's handlingslinjer mens spillets gamepadinterface er slået til, så controllerens HUD tager over.",
	["Hide emotes"] = "Skjul emotes",
	["Hide empty buttons"] = "Skjul tomme knapper",
	["Hide every %s"] = "Skjul alle %s",
	["Hide frame art"] = "Skjul rammegrafik",
	["Hide herb and ore nodes by your Herbalism or Mining skill. Nodes whose required skill isn't known stay shown."] = "Skjul urte- og malmnodes efter din skill i Herbalism eller Mining. Nodes hvor den krævede skill ikke kendes, bliver vist.",
	["Hide in groups"] = "Skjul i grupper",
	["Hide in numbered channels"] = "Skjul i nummererede kanaler",
	["hide in the window"] = "skjul i vinduet",
	["Hide it"] = "Skjul den",
	["Hide main hand"] = "Skjul main hand",
	["Hide mirror timers"] = "Skjul ånde- og udmattelsesbjælker",
	["Hide nodes above my skill"] = "Skjul nodes over min skill",
	["Hide off hand"] = "Skjul off hand",
	["Hide one player in one public channel only. Whispers, guild and group chat and your /ignore list stay as they are. Right-click a sender in a channel line to mute them there."] = "Skjul én spiller i kun én offentlig kanal. Hvisk, guild- og gruppechat og din /ignore-liste forbliver som de er. Højreklik på en afsender i en kanallinje for at dæmpe vedkommende der.",
	["Hide other players' crafting"] = "Skjul andre spilleres crafting",
	["Hide quest timer"] = "Skjul questnedtælling",
	["Hide ranged"] = "Skjul ranged",
	["Hide repeated lines"] = "Skjul gentagne linjer",
	["Hide Return to Graveyard"] = "Skjul Return to Graveyard",
	["Hide runs older than a day."] = "Skjul runs der er ældre end et døgn.",
	["Hide say and yell"] = "Skjul sig og råb",
	["Hide small numbers"] = "Skjul små tal",
	["hide the bar"] = "skjul bjælken",
	["Hide the bars checked below."] = "Skjul de bjælker der har flueben nedenfor.",
	["Hide the channels button"] = "Skjul kanalknappen",
	["Hide the chat menu button"] = "Skjul chatmenuknappen",
	["Hide the combo points with no target or no points."] = "Skjul combopoints når du ikke har noget mål eller ingen point.",
	["Hide the decorative frame around the zone ability; the button stays."] = "Skjul den dekorative ramme omkring zoneevnen; knappen bliver.",
	["Hide the global cooldown"] = "Skjul den globale cooldown",
	["Hide the list while no enemies are listed."] = "Skjul listen når der ikke er nogen fjender på den.",
	["Hide the parts checked below."] = "Skjul de dele der har flueben nedenfor.",
	["Hide the personal resource display"] = "Skjul Personal Resource Display",
	["Hide the power bar while your mana or energy is full. While the game keeps your power secret (in some fights) the bar stays shown."] = "Skjul ressourcebjælken mens din mana eller energi er fuld. Mens spillet holder din ressource hemmelig (i nogle kampe), bliver bjælken vist.",
	["Hide the Quick Join toast"] = "Skjul pop op-beskeden fra Quick Join",
	["Hide the side bar"] = "Skjul sidebjælken",
	["Hide the timers checked below."] = "Skjul de nedtællinger der har flueben nedenfor.",
	["Hide the viewers checked under \"Hide this viewer\"."] = "Skjul de visninger der har flueben under \"Skjul denne visning\".",
	["Hide their chat bubbles"] = "Skjul deres talebobler",
	["Hide this bar while it is full. While the game keeps the value secret the bar stays shown."] = "Skjul bjælken mens den er fuld. Mens spillet holder værdien hemmelig, bliver bjælken vist.",
	["Hide this section"] = "Skjul dette afsnit",
	["Hide this viewer"] = "Skjul denne visning",
	["Hide timers shorter than"] = "Skjul nedtællinger kortere end",
	["Hide totem timers"] = "Skjul totemnedtællinger",
	["Hide voice and speech buttons"] = "Skjul stemme- og taleknapper",
	["Hide what you can't collect"] = "Skjul det du ikke kan samle",
	["Hide when EldoUI replaces it"] = "Skjul når EldoUI erstatter den",
	["Hide when empty"] = "Skjul når tom",
	["Hide when full"] = "Skjul når fuld",
	["Hide whole guilds you don't want to read, without /ignore. Only what you see changes; your ignore list is untouched."] = "Skjul hele guilds du ikke vil læse, uden /ignore. Kun det du ser, ændres; din ignoreliste røres ikke.",
	["Hide with gamepad"] = "Skjul med gamepad",
	["Hides boss and other timers shorter than this many seconds. The pull and the ready check always show."] = "Skjuler boss- og andre nedtællinger der er kortere end dette antal sekunder. Pull-nedtællingen og klar-tjekket vises altid.",
	["Hides lines that contain Cyrillic letters. It looks at the letters, not the language. Off by default."] = "Skjuler linjer der indeholder kyrilliske bogstaver. Den ser på bogstaverne, ikke sproget. Slået fra som standard.",
	["Hides numbers below this. Numbers the game keeps hidden in a fight always show."] = "Skjuler tal under denne værdi. Tal som spillet holder skjult i en kamp, vises altid.",
	["Hides the ghost button. You can still return to the graveyard from the spirit healer."] = "Skjuler spøgelsesknappen. Du kan stadig vende tilbage til kirkegården hos en Spirit Healer.",
	["Hides the guide window for this character. /eui eldostar show brings it back."] = "Skjuler guidevinduet for denne karakter. /eui eldostar show henter det frem igen.", -- l10n: keep
	["Hides this area while you are in a party or raid."] = "Skjuler området mens du er i en gruppe eller et raid.",
	["High"] = "Høj",
	["High (default)"] = "Høj (standard)",
	["Highest threat"] = "Højeste aggro",
	["Highlight color"] = "Fremhævningsfarve",
	["Highlight in accent color"] = "Fremhæv i accentfarve",
	["Highlight look"] = "Fremhævningens udseende",
	["Highlight lower ranks"] = "Fremhæv lavere rang",
	["Highlights"] = "Fremhævninger",
	["Hint"] = "Ledetråd",
	["Hippogryph"] = "Hippogryph",
	["History and search"] = "Historik og søgning",
	["History from %s"] = "Historik fra %s",
	["Hit"] = "Hit",
	["Hit numbers on plates are on, so Blizzard's damage numbers left at \"Blizzard setting\" stay off: one number per hit."] = "Hittal på nameplates er slået til, så Blizzards skadetal der står på \"Blizzard-indstilling\", forbliver slået fra: ét tal pr. hit.",
	["Hit the gnolls as they pop up, and leave the gnome alone."] = "Slå gnollerne når de dukker op, og lad gnomen være.",
	["Hits on enemy plates"] = "Hits på fjendtlige nameplates",
	["Hits on target"] = "Hits på målet",
	["Hits that are fully blocked, absorbed or resisted."] = "Hits der bliver helt blokeret, absorberet eller modstået.",
	["Hits you take."] = "Hits du tager.",
	["Hits your pet takes."] = "Hits dit pet tager.",
	["Hold"] = "Stille",
	["Hold %s over an item Bag Actions can use: the help shows there."] = "Hold %s-tasten nede over en genstand som Taskehandlinger kan bruge, så vises hjælpen ved den.",
	["Hold a modifier key over an item in your bags and click it to disenchant, prospect, mill or pick its lock. One click casts one spell on one item."] = "Hold en ændringstast nede mens du holder musen over en genstand i dine tasker, og klik på den for at bruge Disenchant, Prospecting, Milling eller Pick Lock. Ét klik caster én evne på én genstand.",
	["Hold Shift and drag anywhere on a bar or panel to move it. Saved like move mode; not in combat."] = "Hold Shift nede, og træk et vilkårligt sted på en bjælke eller et panel for at flytte det. Gemmes som i flyttetilstand; ikke i kamp.",
	["Hold Shift, Ctrl or Alt to see just those clicks; no modifier shows plain clicks."] = "Hold Shift, Ctrl eller Alt nede for kun at se de klik; uden ændringstast vises almindelige klik.",
	["Hold the modifier and point at an item: a glow shows when you can break or open it, and your click casts that spell on it. Not in combat."] = "Hold ændringstasten nede, og peg på en genstand: Der vises en glød når du kan bryde den ned eller åbne den, og dit klik caster den evne på den. Ikke i kamp.",
	["Hold this key (and no other) over an item to get the action. Alt-click still attaches items while the mailbox is open."] = "Hold denne tast (og ingen anden) nede over en genstand for at få handlingen. Alt-klik vedhæfter stadig genstande mens postkassen er åben.",
	["Holy"] = "Hellig",
	["Holy for other units, golden motes and a bright finish."] = "Hellig til andre enheder, gyldne fnug og en klar afslutning.",
	["Home"] = "Hjem",
	["Home: chat and your realm. World: combat and the world around you."] = "Hjem: chat og din realm. Verden: kamp og verden omkring dig.",
	["Honor"] = "Ære",
	["Honor and honorable kills in a battleground."] = "Ære og ærefulde drab i et battleground.",
	["Honor gained"] = "Optjent ære",
	["Honor gains"] = "Ære optjent",
	["Honor you gain, from the game's chat line."] = "Ære du får, fra spillets chatlinje.",
	["Honor you gain."] = "Ære du får.",
	["Honorable kill"] = "Ærefuldt drab",
	["Honorable kills"] = "Ærefulde drab",
	["Hop a murloc over the road and the river into the five nests."] = "Hop en murloc over vejen og floden og ind i de fem reder.",
	["Horde ships sunk: %d of %d"] = "Hordens skibe sænket: %d af %d",
	["Horde waters"] = "Hordens farvand",
	["Horde wins 2000-1430"] = "Horde vinder 2000-1430",
	["Horizontal fits the layout spot. Vertical has no layout spot: drag it in move mode."] = "Vandret passer til pladsen i layoutet. Lodret har ingen plads i layoutet: træk den i flyttetilstand.",
	["Horizontal shift of the time text."] = "Vandret forskydning af tidsteksten.",
	["Horse"] = "Hest",
	["Hourly limit"] = "Grænse pr. time",
	["Hourly limit set to %d."] = "Grænsen pr. time er sat til %d.",
	["Hover a campfire first."] = "Hold først musen over et lejrbål.",
	["Hover a frame to see every click in its tooltip."] = "Hold musen over en ramme for at se alle klik i dens tooltip.",
	["Hover a trinket or ring slot to see the matching items in your bags, and click one to wear it there. Out of combat only. Blizzard's own Alt flyout keeps working."] = "Hold musen over en trinket- eller ringplads for at se de passende genstande i dine tasker, og klik på en for at tage den på der. Kun uden for kamp. Blizzards egen Alt-menu virker stadig.",
	["Hover any EldoUI button and press a key to bind it."] = "Hold musen over en EldoUI-knap, og tryk på en tast for at binde den.",
	["Hovering a campfire shows its tier, slots and the features you have seen; hovering a feature shows its buff and whether you have it."] = "Når du holder musen over et lejrbål, vises dets trin, pladser og de faciliteter du har set; over en facilitet vises dens buff og om du har den.",
	["Hovering a frame lists your bindings in the tooltip, grouped by modifier: the game's Click Casting and EldoUI's."] = "Når du holder musen over en ramme, viser tooltippen dine bindinger grupperet efter ændringstast: spillets klikkast og EldoUI's.",
	["How a button shows that it is pressed."] = "Hvordan en knap viser at den er trykket ned.",
	["How a button shows that its spell has procced. The look of \"As set\" is the \"Action bar procs\" row on the Glows page. The game says which spell; EldoUI only draws it."] = "Hvordan en knap viser at dens evne har proccet. Udseendet for \"Som indstillet\" er rækken \"Procs på handlingslinjer\" på siden Glød. Spillet siger hvilken evne; EldoUI tegner kun gløden.",
	["How a button shows that the mouse is over it."] = "Hvordan en knap viser at du holder musen over den.",
	["How a button shows that the target is out of range."] = "Hvordan en knap viser at målet er uden for rækkevidde.",
	["How a crafted item's or recipe's tooltip lists the guild members who know it. The Loot Guide's Crafting page uses the same form."] = "Hvordan tooltippen for en craftet genstand eller opskrift viser de guildmedlemmer der kan den. Siden Crafting i Loot Guide bruger samme form.",
	["How a dashboard looks with sample values, in your art style and accent."] = "Sådan ser et dashboard ud med eksempelværdier i din grafikstil og accentfarve.",
	["How a spell with charges shows that a charge is coming back while you still have one: a light swipe, only the bright edge, or nothing."] = "Hvordan en evne med ladninger viser at en ladning er på vej tilbage mens du stadig har en: et let swipe, kun den lyse kant eller ingenting.",
	["How big the pulse icon is."] = "Hvor stort pulsikonet er.",
	["How Blizzard's combat text around your character moves (Blizzard's option floatingCombatTextFloatMode)."] = "Hvordan Blizzards kamptekst omkring din karakter bevæger sig (Blizzards indstilling floatingCombatTextFloatMode).",
	["How bright the shine is."] = "Hvor kraftig glansen er.",
	["How clock times are written in the log. Like every EldoUI clock: the clock format on the General page."] = "Hvordan klokkeslæt skrives i loggen. Som alle EldoUI-ure: urformatet på siden Generelt.",
	["How close a result must be to what you typed. Close matches also find \"swgry\" for Swift Gryphon."] = "Hvor tæt et resultat skal ligge på det du skrev. Tætte match finder også \"swgry\" for Swift Gryphon.",
	["How close an edge must come before it snaps, in pixels."] = "Hvor tæt en kant skal komme før den fastgøres, i pixels.",
	["How close to pulling aggro, in percent of the point where you would pull."] = "Hvor tæt du er på at tage aggro, i procent af det punkt hvor du ville tage den.",
	["How critical hits and other sticky lines appear."] = "Hvordan kritiske hits og andre faste linjer vises.",
	["How dark the bubble box is."] = "Hvor mørk boksen bag teksten er.",
	["How dark the cooldown swipe over the icon is."] = "Hvor mørkt cooldownens swipe over ikonet er.",
	["How dark the game world behind the panel gets."] = "Hvor mørk spilverdenen bag panelet bliver.",
	["How dark the panel behind the chat is (panel mode only)."] = "Hvor mørkt panelet bag chatten er (kun i paneltilstand).",
	["How dark the swipe is."] = "Hvor mørk swipen er.",
	["How dark this icon's shadow is."] = "Hvor mørk ikonets skygge er.",
	["How early the mail reminder warns."] = "Hvor tidligt postpåmindelsen advarer.",
	["How early the warning comes."] = "Hvor tidligt advarslen kommer.",
	["How early, and for which kinds."] = "Hvor tidligt og for hvilke slags.",
	["How far ahead the bar looks. Events further out wait at the far end."] = "Hvor langt frem bjælken ser. Hændelser længere ude venter i den fjerne ende.",
	["How far the camera sits behind you. The camera stops at the max camera distance (Quality of Life > Sound and misc)."] = "Hvor langt bag dig kameraet sidder. Kameraet stopper ved den maksimale kameraafstand (Livskvalitet > Lyd og diverse).",
	["How far the icon overshoots before it settles (1 = no overshoot)."] = "Hvor meget ikonet skyder over før det falder på plads (1 = ingen overskydning).",
	["How far this icon's shadow reaches beyond its edge."] = "Hvor langt ikonets skygge rækker ud over kanten.",
	["How far up and down particles fan out, in degrees."] = "Hvor langt op og ned partiklerne spredes, i grader.",
	["How far you can scroll back. Game keeps the game's default."] = "Hvor langt du kan rulle tilbage. Spil beholder spillets standard.",
	["How fast every scroll area plays, in percent. Each area can override it."] = "Hvor hurtigt alle rulleområder afspilles, i procent. Hvert område kan tilsidesætte det.",
	["How fast particles drift back along the bar, in pixels per second."] = "Hvor hurtigt partiklerne driver tilbage langs bjælken, i pixels pr. sekund.",
	["How fast the action games run (Snake, Rune Stack, Gryphon Glide and Brick Breaker) and how long WoW Trivia gives you for each question."] = "Hvor hurtigt actionspillene kører (Snake, Runestak, Griffinglid og Murbryder) og hvor lang tid WoW-quizzen giver dig til hvert spørgsmål.",
	["How fast the camera turns."] = "Hvor hurtigt kameraet drejer.",
	["How fast the shine sweeps."] = "Hvor hurtigt glansen fejer.",
	["How gold is written in the bag windows and their tooltips. \"Use general setting\" follows Fonts and text > Money."] = "Hvordan guld skrives i taskevinduerne og deres tooltips. \"Brug den generelle indstilling\" følger Skrifttyper og tekst > Penge.",
	["How icons in EldoUI's rows look in each state the game reports: on cooldown, recharging, not usable or out of range."] = "Hvordan ikoner i EldoUI's rækker ser ud i hver tilstand spillet melder: på cooldown, genoplader, ikke brugbar eller uden for rækkevidde.",
	["How long a character can stay away from the auction house before the reminder."] = "Hvor længe en karakter kan holde sig væk fra auktionshuset før påmindelsen.",
	["How long a line stays before it fades."] = "Hvor længe en linje bliver før den toner ud.",
	["How long a player stays listed after their nameplate went away."] = "Hvor længe en spiller bliver på listen efter at deres nameplate er forsvundet.",
	["How long a repeated line stays hidden."] = "Hvor længe en gentaget linje forbliver skjult.",
	["How long a row of their loot stays."] = "Hvor længe en række med deres loot bliver.",
	["How long each card or row stays. Its time stops while the mouse is over it, and a right-click closes it."] = "Hvor længe hvert kort eller hver række bliver. Tiden står stille mens musen er over det, og et højreklik lukker det.",
	["How long the current fight has lasted, from Blizzard's damage meter session when it has one. The InfoBar's Combat time reads the same timer."] = "Hvor længe den nuværende kamp har varet, fra Blizzards skademålersession når den har en. Infobjælkens Kamptid læser det samme ur.",
	["How long the fade itself takes."] = "Hvor lang tid selve toningen tager.",
	["How long the result stays when someone else won or everyone passed."] = "Hvor længe resultatet bliver når en anden vandt eller alle passede.",
	["How long the result stays when you won the item."] = "Hvor længe resultatet bliver når du vandt genstanden.",
	["How long the roll window stays open without a new roll. It never closes while the mouse is over it. 0 keeps it open."] = "Hvor længe rulvinduet bliver åbent uden et nyt rul. Det lukker aldrig mens musen er over det. 0 holder det åbent.",
	["How long the text stays before it fades."] = "Hvor længe teksten bliver før den tones ud.",
	["How long the text stays. General uses the General tab's time."] = "Hvor længe teksten bliver. Generelt bruger tiden fra fanen Generelt.",
	["How long you were inside."] = "Hvor længe du var inde.",
	["How looted items are valued. Auction prices are the ones EldoUI saved when you searched the auction house."] = "Hvordan lootede genstande vurderes. Auktionspriser er dem EldoUI gemte da du søgte i auktionshuset.",
	["How many boss auras at once."] = "Hvor mange bossauraer der vises på én gang.",
	["How many buffs fit in one row."] = "Hvor mange buffs der er plads til i én række.",
	["How many buttons the bar shows, up to nine. Keys 10 to 12 of the key sets use the Consumable Bar."] = "Hvor mange knapper linjen viser, op til ni. Taster 10 til 12 i tastesættene bruger Forbrugslinjen.",
	["How many buttons the bar shows."] = "Hvor mange knapper linjen viser.",
	["How many classes can a new character choose from?"] = "Hvor mange klasser kan en ny karakter vælge imellem?",
	["How many copper coins make one silver?"] = "Hvor mange kobbermønter giver én sølvmønt?",
	["How many datatexts the panel has. The slots share its width (or height when vertical) evenly."] = "Hvor mange datatekster panelet har. Pladserne deler dets bredde (eller højde når det er lodret) ligeligt.",
	["How many debuffs fit in one row."] = "Hvor mange debuffs der er plads til i én række.",
	["How many fill particles start each second at intensity 100."] = "Hvor mange fyldpartikler der starter hvert sekund ved intensitet 100.",
	["How many icons at most."] = "Det højeste antal ikoner.",
	["How many in your group picked Need, Transmog, Greed or Pass so far, from the game's loot history, above the timer. Point at the counts for the names and who has not chosen yet."] = "Hvor mange i din gruppe der har valgt Need, Transmog, Greed eller Pas indtil nu, fra spillets loothistorik, over tidsbjælken. Peg på tallene for navnene og hvem der ikke har valgt endnu.",
	["How many letters the edit box takes while splitting is on (links count with their hidden part)."] = "Hvor mange bogstaver chatfeltet tager mens opdeling er slået til (links tæller med deres skjulte del).",
	["How many minutes before the time the reminder prints."] = "Hvor mange minutter før tidspunktet påmindelsen skrives.",
	["How many more runs like this one until you level up."] = "Hvor mange flere runs som dette indtil du stiger i level.",
	["How many new instances the server lets you enter per hour. Change it if Forever uses a different limit."] = "Hvor mange nye instanser serveren lader dig gå ind i pr. time. Skift det hvis Forever bruger en anden grænse.",
	["How many of the item each of your characters has, per location (Bags module)."] = "Hvor mange af genstanden hver af dine karakterer har, pr. sted (modulet Tasker).",
	["How many of the item you now have in your bags, on the row's icon."] = "Hvor mange af genstanden du nu har i dine tasker, på rækkens ikon.",
	["How many of the newest lines the list shows."] = "Hvor mange af de nyeste linjer listen viser.",
	["How many of the next pulls the card lists."] = "Hvor mange af de næste pulls kortet viser.",
	["How many of the reagents your class spends you carry, and a hunter's ammo."] = "Hvor mange af din klasses reagenser du har på dig, og en hunters ammo.",
	["How many of this reagent you carry."] = "Hvor mange af dette reagens du har på dig.",
	["How many particles burst from the edge when a cast completes."] = "Hvor mange partikler der springer ud fra kanten når et cast fuldføres.",
	["How many particles start each second at intensity 100."] = "Hvor mange partikler der opstår pr. sekund ved intensitet 100.",
	["How many pet buttons show."] = "Hvor mange petknapper der vises.",
	["How many races can a new character choose from?"] = "Hvor mange racer kan en ny karakter vælge imellem?",
	["How many results the box shows at most."] = "Hvor mange resultater boksen højst viser.",
	["How many runs like this one a whole level takes."] = "Hvor mange runs som dette et helt level kræver.",
	["How many runs this log keeps (all characters). Older runs leave the log; My Adventure keeps every run in its journal, with who was in it."] = "Hvor mange runs loggen gemmer (alle karakterer). Ældre runs forsvinder fra loggen; My Adventure gemmer hvert run i sin journal med hvem der var med.",
	["How many sample frames the test shows. Also /eui grouptest raid20."] = "Hvor mange eksempelrammer testen viser. Også /eui grouptest raid20.",
	["How many saved sessions each zone keeps."] = "Hvor mange gemte sessioner hver zone beholder.",
	["How many seconds before the event the big icon appears."] = "Hvor mange sekunder før hændelsen det store ikon vises.",
	["How many silver coins make one gold?"] = "Hvor mange sølvmønter giver én guldmønt?",
	["How many stacks fill the bar. Set it to the aura's most stacks."] = "Hvor mange stakke der fylder bjælken. Sæt det til auraens maksimale antal stakke.",
	["How many texts can wait while one shows. Extra ones are skipped."] = "Hvor mange tekster der kan vente mens én vises. Ekstra tekster springes over.",
	["How many timer bars at most."] = "Det højeste antal tidsbjælker.",
	["How many toast cards show at once. More wait their turn, and cards for loot in combat wait until the fight ends. The Loot Toasts mover is as tall as these cards."] = "Hvor mange pop op-kort der vises på én gang. Flere venter på tur, og kort for loot i kamp venter til kampen er slut. Flyttefeltet \"Pop op-beskeder for loot\" er lige så højt som disse kort.",
	["How many waiting icons show before a +N count."] = "Hvor mange ventende ikoner der vises før et +N-tal.",
	["How many whispers arrived while you were away. Read them in chat when you're back."] = "Hvor mange hviskebeskeder der kom mens du var væk. Læs dem i chatten når du er tilbage.",
	["How much below the cheapest current price the Quick Sell tab starts."] = "Hvor meget under den laveste aktuelle pris fanen Hurtigt salg starter.",
	["How much below the cheapest current price the Quick Sell tab starts. 100 copper = 1 silver."] = "Hvor meget under den laveste aktuelle pris fanen Hurtigt salg starter. 100 kobber = 1 sølv.",
	["How much of each icon edge is cut away, in percent. 8 is EldoUI's default."] = "Hvor meget af hver ikonkant der skæres væk, i procent. 8 er EldoUI's standard.",
	["How much of the art's edge is cut off, in percent."] = "Hvor meget af billedets kant der skæres af, i procent.",
	["How normal lines move: straight, arc, angled, fountain, or stacked in place."] = "Hvordan normale linjer bevæger sig: lige, bue, skrå, springvand eller stablet på stedet.",
	["How numbered channels are shortened."] = "Hvordan nummererede kanaler forkortes.",
	["How numbers are written. Works for numbers the game keeps hidden in a fight too."] = "Hvordan tal skrives. Virker også for tal som spillet holder skjult i en kamp.",
	["How plate numbers are colored. School colors need the game to say the school."] = "Hvordan tallene på nameplates farves. Skolefarver kræver at spillet oplyser skolen.",
	["How plate numbers move."] = "Hvordan tallene på nameplates bevæger sig.",
	["How see-through the background is."] = "Hvor gennemsigtig baggrunden er.",
	["How see-through the route line and patrol paths are."] = "Hvor gennemsigtige rutelinjen og patruljeruterne er.",
	["How small the icon starts before it pops in (1 = full size)."] = "Hvor lille ikonet er før det popper frem (1 = fuld størrelse).",
	["How solid the marks are."] = "Hvor dækkende stregerne er.",
	["How solid the pins are."] = "Hvor uigennemsigtige nålene er.",
	["How strong the flash is."] = "Hvor kraftigt blinket er.",
	["How strongly the bar's edges light up in this theme."] = "Hvor kraftigt bjælkens kanter lyser op i dette tema.",
	["How strongly the image shows through."] = "Hvor kraftigt billedet skinner igennem.",
	["How the Date datatext writes the date."] = "Hvordan datateksten for dato skriver datoen.",
	["How the Gold datatext shows your money."] = "Hvordan datateksten for guld viser dine penge.",
	["How the line reads. Codes filled in by the game: {amount} {name} {spell} {type} {count} {item} {total} {text}."] = "Hvordan linjen lyder. Koder som spillet udfylder: {amount} {name} {spell} {type} {count} {item} {total} {text}.",
	["How the mark looks: a check, a question mark or a cross; a small colored square; or a short word (New, Look, Have)."] = "Hvordan mærket ser ud: et flueben, et spørgsmålstegn eller et kryds; en lille farvet firkant; eller et kort ord (Nyt, Udseende, Har).",
	["How the Quick Sell tab lowers the cheapest current price. The price never goes below the vendor price."] = "Hvordan fanen Hurtigt salg sænker den laveste aktuelle pris. Prisen kommer aldrig under købmandsprisen.",
	["How the selected tab is marked."] = "Hvordan den valgte fane markeres.",
	["How the text appears."] = "Hvordan teksten vises.",
	["How the text appears. With Animations off (General page) it just shows."] = "Hvordan teksten vises. Med Animationer slået fra (siden Generelt) vises den bare.",
	["How the text comes in: all at once, or a sentence at a time, fast or slow. A click on the text or Space shows all of it."] = "Hvordan teksten kommer frem: det hele på én gang eller en sætning ad gangen, hurtigt eller langsomt. Et klik på teksten eller Space viser det hele.",
	["How the text is colored. By type: damage red, healing green, misses white."] = "Hvordan teksten farves. Efter type: skade rød, heling grøn, miss hvid.",
	["How the time left is shown."] = "Hvordan den resterende tid vises.",
	["How the time left is shown. The game formats it; EldoUI never reads the time."] = "Hvordan den resterende tid vises. Spillet formaterer den; EldoUI læser aldrig tiden.",
	["How the time left is written. The game formats it; EldoUI only picks the format."] = "Hvordan den resterende tid skrives. Spillet formaterer den; EldoUI vælger kun formatet.",
	["How the time left shows on the icons."] = "Hvordan den resterende tid vises på ikonerne.",
	["How times are written in the log, tooltips and chat lines."] = "Hvordan tider skrives i loggen, tooltips og chatlinjer.",
	["How triggers with a flash light up the screen. Capped for comfort: at most one flash every half second."] = "Hvordan udløsere med blink lyser skærmen op. Begrænset af hensyn til komforten: højst ét blink hvert halve sekund.",
	["How visible a faded bar is."] = "Hvor synlig en udtonet bjælke er.",
	["How visible a missing aura's icon is."] = "Hvor synligt ikonet for en manglende aura er.",
	["How visible an icon is while its spell or item is on cooldown. 100 = fully visible."] = "Hvor synligt et ikon er mens dets evne eller genstand er på cooldown. 100 = helt synligt.",
	["How visible an icon is while the game says you can't cast it (not enough mana, rage or energy, or a missing requirement)."] = "Hvor synligt et ikon er mens spillet siger at du ikke kan caste det (ikke nok mana, rage eller energi eller et manglende krav).",
	["How visible DBM's bars stay."] = "Hvor synlige DBM's bjælker forbliver.",
	["How visible the idle edit box stays. 0 is invisible until you point at it or type."] = "Hvor synligt tekstfeltet er når det ikke bruges. 0 gør det usynligt indtil du peger på det eller skriver.",
	["HPS (damage meter)"] = "HPS (skademåler)",
	["Hunter"] = "Hunter",
	["Hunters: one message and sound when ammo drops below the amount below, again only after restocking."] = "Hunters: én besked og lyd når ammunitionen falder under mængden nedenfor, og først igen når du har fyldt op.",
	["Hybrid (druid)"] = "Hybrid (Druid)",
	["I died at level %d in %s."] = "Jeg døde på level %d i %s.",
	["I died at level %d."] = "Jeg døde på level %d.",
	["Icon art"] = "Ikonbillede",
	["Icon border"] = "Ikonkant",
	["Icon Mahjong"] = "Ikon-mahjong",
	["Icon picked. Its settings are in %s > Cooldown Manager."] = "Ikon valgt. Dets indstillinger findes i %s > Cooldown Manager.",
	["Icon pop"] = "Ikonpop",
	["Icon size"] = "Ikonstørrelse",
	["Icon size, capped by the frame height."] = "Ikonstørrelse, begrænset af rammens højde.",
	["Icon tiles"] = "Ikonfliser",
	["Icon zoom"] = "Ikonzoom",
	["Icons"] = "Ikoner",
	["Icons before names"] = "Ikoner foran navne",
	["Icons in %s"] = "Ikoner i %s",
	["Icons in EldoUI's cooldown rows while the game says the spell is off cooldown. Off by default."] = "Ikoner i EldoUI's cooldownrækker mens spillet siger at evnen er klar. Slået fra som standard.",
	["Icons in EldoUI's cooldown rows whose spell the game lights up (a proc or a reactive spell). Only the game's own spell alert starts it."] = "Ikoner i EldoUI's cooldownrækker hvis evne spillet lyser op (en proc eller en reaktiv evne). Kun spillets egen evneadvarsel starter det.",
	["Icons in one line before a new one starts."] = "Ikoner på én linje før en ny starter.",
	["Icons in one row (or bars in one column) before a new one starts."] = "Antal ikoner i en række (eller bjælker i en kolonne) før en ny begynder.",
	["Icons in one row (or column) before a new one starts."] = "Ikoner i én række (eller kolonne) før en ny begynder.",
	["Icons in one row before a new one starts."] = "Ikoner i én række før en ny begynder.",
	["Icons in rows, or one timer bar per aura with its icon, name and time."] = "Ikoner i rækker, eller én tidsbjælke pr. aura med dens ikon, navn og tid.",
	["Icons in your aura groups while the game marks the aura as safe to refresh early. Only auras the game marks ever glow."] = "Ikoner i dine auragrupper mens spillet markerer at auraen trygt kan fornyes før tid. Kun auraer som spillet markerer, kan gløde.",
	["Icons on item and spell links"] = "Ikoner på genstands- og evnelinks",
	["Icons only"] = "Kun ikoner",
	["Icons per line"] = "Ikoner pr. linje",
	["Icons per row"] = "Ikoner pr. række",
	["Icons right"] = "Ikoner til højre",
	["Icons show only while the aura is on; nothing marks a missing one."] = "Ikonerne vises kun mens auraen er aktiv; intet markerer en manglende aura.",
	["Icons slide to their new spot instead of jumping when an icon hides, shows or is dragged. With animations off (General) they jump."] = "Ikonerne glider til deres nye plads i stedet for at hoppe når et ikon skjules, vises eller trækkes. Med animationer slået fra (Generelt) hopper de.",
	["Icons that would touch split into an upper and a lower lane, so none hides another. Off keeps one line at full size. Either way, an icon with no room moves on a little and shows its seconds."] = "Ikoner der ville røre hinanden, deles i en øvre og en nedre bane, så ingen skjuler et andet. Fra: én linje i fuld størrelse. Et ikon uden plads rykker altid lidt videre og viser sine sekunder.",
	["Icons travel toward the other end: right on a horizontal bar, top on a vertical one."] = "Ikonerne bevæger sig mod den anden ende: mod højre på en vandret bjælke, opad på en lodret.",
	["Icons, or timer bars with the spell's icon, name and time. The game runs the time."] = "Ikoner, eller tidsbjælker med evnens ikon, navn og tid. Spillet styrer tiden.",
	["Id, name and source. Use the id with /eui sound."] = "Id, navn og kilde. Brug id'et med /eui sound.",
	["If missing, play"] = "Hvis den mangler, afspil",
	["Ignore when sorting"] = "Ignorer ved sortering",
	["iLvl"] = "iLvl",
	["Image file"] = "Billedfil",
	["Image opacity"] = "Billedets opacitet",
	["Immune"] = "Immune",
	["Imp"] = "Imp",
	["Import a dungeon route"] = "Importer en dungeonrute",
	["Import a Legacy build"] = "Importer et Legacy-build",
	["Import a route"] = "Importer en rute",
	["Import a shopping list"] = "Importer en indkøbsliste",
	["Import gathering nodes"] = "Importer indsamlingsnodes",
	["Import nodes"] = "Importer nodes",
	["Import this spec's set"] = "Importer denne specs sæt",
	["Imported %d bag categories."] = { one = "Importerede %d taskekategori.", other = "Importerede %d taskekategorier." },
	["Imported %d search terms."] = "%d søgeord er importeret.",
	["Imported route"] = "Importeret rute",
	["Imports EldoUI's Details profile for this layout through Details' own import, as \"EldoUI - <layout>\", and switches Details to it. Your own Details profiles stay in its list. Not in combat."] = "Importerer EldoUI's Details-profil til dette layout via Details' egen import som \"EldoUI - <layout>\" og skifter Details over til den. Dine egne Details-profiler bliver i listen. Ikke i kamp.",
	["Improve: turn on the game's buff duration display."] = "Forbedr: slå spillets visning af buffvarighed til.",
	["in %s"] = "om %s",
	["In a battleground the main bar's center shows your score and the fight time instead of its usual blocks."] = "I et battleground viser midten af hovedbjælken din score og kamptiden i stedet for de sædvanlige blokke.",
	["In a party"] = "I en gruppe",
	["In a raid"] = "I et raid",
	["In Alterac Valley, a small marker per mine in its owner's color."] = "I Alterac Valley en lille markør pr. mine i ejerens farve.",
	["In Alterac Valley, shows how many hand-in items you carry and who takes them. It never hands them in for you."] = "I Alterac Valley viser den hvor mange afleveringsgenstande du bærer på, og hvem der tager imod dem. Den afleverer dem aldrig for dig.",
	["In combat the game hides some stats from addons; they show \"%s\" until the fight ends."] = "I kamp skjuler spillet nogle stats for addons; de viser \"%s\" indtil kampen slutter.",
	["In combat: only results that need no secure click."] = "I kamp: kun resultater der ikke kræver et sikret klik.",
	["In fishing mode, out of combat, the second of two quick right-clicks casts Fishing."] = "I fisketilstand uden for kamp kaster det andet af to hurtige højreklik snøren.",
	["In groups too"] = "Også i grupper",
	["In hand: you %d, the Horde %d"] = "På hånden: du %d, Horden %d",
	["In its last seconds the next event moves off the bar into a big icon at the bar's now end."] = "I sine sidste sekunder flytter den næste hændelse fra bjælken over i et stort ikon ved bjælkens nu-ende.",
	["In log"] = "I loggen",
	["in progress"] = "i gang",
	["In public channels, say and yell: the same text from the same player within the time below shows only once. Off by default."] = "I offentlige kanaler og i sig og råb vises den samme tekst fra den samme spiller kun én gang inden for tiden nedenfor. Slået fra som standard.",
	["In the bag window"] = "I taskevinduet",
	["In the bank window"] = "I bankvinduet",
	["In the chat window (top edge)"] = "I chatvinduet (øverste kant)",
	["In the chat window the bar is as wide as the chat."] = "I chatvinduet er bjælken lige så bred som chatten.",
	["In the chat window: the bar fills the top edge of the chat box, as wide as the chat, and the messages and docked panels make room. Its own mover: drag it in move mode."] = "I chatvinduet: bjælken fylder chattens øverste kant, lige så bred som chatten, og beskederne og de dokkede paneler giver plads. Eget flyttefelt: træk den i flyttetilstand.",
	["In the stack"] = "I stakken",
	["In the stack with the other bars, or on its own mover (Resource Bar %d in move mode)."] = "I stakken med de andre bjælker, eller på sit eget flyttefelt (Ressourcebjælke %d i flyttetilstand).",
	["In which battleground do the Stormpike Guard and the Frostwolf Clan fight?"] = "I hvilket battleground kæmper Stormpike Guard og Frostwolf Clan?",
	["In which battleground do you capture the enemy's flag?"] = "I hvilket battleground skal du erobre fjendens flag?",
	["In which battleground do you hold the Stables, the Farm and the Lumber Mill?"] = "I hvilket battleground skal du holde Stables, Farm og Lumber Mill?",
	["In which dungeon or raid do you face %s?"] = "I hvilket dungeon eller raid møder du %s?",
	["In which starting area does a new %s wake up?"] = "I hvilket startområde vågner en ny %s op?",
	["In which zone does a new %s begin?"] = "I hvilken zone begynder en ny %s?",
	["In which zone is %s?"] = "I hvilken zone ligger %s?",
	["In which zone is Dalaran sealed under a magic dome?"] = "I hvilken zone er Dalaran lukket inde under en magisk kuppel?",
	["In which zone is the entrance to %s?"] = "I hvilken zone ligger indgangen til %s?",
	["Include an EldoUI note"] = "Medtag en EldoUI-note",
	["Include guild chat"] = "Medtag guildchat",
	["Include macros"] = "Medtag makroer",
	["Include offline crafters"] = "Medtag offline craftere",
	["Include pets"] = "Medtag pets",
	["Include this character"] = "Medtag denne karakter",
	["Incoming"] = "Indkommende",
	["Indicators"] = "Indikatorer",
	["Indoors"] = "Indendørs",
	["Indoors only"] = "Kun indendørs",
	["Inferno"] = "Inferno",
	["Info bar only"] = "Kun infobjælke",
	["Info bar with XP, zone and coordinates for questing."] = "Infobjælke med XP, zone og koordinater til questing.",
	["Inside a dungeon the window opens on it, and switches when you zone into another one while it is open."] = "Inde i et dungeon åbner vinduet på det og skifter når du går ind i et andet mens det er åbent.",
	["Inside a dungeon, the world map shows the game's painted map of your floor with the bosses listed beside it, instead of the empty instance map. Game map switches back."] = "Inde i en dungeon viser verdenskortet spillets malede kort over din etage med bosserne listet ved siden af, i stedet for det tomme instance-kort. Spillets kort skifter tilbage.",
	["Inside Edit Mode"] = "I Edit Mode",
	["Inside the power bar"] = "Inde i ressourcebjælken",
	["Inside the power bar as a strip along its bottom edge, as its own row in the stack, or as a strip under EldoUI's player frame."] = "Inde i ressourcebjælken som en strimmel langs den nederste kant, som sin egen række i stakken eller som en strimmel under EldoUI's spillerramme.",
	["Inside, bottom"] = "Indeni, nederst",
	["Inside, top"] = "Indeni, øverst",
	["Instance"] = "Instans",
	["Instance difficulty"] = "Instansens sværhedsgrad",
	["Instance Log"] = "Instanslog",
	["Instance run"] = "Instansrun",
	["Instances per day"] = "Instanser pr. dag",
	["Instances per hour"] = "Instanser pr. time",
	["Instances were reset by the leader (%s): %s."] = "Instanserne blev resat af lederen (%s): %s.",
	["Instant"] = "Øjeblikkelig",
	["Int"] = "Int",
	["Integrated"] = "Integreret",
	["Integrated, and each Edit Mode layout keeps its own EldoUI positions."] = "Integreret, og hvert Edit Mode-layout beholder sine egne EldoUI-placeringer.",
	["Integration off: EldoUI leaves RestedXP alone."] = "Integration fra: EldoUI lader RestedXP være.",
	["Integrations"] = "Integrationer",
	["Intellect"] = "Intellect",
	["Intensity"] = "Intensitet",
	["Interrupt color"] = "Afbrydelsesfarve",
	["into another group, between two icons, or onto empty screen for a free icon"] = "ind i en anden gruppe, mellem to ikoner eller ud på tom skærm som frit ikon",
	["inv please"] = "inv pls",
	["Inventory block in item tooltips"] = "Beholdningsblok i tooltips for genstande",
	["invites you"] = "inviterer dig",
	["It is added to your routes. Nothing you have is changed."] = "Den føjes til dine ruter. Intet af det du har, ændres.",
	["It is saved as a profile. Nothing is spent."] = "Det gemmes som en profil. Intet bruges.",
	["It points to the step's next goal, with the distance."] = "Den peger på trinnets næste mål og viser afstanden.",
	["It refused at %d entries."] = "Serveren afviste ved %d besøg.",
	["Item %d"] = "Genstand %d",
	["item %d"] = "genstand %d",
	["Item %s"] = "Genstand %s",
	["Item and spell links in chat show their icon in front of the name, at the height of the chat text. The link works as before."] = "Genstands- og evnelinks i chatten viser deres ikon foran navnet i chattekstens højde. Linket virker som før.",
	["Item cooldowns"] = "Cooldowns på genstande",
	["Item counts in tooltips"] = "Antal genstande i tooltips",
	["Item counts next to Baganator, Bagnon or ArkInventory"] = "Antal genstande sammen med Baganator, Bagnon eller ArkInventory",
	["Item counts per character are set on the Bags page and in the Tooltip sections. They also work while Bags is off."] = "Antal genstande pr. karakter indstilles på siden Tasker og i afsnittene om Tooltip. Optællingen virker også mens Tasker er slået fra.",
	["Item IDs (separated by commas) that the character tooltip counts as reagents, next to the class reagents EldoUI knows."] = "Genstands-ID'er (adskilt af kommaer) som karaktertooltippen tæller som reagenser ud over de klassereagenser EldoUI kender.",
	["Item level"] = "Item level",
	["Item level color"] = "Farve på item level",
	["Item level from"] = "Item level fra",
	["Item level on each slot"] = "Item level på hver plads",
	["Item level on gear"] = "Item level på udstyr",
	["Item level position"] = "Placering af item level",
	["Item level text size"] = "Tekststørrelse for item level",
	["Item level, durability, lockouts and gold. Opens on the Lockouts tab."] = "Item level, holdbarhed, lockouts og guld. Åbner på fanen Lockouts.",
	["Item level; \"lvl:20\" means 20 or more"] = "Genstandsniveau; \"lvl:20\" betyder 20 eller mere",
	["Item lists"] = "Genstandslister",
	["Item marks"] = "Genstandsmærker",
	["Item names or IDs, separated by commas, in the order they should show (for example Major Healing Potion, 5512). Names work for items in your bags."] = "Genstandsnavne eller -ID'er adskilt af kommaer i den rækkefølge de skal vises (fx Major Healing Potion, 5512). Navne virker for genstande i dine tasker.",
	["Item names or IDs, separated by commas, that always show."] = "Genstandsnavne eller ID'er der altid vises, adskilt af kommaer.",
	["Item names or IDs, separated by commas, that never show."] = "Genstandsnavne eller ID'er der aldrig vises, adskilt af kommaer.",
	["Item quality"] = "Genstandskvalitet",
	["Item ready"] = "Genstand klar",
	["Item row"] = "Genstandsrække",
	["Item rows take the item's quality color on their border."] = "Genstandsrækker får genstandens kvalitetsfarve på kanten.",
	["Item score"] = "Genstandsscore",
	["Item slots"] = "Genstandspladser",
	["Item type, subtype or slot"] = "Genstandstype, undertype eller plads",
	["Item value"] = "Genstandsværdi",
	["Item, %d in your bags"] = "Genstand, %d i dine tasker",
	["Item, none in your bags"] = "Genstand, ingen i dine tasker",
	["Items"] = "Genstande",
	["Items and their value"] = "Genstande og deres værdi",
	["Items attached to mail in the mailbox, as of the last visit."] = "Genstande vedhæftet breve i postkassen, fra det seneste besøg.",
	["Items below this quality are left out of the post."] = "Genstande under denne kvalitet kommer ikke med i beskeden.",
	["Items below this quality are not shown."] = "Genstande under denne kvalitet vises ikke.",
	["Items below this quality keep the plain border."] = "Genstande under denne kvalitet beholder den almindelige kant.",
	["Items bound to you"] = "Genstande bundet til dig",
	["Items for quests and items that start one."] = "Genstande til quests og genstande der starter en.",
	["Items in one of your equipment sets get a small mark in the bottom corner."] = "Genstande i et af dine udstyrssæt får et lille mærke i det nederste hjørne.",
	["Items in the bags, bank and mailbox. The Bags button opens the Bags module's own windows on this character."] = "Genstande i tasker, bank og postkasse. Knappen Tasker åbner Tasker-modulets egne vinduer for denne karakter.",
	["Items in the bags."] = "Genstande i taskerne.",
	["Items in the bank, as of the last visit."] = "Genstande i banken, fra det seneste besøg.",
	["Items in the guild bank tabs a character of yours opened."] = "Genstande i de guildbankfaner som en af dine karakterer har åbnet.",
	["Items in your bags that have a use. Your click or Enter on the result uses it."] = "Genstande i dine tasker der kan bruges. Dit klik eller Enter på resultatet bruger den.",
	["Items looted"] = "Lootede genstande",
	["Items looted, and items per hour."] = "Lootede genstande og genstande pr. time.",
	["Items new in your bags"] = "Genstande der er nye i dine tasker",
	["Items on this list never get an action. Modifier + right-click an item with a glow to add it, or type it here."] = "Genstande på denne liste får aldrig en handling. Ændringstast + højreklik på en genstand med glød for at tilføje den, eller skriv den her.",
	["Items per hour"] = "Genstande pr. time",
	["Items that always or never show."] = "Genstande der altid eller aldrig vises.",
	["Items that bind when equipped and are not bound yet"] = "Genstande der bindes når de tages på og ikke er bundet endnu",
	["Items that bind when picked up"] = "Genstande der bindes når de samles op",
	["Items the character has on the auction house, as of the last visit."] = "Genstande karakteren har i auktionshuset, fra det seneste besøg.",
	["Items this search finds go into the category. The bag window's Search help lists every word."] = "Genstande denne søgning finder kommer i kategorien. Taskevinduets søgehjælp viser alle ordene.",
	["Items waiting in the mailbox; red when a mail returns or is deleted within 5 days."] = "Genstande der venter i postkassen; rød når et brev sendes retur eller slettes inden for 5 dage.",
	["Items whose name has the word"] = "Genstande hvis navn har ordet",
	["items worth %s"] = "genstande til en værdi af %s",
	["Items you create, such as crafted goods and conjured food."] = "Genstande du laver, for eksempel craftede varer og fremmanet mad.",
	["Items you just got glow until you close your bags."] = "Genstande du lige har fået, gløder indtil du lukker dine tasker.",
	["Items you just got, until you close your bags."] = "Genstande du lige har fået (indtil du lukker dine tasker).",
	["Items you left out of this category from a section title's menu. Forgetting them lets its search find them again."] = "Genstande du har udeladt fra kategorien via en afsnitstitels menu. Glemmer du dem, kan dens søgning finde dem igen.",
	["Items you loot, receive or create."] = "Genstande du looter, modtager eller crafter.",
	["Items you loot. Only while EldoUI's loot toasts are off, unless you check the option on the Loot and Info tab."] = "Genstande du looter. Kun mens EldoUI's pop op-beskeder om loot er slået fra medmindre du sætter flueben ved indstillingen på fanen Loot og info.",
	["Items you make"] = "Genstande du laver",
	["Items, money and currencies show only while EldoUI's loot toasts are off, so nothing shows twice. XP, honor and reputation always can."] = "Genstande, penge og valutaer vises kun mens EldoUI's pop op-beskeder om loot er slået fra, så intet vises to gange. XP, ære og omdømme kan altid vises.",
	["Its own mover"] = "Eget flyttefelt",
	["Its own mover: drag it in move mode. In the chat window (up to three, the docked second info bar counts as one) or on the minimap (two): it sits inside the edge, moves along and the frame makes room."] = "Eget flyttefelt: træk det i flyttetilstand. I chatvinduet (op til tre, den dokkede anden infobjælke tæller som én) eller på minikortet (to): panelet sidder inden for kanten, flytter med, og rammen giver plads.",
	["Its own position"] = "Sin egen placering",
	["Its own sound for a legendary item. None plays the sound above."] = "En egen lyd for en legendarisk genstand. Ingen spiller lyden ovenfor.",
	["Its packs are not in your dungeon data."] = "Dens packs findes ikke i dine dungeondata.",
	["Its saved bags, bank, gold, mail, auctions, professions, quests, lockouts, level log, wishlist and journal leave EldoUI. Its journal is backed up first, and the Saved data page can put it back or remove it. Log in on it again to record it anew."] = "Dens gemte tasker, bank, guld, post, auktioner, fag, quests, lockouts, levellog, ønskeliste og journal fjernes fra EldoUI. Journalen sikkerhedskopieres først, og siden Gemte data kan lægge den tilbage eller fjerne den. Log ind på den igen for at registrere den på ny.",
	["Its search alone fills it."] = "Kun dens søgning fylder den.",
	["Join a group first, or pick Guild under Ask and share with."] = "Kom først i en gruppe, eller vælg Guild under Spørg og del med.",
	["Join a guild first, or pick Group under Ask and share with."] = "Kom først i en guild, eller vælg Gruppe under Spørg og del med.",
	["Join each pair of runes with a line and fill every cell."] = "Forbind hvert runepar med en linje, og fyld alle felter.",
	["Join order (no grouping)"] = "Tilslutningsrækkefølge (ingen gruppering)",
	["Join similar hits"] = "Saml ens hits",
	["Join the pull before"] = "Slå sammen med pullet før",
	["Join the pulls of the picked route with a line in each pull's color."] = "Forbind pulls i den valgte rute med en linje i hvert pulls farve.",
	["Join window"] = "Samleinterval",
	["Joined %d of %d"] = "Forbundet %d af %d",
	["Joined in %d strokes"] = { one = "Forbundet med %d streg", other = "Forbundet med %d streger" },
	["Joins hits of the same kind that land within a moment into one line."] = "Samler hits af samme slags der lander inden for et øjeblik, til én linje.",
	["Journal moment"] = "Journaløjeblik",
	["Journeyman campfire"] = "Journeyman-lejrbål",
	["Jump a rune over its neighbor into an empty hole."] = "Hop en rune over naboen ned i et tomt hul.",
	["Jump and take the Horde's pieces; crown yours on the far row."] = "Spring over og tag Hordens brikker; kron dine på den fjerne række.",
	["Jump runes over each other until one is left."] = "Hop runer over hinanden, til der er én tilbage.",
	["Jump to newest button"] = "Knap til nyeste linje",
	["Jump to the newest line"] = "Hop til nyeste linje",
	["Jumps back to today."] = "Hopper tilbage til i dag.",
	["just now"] = "for et øjeblik siden",
	["Just the camp lines on tooltips."] = "Kun lejrlinjerne i tooltips.",
	["Just the panel; the UI and world stay as they are."] = "Kun panelet; brugerfladen og spilverdenen forbliver som de er.",
	["Kalimdor"] = "Kalimdor",
	["Keep a hidden-lines log"] = "Før log over skjulte linjer",
	["Keep after combat"] = "Behold efter kamp",
	["Keep after rolling"] = "Bliv efter rul",
	["Keep and open on the map"] = "Behold og åbn på kortet",
	["Keep both"] = "Behold begge",
	["Keep buff food"] = "Spar på buffmad",
	["Keep chat between sessions"] = "Behold chatten mellem sessioner",
	["Keep drafts"] = "Gem kladder",
	["Keep Edit Mode's positions"] = "Behold Edit Modes placeringer",
	["Keep EldoUI's played request out of chat"] = "Hold EldoUI's forespørgsel om spilletid ude af chatten",
	["Keep game setting"] = "Behold spillets indstilling",
	["Keep it in line with the layout"] = "Hold den i trit med layoutet",
	["Keep only %d lines per window?\n\n%d saved chat lines are deleted."] = "Behold kun %d linjer pr. vindue?\n\n%d gemte chatlinjer slettes.",
	["Keep partial stacks apart"] = "Hold halve stakke for sig",
	["Keep the card shown outside dungeons with the dungeon you were in last, to plan the next run."] = "Vis fortsat kortet uden for dungeons med det dungeon du sidst var i, så du kan planlægge næste run.",
	["Keep the current look"] = "Behold det nuværende udseende",
	["Keep these at their rank"] = "Behold disse på deres rang",
	["Keep this route as one of yours, to name it, label and color its pulls, and share it."] = "Gem ruten som en af dine egne så du kan navngive den, give dens pulls etiketter og farver og dele den.",
	["Keep this zone's nodes out of minimap range on its edge instead of hiding them."] = "Vis zonens nodes uden for minikortets rækkevidde på kanten i stedet for at skjule dem.",
	["Keep your own frame visible when not in a group."] = "Hold din egen ramme synlig når du ikke er i en gruppe.",
	["Keeps Blizzard's alternating row shading in the stats."] = "Beholder Blizzards skiftevis skyggede rækker i stats.",
	["Keeps the swipe this many pixels inside the icon edge."] = "Holder swipen så mange pixels inden for ikonets kant.",
	["Kept"] = "Beholdt",
	["Kept in RestedXP: the guide stays where RestedXP puts it."] = "Bevaret i RestedXP: guiden bliver der hvor RestedXP sætter den.",
	["Kept in the SavedVariables file after /reload (the last %d dumps)."] = { one = "Bevares i SavedVariables-filen efter /reload (det seneste %d dump).", other = "Bevares i SavedVariables-filen efter /reload (de seneste %d dumps)." },
	["Key and mouse wheel bindings work while the mouse is over an EldoUI frame."] = "Taste- og musehjulsbindinger virker mens du holder musen over en EldoUI-ramme.",
	["Key and wheel bindings work once \"Keys and wheel on hover\" is on."] = "Taste- og hjulbindinger virker når \"Taster og hjul under musen\" er slået til.",
	["Key cooldowns"] = "Vigtige cooldowns",
	["Keybind"] = "Genvejstast",
	["Keybind color"] = "Farve på genvejstast",
	["Keybind mode: hover a button and press a key. The icons show the keys of their spells."] = "Genvejstasttilstand: hold musen over en knap, og tryk på en tast. Ikonerne viser tasterne for deres evner.",
	["Keybind position"] = "Placering af genvejstast",
	["Keybind size"] = "Størrelse på genvejstast",
	["Keybind text on the icons and the visibility rules."] = "Genvejstasttekst på ikonerne og synlighedsreglerne.",
	["Keybinds"] = "Genvejstaster",
	["Keybinds and charges in the corners, at the layout's own button size."] = "Genvejstaster og ladninger i hjørnerne, i layoutets egen knapstørrelse.",
	["Keybinds plus the macro name on each button, at the layout's own button size."] = "Genvejstaster plus makronavnet på hver knap, i layoutets egen knapstørrelse.",
