	["Keys outside the keyring."] = "Nøgler uden for nøgleringen.",
	["Keyword alert"] = "Advarsel ved nøgleord",
	["Keyword, whisper and channel sounds and the taskbar flash are skipped while you are in combat. They are not played afterwards. The game's own whisper sound is not affected."] = "Lyde for nøgleord, hvisk og kanaler og blink på proceslinjen springes over mens du er i kamp. Lydene afspilles ikke bagefter. Spillets egen hviskelyd påvirkes ikke.",
