	["Landing closes the window it opened in flight; your best score is kept. Off: play on after landing."] = "Landing lukker vinduet hvis det blev åbnet under flyvningen; din bedste score gemmes. Fra: spil videre efter landing.",
	["Lands in %s"] = "Lander om %s",
