	["Layout:"] = "Layout:",
	["Layouts place Details!, RestedXP guides, BigWigs bars and Questie's tracker, with an EldoUI look where the addon allows it."] = "Layouts placerer Details!, RestedXP-guider, BigWigs-bjælker og Questies tracker med et EldoUI-udseende hvor addonen tillader det.",
	["Layouts place every window, but each addon keeps its own look."] = "Layouts placerer alle vinduer, men hver addon beholder sit eget udseende.",
