	["Leave vehicle button"] = "Knap til at forlade køretøj",
	["Leaves the summary out when the run gave no experience, kills, gold, reputation or currency."] = "Udelader oversigten når runnet ikke gav erfaring, drab, guld, omdømme eller valuta.",
	["Leaving"] = "Når du går ud",
	["Leaving combat"] = "Forlader kamp",
	["Left %s: %s"] = "Forlod %s: %s",
	["Left and right move the cursor in the edit box without holding Alt. Up and down still browse what you typed."] = "Venstre- og højrepil flytter markøren i tekstfeltet uden at holde Alt nede. Op- og nedpil bladrer stadig i det du har skrevet.",
	["Left and right or the mouse: fly. Space, Up or a click: shoot. P: pause."] = "Venstre og højre eller musen: flyv. Mellemrum, op eller et klik: skyd. P: pause.",
	["Left and right: move. Up: turn. Down: drop faster. Space: drop. P: pause."] = "Venstre og højre: flyt. Op: drej. Ned: fald hurtigere. Mellemrum: slip. P: pause.",
	["Left and Right: turn. Up: fly. Space or a click: fire. P: pause."] = "Venstre og Højre: drej. Op: flyv. Mellemrum eller et klik: skyd. P: pause.",
	["Left click"] = "Venstreklik",
	["Left groups"] = "Venstrestillede grupper",
