	["Legacy Challenges with progress, filters and search."] = "Legacy-udfordringer med fremskridt, filtre og søgning.",
	["Legacy draft"] = "Legacy-kladde",
	["Legacy isn't on this client"] = "Legacy findes ikke i denne klient",
