	["Legacy points spent of the points the character had, as of its last login (Legacy Planner)."] = "Brugte Legacy-point ud af de point karakteren havde, fra dens seneste login (Legacy-planlægger).",
	["Legacy probe (what this client answers):"] = "Legacy-probe (hvad denne klient svarer):",
	["Legacy profiles"] = "Legacy-profiler",
	["Legacy unlocks with your first Legacy level. Open Blizzard's Legacy window once, then open the planner again."] = "Legacy låses op med dit første Legacy-level. Åbn Blizzards Legacy-vindue én gang, og åbn så planlæggeren igen.",
	["LEGACY_TREE_ADVENTURE"] = "LEGACY_TREE_ADVENTURE",
	["LEGACY_TREE_PROFESSIONS"] = "LEGACY_TREE_PROFESSIONS",
