	["Legendary!"] = "Legendarisk!",
	["Length of each of the four bars, in pixels."] = "Længden af hver af de fire bjælker i pixels.",
	["Length of your current or last fight."] = "Længden af din nuværende eller sidste kamp.",
	["Let Blizzard draw private auras next to EldoUI's debuffs."] = "Lad Blizzard tegne private auraer ved siden af EldoUI's debuffs.",
	["Lets EldoUI place and frame Details' windows. Off: EldoUI leaves Details alone."] = "Lader EldoUI placere og indramme Details' vinduer. Fra: EldoUI lader Details være.",
	["Lets EldoUI place Questie's quest tracker. Off: EldoUI leaves Questie alone."] = "Lader EldoUI placere Questies questtracker. Fra: EldoUI lader Questie være.",
	["Lets EldoUI place the guide window and offer its theme. Off: EldoUI leaves RestedXP alone."] = "Lader EldoUI placere guidevinduet og tilbyde EldoUI-temaet. Fra: EldoUI lader RestedXP være.",
	["Letters of the name to show, counted after the Name format (General page). Accents and other alphabets stay whole."] = "Antal bogstaver af navnet der vises, talt efter navneformatet (siden Generelt). Accenter og andre alfabeter forbliver hele.",
	["Letters that run out go back to the sender or are deleted. Log in on that character and empty its mailbox."] = "Breve der udløber sendes retur til afsenderen eller slettes. Log ind på den karakter og tøm dens postkasse.",
	["Level"] = "Level",
