	["Light line"] = "Lyslinje",
	["Light the Braziers"] = "Tænd fyrfadene",
	["Light the runes again in the order they lit; one more each round."] = "Tænd runerne igen i den rækkefølge de lyste; én mere hver runde.",
	["Light trail"] = "Lysspor",
	["Light up the action buttons that hold a lower rank of a spell you know at a higher rank. Its look is on the Glows page (Lower spell ranks)."] = "Lys de handlingsknapper op der har en lavere rang af en evne du kender i en højere rang. Udseendet findes på siden Glød (Evner i lavere rang).",
	["Like every EldoUI clock"] = "Som alle EldoUI-ure",
	["Like the rest of EldoUI"] = "Som resten af EldoUI",
	["Line at"] = "Grænse ved",
	["Line color"] = "Stregfarve",
	["Line in my chat"] = "Linje i min chat",
	["Line opacity"] = "Linjens opacitet",
	["Line spacing"] = "Linjeafstand",
	["Line width"] = "Linjebredde",
	["Lines between cells"] = "Streger mellem felterne",
	["Lines hidden from muted guilds in the last 15 minutes, newest first. Kept in memory only."] = "Linjer fra dæmpede guilds der er skjult inden for de sidste 15 minutter, nyeste først. Gemmes kun i hukommelsen.",
	["Lines in your own chat window. Nothing here is sent to other players."] = "Linjer i dit eget chatvindue. Intet her sendes til andre spillere.",
	["Lines kept per window"] = "Linjer pr. vindue",
	["Lines like \"Name creates Item.\" from players near you stay out of chat, so the Loot tab shows only what you craft yourself. Your own crafts always show."] = "Linjer som \"Name creates Item.\" fra spillere nær dig holdes ude af chatten, så Loot-fanen kun viser det du selv crafter. Dine egne crafts vises altid.",
	["Lines per second"] = "Linjer pr. sekund",
	["Lines saved per window"] = "Gemte linjer pr. vindue",
	["Lines shown"] = "Viste linjer",
	["Lines start at the bar"] = "Linjerne starter ved bjælken",
	["Lines that mention a keyword are highlighted and can play a sound. Works outside chat lockdown only; EldoUI never replies for you."] = "Linjer der nævner et nøgleord, fremhæves og kan afspille en lyd. Virker kun uden for chatlåsning; EldoUI svarer aldrig for dig.",
	["Lines with one of these words are highlighted and play the word's sound. With the Alerts tab on they are copied there too. Upper and lower case don't matter."] = "Linjer med et af disse ord fremhæves og afspiller ordets lyd. Når Alerts-fanen er slået til, kopieres de også dertil. Store og små bogstaver er ligegyldige.",
	["Lines with one of these words or phrases are hidden (ignoring upper and lower case). Test a line below before you add a phrase."] = "Linjer med et af disse ord eller en af disse fraser skjules (uanset store og små bogstaver). Test en linje nedenfor før du tilføjer en frase.",
	["Linger"] = "Linger",
	["Link"] = "Link",
	["Link button"] = "Link-knap",
	["Link color"] = "Linkfarve",
	["link it in chat"] = "link den i chatten",
	["Link to"] = "Link til",
	["Link tooltips on hover"] = "Linktooltips når du holder musen over",
	["Links"] = "Links",
	["Links in accent color"] = "Links i accentfarve",
	["List \"Open menu\" clicks too"] = "Vis også \"Åbn menu\"-klik",
	["List every frame placed by both, in chat (also /eui editmode)."] = "Vis alle rammer der placeres af begge, i chatten (også /eui editmode).",
	["List text size"] = "Tekststørrelse i lister",
	["List the action slots that hold a lower rank and light them up for a moment. Same as /eui rankcheck."] = "Vis de handlingspladser der har en lavere rang, og lys dem op et øjeblik. Det samme som /eui rankcheck.",
	["List the runs of your other characters too, in gray."] = "Vis også dine andre karakterers runs, i gråt.",
	["List whispers"] = "Vis hviskebeskeder",
	["Listen for routes people in your party or raid send. They wait in the From your group list of the Dungeons window until you keep or dismiss one. Nothing is ever sent back. Off by default."] = "Lyt efter ruter som folk i din gruppe eller dit raid sender. Ruterne venter i listen Fra din gruppe i dungeonvinduet indtil du beholder eller afviser en. Intet sendes nogensinde tilbage. Fra som standard.",
	["Listen for routes people in your party or raid send. They wait in this list until you keep or dismiss them; nothing is ever sent back."] = "Lyt efter ruter som folk i din gruppe eller dit raid sender. De venter i listen indtil du beholder eller afviser dem; der sendes aldrig noget tilbage.",
	["Listen in"] = "Hold øje med",
	["Lists"] = "Lister",
	["Lists hostile players whose nameplates you see; never targets them. Needs enemy nameplates. Off by default: turn it on under Modules."] = "Viser fjendtlige spillere hvis nameplates du kan se; vælger dem aldrig som mål. Kræver fjendtlige nameplates. Slået fra som standard: slå det til under Moduler.",
	["Lists how many of the item each character has, per location."] = "Viser hvor mange af genstanden hver karakter har, pr. sted.",
	["Lists the action buttons that hold a lower rank of a spell you know and lights them up."] = "Viser de handlingsknapper der har en lavere rang af en evne du kender, og lyser dem op.",
	["Lists which Blizzard frames EldoUI places, hides or replaces, and any conflicts."] = "Viser hvilke Blizzard-rammer EldoUI placerer, skjuler eller erstatter, og eventuelle konflikter.",
	["Lists your group on the threat table of your target or focus, as the game reports it. Where the game hides threat, the window says so."] = "Viser din gruppe på aggrotabellen for dit mål eller fokus efter hvad spillet melder. Hvor spillet skjuler aggro, siger vinduet det.",
	["Lit in %d touches"] = { one = "Tændt med %d tryk", other = "Tændt med %d tryk" },
