	["Locked backpack slots"] = "Låste pladser i rygsækken",
	["Locked bars only let you drag a spell off while you hold the pick-up key, on EldoUI's and Blizzard's bars alike. Game setting leaves Options > Action Bars > Lock action bars as it is."] = "Låste linjer lader dig kun trække en evne af mens du holder tasten til at samle op nede, på både EldoUI's og Blizzards linjer. Spillets indstilling lader Options > Action Bars > Lock action bars være som den er.",
	["Locked boxes your Lockpicking skill can open. Rogues only."] = "Låste kasser som din Lockpicking-skill kan åbne. Kun Rogues.",
