	["Log in"] = "Du logger ind",
	["Log in on this character and open the profession window once; its recipes are saved then."] = "Log ind på denne karakter, og åbn fagvinduet én gang; så gemmes opskrifterne.",
	["Log in on your other characters once; each one records itself and shows up here."] = "Log ind på dine andre karakterer én gang; hver af dem registrerer sig selv og dukker op her.",
	["Log only"] = "Kun log",
	["Log panel"] = "Logpanel",
	["Log the deaths guild members tell the guild about with EldoUI. Notes are accepted from guild members only and never answered."] = "Log de dødsfald som guildmedlemmer fortæller guilden om via EldoUI. Noter tages kun imod fra guildmedlemmer og besvares aldrig.",
	["Logged in inside %s: %s."] = "Logget ind i %s: %s.",
	["Long chat messages in parts you send one Enter at a time, undo and redo, draft recovery and an opt-in party \"is typing\" line."] = "Lange chatbeskeder i dele som du sender med ét tryk på Enter ad gangen, fortryd og gentag, gendannelse af kladder og en valgfri \"skriver\"-linje for gruppen.",
	["Long horizontal bars; the raid in four columns of ten."] = "Lange vandrette bjælker; raidet i fire kolonner på ti.",
	["Long list for open-world PvP: 15 rows, quick to forget."] = "Lang liste til PvP i den åbne verden: 15 rækker, glemmer hurtigt.",
	["Long messages"] = "Lange beskeder",
