	["Make a shopping list of its reagents"] = "Lav en indkøbsliste over dens reagenser",
	["Make the nearest inn your home"] = "Gør den nærmeste kro til dit hjem",
	["Make your own categories with a name, color, search and place. Drop an item on a section title in the bag window to file it there."] = "Lav dine egne kategorier med navn, farve, søgning og plads. Slip en genstand på en afsnitstitel i taskevinduet for at lægge den dér.",
	["Makes a copy of this theme to change freely."] = "Laver en kopi af temaet som du frit kan ændre.",
	["Makes a string of your alt list on this realm (name, class, level, item level) to give to a friend."] = "Laver en streng af din altliste på denne realm (navn, klasse, level, item level) som du kan give til en ven.",
	["Makes DBM's bars see-through while the timeline is on, through EldoUI's DBM profile. DBM keeps them, so turning this off brings them back. Needs EldoUI's DBM profile."] = "Gør DBM's bjælker gennemsigtige mens tidslinjen er slået til, via EldoUI's DBM-profil. DBM beholder dem, så de kommer tilbage når du slår dette fra. Kræver EldoUI's DBM-profil.",
	["Makes the Alerts tab now (outside combat) and shows it. Close it like any chat tab; the next match makes it again while this option is on."] = "Opretter Alerts-fanen nu (uden for kamp) og viser den. Luk den som enhver anden chatfane; næste match opretter den igen mens denne indstilling er slået til.",
