	["Map %s points of interest:"] = "Kort %s, interessepunkter:",
	["Map art"] = "Kortgrafik",
	["Map art shows the game's own dungeon map when its edges are known. Schematic places the packs on a plain grid by where they stand. Automatic picks the map art when it can."] = "Kortgrafik viser spillets eget dungeonkort når dets kanter er kendt. Skematisk placerer packs på et enkelt gitter efter hvor de står. Automatisk vælger kortgrafikken når det kan lade sig gøre.",
