	["Markdown with the context. Press Ctrl+C and paste it into a new issue."] = "Markdown med konteksten. Tryk på Ctrl+C, og indsæt den i et nyt issue.",
	["Marker scale"] = "Markørskala",
	["Marks item buttons with whether you have the item's appearance. The game gives every answer; EldoUI only shows it."] = "Markerer genstandsknapper med om du har genstandens udseende. Spillet giver alle svarene; EldoUI viser dem kun.",
	["Marks items in the loot window and on loot rolls."] = "Markerer genstande i lootvinduet og ved lootrul.",
	["Marks items in your bags and bank (EldoUI's and Blizzard's)."] = "Markerer genstande i dine tasker og din bank (EldoUI's og Blizzards).",
	["Marks items whose appearance is in your collection."] = "Markerer genstande hvis udseende er i din samling.",
	["Marks items whose appearance you don't have yet and can collect."] = "Markerer genstande hvis udseende du ikke har endnu, men kan samle.",
	["Marks items whose look you already have from another item."] = "Markerer genstande hvis udseende du allerede har fra en anden genstand.",
	["Marks members with a debuff that can be dispelled. The game decides which debuffs count."] = "Markerer medlemmer med en debuff der kan dispelles. Spillet afgør hvilke debuffs der tæller.",
	["Marks the first item of each letter in the inbox and the items of an open letter."] = "Markerer den første genstand i hvert brev i indbakken og genstandene i et åbent brev.",
	["Marks the items a vendor sells."] = "Markerer de genstande en købmand sælger.",
	["Marks the items in EldoUI's Shopping, Selling and Canceling lists at the auction house."] = "Markerer genstandene i EldoUI's lister Indkøb, Salg og Annullering i auktionshuset.",
	["Marks while the bar shows energy. Write values (40, 80), percents (50%), every N (every 20) or every N percent (every 25%). Empty = no marks."] = "Streger mens bjælken viser energi. Skriv værdier (40, 80), procenter (50%), for hver N (skriv every 20) eller for hver N procent (skriv every 25%). Tomt = ingen streger.", -- l10n: keep
	["Marks while the bar shows mana. Write values (40, 80), percents (50%), every N (every 20) or every N percent (every 25%). Empty = no marks."] = "Streger mens bjælken viser mana. Skriv værdier (40, 80), procenter (50%), for hver N (skriv every 20) eller for hver N procent (skriv every 25%). Tomt = ingen streger.", -- l10n: keep
	["Marks while the bar shows rage. Write values (40, 80), percents (50%), every N (every 20) or every N percent (every 25%). Empty = no marks."] = "Streger mens bjælken viser rage. Skriv værdier (40, 80), procenter (50%), for hver N (skriv every 20) eller for hver N procent (skriv every 25%). Tomt = ingen streger.", -- l10n: keep
	["Marks you as passing and says \"pass\" once in party or raid chat."] = "Markerer at du passer, og skriver \"pas\" én gang i gruppe- eller raidchatten.",
