	["Master switch for blocked phrases, the Cyrillic filter and channel mutes. Off pauses them; the lists stay saved. The editors show whether they are on."] = "Hovedkontakt for blokerede fraser, det kyrilliske filter og dæmpede kanaler. Fra sætter dem på pause; listerne forbliver gemt. Editorerne viser om de er slået til.",
