	["None of these characters had a quest in the log at logout."] = "Ingen af disse karakterer havde en quest i loggen ved logout.",
	["None of these characters had auctions running at their last auction house visit."] = "Ingen af disse karakterer havde aktive auktioner ved deres seneste besøg i auktionshuset.",
	["None of these characters had bids at their last auction house visit."] = "Ingen af disse karakterer havde bud ved deres seneste besøg i auktionshuset.",
	["None of these characters had mail at their last mailbox visit. Mail you send to your own characters shows up at once."] = "Ingen af disse karakterer havde post ved deres seneste besøg ved postkassen. Post du sender til dine egne karakterer, vises med det samme.",
	["None of these characters has saved anything for this grid yet."] = "Ingen af disse karakterer har gemt noget til denne tabel endnu.",
	["None of your characters has a matching item in the places picked above. Banks, mail and auctions show what each character saw on its last visit."] = "Ingen af dine karakterer har en matchende genstand de steder der er valgt ovenfor. Bank, post og auktioner viser hvad hver karakter så ved sit seneste besøg.",
	["None of your characters is saved to an instance right now. Lockouts show here after each character logs in (or opens the raid info)."] = "Ingen af dine karakterer er låst til en instans lige nu. Lockouts vises her når hver karakter har logget ind (eller åbnet raidinfoen).",
	["None picked"] = "Ingen valgt",
	["None tracked"] = "Ingen sporet",
	["None watched"] = "Ingen fulgt",
	["not a route"] = "ikke en rute",
	["Not a run"] = "Ikke et run",
	["Not available in this client."] = "Ikke tilgængelig i denne klient.",
	["Not available in this game client: aura alarms are off. Breath, fatigue and AFK alarms still work."] = "Ikke tilgængelig i denne spilklient: auraalarmer er slået fra. Alarmer for åndedræt, udmattelse og AFK virker stadig.",
	["Not chosen yet: %s"] = "Har ikke valgt endnu: %s",
	["not collected"] = "ikke i samlingen",
	["Not enough gold"] = "Ikke nok guld",
	["Not enough power color"] = "Farve for manglende ressource",
	["Not found. Use an item link or ID, a currency link, c<currency ID>, or a currency name."] = "Ikke fundet. Brug et genstandslink eller -ID, et valutalink, c<valuta-ID> eller et valutanavn.",
	["not given"] = "ikke oplyst",
	["Not in an instance."] = "Ikke i en instans.",
	["Not in combat."] = "Ikke i kamp.",
	["Not in the route"] = "Ikke i ruten",
	["Not placed: another guide is selected for the guide spot."] = "Ikke placeret: en anden guide er valgt til guidepladsen.",
	["Not placed: the guide spot goes to the guide you picked on Eldostar's page."] = "Ikke placeret: guidepladsen går til den guide du valgte på Eldostars side.",
	["Not played yet"] = "Ikke spillet endnu",
	["Not quite. The answer was %s."] = "Ikke helt. Svaret var %s.",
	["Not reset: %s."] = "Ikke resat: %s.",
	["not seen yet"] = "ikke set endnu",
	["Not set"] = "Ikke valgt",
	["not set (the addon's default)"] = "ikke angivet (addonens standard)",
	["Not set up: EldoUI changes nothing in DBM until you click \"Set up DBM for EldoUI\"."] = "Ikke sat op: EldoUI ændrer intet i DBM før du klikker på \"Opsæt DBM til EldoUI\".",
	["Not started"] = "Ikke startet",
	["Not usable color"] = "Farve når den ikke kan bruges",
	["Not used by your class"] = "Bruges ikke af din klasse",
	["Not: leaves out what the word finds"] = "Ikke: udelader det ordet finder",
	["Note when a camp buff starts"] = "Besked når en lejrbuff starter",
	["Notes and drawings"] = "Noter og tegninger",
	["Nothing found on any character."] = "Intet fundet på nogen karakter.",
	["Nothing found."] = "Intet fundet.",
	["Nothing here can go there."] = "Intet herfra kan flyttes dertil.",
	["Nothing here yet."] = "Intet her endnu.",
	["Nothing in this log yet."] = "Intet i denne log endnu.",
	["Nothing is damaged."] = "Intet er beskadiget.",
	["Nothing is filtered"] = "Intet filtreres",
	["Nothing is spent."] = "Intet bruges.",
	["Nothing matches the filters. Turn on Alts or turn off 24 h to see more."] = "Intet passer til filtrene. Slå Alts til, eller slå 24 t fra for at se mere.",
	["nothing recorded"] = "intet registreret",
	["Nothing saved"] = "Intet gemt",
	["Nothing this day"] = "Intet denne dag",
	["Nothing to copy: search for something first."] = "Intet at kopiere: søg efter noget først.",
	["Nothing to import."] = "Intet at importere.",
	["Nothing to show"] = "Intet at vise",
	["Nothing was hidden."] = "Intet blev skjult.",
	["Nothing watched yet."] = "Intet overvåges endnu.",
	["Nothing yet: EldoUI leaves every Edit Mode frame to Blizzard."] = "Intet endnu: EldoUI overlader alle Edit Mode-rammer til Blizzard.",
	["Notice when a route arrives"] = "Besked når en rute ankommer",
	["Notice without fuss: EldoUI's soft sounds, a clean banner, a flash only when a queue pops or a ready check starts."] = "Besked uden ståhej: EldoUI's bløde lyde, et enkelt banner og kun et blink når køen er klar eller et klar-tjek starter.",
	["Notifications"] = "Notifikationer",
	["Novice"] = "Nybegynder",
	["Now"] = "Nu",
	["now %d"] = "nu %d",
	["Now %d of %d ranks, draft %d."] = "Nu %d af %d rangtrin, kladde %d.",
	["Now %s  ·  %s (%s)"] = "Nu %s  ·  %s (%s)",
	["Now click the last letter."] = "Klik nu på det sidste bogstav.",
	["NPC and boss speech"] = "NPC- og bosstale",
	["NPC Dialog"] = "NPC-dialog",
	["NPC model"] = "NPC-model",
	["Nudge sideways"] = "Skub til siden",
	["Nudge step"] = "Skubbetrin",
	["Nudge up or down"] = "Skub op eller ned",
	["Number keys pick"] = "Taltaster vælger",
	["Number of characters"] = "Antal karakterer",
	["Number of rows (up to %d buffs in total)."] = "Antal rækker (op til %d buffs i alt).",
	["Number of rows (up to %d debuffs in total)."] = "Antal rækker (op til %d debuffs i alt).",
	["Number on the bar, straight from the game. Percent is not shown for combo points."] = "Tal på bjælken, direkte fra spillet. Procent vises ikke for combopoints.",
	["Number on the health bar, straight from the game."] = "Tal på livsbjælken, direkte fra spillet.",
	["Number on the power bar, straight from the game."] = "Tal på ressourcebjælken, direkte fra spillet.",
	["Number size"] = "Talstørrelse",
	["Number: [2]"] = "Nummer: [2]",
	["Numbered channels"] = "Nummererede kanaler",
	["Numbers and words over EldoUI's unit frames when the unit is hit, healed, dodges, parries, misses or is immune."] = "Tal og ord over EldoUI's unitframes når enheden bliver ramt, healet, undviger, parerer, misser eller er immun.",
	["Numbers fade and scale with EldoUI's plate (non-target fade, target scale)."] = "Tallene tones og skaleres med EldoUI's nameplate (toning for ikke-mål, skalering for mål).",
	["Numbers from"] = "Tal fra",
	["Numbers on the enemy's nameplate when it is hit. Every hit the enemy takes, not only yours."] = "Tal på fjendens nameplate når den bliver ramt. Alle hits fjenden tager, ikke kun dine.",
	["Numbers on the enemy's nameplate, a slim incoming lane, no target area."] = "Tal på fjendens nameplate, en smal bane for indkommende, intet målområde.",
	["Numbers on the swipe: EldoUI's cooldown text (Fonts and text page), the game's own (its Action Bars setting), or none."] = "Tal på cooldown-swipen: EldoUI's cooldowntekst (siden Skrifttyper og tekst), spillets egen (indstillingen under Action Bars i spillet) eller ingen.",
	["Numbers on your target's plate only, or on every enemy plate."] = "Tal kun på dit måls nameplate eller på alle fjendtlige nameplates.",
	["Numbers over targets too"] = "Også tal over mål",
	["Numbers rise off an enemy's nameplate when it is hit, by you or anyone else: the game doesn't say who hit."] = "Tal stiger op fra en fjendes nameplate når den bliver ramt, af dig eller nogen anden: spillet siger ikke hvem der ramte.",
	["object %d"] = "objekt %d",
	["Off by default. Nothing is ever sent without your click, and gold is never posted."] = "Slået fra som standard. Intet sendes nogensinde uden dit klik, og guld deles aldrig.",
	["Off by default. On shows the send buttons below; each send is one click, and the other player must accept."] = "Slået fra som standard. Slået til vises sendeknapperne nedenfor; hver afsendelse er ét klik, og den anden spiller skal acceptere.",
	["Off Hand"] = "Off Hand",
	["Off hand color"] = "Farve for off hand",
	["Off in dungeons, raids and battlegrounds."] = "Fra i dungeons, raids og battlegrounds.",
	["Off leaves Blizzard's buff bars viewer exactly as Blizzard made it."] = "Fra: Blizzards visning af buffbjælker forbliver præcis som Blizzard lavede den.",
	["Off leaves Blizzard's buff icons viewer exactly as Blizzard made it."] = "Fra: Blizzards visning af buffikoner forbliver præcis som Blizzard lavede den.",
	["Off leaves Blizzard's essential viewer exactly as Blizzard made it."] = "Fra: Blizzards essentielle visning forbliver præcis som Blizzard lavede den.",
	["Off leaves Blizzard's utility viewer exactly as Blizzard made it."] = "Fra: Blizzards Utility-visning forbliver præcis som Blizzard lavede den.",
	["Off leaves whispers out of the saved history."] = "Fra holder hvisk ude af den gemte historik.",
	["Off lists every character, with 0 where they have none."] = "Når den er slået fra, vises alle karakterer, med 0 hvor de ikke har nogen.",
	["Off lists only your other characters."] = "Når den er slået fra, vises kun dine andre karakterer.",
	["Off uses the color below."] = "Fra bruger farven nedenfor.",
	["Off uses the link color below."] = "Fra bruger linkfarven nedenfor.",
	["Off uses the spot you set in move mode (/eui move). For Blizzard's window this needs the Move switch and sets the game's \"loot under mouse\" option."] = "Når den er slået fra, bruges det sted du har valgt i flyttetilstand (/eui move). For Blizzards vindue kræver det kontakten Flyt, og det slår spillets indstilling \"loot under mouse\" til.",
	["Off: any debuff someone in the group can dispel."] = "Fra: enhver debuff som nogen i gruppen kan dispelle.",
	["Off: dark health bars."] = "Fra: mørke livsbjælker.",
	["Off: frames keep only the game's own Click Casting and the default target and menu clicks."] = "Fra: rammerne beholder kun spillets eget klikkast og standardklikkene for mål og menu.",
	["Off: friends coming online or going offline keep their own lines. On: they are folded with the guild."] = "Fra: venner der logger på eller af, beholder deres egne linjer. Til: de samles med guildbeskederne.",
	["Off: Game colors"] = "Fra: Spilfarver",
	["Off: it appears when the first error is logged."] = "Fra: den vises når den første fejl logges.",
	["Off: its items go to Other."] = "Slået fra: dets genstande kommer i Andet.",
	["Off: right-click to show it"] = "Slået fra: højreklik for at vise det",
	["Off: routes your group sends are not listened to."] = "Fra: ruter som din gruppe sender, bliver ikke modtaget.",
	["Off: the action bars use the cooldown colors and thresholds of the Fonts and text page, like every other cooldown. On: the rows below set them for the action bars only."] = "Fra: handlingslinjerne bruger cooldownfarverne og -grænserne fra siden Skrifttyper og tekst, ligesom alle andre cooldowns. Til: rækkerne nedenfor indstiller dem kun for handlingslinjerne.",
	["Off: the bar steps out of sight and its keys keep working. It shows when you point at it out of combat, near your bags or the right edge, and hides in combat."] = "Fra: linjen forsvinder ud af syne, og dens taster virker stadig. Den vises når du peger på den uden for kamp, ved dine tasker eller ved højre kant, og skjules i kamp.",
	["Off: the windows, search and tooltips use only this character. Saved data stays until you forget it."] = "Når den er slået fra, bruger vinduerne, søgningen og tooltips kun denne karakter. Gemte data bevares indtil du glemmer dem.",
	["Off: these items go to their next section in the bag window."] = "Slået fra: genstandene kommer i deres næste afsnit i taskevinduet.",
	["Off: these items go to their next section in the bank window."] = "Slået fra: genstandene kommer i deres næste afsnit i bankvinduet.",
	["Off: white names."] = "Fra: hvide navne.",
	["Offer"] = "Tilbyd",
	["Offer every node on every map."] = "Tilbyd alle nodes på alle kort.",
	["Offer rank upgrades"] = "Tilbyd rangopgraderinger",
	["Offer the nodes of the map you are on."] = "Tilbyd nodes fra det kort du er på.",
	["offline"] = "offline",
	["Offline guild members show in the tooltip line and the Crafters tab too, after the ones who are online."] = "Offline guildmedlemmer vises også i tooltiplinjen og på fanen Craftere, efter dem der er online.",
	["older or alt"] = "ældre eller alts",
	["On a character that is not Hardcore the module does nothing. Messages go out only when you click Tell the guild."] = "På en karakter der ikke er Hardcore, gør modulet intet. Beskeder sendes kun når du klikker på Fortæl guilden.",
	["On a cooldown icon's label: the key bound to the action button that holds its spell. Empty everywhere else."] = "På et cooldownikons etiket: tasten der er tildelt den handlingsknap som har evnen. Tom alle andre steder.",
	["On a cooldown icon's label: the name of its spell or item. Empty everywhere else."] = "På et cooldownikons etiket: navnet på evnen eller genstanden. Tom alle andre steder.",
	["On a currency: how much of it each of your other characters has (Bags module)."] = "På en valuta: hvor meget hver af dine andre karakterer har (modulet Tasker).",
	["On a flight path"] = "På en flyverute",
	["On a quest page, R hides the text so only the rewards show, and R again brings it back. With Shift or Alt held, R always goes on to the game. Off: R stays on your Reply key."] = "På en questside skjuler R teksten så kun belønningerne vises, og et tryk mere på R henter den tilbage. Med Shift eller Alt holdt nede går R altid videre til spillet. Fra: R bruges stadig til at svare i chatten.",
	["On cooldown"] = "På cooldown",
	["On crafted items and recipes: the guild members who know the recipe, from the lists they shared (Alts module, Crafters tab)."] = "På craftede genstande og opskrifter: de guildmedlemmer der kan opskriften, ud fra de lister de har delt (Alts-modulet, fanen Craftere).",
	["on my way"] = "på vej",
	["On quest links: which of your characters are on the quest, ready to turn it in or completed it (Alts module)."] = "På questlinks: hvilke af dine karakterer der har questen, er klar til at aflevere den eller har fuldført den (Alts-modulet).",
	["On recipes: which of your characters already know it, who can learn it now and who later (Alts module)."] = "På opskrifter: hvilke af dine karakterer der allerede kan den, hvem der kan lære den nu, og hvem senere (Alts-modulet).",
	["On the blessing reminder"] = "På velsignelsespåmindelsen",
	["On the minimap (bottom edge)"] = "På minikortet (nederste kant)",
	["On the target's nameplate"] = "På målets nameplate",
	["On this quest"] = "På denne quest",
	["On which great tree is Darnassus built?"] = "På hvilket stort træ er Darnassus bygget?",
	["On WoW: Forever, DBM with DBM-Dungeons and DBM-Vanilla has the boss timers for the Forever and classic dungeons and raids. Install it like any addon; this page sets it up afterwards."] = "På WoW: Forever har DBM med DBM-Dungeons og DBM-Vanilla bossnedtællingerne til Forever og de klassiske dungeons og raids. Installer den som enhver anden addon; denne side sætter den op bagefter.",
	["On your unit and group frames: what each mouse button casts with the modifier you hold (Click Casting module)."] = "På dine unit- og grupperammer: hvad hver museknap caster med den ændringstast du holder nede (Klikkast-modulet).",
	["On: %s"] = "Til: %s",
	["On: after a layout click or a drag of the BigWigs movers, BigWigs asks in its own popup whether to take the new spots. Off: send them with the button below."] = "Til: når du har valgt et layout eller trukket i BigWigs' flyttefelter, spørger BigWigs i sit eget pop op-vindue om de nye placeringer skal bruges. Fra: send dem med knappen nedenfor.",
	["On: trinkets without a use effect stay out of the row. Off: both trinket slots always show."] = "Til: trinkets uden en brugseffekt holdes ude af rækken. Fra: begge trinketpladser vises altid.",
	["One addon message with the plan to your group, out of combat. Paladins with EldoUI see their part."] = "Én addon-besked med planen til din gruppe, uden for kamp. Paladins med EldoUI ser deres del.",
	["One bar"] = "Én bjælke",
	["One bar with the buffs you keep up, your key cooldowns and the reagents you spend. Each icon shows once you know its spell."] = "Én bjælke med de buffs du holder oppe, dine vigtige cooldowns og de reagenser du bruger. Hvert ikon vises når du kender evnen.",
	["One bar, one segment per stack, or folded (the stacks above half color over the first half)."] = "Én bjælke, ét segment pr. stak eller foldet (stakkene over halvdelen farver oven på den første halvdel).",
	["One block hanging under the main cooldown row, 2 px apart."] = "Én blok der hænger under hovedrækken af cooldowns, med 2 px imellem.",
	["One button per set; click to equip it. The open set has an accent border, a set with missing items a red one."] = "Én knap pr. sæt; klik for at tage det på. Det aktive sæt har en kant i accentfarve, et sæt med manglende genstande en rød.",
	["One character in detail: summary with stats, items, gear, quests and reputation."] = "Én karakter i detaljer: oversigt med stats, genstande, udstyr, quests og omdømme.",
	["One character's gold, or all characters added up."] = "Guld for én karakter eller alle karakterer lagt sammen.",
	["One chat line at log-in when a letter on any of your characters runs out soon. Only while the Mail block is on a bar or panel, and not when the Characters module's mail reminder says it."] = "Én chatlinje ved login når et brev på en af dine karakterer snart udløber. Kun mens Post-blokken er på en bjælke eller et panel, og ikke når Karakterer-modulets postpåmindelse siger det.",
	["One chat line the first time Auto falls back in a session."] = "Én chatlinje første gang Auto skifter over i en session.",
	["One class"] = "Én klasse",
	["One color for the countdown when Color by time left is off."] = "Én farve til nedtællingen når Farv efter resterende tid er slået fra.",
	["One combined bag"] = "Én samlet taske",
	["One equip per click; not in combat."] = "Ét udstyrsskift pr. klik; ikke i kamp.",
	["One grid"] = "Ét gitter",
	["One grid of every slot, sections by item type (Categories), or one section per bag."] = "Ét gitter med alle pladser, afsnit efter genstandstype (Kategorier) eller ét afsnit pr. taske.",
	["One grid that fills from the bottom right, like the old bag windows."] = "Ét gitter der fyldes fra nederste højre hjørne, ligesom de gamle taskevinduer.",
	["One grid, 12 columns, 38 px slots, every marker on."] = "Ét gitter, 12 kolonner, pladser på 38 px, alle markeringer slået til.",
	["One grid, categories or bag by bag, and the bag bar that shows, hides and swaps single bags."] = "Ét gitter, kategorier eller taske for taske, og taskelinjen der viser, skjuler og bytter enkelte tasker.",
	["One grid, categories or bag by bag, the bag bar and more."] = "Ét gitter, kategorier eller taske for taske, taskelinjen og mere.",
	["One icon for a big defensive cooldown, from Blizzard's defensive filter."] = "Ét ikon for en stor defensiv cooldown, fra Blizzards filter for defensive evner.",
	["One key casts Fishing and loots the bobber while it is out: one action per press. Combat clears the key. Also: /eui fish."] = "Én tast kaster snøren og looter flådet mens det er ude: én handling pr. tryk. Når du går i kamp, ryddes tasten. Også: /eui fish.",
	["One line in your chat after a reset: which instances were reset, and which weren't and why."] = "Én linje i din chat efter et reset: hvilke instanser der blev resat, og hvilke der ikke blev og hvorfor.",
	["One line per paladin in party or raid chat, out of combat."] = "Én linje pr. Paladin i gruppe- eller raidchatten, uden for kamp.",
	["One line with the winner in party or raid chat. Only the group leader has this button."] = "Én linje med vinderen i gruppe- eller raidchatten. Kun gruppelederen har denne knap.",
	["One mover per bar (main hand, off hand, ranged) and the size below."] = "Ét flyttefelt pr. bjælke (main hand, off hand, ranged) og størrelsen nedenfor.",
	["One pair"] = "Et par",
	["One panel in your skin's material behind bars 1 and 2, so both rows sit in a single tray. Twin Orbs turns it on; Vanilla Original keeps its classic tray under bar 1."] = "Ét panel i dit skins materiale bag linje 1 og 2, så begge rækker står i én bakke. Twin Orbs slår den til; Vanilla Original beholder sin klassiske bakke under linje 1.",
	["One place earlier in the bag window."] = "Én plads tidligere i taskevinduet.",
	["One place earlier in the group."] = "Én plads tidligere i gruppen.",
	["One place later in the bag window."] = "Én plads senere i taskevinduet.",
	["One place later in the group."] = "Én plads senere i gruppen.",
	["One rank less in the draft. Nothing is refunded."] = "Ét rangtrin mindre i kladden. Intet refunderes.",
	["One rank more in the draft. Nothing is spent."] = "Ét rangtrin mere i kladden. Intet bruges.",
	["One row per character: sort by any column, filter with the chips, hover for details, right-click for groups, bank marks and Forget."] = "Én række pr. karakter: sorter efter en vilkårlig kolonne, filtrer med knapperne, hold musen over for detaljer, og højreklik for grupper, bankmærker og Glem.",
	["One rune left, back in the starting hole!"] = "Én rune tilbage, i starthullet!",
	["One rune left, in the middle!"] = "Én rune tilbage, i midten!",
	["One sample for every source you have on, in the current look."] = "Ét eksempel for hver kilde du har slået til, i det nuværende udseende.",
	["One search box for game panels, settings, mounts, toys, bag items, macros, places and EldoUI commands, with a small calculator. Using a mount, toy, item or macro is always your own click or key press."] = "Ét søgefelt til spilpaneler, indstillinger, mounts, toys, genstande i tasker, makroer, steder og EldoUI-kommandoer, med en lille lommeregner. En mount, et toy, en genstand eller en makro bruges altid kun med dit eget klik eller tastetryk.",
	["One search term per line. Press Ctrl+C to copy; others paste it under Import."] = "Ét søgeord pr. linje. Tryk på Ctrl+C for at kopiere; andre indsætter det under Importer.",
	["One segment per stack"] = "Ét segment pr. stak",
	["One session counts gold and XP for these blocks, the XP bar and My Adventure, and goes on over a reload. A longer log-out starts a new one. Right-click a rate block to start one yourself."] = "Én session tæller guld og XP for disse felter, XP-bjælken og My Adventure og fortsætter efter en genindlæsning. Et længere log ud starter en ny. Højreklik et ratefelt for selv at starte en.",
	["One slot per bag type for free space"] = "Én plads pr. tasketype til ledig plads",
	["One strip, counters side by side, with goals and session gain."] = "Én stribe med tællerne side om side, med mål og gevinst i sessionen.",
	["One strip, counters stacked."] = "Én stribe med tællerne stablet.",
	["One window per bag"] = "Ét vindue pr. taske",
	["One-grid view: the first bag slot sits at the bottom right instead of the top left."] = "Visningen Ét gitter: den første taskeplads sidder nederst til højre i stedet for øverst til venstre.",
	["One-grid view: the reagent bag gets its own section. Off puts its slots into the main grid."] = "Visningen Ét gitter: reagenstasken får sit eget afsnit. Når den er slået fra, kommer dens pladser i hovedgitteret.",
	["Ones"] = "Enere",
	["Online"] = "Online",
	["online"] = "online",
	["Online %d of %d"] = "%d af %d online",
	["Online only"] = "Kun online",
	["Only Alliance characters."] = "Kun Alliance-karakterer.",
	["Only auras you cast. Off: the same spell from anyone counts."] = "Kun auraer du selv caster. Fra: den samme evne fra alle tæller med.",
	["Only auras you or your pet applied. Off: the same spell from anyone counts."] = "Kun auraer som du eller dit pet har lagt på. Fra: den samme evne fra hvem som helst tæller.",
	["Only below"] = "Kun under",
	["Only characters at the highest level."] = "Kun karakterer på højeste level.",
	["Only characters below the highest level."] = "Kun karakterer under højeste level.",
	["Only characters saved to an instance."] = "Kun karakterer der er låst til en instans.",
	["Only characters that have the item"] = "Kun karakterer der har genstanden",
	["Only characters whose rested bar is full (estimate for offline characters)."] = "Kun karakterer med fuld udhvilet XP (estimat for karakterer der er offline).",
	["Only characters with items in the mailbox."] = "Kun karakterer med genstande i postkassen.",
	["Only characters with mail that returns or is deleted within 5 days."] = "Kun karakterer med post der sendes retur eller slettes inden for 5 dage.",
	["Only combo points, no power bar (Blizzard's player frame or EldoUI's shows power)."] = "Kun combopoints, ingen ressourcebjælke (Blizzards eller EldoUI's spillerramme viser ressourcen).",
	["Only damage and healing you take, small and fast."] = "Kun skade og heling du modtager, små og hurtige.",
	["Only debuffs I can dispel"] = "Kun debuffs jeg kan dispelle",
	["Only Disenchanting."] = "Kun Disenchanting.",
	["Only fishing pools."] = "Kun fiskestimer.",
	["Only from these players (comma separated), or the words friends / guild. Empty: anyone. In chat lockdown the sender is hidden and this check doesn't fire."] = "Kun fra disse spillere (adskilt med komma) eller ordene friends / guild. Tom: alle. Ved chatlåsning er afsenderen skjult, og denne betingelse tjekkes ikke.",
	["Only from this character level."] = "Kun fra dette karakterlevel.",
	["Only full stacks are grouped; a stack that is not full keeps its own slot."] = "Kun fulde stakke samles; en stak som ikke er fuld, beholder sin egen plads.",
	["Only herb nodes, and only those you can gather."] = "Kun urtenodes, og kun dem du kan indsamle.",
	["Only hidden buttons"] = "Kun skjulte knapper",
	["Only Horde characters."] = "Kun Horde-karakterer.",
	["Only if"] = "Kun hvis",
	["Only in combat"] = "Kun i kamp",
	["Only in fishing mode"] = "Kun i fisketilstand",
	["Only in or out of combat."] = "Kun i eller uden for kamp.",
	["Only in the right panel"] = "Kun i højre panel",
	["Only in this kind of place."] = "Kun på denne type sted.",
	["Only in this stance or form"] = "Kun i denne stance eller form",
	["Only in zones whose name contains one of these words (comma separated). Empty: anywhere."] = "Kun i zoner hvis navn indeholder et af disse ord (adskilt med komma). Tom: overalt.",
	["Only items of this quality or better."] = "Kun genstande af denne kvalitet eller bedre.",
	["Only members the guild allows can change this text."] = "Kun medlemmer guilden giver lov kan ændre denne tekst.",
	["Only mine"] = "Kun mine",
	["Only near a camp"] = "Kun nær en lejr",
	["Only nodes that still give skill"] = "Kun nodes der stadig giver skill",
	["Only on a Hardcore character."] = "Kun på en Hardcore-karakter.",
	["Only ore and treasure, and only veins you can mine."] = "Kun malm og skatte, og kun årer du kan udvinde.",
	["Only Pick Lock, in bags and trades."] = "Kun Pick Lock, i tasker og byttehandler.",
	["Only pulls in indoors, so walls don't block the view."] = "Zoomer kun ind indendørs, så vægge ikke spærrer for udsynet.",
	["Only PvP warnings and your own death card; a compact, see-through log."] = "Kun PvP-advarsler og dit eget dødskort; en kompakt, gennemsigtig log.",
	["Only quality borders: no item level, coins, tints, bind text or glow."] = "Kun kvalitetskanter: intet item level, ingen mønter, farvetoner, bindingstekst eller glød.",
	["Only solo, in a party or in a raid."] = "Kun solo, i en gruppe eller i et raid.",
	["Only standing in bad stuff and its stacks, with the flash; breath, fatigue and AFK stay quiet."] = "Kun advarsler om at stå i noget skadeligt og om nye stakke, med blinket; åndedræt, udmattelse og AFK giver ingen lyd.",
	["Only the %s tree."] = "Kun %s-træet.",
	["Only the game's own Click Casting, listed in the tooltip."] = "Kun spillets eget klikkast, vist i tooltippen.",
	["Only the modifier I hold"] = "Kun den ændringstast jeg holder nede",
	["Only the next event counts down, so two countdowns never overlap. Off counts down every event."] = "Kun den næste hændelse tæller ned, så to nedtællinger aldrig overlapper. Fra: alle hændelser tæller ned.",
	["Only the soonest event"] = "Kun den nærmeste hændelse",
	["Only the track line and the icons: no background, no tick numbers, a smaller big icon without glow."] = "Kun sporlinjen og ikonerne: ingen baggrund, ingen stregtal og det store ikon i en mindre udgave uden glød.",
	["Only this character so far"] = "Kun denne karakter indtil videre",
	["Only trinkets with a use effect"] = "Kun trinkets med en brugseffekt",
	["Only undo and drafts; long messages are cut at 255 letters as the game does."] = "Kun fortryd og kladder; lange beskeder klippes ved 255 bogstaver som i spillet.",
	["Only up to this character level."] = "Kun op til dette karakterlevel.",
	["Only what you don't have yet, as a small corner."] = "Kun det du ikke har endnu, som et lille hjørne.",
	["Only when something happened"] = "Kun når der skete noget",
	["Only when the game or EldoUI's tooltip doesn't show it already."] = "Kun når spillet eller EldoUI's tooltip ikke allerede viser den.",
	["Only when the Improve switch for party or raid frames is on (Blizzard UI page). Key and wheel bindings stay on EldoUI's frames."] = "Kun når Forbedr-kontakten for gruppe- eller raidrammer er slået til (siden Blizzard-UI). Taste- og hjulbindinger forbliver på EldoUI's rammer.",
	["Only when the Move switch is on: Blizzard's frames then sit on EldoUI's party and raid movers at this scale."] = "Kun når Flyt-kontakten er slået til: Blizzards rammer sidder så på EldoUI's flyttefelter for gruppe og raid i denne skala.",
	["Only when the Skin switch for party and raid frames is on (Blizzard UI page)."] = "Kun når Skin-kontakten for gruppe- og raidrammer er slået til (Blizzard-UI-siden).",
	["Only when there is threat"] = "Kun når der er aggro",
	["Only while it is your power"] = "Kun mens det er din ressource",
	["Only while mounted or not."] = "Kun når du er på mount, eller kun når du ikke er.",
	["Only while resting (inn, city) or not."] = "Kun når du hviler (kro, by), eller kun når du ikke gør.",
	["Only while up"] = "Kun mens aktiv",
	["Only zooms in while you talk to an NPC."] = "Zoomer kun ind mens du taler med en NPC.",
	["OOF"] = "OOF",
	["Opacity of every line, in percent."] = "Opacitet for hver linje, i procent.",
	["Opacity of members out of range. The game decides who is in range."] = "Opacitet for medlemmer uden for rækkevidde. Spillet afgør hvem der er inden for rækkevidde.",
	["Opacity of the bar while it is shown and not faded."] = "Linjens opacitet mens den vises og ikke er tonet ud.",
	["Opacity of the box behind the meter windows, in percent."] = "Opacitet for boksen bag målervinduerne i procent.",
	["Opacity of the crosshair, in percent."] = "Sigtekorsets opacitet i procent.",
	["Opacity of the ring itself, in percent."] = "Opacitet for selve ringen i procent.",
	["Opacity of the spell alerts while they use the EldoUI mover."] = "Opacitet for evneadvarslerne mens de bruger EldoUI-flyttefeltet.",
	["Opacity of the window background, in percent."] = "Opacitet for vinduets baggrund i procent.",
	["Opacity while shown and not faded."] = "Opacitet mens den vises og ikke er tonet ud.",
	["Open a lockbox someone puts in the trade window's \"Will not be traded\" slot."] = "Åbn en lockbox som nogen lægger på pladsen \"Will not be traded\" i byttevinduet.",
	["Open a profession window once and its recipes show here."] = "Åbn et fagvindue én gang, så vises dets opskrifter her.",
	["Open Alerts tab"] = "Åbn Alerts-fanen",
	["Open and close with"] = "Åbn og luk sammen med",
	["Open at the mouse"] = "Åbn ved musen",
	["Open Blizzard UI > System and settings windows, where 'Edit Mode integration' is switched on."] = "Åbn Blizzard-UI > System- og indstillingsvinduer hvor 'Edit Mode-integration' slås til.",
	["Open every safe field; the numbers count the mines around."] = "Åbn alle sikre felter; tallene viser hvor mange miner der ligger omkring.",
	["Open in Bags"] = "Åbn i Tasker",
	["open it in Blizzard's buy screen"] = "åbn den i Blizzards købsvindue",
	["open its settings"] = "åbn dens indstillinger",
	["Open loot history"] = "Åbn loothistorik",
	["Open menu"] = "Åbn menu",
	["Open on the first group roll"] = "Åbn ved gruppens første rul",
	["Open on the map"] = "Åbn på kortet",
	["open once"] = "åbn én gang",
	["open or close the blessing plan window"] = "åbn eller luk vinduet med velsignelsesplanen",
	["open or close the Flight Games, on a flight path or not"] = "åbn eller luk Flyvespil, på en flyverute eller ej",
	["Open the Alts window"] = "Åbn Alts-vinduet",
	["Open the auction house on"] = "Åbn auktionshuset på",
	["Open the bank, mail, trade or a vendor first."] = "Åbn først banken, posten, byttevinduet eller en købmand.",
	["Open the blessing plan"] = "Åbn velsignelsesplanen",
	["Open the chat (Enter): the emoji goes in there."] = "Åbn chatten (Enter): emojien sættes ind der.",
	["open the click-casting bindings window"] = "åbn vinduet med klikkastbindinger",
	["open the currency list"] = "åbn valutalisten",
	["Open the death log"] = "Åbn dødsloggen",
	["Open the Death Log window. /eui deaths does the same."] = "Åbn Dødslog-vinduet. /eui deaths gør det samme.",
	["Open the Dungeons window"] = "Åbn dungeonvinduet",
	["Open the error log in its own window, with filters and room for long errors."] = "Åbn fejlloggen i sit eget vindue med filtre og plads til lange fejl.",
	["Open the Finder with your key or /eui go. A result that uses a mount, toy, item or macro needs your click or Enter, out of combat."] = "Åbn Finder med din tast eller /eui go. Et resultat der bruger en mount, et toy, en genstand eller en makro, kræver dit klik eller Enter uden for kamp.",
	["Open the game's own bank window, e.g. to buy bank space."] = "Åbn spillets eget bankvindue, fx for at købe bankplads.",
	["Open the games at take-off"] = "Åbn spillene ved afgang",
	["Open the guide list"] = "Åbn guidelisten",
	["open the Hardcore death log"] = "åbn Hardcore-dødsloggen",
	["Open the keys and spells preview at the spell ranks: check the buttons to move, then press Apply (out of combat). Same as /eui ranks."] = "Åbn forhåndsvisningen af taster og evner ved evnerang: sæt flueben ved de knapper der skal flyttes, og tryk Anvend (uden for kamp). Det samme som /eui ranks.",
	["Open the Legacy Planner"] = "Åbn Legacy-planlæggeren",
	["Open the list of watched items and currencies, set goals and remove entries."] = "Åbn listen over overvågede genstande og valutaer, sæt mål og fjern poster.",
	["open the reputation list"] = "åbn omdømmelisten",
	["open the roll window"] = "åbn rulvinduet",
	["Open the run log"] = "Åbn runloggen",
	["Open the window again when combat ends."] = "Åbn vinduet igen når kampen er slut.",
	["Open window"] = "Åbn vindue",
	["Open with the Legacy window"] = "Åbn med Legacy-vinduet",
	["open your bags"] = "åbn dine tasker",
	["Open your guild bank and click through its tabs once; each tab you see is saved here."] = "Åbn din guildbank, og klik dig igennem fanerne én gang; hver fane du ser, gemmes her.",
	["Opening"] = "Åbning",
	["Opens a whisper to the crafter you clicked, with the recipe link in the edit box. You press Enter."] = "Åbner et hvisk til den crafter du klikkede på, med opskriftslinket i chatfeltet. Du trykker selv på Enter.",
	["Opens after combat."] = "Åbner efter kampen.",
	["Opens Alerts and Banners > Ready check, where you set the ready sound and the countdown on Blizzard's queue pop-up."] = "Åbner Advarsler og bannere > Klar-tjek. Der indstiller du klar-lyden og nedtællingen på Blizzards pop op-vindue for køen.",
	["Opens Blizzard's Cooldown Manager settings: which spells show in which viewer."] = "Åbner Blizzards indstillinger for Cooldown Manager: hvilke evner der vises i hvilken visning.",
	["Opens Camera Situations, where Talking to an NPC sets the distance."] = "Åbner Kamerasituationer, hvor Samtale med en NPC sætter afstanden.",
	["Opens Eldostar's page, where you pick the one guide that takes the layout's guide spot: Automatic, Eldostar, RestedXP, Guidelime or Off."] = "Åbner Eldostars side hvor du vælger den ene guide der tager layoutets guideplads: Automatisk, Eldostar, RestedXP, Guidelime eller Fra.",
	["Opens EldoUI's Legacy Planner beside this window: a draft build, profiles and the challenge browser. It never spends points."] = "Åbner EldoUI's Legacy-planlægger ved siden af dette vindue: et kladdebuild, profiler og udfordringsbrowseren. Den bruger aldrig point.",
	["Opens on"] = "Åbner på",
	["Opens or closes Blizzard's loot history (also /eui loothistory)."] = "Åbner eller lukker Blizzards loothistorik (også /eui loothistory).",
	["Opens the Alerts tab now (outside combat) and shows it."] = "Åbner Alerts-fanen nu (uden for kamp) og viser den.",
	["Opens the binding window. Also /eui clickcast."] = "Åbner bindingsvinduet. Også /eui clickcast.",
	["Opens the category editor: add, rename, color, order and share your categories, and turn the built-in sections on or off."] = "Åbner kategorieditoren: tilføj, omdøb, farvelæg, sorter og del dine kategorier, og slå de indbyggede afsnit til eller fra.",
	["Opens the channel list; /chatlist and the social panel still work."] = "Åbner kanallisten; /chatlist og det sociale panel virker stadig.",
	["Opens the Dungeons window on this dungeon, to pick, edit and share routes. Out of combat."] = "Åbner dungeonvinduet på dette dungeon så du kan vælge, redigere og dele ruter. Uden for kamp.",
	["Opens the game's own Click Casting window; its bindings work on EldoUI's frames too."] = "Åbner spillets eget klikkastvindue; bindingerne derfra virker også på EldoUI's rammer.",
	["Opens the game's own gold deposit."] = "Åbner spillets egen indsættelse af guld.",
	["Opens the game's own gold withdrawal."] = "Åbner spillets egen hævning af guld.",
	["Opens the games here and now, on a flight path or not. Typing /eui games does the same."] = "Åbner spillene her og nu, på en flyverute eller ej. /eui games gør det samme.",
	["Opens the Glows page, where the Bag actions glow gets its style and color."] = "Åbner siden Glød. Her får gløden for Taskehandlinger sin stil og farve.",
	["Opens the Glows page, where the dispel and boss aura glows get their style and color."] = "Åbner siden Glød hvor glødene for dispel og bossauraer får deres stil og farve.",
	["Opens the guide list in the Journal, where you start another guide."] = "Åbner guidelisten i journalen hvor du starter en anden guide.",
	["Opens the guide list in the Journal."] = "Åbner guidelisten i journalen.",
	["Opens the plan window. Click a square to pick a blessing, right-click to clear it. Also /eui blessings."] = "Åbner planvinduet. Klik på et felt for at vælge en velsignelse, højreklik for at rydde det. Også /eui blessings.",
	["Opens the planner beside Blizzard's Legacy window whenever that window opens, and closes it again with it."] = "Åbner planlæggeren ved siden af Blizzards Legacy-vindue hver gang det vindue åbnes, og lukker den igen sammen med det.",
	["Opens the roll window when someone in your group starts a round of rolls. The Rolls block opens it with a click."] = "Åbner rulvinduet når nogen i din gruppe starter en runde rul. Rul-blokken åbner det med et klik.",
	["Opens the window (/eui alts)."] = "Åbner vinduet (/eui alts).",
	["Opens your bags when the %s window opens (by default %s)."] = "Åbner dine tasker når vinduet (%s) åbnes. Som standard: %s.",
	["Optional: it never holds the step up."] = "Valgfrit: det holder aldrig trinnet tilbage.",
	["Or spell ID"] = "Eller evne-ID",
	["Or: items either side finds"] = "Eller: genstande som en af siderne finder",
	["Orange"] = "Orange",
	["Order gained"] = "Rækkefølge de kom i",
	["Order of the buffs (the game sorts them, also in combat). Custom filter groups have their own sort."] = "Buffenes rækkefølge (spillet sorterer dem, også i kamp). Brugerdefinerede filtergrupper har deres egen sortering.",
	["Order of the debuffs (the game sorts them, also in combat). Custom filter groups have their own sort."] = "Debuffenes rækkefølge (spillet sorterer dem, også i kamp). Brugerdefinerede filtergrupper har deres egen sortering.",
	["Order of the members. Role, Class, Name and Join order sort the whole raid, ignoring groups. Changes wait until combat ends."] = "Medlemmernes rækkefølge. Rolle, Klasse, Navn og Tilslutningsrækkefølge sorterer hele raidet uden hensyn til grupper. Ændringer venter til kampen er slut.",
	["Ore"] = "Malm",
	["Orgrimmar is named after which orc?"] = "Hvilken ork er Orgrimmar opkaldt efter?",
	["Other addons (LibDataBroker)"] = "Andre addons (LibDataBroker)",
	["Other bar addons"] = "Andre addons til handlingslinjer",
	["Other characters"] = "Andre karakterer",
	["Other frames"] = "Andre rammer",
	["Other panels in the window"] = "Andre paneler i vinduet",
	["Other timers"] = "Andre nedtællinger",
	["Out in the world"] = "Ude i verden",
	["Out of breath"] = "Ingen luft",
	["Out of combat only"] = "Kun uden for kamp",
	["Out of combat only."] = "Kun uden for kamp.",
	["Out of combat, marks members who lack a group buff you can give (from Buff and Consumable Reminders, or the buffs you can cast). Hidden in combat."] = "Uden for kamp markeres medlemmer der mangler en gruppebuff som du kan give (fra Påmindelser om buffs og forbrugsvarer, eller de buffs du kan caste). Skjult i kamp.",
	["Out of range"] = "Uden for rækkevidde",
	["Out of range (all rows)"] = "Uden for rækkevidde (alle rækker)",
	["Out of range color"] = "Farve uden for rækkevidde",
	["Out-of-range tint"] = "Farve uden for rækkevidde",
	["Outline around the big text, so it reads on any background."] = "Kontur om den store tekst, så den kan læses på enhver baggrund.",
	["Outline around the bubble text. Helps when the background is off."] = "Kontur om teksten i taleboblen. Hjælper når baggrunden er slået fra.",
	["Outline around the chat text (skin switch)."] = "Kontur om chatteksten (Skin-kontakt).",
	["Outline around the item level (and the bind text)."] = "Kontur om item level (og bindingsteksten).",
	["Outline around the stack count."] = "Kontur om antallet i stakken.",
	["Outline of Blizzard's combat text."] = "Kontur på Blizzards kamptekst.",
	["Outline of every button text. Theme follows the outline set on the Fonts and text page."] = "Kontur på al knaptekst. Tema følger konturen på siden Skrifttyper og tekst.",
	["Outline of the cooldown texts."] = "Kontur på cooldown-teksterne.",
	["Outline of the text. An outline keeps it readable over the world."] = "Tekstens kontur. En kontur holder den læsbar oven på spilverdenen.",
	["outline the chat frames and print their positions"] = "vis omrids af chatrammerne og skriv deres placeringer",
	["Outlines: %s, %s, %s, %s, %s. Run it again to turn off."] = "Omrids: %s, %s, %s, %s, %s. Kør kommandoen igen for at slå dem fra.",
	["Over the tabs"] = "Over fanerne",
	["Over the tabs: the box covers the tab strip while you type. Top of screen: centered near the top."] = "Over fanerne: feltet dækker fanelinjen mens du skriver. Øverst på skærmen: centreret nær toppen.",
	["Overwrite"] = "Overskriv",
	["Own bar color"] = "Farve på egen bjælke",
	["Own colors and thresholds"] = "Egne farver og grænser",
	["Own groups"] = "Egne grupper",
	["Own groups are on: the icons of every row are listed on the Groups tab."] = "Egne grupper er slået til: ikonerne i alle rækker står på fanen Grupper.",
	["Own groups on; every group and row lines its icons up from the center."] = "Egne grupper slået til; hver gruppe og række stiller sine ikoner op fra midten.",
	["Own groups on; every group and row starts at the left edge of its mover and grows to the right."] = "Egne grupper slået til; hver gruppe og række starter ved venstre kant af sit flyttefelt og vokser mod højre.",
	["Own label text"] = "Egen etikettekst",
	["Own mover (Tracking bars)"] = "Eget flyttefelt (Sporingsbjælker)",
	["Own mover: drag it in move mode (%s). Otherwise the viewer follows the chosen frame."] = "Eget flyttefelt: træk det i flyttetilstand (%s). Ellers følger visningen den valgte ramme.",
	["Own mover: drag it in move mode. The other choices follow the chat or the bag position."] = "Eget flyttefelt: træk det i flyttetilstand. De andre valg følger chatten eller taskernes placering.",
	["Own movers for the mirror timers and the quest timer, and the size below."] = "Egne flyttefelter til ånde- og udmattelsesbjælkerne og til questnedtællingen samt størrelsen nedenfor.",
	["Own movers for the recap window and the Return to Graveyard button."] = "Egne flyttefelter til oversigtsvinduet og knappen Return to Graveyard.",
	["Own rows"] = "Egne rækker",
	["Own settings for this raid size"] = "Egne indstillinger for denne raidstørrelse",
	["Own swing bars"] = "Egne swingbjælker",
