	["Pack sections"] = "Pak afsnit tæt",
	["Packs and route"] = "Packs og rute",
	["Packs from the Classic data"] = "Packs fra Classic-dataene",
	["Packs from the Classic data; WoW: Forever may differ."] = "Packs fra Classic-dataene; WoW: Forever kan afvige.",
	["Packs on the Loot Guide's dungeon map"] = "Packs på Loot Guides dungeonkort",
	["Packs only"] = "Kun packs",
	["Packs the route skips get a dark ring, so the route stands out."] = "Packs som ruten springer over, får en mørk ring, så ruten skiller sig ud.",
	["Packs with an elite mob get a gold ring, the others a plain one."] = "Packs med en elitemob får en guldring, de andre en almindelig.",
	["Packs with counts, patrols, bosses and the route with numbers."] = "Packs med antal, patruljer, bosser og ruten med numre.",
	["Packs, patrols and bosses from the Classic data (EldoUI_LootData). Planning only."] = "Packs, patruljer og bosser fra Classic-dataene (EldoUI_LootData). Kun til planlægning.",
	["Packs, patrols and bosses without a route line, to read a dungeon."] = "Packs, patruljer og bosser uden rutelinje, til at læse et dungeon.",
	["Padding"] = "Indvendig afstand",
	["Paging"] = "Sideskift",
