	["Panel visibility"] = "Panelets synlighed",
	["Panel width"] = "Panelbredde",
	["Panel, flat item slots, stats and tabs."] = "Panel, flade genstandspladser, stats og faner.",
	["Panel, Setting, Mount and the other kinds on the right of each row."] = "Panel, Indstilling, Mount og de andre typer i højre side af hver række.",
	["Panels, settings, mounts, toys, items, macros, places and EldoUI commands. Start with = for a sum."] = "Paneler, indstillinger, mounts, toys, genstande, makroer, steder og EldoUI-kommandoer. Start med = for at regne.",
	["Parry"] = "Parry",
