	["Party bubbles"] = "Talebobler i gruppechat",
	["Party frames to match the Boxed unit frames: a boxed 3D portrait, a name bar, a thick health bar with value and percent, buffs and debuffs below, a class badge."] = "Grupperammer der passer til Boxed-unitframes: et 3D-portræt i boks, en navnebjælke, en tyk livsbjælke med værdi og procent, buffs og debuffs nedenunder og et klassemærke.",
	["Party typing"] = "Gruppen skriver",
	["Party, raid and instance"] = "Gruppe, raid og instans",
	["Party, raid, main tank and pet frames with role, leader, status, aggro, buff, debuff, defensive and boss-mechanic indicators."] = "Gruppe-, raid-, main tank- og petrammer med indikatorer for rolle, leder, status, aggro, buffs, debuffs, defensive evner og bossmekanikker.",
	["Pass"] = "Pas",
	["pass"] = "pas",
	["Passed: %s"] = "Passer: %s",
	["Past 255 letters, Enter sends the first part and puts the rest back in the box for your next Enter. Parts end on a space and keep links whole."] = "Over 255 bogstaver sender Enter den første del og lægger resten tilbage i feltet til dit næste Enter. Delene slutter ved et mellemrum og holder links hele.",
	["Paste a bag category string. You see what it holds before anything changes."] = "Indsæt en streng med taskekategorier. Du ser hvad den indeholder før noget ændres.",
	["Paste a Legacy build string (Ctrl+V) and click Save. You see what it holds before it is saved as a profile; nothing is spent."] = "Indsæt en Legacy-build-streng (Ctrl+V), og klik på Gem. Du ser hvad den indeholder før den gemmes som profil; intet bruges.",
	["Paste a Legacy build string. It is saved as a profile; nothing is spent."] = "Indsæt en Legacy-build-streng. Den gemmes som en profil; intet bruges.",
	["Paste a list (one search term per line) and click Save."] = "Indsæt en liste (ét søgeord pr. linje), og klik på Gem.",
	["Paste a node string (Ctrl+V) and click Save. You see what it holds before anything is added."] = "Indsæt en nodestreng (Ctrl+V), og klik på Gem. Du ser indholdet før noget tilføjes.",
	["Paste a node string from a friend. You see what it holds first; the nodes are added to yours and nothing is removed."] = "Indsæt en nodestreng fra en ven. Du ser først hvad den indeholder; nodes tilføjes til dine, og intet fjernes.",
	["Paste a route string (!EUR1!...) and click Save. You see what it holds before anything is added."] = "Indsæt en rutestreng (!EUR1!...), og klik på Gem. Du ser hvad den indeholder før noget bliver tilføjet.",
	["Paste a route string someone shared (!EUR1!). You see what it holds before it is added."] = "Indsæt en rutestreng som nogen har delt (!EUR1!). Du ser hvad den indeholder før den bliver tilføjet.",
	["Paste an alt list string someone gave you."] = "Indsæt en streng med en altliste som nogen har givet dig.",
	["Paste an EldoUI string."] = "Indsæt en EldoUI-streng.",
	["Path of your own image, for example Interface\\AddOns\\MyMedia\\chat.tga (a .tga or .blp in an addon folder)."] = "Sti til dit eget billede, fx Interface\\AddOns\\MyMedia\\chat.tga (en .tga eller .blp i en addonmappe).",
