	["Place the alert on its own mover (EldoUI_LossOfControl) and scale it here."] = "Placer advarslen på sit eget flyttefelt (EldoUI_LossOfControl), og skaler den her.",
	["Place the main window on the damage meter mover (EldoUI_Details) and size it here."] = "Placer hovedvinduet på skademålerens flyttefelt (EldoUI_Details), og angiv størrelsen her.",
	["Place timers, warnings and the info frame with the EldoUI layout"] = "Placer nedtællinger, advarsler og inforammen med EldoUI-layoutet",
