	["Placed by both:"] = "Placeret af begge:",
	["Placed by EldoUI: the guide and its step card follow the \"RestedXP Guide\" mover."] = "Placeret af EldoUI: guiden og dens trinkort følger flyttefeltet \"RestedXP-guide\".",
	["Plain"] = "Plain",
	["Plain (12345)"] = "Enkel (12345)",
	["Plain black"] = "Ensfarvet sort",
	["Plain dark"] = "Ensfarvet mørk",
	["Plain left and right clicks still target and open the menu."] = "Almindeligt venstre- og højreklik vælger stadig mål og åbner menuen.",
	["Plan from %s"] = "Plan fra %s",
	["Plan which blessing each paladin keeps up on each class, and send it to the group or chat on your click. Nothing is cast for you."] = "Planlæg hvilken velsignelse hver Paladin holder oppe på hver klasse, og send planen til gruppen eller chatten når du klikker. Intet castes for dig.",
	["Plan which blessing each paladin of your group keeps up on each class, then send the plan to the group or post it in chat with one click."] = "Planlæg hvilken velsignelse hver Paladin i din gruppe holder oppe på hver klasse, og send så planen til gruppen eller skriv den i chatten med ét klik.",
	["Plan your Legacy points, keep named profiles for your characters and browse Legacy Challenges. You spend points in Blizzard's Legacy window."] = "Planlæg dine Legacy-point, gem navngivne profiler for dine karakterer, og gennemse Legacy-udfordringer. Du bruger point i Blizzards Legacy-vindue.",
	["Plan your Legacy points: a draft build next to your current one, named profiles for all your characters, a cost check against the season cap and a challenge browser. It never spends a point."] = "Planlæg dine Legacy-point: et kladdebuild ved siden af dit nuværende, navngivne profiler for alle dine karakterer, et omkostningstjek mod sæsonloftet og en udfordringsbrowser. Den bruger aldrig et point.",
	["Planner button"] = "Planlægger-knap",
	["Plate focus"] = "Plate focus",
	["Plate hits"] = "Hits på nameplates",
	["Play a sound when a new hostile player appears. Off by default."] = "Afspil en lyd når en ny fjendtlig spiller dukker op. Slået fra som standard.",
	["Play a sound with the flash, at most once every half second. Off by default."] = "Afspil en lyd med blinket, højst én gang hvert halve sekund. Fra som standard.",
	["Play now"] = "Spil nu",
	["Play the danger alarm once."] = "Afspil farealarmen én gang.",
	["Play the fatigue alarm once."] = "Afspil udmattelsesalarmen én gang.",
	["Play the game's cast and targeting animation on EldoUI buttons."] = "Afspil spillets cast- og målanimation på EldoUI-knapper.",
	["Play the stack sound each time the same bad aura gains another stack."] = "Afspil staklyden hver gang den samme skadelige aura får endnu en stak.",
	["Play the stack sound once."] = "Afspil staklyden én gang.",
	["play this game"] = "spil dette spil",
	["Play this trigger now with sample values, ignoring its conditions."] = "Afspil denne udløser nu med eksempelværdier, uden hensyn til dens betingelser.",
	["Play while you fly"] = "Spil mens du flyver",
	["Played"] = "Spilletid",
	["Played %d, found %d, run %d"] = "Spillet %d, fundet %d, stime %d",
	["Played instead when the first sound's addon is not installed."] = "Afspilles i stedet når den første lyds addon ikke er installeret.",
	["Played when a bad aura from the spell list stacks again."] = "Afspilles når en skadelig aura fra evnelisten får en stak mere.",
	["Played when a line mentions your name. Every other keyword has its own sound in Edit keywords. At most one sound every 2 seconds."] = "Afspilles når en linje nævner dit navn. Alle andre nøgleord har deres egen lyd i Rediger nøgleord. Højst én lyd hvert 2. sekund.",
	["Played when someone else writes in %s chat."] = "Afspilles når en anden skriver i chattypen %s.",
	["Played when you stand in something from the spell list, when your breath runs out and when something attacks you while you are AFK. Sound files only: the game plays aura sounds from a file."] = "Afspilles når du står i noget fra evnelisten, løber tør for luft eller bliver angrebet mens du er AFK. Kun lydfiler: spillet afspiller auralyde fra en fil.",
	["Played when you swim into deep water fatigue."] = "Afspilles når du svømmer så langt ud på dybt vand at du bliver udmattet.",
	["Played with each death card."] = "Afspilles med hvert dødskort.",
	["Played with each PvP warning."] = "Afspilles med hver PvP-advarsel.",
	["Player vs. Player"] = "Spiller mod spiller",
	["Player, e.g. Name-Realm"] = "Spiller, fx Navn-Realm",
	["Player, target and focus frames"] = "Spiller-, mål- og fokusrammer",
	["Player, target, focus, pet and target-of-target frames."] = "Rammerne for spiller, mål, fokus, pet og målets mål.",
	["Players"] = "Spillere",
	["players are still inside"] = "der er stadig spillere inde",
	["Players hidden in one public channel only (up to 50). Also /eui chat mute <channel>; <name>, or right-click a sender in a channel line."] = "Spillere der kun skjules i én offentlig kanal (op til 50). Også /eui chat mute <channel>; <name>, eller højreklik på en afsender i en kanallinje.",
	["Players of the other faction can attack you now."] = "Spillere fra den anden fraktion kan angribe dig nu.",
	["Playing %s on the %s channel."] = "Afspiller %s på kanalen %s.",
	["Plays a 3-second test cast on every enabled cast bar, each in the theme it would use (out of combat; also /eui castfx test)."] = "Afspiller et testcast på 3 sekunder på alle castbars der er slået til, hver i det tema den ville bruge (uden for kamp; også /eui castfx test).",
	["Plays a busy sample raid boss: close timers in two lanes and waiting events. Click again to stop."] = "Kører en travl eksempelkamp mod en raidboss: tætte nedtællinger i to baner og ventende hændelser. Klik igen for at stoppe.",
	["Plays a pull countdown and a break timer. Click again to stop."] = "Starter en pull-nedtælling og en pausenedtælling. Klik igen for at stoppe.",
	["Plays a sample dungeon boss on the timeline so you can judge the look and the place. Click again to stop."] = "Kører en eksempelkamp mod en dungeonboss på tidslinjen, så du kan bedømme udseende og placering. Klik igen for at stoppe.",
	["Plays the sounds you picked for single events (Events tab, the cog of an event)."] = "Afspiller de lyde du har valgt til enkelte hændelser (fanen Hændelser, tandhjulet ved en hændelse).",
	["Plays when a spell or item is ready."] = "Afspilles når en evne eller genstand er klar.",
	["Point at an item, spell, quest, achievement, currency or talent link in chat to see its tooltip, where your tooltips usually show."] = "Peg på et genstands-, evne-, quest-, achievement-, valuta- eller talentlink i chatten for at se dets tooltip der hvor dine tooltips normalt vises.",
	["Points in this tree now %d, in the draft %d."] = "Point i dette træ nu %d, i kladden %d.",
	["Points you to this camp: the Waypoints arrow, or the game's map pin."] = "Viser dig vej til denne lejr: Waypoints-pilen eller spillets kortnål.",
	["Points: %s unspent, %s spent, %s owned, cap (maxQuantity) %s, most available %s"] = "Point: %s ubrugt, %s brugt, %s ejet, loft (maxQuantity) %s, højst tilgængelige %s",
	["Poisons, oils, stones and weapon imbues as icons (mover: Weapon Enchants)."] = "Gifte, olier, sten og våbenimbues som ikoner (flyttefelt: Våbenenchants).",
	["Polymorph on your target"] = "Polymorph på dit mål",
