	["Price scan finished."] = "Prisscanning færdig.",
	["Princess Theradras is the daughter of which elemental lord?"] = "Princess Theradras er datter af hvilken elementarherre?",
	["Print a chat line when a find adds a new node."] = "Skriv en chatlinje når et fund tilføjer en ny node.",
	["Print a line in your own chat window. Nothing is ever sent to other players."] = "Skriv en linje i dit eget chatvindue. Intet sendes nogensinde til andre spillere.",
	["Print the count"] = "Skriv tællingen",
	["Print to my chat"] = "Skriv i min chat",
	["Prints \"Instances were reset by the leader\" when your group leader runs EldoUI and resets."] = "Skriver \"Instanserne blev resat af lederen\" når din gruppeleder kører EldoUI og resetter.",
	["Prints a chat line shortly before a profession cooldown is ready, a lockout resets or a calendar event starts, for any of your characters. Once each, and not while you are in combat."] = "Skriver en chatlinje kort før en fagcooldown er klar, en lockout resetter eller en kalenderbegivenhed starter, for alle dine karakterer. Én gang for hver og ikke mens du er i kamp.",
	["Priority"] = "Prioritet",
	["Proc Alerts"] = "Procadvarsler",
	["Proc alerts"] = "Procadvarsler",
	["Proc flash"] = "Procblink",
	["Proc glow"] = "Procglød",
	["Proc sound"] = "Proclyd",
	["profession"] = "fag",
	["Profession"] = "Fag",
	["Profession cooldowns"] = "Fagcooldowns",
	["Profession cooldowns ready now, of those recorded."] = "Fagcooldowns der er klar nu, blandt dem der er registreret.",
	["Profession icons; small dots colored by kind (green herbs, orange ore, blue treasure, violet fishing); or bright dots with a white ring that stand out on any map."] = "Fagikoner; små prikker farvet efter type (grøn for urter, orange for malm, blå for skatte, violet for fiskeri); eller klare prikker med en hvid ring som skiller sig ud på ethvert kort.",
	["professions book"] = "fagbog",
	["Professions show here after each character logs in. Recipe lists fill in when a character opens its profession window."] = "Fag vises her når hver karakter har logget ind. Opskriftslisterne udfyldes når en karakter åbner sit fagvindue.",
	["Profile"] = "Profil",
	["Profiles are saved for all your characters. Loading one only changes the draft; you spend points in Blizzard's Legacy window."] = "Profiler gemmes for alle dine karakterer. Når du indlæser en, ændres kun kladden; du bruger point i Blizzards Legacy-vindue.",
	["Progress"] = "Fremskridt",
	["Progress comes from the game's achievement data. Spend Legacy points in Blizzard's Legacy window."] = "Fremskridtet kommer fra spillets achievementdata. Brug Legacy-point i Blizzards Legacy-vindue.",
	["Progression"] = "Progression",
	["Prospect"] = "Prospect",
	["Prospecting"] = "Prospecting",
	["PSST"] = "PSST",
	["Public channels"] = "Offentlige kanaler",
	["Public channels (Trade, General, LFG)"] = "Offentlige kanaler (Trade, General, LFG)",
	["Public channels, say and yell"] = "Offentlige kanaler, sig og råb",
	["Public channels, say, yell and emotes from members of these guilds are hidden, and their bubbles outside instances. EldoUI learns guilds from players you see (mouse-over, target, nameplates, group); a player not seen yet is shown."] = "Offentlige kanaler, sig, råb og emotes fra medlemmer af disse guilds skjules, og det samme gør deres talebobler uden for instanser. EldoUI lærer guilds at kende fra spillere du ser (hold musen over, mål, nameplates, gruppe); en spiller der ikke er set endnu, vises.",
	["Pull %d"] = "Pull %d",
	["Pull %d of the route"] = "Pull %d i ruten",
	["Pull aggro line"] = "Aggrogrænse",
	["Pull aggro line and warning"] = "Aggrogrænse og advarsel",
	["Pull and break"] = "Pull og pause",
	["Pull numbers"] = "Pull-numre",
	["Pull timer"] = "Pull-nedtælling",
	["Pull timer starts"] = "Pull-nedtælling starter",
	["PULL {seconds}"] = "PULL {seconds}",
	["Pulls"] = "Pulls",
	["Pulls on the card"] = "Pulls på kortet",
	["Pulse only while this talent group (dual specialization) is active."] = "Puls kun mens denne talentgruppe (dual spec) er aktiv.",
	["Pure fun: huge white captions and silly sounds, some only half the time. Never in combat. Funniest with WeakAuras SharedMedia installed."] = "Rent fjolleri: kæmpe hvide tekster og fjollede lyde, nogle kun halvdelen af gangene. Aldrig i kamp. Sjovest med WeakAuras SharedMedia installeret.",
	["Purple"] = "Lilla",
	["Push every crate onto its spot; ten storerooms, each harder."] = "Skub hver kasse ind på sin plads; ti lagerrum, hvert sværere.",
	["Pushback pulse"] = "Pushback-puls",
	["Put \"Custom currency 1-4\" in any slot and pick its currency here. The list shows the currencies of open headers in your currency tab."] = "Sæt \"Brugerdefineret valuta 1-4\" på en vilkårlig plads, og vælg dens valuta her. Listen viser valutaerne under de åbne overskrifter på din valutafane.",
	["Put a term in quotes (\"Iron Ore\") for an exact name."] = "Sæt et søgeord i anførselstegn (\"Iron Ore\") for et præcist navn.",
	["Put away"] = "Læg væk",
	["Put back the spells the last automatic upgrade changed and keep those buttons at that rank. A button you changed since stays as it is. Same as /eui ranks undo."] = "Læg de evner tilbage som den sidste automatiske opgradering ændrede, og hold de knapper på den rang. En knap du har ændret siden, bliver som den er. Det samme som /eui ranks undo.",
	["Put down what is on your cursor first, then upgrade the spell ranks."] = "Slip først det du har på markøren, og opgrader så evnerne til højeste rang.",
	["Put EldoUI's cooldown icons in your own groups. In move mode, drag an icon's handle to another group or the screen; click it for settings."] = "Placer EldoUI's cooldownikoner i dine egne grupper. I flyttetilstand trækker du et ikons håndtag til en anden gruppe eller ud på skærmen; klik på det for indstillinger.",
	["Put new spells on their key"] = "Sæt nye evner på deres tast",
	["Put your class's out-of-combat spells (travel, tracking, poisons, pet care) on the empty buttons of bars 4 and 5, out of combat. Buttons you filled are never touched."] = "Sæt din klasses evner til uden for kamp (rejse, sporing, gifte, pleje af pet) på de tomme knapper på linje 4 og 5, uden for kamp. Knapper du selv har fyldt, røres aldrig.",
	["Puts Details' window 1 on the \"Details! Window 1\" mover, so layouts, move mode and the Positions page place it. Dragging the window in Details moves the mover too."] = "Sætter Details' vindue 1 på flyttefeltet \"Details!-vindue 1\", så layouts, flyttetilstand og siden Placeringer placerer det. Trækker du vinduet i Details, flytter flyttefeltet med.",
	["Puts every item that fits into the bank, as the game's own deposit does."] = "Lægger alle genstande der er plads til i banken, ligesom spillets egen knap.",
	["Puts every scroll area back where your layout places it. Sizes and looks stay."] = "Sætter hvert rulleområde tilbage hvor dit layout placerer det. Størrelser og udseende bliver.",
	["Puts Questie's \"grow from\" corner back as it was before EldoUI's change. A corner you picked in Questie since stays yours."] = "Sætter Questies \"vokser fra\"-hjørne tilbage som før EldoUI's ændring. Har du siden valgt et hjørne i Questie, beholder du det.",
	["Puts Questie's tracker on the \"Questie Tracker\" mover, at the layout's quest tracker spot. Dragging it in Questie moves the mover too."] = "Sætter Questies tracker på flyttefeltet \"Questie-tracker\" på layoutets plads til questtrackeren. Trækker du den i Questie, flytter flyttefeltet med.",
	["Puts RestedXP's \"Current step frame anchor\" back as it was before EldoUI's change. A value you changed in RestedXP since stays yours."] = "Sætter RestedXP's ankerpunkt for den aktuelle trinramme tilbage som før EldoUI's ændring. Har du siden ændret værdien i RestedXP, beholder du den.",
	["Puts the Games box and the game window back in their first place."] = "Sætter Spil-boksen og spilvinduet tilbage på deres første plads.",
	["Puts the guide window on the \"RestedXP Guide\" mover. Dragging it in RestedXP moves the mover too."] = "Sætter guidevinduet på flyttefeltet \"RestedXP-guide\". Trækker du det i RestedXP, flytter flyttefeltet med.",
	["Puts this built-in theme back as EldoUI ships it."] = "Gendanner dette indbyggede tema som EldoUI leverer det.",
	["Puts this item on the auction house. One click, one post."] = "Sætter denne genstand til salg i auktionshuset. Ét klik, ét opslag.",
	["Puzzles"] = "Puslespil",
	["PvP flag"] = "PvP-flag",
	["PvP tab"] = "PvP-fane",
	["PvP target"] = "PvP-mål",
	["Q, R, B or N, or a click."] = "Q, R, B eller N (dronning, tårn, løber, springer) eller et klik.",
	["Qty"] = "Antal",
	["Quality border"] = "Kvalitetskant",
	["Quality borders"] = "Kvalitetskanter",
	["Quality borders, item level at the bottom, dark model background."] = "Kvalitetskanter, item level nederst, mørk modelbaggrund.",
	["Quality by name or number (0 poor to 7 heirloom)"] = "Kvalitet efter navn eller tal (0 ringe til 7 heirloom)",
	["Quantity"] = "Antal",
	["Quartermaster"] = "Quartermaster",
	["quest %d"] = "quest %d",
	["Quest and gossip NPCs talk in a wide panel at the top: numbered choices, Space to go on, Esc to leave. Nothing is accepted for you."] = "Quest- og samtale-NPC'er taler i et bredt panel øverst: nummererede valg, Space for at gå videre, Esc for at afslutte. Intet accepteres for dig.",
	["Quest items"] = "Questgenstande",
