	["Quest turned in"] = "Quest afleveret",
	["Questie integration"] = "Questie-integration",
	["Questie Tracker"] = "Questie-tracker",
	["Questie's quest tracker goes to the layout's quest tracker spot, and move mode places it like any EldoUI frame. Unchecked, Questie keeps its own spot."] = "Questies questtracker flyttes til layoutets plads til questtrackeren, og flyttetilstand placerer den som enhver anden EldoUI-ramme. Uden flueben beholder Questie sin egen plads.",
	["Questie: grow from the layout's corner"] = "Questie: voks fra layoutets hjørne",
