	["Question %d of %d"] = "Spørgsmål %d af %d",
	["Quests"] = "Quests",
	["Quests in your characters' logs, who is ready to turn in, dailies and completed quests."] = "Quests i dine karakterers logge, hvem der er klar til aflevering, dailies og fuldførte quests.",
