	["QUEUE READY"] = "KØEN ER KLAR",
	["Queues"] = "Køer",
	["Quick arcade games while you fly a flight path: a small Games box shows during the flight, and a click opens the games. Keys and the mouse play; landing or combat closes them."] = "Hurtige arkadespil mens du flyver en flyverute: en lille Spil-boks vises under flyvningen, og et klik åbner spillene. Du spiller med tastatur og mus; landing eller kamp lukker dem.",
