	["Raid runs. They count only with \"Count raids\" on."] = "Raidruns. De tæller kun med når \"Tæl raids\" er slået til.",
	["Raid target marker"] = "Raidmålmarkør",
	["Raider"] = "Raider",
	["Raids count toward the hourly limit too. Off: raids are logged in orange and don't count."] = "Raids tæller også med i grænsen pr. time. Fra: raids logges i orange og tæller ikke med.",
	["Raids don't count toward the hourly limit."] = "Raids tæller ikke med i grænsen pr. time.",
	["Raids with at least this many members use these settings (the largest size reached wins). Switches out of combat."] = "Raids med mindst dette antal medlemmer bruger disse indstillinger (den største størrelse der nås, vinder). Skifter uden for kamp.",
	["Raise %s"] = "Hæv %s",
	["Raises the sound effects and master volume while fishing, and puts your own values back when fishing mode ends."] = "Skruer op for lydeffekter og samlet lydstyrke mens du fisker, og sætter dine egne værdier tilbage når fisketilstanden slutter.",
	["Ram"] = "Vædder",
