	["Re-apply EldoUI settings"] = "Anvend EldoUI-indstillinger igen",
	["Re-apply to BigWigs"] = "Anvend igen på BigWigs",
	["Reach level %s"] = "Nå level %s",
	["reached level {level}"] = "nåede level {level}",
	["Reached wave %d"] = "Nåede bølge %d",
	["read %s ago"] = "læst for %s siden",
	["Read the spoken line for this entry, or not."] = "Læs den talte linje op for denne post, eller ej.",
	["Read the values below as power points, or as a percent of your maximum power (better for mana, which grows with your level)."] = "Læs værdierne herunder som ressourcepoint eller som procent af din maksimale ressource (bedre til mana som vokser med dit level).",
	["readable"] = "læsbar",
	["Reading the full scan: %d%%"] = "Læser den fulde scanning: %d%%",
	["Reads a line out with the game's text-to-speech (its voice and volume from the game's Text to Speech settings)."] = "Læser en linje op med spillets tekst-til-tale (stemme og lydstyrke fra spillets indstillinger for Text to Speech).",
	["ready"] = "klar",
	["READY CHECK"] = "KLAR-TJEK",
	["Ready check and status"] = "Klar-tjek og status",
	["Ready check and status size"] = "Størrelse på klar-tjek og status",
	["Ready text"] = "Klar-tekst",
	["Ready, not ready and waiting during a ready check; the result stays a while, then fades."] = "Klar, ikke klar og venter under et klar-tjek; resultatet bliver stående et stykke tid og toner så ud.",
	["Reagent bag in its own section"] = "Reagenstaske i eget afsnit",
	["Reagents"] = "Reagenser",
