	["Recent"] = "Seneste",
	["Recent and pinned results cleared."] = "Seneste og fastgjorte resultater er ryddet.",
	["Recent results first"] = "Seneste resultater først",
	["Recharging"] = "Genoplader",
	["Recipe"] = "Opskrift",
	["Recipe colors at vendors and the auction house"] = "Opskriftsfarver hos købmænd og i auktionshuset",
	["Recipe lists older than this leave the Crafters tab, so a member who left or stopped sharing drops out."] = "Opskriftslister der er ældre end dette, forsvinder fra fanen Craftere, så et medlem der er gået eller er holdt op med at dele, falder fra.",
	["Recipes"] = "Opskrifter",
	["Recipes forgotten."] = "Opskrifter glemt.",
	["Recipes not saved yet"] = "Opskrifter er ikke gemt endnu",
	["Recipes, mounts, pets and toys you already have get a green icon in EldoUI's Shopping results."] = "Opskrifter, mounts, pets og toys som du allerede har, får et grønt ikon i EldoUI's indkøbsresultater.",
	["Recipes, mounts, pets and toys you already know or own get a green icon, like at the merchant and the auction house."] = "Opskrifter, mounts, pets og toys som du allerede kender eller ejer, får et grønt ikon, ligesom hos købmanden og i auktionshuset.",
	["Recipes, patterns, plans and formulas."] = "Opskrifter, mønstre, planer og formler.",
	["Recommended: DBM (with DBM-Dungeons and DBM-Vanilla) has the boss timers for WoW: Forever."] = "Anbefalet: DBM (med DBM-Dungeons og DBM-Vanilla) har bossnedtællingerne til WoW: Forever.",
	["Record a node each time you gather. Off keeps the nodes you have but adds no new ones."] = "Registrer en node hver gang du indsamler. Slået fra beholdes dine nodes, men der tilføjes ingen nye.",
	["Record Legacy points for alts"] = "Registrer Legacy-point for alts",
	["Recording"] = "Registrering",
	["Red"] = "Rød",
	["Red (danger)"] = "Rød (fare)",
	["Red icon on items you can't use"] = "Rødt ikon på genstande du ikke kan bruge",
	["Red screen-edge flash"] = "Rødt blink i skærmkanten",
	["Red tint when low"] = "Rød farvetone ved lav holdbarhed",
	["Red titles, an alarm for PvP and a warning tone for deaths."] = "Røde titler, en alarm ved PvP og en advarselstone ved dødsfald.",
	["Reflect"] = "Reflect",
	["Refresh"] = "Opdater",
	["Relaxed"] = "Afslappet",
	["Reload to finish changing the guide on the guide spot. Guidelime keeps its open window until then."] = "Genindlæs for at afslutte skiftet af guide på guidepladsen. Guidelime beholder sit åbne vindue indtil da.",
	["Remember my last price"] = "Husk min sidste pris",
	["Remember new finds"] = "Husk nye fund",
	["Remember recipes"] = "Husk opskrifter",
	["Remembers what was hidden for 15 minutes (in memory only), for the Hidden lines window."] = "Husker i 15 minutter hvad der blev skjult (kun i hukommelsen), til vinduet Skjulte linjer.",
	["Remembers where you gathered herbs, ore, treasure and fishing pools and shows the nodes on the world map and minimap."] = "Husker hvor du har indsamlet urter, malm, skatte og fiskestimer, og viser nodes på verdenskortet og minikortet.",
	["Remembers your current DBM profile, switches DBM to the EldoUI profile of this layout (created on first use) and applies the settings below."] = "Husker din nuværende DBM-profil, skifter DBM til dette layouts EldoUI-profil (oprettes ved første brug) og anvender indstillingerne nedenfor.",
	["Remind after this many days without an auction house visit."] = "Påmind efter så mange dage uden besøg i auktionshuset.",
	["Remind when a calendar event one of your characters saw is about to start."] = "Påmind når en kalenderbegivenhed som en af dine karakterer har set, er ved at starte.",
	["Remind when a saved profession cooldown is about to be ready."] = "Påmind når en gemt fagcooldown snart er klar.",
	["Remind when a saved raid or dungeon lockout is about to reset."] = "Påmind når en gemt raid- eller dungeonlockout snart resetter.",
	["Remove all"] = "Fjern alle",
	["Remove all %d blocked phrases?"] = "Fjern alle %d blokerede fraser?",
	["Remove all runs"] = "Fjern alle runs",
	["Remove bar"] = "Fjern bjælke",
	["Remove characters you deleted or no longer play. Their journal stays on the Saved data page until you put it back or remove it."] = "Fjern karakterer du har slettet eller ikke spiller mere. Journalen bliver på siden Gemte data indtil du lægger den tilbage eller fjerner den.",
	["Remove every entry from the death log. Click twice to confirm."] = "Fjern alle poster fra dødsloggen. Klik to gange for at bekræfte.",
	["Remove every run from the log, for all characters? Trades and lockouts are kept."] = "Vil du fjerne alle runs fra loggen for alle karakterer? Byttehandler og lockouts bevares.",
	["remove from Favorites"] = "fjern fra Favoritter",
	["Remove from the list"] = "Fjern fra listen",
	["Remove group"] = "Fjern gruppe",
	["Remove the panel picked above (asks first). Panels after it move up one place."] = "Fjern panelet der er valgt ovenfor (spørger først). Paneler efter det rykker én plads op.",
	["Remove this run from the log (%s)? It no longer counts toward the limit."] = "Vil du fjerne dette run fra loggen (%s)? Det tæller så ikke længere med i grænsen.",
	["Remove this trigger. Built-in ones come back with Restore built-ins."] = "Fjern denne udløser. Indbyggede udløsere kommer tilbage med Gendan indbyggede.",
	["Removed \"%s\" from the alert keywords."] = "\"%s\" er fjernet fra nøgleordene for advarsler.",
	["Removed in the draft"] = "Fjernet i kladden",
	["Removes every color you set here."] = "Fjerner alle farver du har sat her.",
	["Removes every saved character (not this one) below the level above, for example old bank or mail alts you deleted."] = "Fjerner alle gemte karakterer (ikke denne) under levelet ovenfor, for eksempel gamle bank- eller postalts du har slettet.",
	["Removes the character's profile choice, its own settings, installer state, profile rules and key binding backup too. Leave it off when you may play the character again."] = "Fjerner også karakterens profilvalg, dens egne indstillinger, status for opsætningsguiden, profilregler og sikkerhedskopien af genvejstaster. Lad den være slået fra hvis du måske spiller karakteren igen.",
	["Removes the dark shadow and the red lines, leaving icon, name and time."] = "Fjerner den mørke skygge og de røde linjer, så ikon, navn og tid står tilbage.",
	["Removes the saved data picked above. Log in on it (or open the guild bank) to save it again."] = "Fjerner de gemte data valgt ovenfor. Log ind på karakteren (eller åbn guildbanken) for at gemme dem igen.",
	["Removes these lines from the main chat. Off shows them in both."] = "Fjerner disse linjer fra hovedchatten. Fra viser dem begge steder.",
	["Removes this run after a confirmation."] = "Fjerner dette run efter en bekræftelse.",
	["Rename bank tab"] = "Omdøb bankfane",
	["Rename list"] = "Omdøb liste",
	["Renew and shield on your target"] = "Renew og skjold på dit mål",
	["REPAIR"] = "REPARER",
	["Repair cost"] = "Reparationspris",
	["Repair needed"] = "Reparation nødvendig",
	["Repeat window"] = "Tidsrum for gentagelser",
	["Repeated lines"] = "Gentagne linjer",
	["Replace"] = "Erstat",
	["Replace the draft with the profile %s?"] = "Vil du erstatte kladden med profilen %s?",
	["Replace the draft with the ranks you have now?"] = "Vil du erstatte kladden med de rangtrin du har nu?",
	["Replace this talent group's click-cast bindings with the class list (%d)?"] = "Vil du erstatte denne talentgruppes klikkastbindinger med klasselisten (%d)?",
