	["Send to group (in the Dungeons window) sends a route to your party or raid in one click, unless the game holds addon messages back."] = "Send til gruppen (i dungeonvinduet) sender en rute til din gruppe eller dit raid med ét klik medmindre spillet holder addonbeskeder tilbage.",
	["Send wave %d"] = "Send bølge %d",
	["Sending nodes is off. Turn on \"Allow sending nodes\" under /eui > Gathering."] = "Afsendelse af nodes er slået fra. Slå \"Tillad afsendelse af nodes\" til under /eui > Indsamling.",
	["Sending waits until combat ends."] = "Afsendelsen venter til kampen er slut.",
	["Sends every event of this group to the picked area."] = "Sender alle hændelser i denne gruppe til det valgte område.",
	["Sends the known recipes of your characters on this realm (what each profession window saved) to guild members who use EldoUI and share theirs."] = "Sender de kendte opskrifter for dine karakterer på denne realm (det hvert fagvindue har gemt) til guildmedlemmer der bruger EldoUI og deler deres.",
	["Sends the place and tier of the fire you last hovered or lit, to your guild or group."] = "Sender placering og trin for det bål du sidst holdt musen over eller tændte, til din guild eller gruppe.",
	["Sends the place and tier of this fire to your guild or group (camp finder settings). Only members who use EldoUI see it."] = "Sender dette båls placering og trin til din guild eller gruppe (indstillinger for lejrsøger). Kun medlemmer der bruger EldoUI, ser det.",
	["Sends your characters on this realm (name, class, level, item level) to guild members who use EldoUI and share theirs."] = "Sender dine karakterer på denne realm (navn, klasse, level, item level) til guildmedlemmer der bruger EldoUI og deler deres.",
	["Sent marker"] = "Markør for sendt",
	["Sent your camp to %s."] = "Din lejr er sendt til %s.",
	["Separate"] = "Separat",
	["Separate bindings per talent group"] = "Separate bindinger pr. talentgruppe",
	["Separate layout per talent group"] = "Separat layout pr. talentgruppe",
	["Separate movers"] = "Separate flyttefelter",
	["Session"] = "Session",
	["Session earned"] = "Tjent i sessionen",
	["Session ended (too short to save)."] = "Sessionen er afsluttet (for kort til at blive gemt).",
	["Session history"] = "Sessionshistorik",
	["Session net"] = "Netto i sessionen",
	["Session saved: %s in %s."] = "Session gemt: %s på %s.",
	["Session spent"] = "Brugt i sessionen",
	["Sessions kept per zone"] = "Gemte sessioner pr. zone",
	["Sessions start only with a click; the bar stays on screen."] = "Sessioner starter kun med et klik; bjælken bliver på skærmen.",
	["Set a waypoint here"] = "Sæt et waypoint her",
	["Set button size"] = "Størrelse på sætknapper",
	["Set buttons on the character window"] = "Sætknapper på karaktervinduet",
	["Set buttons position"] = "Placering af sætknapper",
	["Set DBM up for EldoUI first"] = "Opsæt DBM til EldoUI først",
	["Set DBM up for EldoUI first."] = "Opsæt DBM til EldoUI først.",
	["Set fences in turn; close a pen to claim it and set another. Most pens wins."] = "Sæt hegn på skift; luk en indhegning for at tage den og sæt et hegn mere. Flest indhegninger vinder.",
	["Set the window size"] = "Angiv vinduesstørrelsen",
	["Set up DBM for EldoUI"] = "Opsæt DBM til EldoUI",
	["Set up: EldoUI keeps %s in line with your layout. Your own profile: %s."] = "Sat op: EldoUI holder %s i trit med dit layout. Din egen profil: %s.",
	["Set waypoint"] = "Sæt waypoint",
	["Sets Blizzard's own Cooldown Manager option (CVar cooldownViewerEnabled) while the master switch is on. The old value comes back with Blizzard default."] = "Sætter Blizzards egen Cooldown Manager-indstilling (CVar cooldownViewerEnabled) mens hovedafbryderen er slået til. Den gamle værdi kommer tilbage med Blizzard-standard.",
	["Sets per class and spec"] = "Sæt pr. klasse og spec",
	["Shaded stat rows"] = "Skyggede statsrækker",
	["Shadow"] = "Skygge",
	["Shadow for other units, dark wisps and a glow while casting."] = "Skygge til andre enheder, mørke slør og en glød mens du caster.",
	["Shadow Volley"] = "Shadow Volley",
	["Shadow Word: Pain on your target"] = "Shadow Word: Pain på dit mål",
	["Shake"] = "Rystelse",
	["Shaman totem bar"] = "Shaman-totemlinje",
	["Shamans have the cooldown bar of Shaman Totems instead, so this bar stays hidden."] = "Shamaner har cooldown-bjælken i Shaman Totems i stedet, så denne bjælke forbliver skjult.",
	["Shape of the flash."] = "Blinkets form.",
	["Share alt info with your guild"] = "Del alt-info med din guild",
	["Share my recipes with the guild"] = "Del mine opskrifter med guilden",
	["Share that I am typing"] = "Del at jeg skriver",
	["Share this camp"] = "Del denne lejr",
	["Shared Legacy build"] = "Delt Legacy-build",
	["Shared your camp with your group."] = "Din lejr er delt med din gruppe.",
	["Shared your camp with your guild."] = "Din lejr er delt med din guild.",
	["Sharing"] = "Deling",
	["Sharing (acts for you)"] = "Deling (handler på dine vegne)",
	["Sharing recipes with the guild is off (/eui > Alts)."] = "Deling af opskrifter med guilden er slået fra (/eui > Alts).",
	["Sharing with the guild is off (/eui > Alts)."] = "Deling med guilden er slået fra (/eui > Alts).",
	["Shields on you"] = "Skjolde på dig",
	["Shift shows"] = "Med Shift nede",
	["Shift+drag to move"] = "Shift+træk for at flytte",
	["Shift+Space"] = "Shift+Space",
	["Shift-click"] = "Shift-klik",
	["Shift-click a bar to put its text in the chat box. You send it yourself. Bars only take the mouse while this is on."] = "Shift-klik på en bjælke for at sætte dens tekst i chatfeltet. Du sender den selv. Bjælkerne reagerer kun på musen mens dette er slået til.",
	["Shift-click an item or currency into the box, or type an item ID, c<currency ID> or a currency name. Goal 0 means no goal."] = "Shift-klik en genstand eller valuta ind i feltet, eller skriv et genstands-ID, c<valuta-ID> eller et valutanavn. Mål 0 betyder intet mål.",
	["Shift-click to chat"] = "Shift-klik til chat",
	["Shine"] = "Glans",
	["Shine color"] = "Glansfarve",
	["Shine speed"] = "Glanshastighed",
	["Shine strength"] = "Glansstyrke",
	["SHINY!"] = "SHINY!",
	["SHit"] = "SHit",
	["Shoot down the sweeping flock before it reaches your gryphon."] = "Skyd flokken ned før den når din griffin.",
	["Shoot mana bubbles; three of a color pop. Clear the ceiling."] = "Skyd med manabobler; tre af samme farve brister. Ryd loftet.",
	["Shopping list"] = "Indkøbsliste",
	["Shopping List"] = "Indkøbsliste",
	["Shopping List, Quick Sell and Cancel Undercut are EldoUI's tabs, next to the game's Buy, Sell and Auctions. Every search, post, purchase and cancel is one click of yours."] = "Indkøbsliste, Hurtigt salg og Annuller undercut er EldoUI's faner ved siden af spillets Buy, Sell og Auctions. Hver gang du søger, lægger op, køber eller annullerer, er det ét klik fra dig.",
	["Shopping lists, quick selling with price checks, canceling, full scans, crafting costs and a price database for the auction house."] = "Indkøbslister, hurtigt salg med pristjek, annullering, fulde scanninger, craftingpriser og en prisdatabase til auktionshuset.",
	["Short (12, 2m)"] = "Kort (12, 2m)",
	["Short (12.3k g)"] = "Kort (12.3k g)",
	["Short (12.3K)"] = "Kort (12.3K)",
	["Short channel names"] = "Korte kanalnavne",
	["Short channel style"] = "Stil for korte kanalnavne",
	["Short key names"] = "Korte tastenavne",
	["Short rows and small icons: more results on screen."] = "Lave rækker og små ikoner: flere resultater på skærmen.",
	["Short sounds from the game for points, a new best and the end of a game."] = "Korte lyde fra spillet for point, en ny rekord og slutningen på et spil.",
	["Short sounds only, nothing on screen."] = "Kun korte lyde, intet på skærmen.",
	["Short-lived combat text over EldoUI's player, target, pet and focus frames."] = "Kortvarig kamptekst over EldoUI's spiller-, mål-, pet- og fokusrammer.",
	["Shortcode"] = "Kortkode",
	["Show \"Enemies (n)\" above the list."] = "Vis \"Fjender (n)\" over listen.",
	["Show %s in the right panel."] = "Vis %s i højre panel.",
	["Show all nodes"] = "Vis alle nodes",
	["Show alts"] = "Vis alts",
	["Show bar title"] = "Vis bjælketitel",
	["Show big text in the middle of the screen."] = "Vis stor tekst midt på skærmen.",
	["Show boss mechanic auras"] = "Vis auraer fra bossmekanikker",
	["Show buffs other people cast in gray (puts yours first too)."] = "Vis buffs som andre har castet, i gråt (sætter også dine først).",
	["Show buttons with nothing on them. Empty slots always show while you drag a spell."] = "Vis knapper uden noget på. Tomme pladser vises altid mens du trækker en evne.",
	["Show charges and item counts on this bar."] = "Vis ladninger og antal genstande på denne linje.",
	["Show charges and item counts."] = "Vis ladninger og antal genstande.",
	["Show chests you opened. An opened object counts only when it gave a loot window without quest items, so quest objects are left out."] = "Vis kister du har åbnet. Et åbnet objekt tæller kun når det gav et lootvindue uden questgenstande, så questobjekter udelades.",
	["Show count"] = "Vis antal",
	["Show debuffs other people cast in gray (puts yours first too)."] = "Vis debuffs som andre har castet, i gråt (sætter også dine først).",
	["Show each EldoUI frame's name on its box."] = "Vis navnet på hver EldoUI-ramme på dens boks.",
	["Show each feed's icon in front of its text."] = "Vis ikonet for hvert feed foran teksten.",
	["Show each feed's label in front of its value."] = "Vis etiketten for hvert feed foran værdien.",
	["Show each player's level, colored by difficulty."] = "Vis hver spillers level farvet efter sværhedsgrad.",
	["Show EldoUI frames"] = "Vis EldoUI-rammer",
	["Show EldoUI's action bar %d, with the game's \"Action Bar %d\" keys. It shows while Blizzard's bar is replaced, hidden or switched off, so there are never two bars. Turned off, its keys stop working."] = "Vis EldoUI's handlingslinje %d med spillets \"Action Bar %d\"-taster. Den vises mens Blizzards linje er erstattet, skjult eller slået fra, så der aldrig er to linjer. Slået fra holder dens taster op med at virke.",
	["Show EldoUI's action bar %d, with the game's \"Action Button\" keys. It shows while Blizzard's bar is replaced or hidden, so there are never two bars. Turned off, its keys stop working."] = "Vis EldoUI's handlingslinje %d med spillets \"Action Button\"-taster. Den vises mens Blizzards linje er erstattet eller skjult, så der aldrig er to linjer. Slået fra holder dens taster op med at virke.",
	["Show EldoUI's main tanks frames."] = "Vis EldoUI's main tank-rammer.",
	["Show EldoUI's own swing bars."] = "Vis EldoUI's egne swingbjælker.",
	["Show EldoUI's party frames."] = "Vis EldoUI's grupperammer.",
	["Show EldoUI's pets frames."] = "Vis EldoUI's petrammer.",
	["Show EldoUI's raid frames."] = "Vis EldoUI's raidrammer.",
	["Show emoji"] = "Vis emojis",
	["Show empty slots"] = "Vis tomme pladser",
	["Show events of"] = "Vis hændelser for",
	["Show every bag again"] = "Vis alle tasker igen",
	["Show every node name you hid with \"Hide every ...\" in the pin menu."] = "Vis alle nodenavne du har skjult med \"Skjul alle ...\" i nålens menu.",
	["Show fishing pools you fished. Point at the pool before you cast so its name is known; catches in open water are not recorded."] = "Vis fiskestimer du har fisket i. Peg på stimen før du kaster, så dens navn kendes; fangster i åbent vand registreres ikke.",
	["Show goal"] = "Vis mål",
	["Show have/goal; the count turns green once the goal is reached."] = "Vis har/mål; tallet bliver grønt når målet er nået.",
	["Show herb nodes."] = "Vis urtenodes.",
	["Show hidden nodes again"] = "Vis skjulte nodes igen",
	["Show hidden sections"] = "Vis skjulte afsnit",
	["Show how many features you have seen at this camp and the fire's slots."] = "Vis hvor mange faciliteter du har set ved denne lejr, og bålets pladser.",
	["Show how many you carry."] = "Vis hvor mange du har.",
	["Show in the window"] = "Vis i vinduet",
	["show in the window"] = "vis i vinduet",
	["Show it faded"] = "Vis den nedtonet",
	["show it in the Dungeons window (out of combat)"] = "vis den i dungeonvinduet (uden for kamp)",
	["show it in your journal"] = "vis den i din journal",
	["Show it inside dungeons, raids and battlegrounds too."] = "Vis den også i dungeons, raids og battlegrounds.",
	["show it on the map"] = "vis den på kortet",
	["show its map, packs and routes"] = "vis dets kort, packs og ruter",
	["show its terms"] = "vis dens søgeord",
	["Show keybind"] = "Vis genvejstast",
	["Show LibDataBroker feeds"] = "Vis LibDataBroker-feeds",
	["Show macro name"] = "Vis makronavn",
	["Show mining nodes."] = "Vis malmnodes.",
	["Show nearby nodes on the minimap, also from the zone next door when you stand near its border."] = "Vis nodes i nærheden på minikortet, også fra nabozonen når du står nær grænsen.",
	["Show next to DBM-PvP"] = "Vis sammen med DBM-PvP",
	["Show on"] = "Vis på",
	["Show on mouse over"] = "Vis med musen over",
	["Show on screen"] = "Vis på skærmen",
	["Show only one class, characters with one profession, or characters with one bank mark."] = "Vis kun én klasse, karakterer med et bestemt fag eller karakterer med et bestemt bankmærke.",
	["Show only runs from the last 24 hours."] = "Vis kun runs fra de seneste 24 timer.",
	["Show only the model"] = "Vis kun modellen",
	["Show or fold the Info Bar"] = "Vis eller fold infobjælken sammen",
	["show or hide the game's own frame rate counter"] = "vis eller skjul spillets egen FPS-tæller",
	["Show pets in five-player groups."] = "Vis pets i grupper med fem spillere.",
	["Show pets in raids."] = "Vis pets i raids.",
	["Show placeholders in move mode"] = "Vis pladsholdere i flyttetilstand",
	["Show raid groups 1 to this number, e.g. 5 to leave out bench groups 6 to 8."] = "Vis raidgruppe 1 til dette tal, fx 5 for at udelade reservegrupperne 6 til 8.",
	["Show rank upgrades"] = "Vis rangopgraderinger",
	["Show samples"] = "Vis eksempler",
	["Show session gain"] = "Vis gevinst i sessionen",
	["Show tabs only on mouse-over"] = "Vis kun fanerne når musen er over chatten",
	["Show tenths of a second under ten seconds, or whole seconds only."] = "Vis tiendedele af sekunder under ti sekunder eller kun hele sekunder.",
	["Show test timers"] = "Vis testnedtællinger",
	["Show texts, flashes and icons in combat for every trigger. When off, only triggers that allow it (ready check, queue pop, pull) show in combat. Sounds always play."] = "Vis tekster, blink og ikoner i kamp for alle udløsere. Når det er slået fra, vises kun de udløsere i kamp som tillader det (klar-tjek, kø klar, pull). Lyde afspilles altid.",
	["show the bar"] = "vis bjælken",
	["Show the bar also when no session runs, to start one with a click. On a flight path it steps aside for the flight bar. Move it in move mode (Farming Bar)."] = "Vis også bjælken når ingen session kører, så du kan starte en med et klik. På en flyverute viger den for flyvenedtællingens bjælke. Flyt den i flyttetilstand (Farmingbjælke).",
	["Show the bar only while this is the power your character uses right now (a druid's energy only in cat form)."] = "Vis kun bjælken mens det er den ressource din karakter bruger lige nu (en Druids energi kun i Cat Form).",
	["Show the block"] = "Vis blokken",
	["Show the buffs as icons with timers instead of rows."] = "Vis buffs som ikoner med nedtællinger i stedet for rækker.",
	["Show the changes"] = "Vis ændringerne",
	["show the changes, then move them to the highest rank you know with Apply (macros change in /eui macros)"] = "vis ændringerne, og flyt dem derefter til den højeste rang du kender med Anvend (makroer ændres i /eui macros)",
	["Show the count"] = "Vis antallet",
	["Show the countdown only once fewer seconds than this are left."] = "Vis først nedtællingen når der er færre sekunder end dette tilbage.",
	["Show the game's spinning glow on pet abilities set to autocast."] = "Vis spillets roterende glød på petevner der er sat til autocast.",
	["Show the gold you looted and gold per hour."] = "Vis det guld du har lootet, og guld pr. time.",
	["Show the icon faded"] = "Vis ikonet nedtonet",
	["Show the icon in gray while it is on cooldown."] = "Vis ikonet i gråt mens det er på cooldown.",
	["Show the icon in gray while its action is on cooldown. The game says when; the global cooldown alone doesn't gray it."] = "Vis ikonet i gråt mens handlingen er på cooldown. Spillet siger hvornår; den globale cooldown alene gør det ikke gråt.",
	["Show the icon in gray while you can't cast it."] = "Vis ikonet i gråt mens du ikke kan caste det.",
	["Show the items you looted, their value and value per hour."] = "Vis de genstande du har lootet, deres værdi og værdi pr. time.",
	["Show the key bound to each button of this bar."] = "Vis tasten der er bundet til hver knap på denne linje.",
	["Show the key bound to each button."] = "Vis tasten der er bundet til hver knap.",
	["Show the last fight's time until the next fight starts."] = "Vis den sidste kamps tid indtil den næste kamp starter.",
	["Show the leader's resets"] = "Vis lederens resets",
	["Show the list in five-player groups too."] = "Vis også listen i grupper med fem spillere.",
	["Show the name"] = "Vis navnet",
	["Show the name icons in %s lines."] = "Vis navneikonerne i linjer fra %s.",
	["Show the name icons in channel %d."] = "Vis navneikonerne i kanal %d.",
	["Show the name icons in chat tab %d (counted from the left in the chat settings)."] = "Vis navneikonerne i chatfane %d (talt fra venstre i chatindstillingerne).",
	["Show the name of macros on their button."] = "Vis navnet på makroer på deres knap.",
	["Show the name of macros on this bar."] = "Vis navnet på makroer på denne linje.",
	["Show the nodes on the world map."] = "Vis nodes på verdenskortet.",
	["Show the notes, arrows and free-hand lines of the route on the map. The editor always shows them."] = "Vis rutens noter, pile og frihåndslinjer på kortet. Editoren viser dem altid.",
	["Show the number of stacks in the button's top right corner, as the game counts them."] = "Vis antallet af stakke i knappens øverste højre hjørne som spillet tæller dem.",
	["Show the panel only near a campfire or while a camp buff is on you."] = "Vis kun panelet nær et lejrbål eller mens du har en lejrbuff.",
	["Show the panels"] = "Vis panelerne",
	["Show the right panel"] = "Vis højre panel",
	["Show the runs of your other characters too (in gray)."] = "Vis også dine andre karakterers runs (i gråt).",
	["Show the saved bank of the selected character."] = "Vis den gemte bank for den valgte karakter.",
	["Show the sessions of one zone, or of all zones."] = "Vis sessionerne for én zone eller for alle zoner.",
	["Show the tabs while one flashes"] = "Vis fanerne mens en af dem blinker",
	["Show the time left on each bar."] = "Vis den resterende tid på hver bjælke.",
	["Show the window"] = "Vis vinduet",
	["Show the XP you gained and XP per hour."] = "Vis den XP du har fået, og XP pr. time.",
	["Show this area"] = "Vis dette område",
	["Show this bar"] = "Vis denne bjælke",
	["Show this buff on the bar."] = "Vis denne buff på bjælken.",
	["Show this cooldown on the bar once you know it."] = "Vis denne cooldown på bjælken når du kender den.",
	["Show this group"] = "Vis denne gruppe",
	["Show this panel. Off keeps its settings without showing it."] = "Vis dette panel. Slået fra beholder panelet sine indstillinger uden at blive vist.",
	["Show this section"] = "Vis dette afsnit",
	["Show this trigger's text, flash and icon in combat too. Sounds always play."] = "Vis også denne udløsers tekst, blink og ikon i kamp. Lyde afspilles altid.",
	["Show time"] = "Vis tid",
	["Show tooltip"] = "Vis tooltip",
	["Show waiting events"] = "Vis ventende hændelser",
	["Show what you gained or lost since login next to the count."] = "Vis ved siden af tallet hvad du har tjent eller tabt siden du loggede ind.",
	["Show what you loot"] = "Vis hvad du looter",
	["Show when solo"] = "Vis når du er alene",
	["Show when you can place your next camp feature (one per hour, shared by all features)."] = "Vis hvornår du kan placere din næste lejrfacilitet (én pr. time, fælles for alle faciliteter).",
	["Show who is typing"] = "Vis hvem der skriver",
	["Show your buffs in EldoUI's buff frame (mover: Buffs)."] = "Vis dine buffs i EldoUI's bufframme (flyttefelt: Buffs).",
	["Show your character"] = "Vis din karakter",
	["Show your debuffs in EldoUI's debuff frame (mover: Debuffs)."] = "Vis dine debuffs i EldoUI's debufframme (flyttefelt: Debuffs).",
	["show your saved bank anywhere"] = "vis din gemte bank hvor som helst",
	["Show yourself"] = "Vis dig selv",
	["Show, fade or hide the bar while the aura is missing, the spell is ready or every charge is back."] = "Vis, ton ud eller skjul bjælken mens auraen mangler, evnen er klar eller alle ladninger er tilbage.",
	["Showing test frames. Click the button again to hide them, or use /eui move to place them."] = "Viser testrammer. Klik på knappen igen for at skjule dem, eller brug /eui move for at placere dem.",
	["Shown"] = "Vist",
	["Shown in front of the value when the label is set to \"My own text\"."] = "Vises foran værdien når etiketten er sat til \"Min egen tekst\".",
	["Shown name"] = "Vist navn",
	["Shown now: %d. Secret values skipped this session: %d."] = "Vist nu: %d. Hemmelige værdier sprunget over i denne session: %d.",
	["Shows 1/3 on the edit box while a message needs more than one part, and the letters used close to the 255 limit."] = "Viser 1/3 på chatfeltet når en besked kræver mere end én del, og antallet af brugte bogstaver tæt på grænsen på 255.",
	["Shows a pulse now (the entry chosen below, or the first on the list)."] = "Viser en puls nu (posten der er valgt nedenfor, eller den første på listen).",
	["Shows a sample line in every scroll area and on your target's nameplate. Out of combat only."] = "Viser en prøvelinje i hvert rulleområde og på dit måls nameplate. Kun uden for kamp.",
	["Shows a small handle on every icon in move mode to drag it or open its settings."] = "Viser et lille håndtag på alle ikoner i flyttetilstand, så du kan trække dem eller åbne deres indstillinger.",
	["Shows AFK in place of the health text."] = "Viser AFK i stedet for livsteksten.",
	["Shows at once at full size and fades, no pop."] = "Vises straks i fuld størrelse og tones ud, uden pop.",
	["Shows Dodge, Parry, Miss and similar words on the plate."] = "Viser Dodge, Parry, Miss og lignende ord på nameplaten.",
	["Shows each Legacy node's icon in front of its name on the Build page."] = "Viser hver Legacy-nodes ikon foran dens navn på siden Build.",
	["Shows EldoUI's map of this dungeon with its packs and your route again."] = "Viser igen EldoUI's kort over dette dungeon med dets packs og din rute.",
	["Shows every section you hid on this character. Right-click a section's title in the bag or bank window to hide it; click a hidden title to show it again."] = "Viser alle afsnit som du har skjult på denne karakter. Højreklik på et afsnits titel i taske- eller bankvinduet for at skjule det; klik på en skjult titel for at vise det igen.",
	["Shows faded icons in move mode where hidden icons would sit."] = "Viser udtonede ikoner i flyttetilstand der hvor skjulte ikoner ville sidde.",
	["Shows heals the enemy receives."] = "Viser heals som fjenden modtager.",
	["Shows how many looks of each set you have on the Loot Guide's Sets page, and marks the items in Loot Guide lists."] = "Viser hvor mange udseender af hvert sæt du har, på siden Sæt i Loot Guide, og markerer genstandene i Loot Guide-lister.",
	["Shows how much rested XP your offline characters have built up since logout, from the game's published rate. Estimates are marked with ~."] = "Viser hvor meget udhvilet XP dine offline karakterer har opbygget siden logout, ud fra spillets offentliggjorte rate. Estimater er markeret med ~.",
	["Shows how much saved data each character uses (/eui alts size)."] = "Viser hvor meget plads hver karakters gemte data fylder (/eui alts size).",
	["Shows links as [example.com]."] = "Viser links som [example.com].",
	["Shows loot, money and currency lines even while EldoUI's loot toasts show them too."] = "Viser linjer for loot, penge og valuta selv om EldoUI's pop op-beskeder for loot også viser dem.",
	["Shows one bar of each kind for half a minute, so you can set up the look. Drag the bars in Move mode."] = "Viser én bjælke af hver slags i et halvt minut, så du kan indstille udseendet. Træk bjælkerne i flyttetilstand.",
	["Shows one decimal when less than a second is left."] = "Viser én decimal når der er mindre end et sekund tilbage.",
	["Shows only the nodes your draft adds, removes or changes."] = "Viser kun de noder din kladde tilføjer, fjerner eller ændrer.",
	["Shows only the recipes whose name contains this text."] = "Viser kun de opskrifter hvis navn indeholder denne tekst.",
	["Shows sample frames so you can size and place them while solo. Click again to hide them."] = "Viser eksempelrammer så du kan tilpasse størrelse og placering mens du er alene. Klik igen for at skjule dem.",
	["Shows the account bank pages in the bank window when the game lets you view them."] = "Viser kontobankens sider i bankvinduet når spillet lader dig se dem.",
	["Shows the average item level the game reports for your gear."] = "Viser det gennemsnitlige item level som spillet angiver for dit udstyr.",
	["Shows the broom that runs the game's own bag and bank sort. Right-click it at the bank to sort the account bank."] = "Viser kosten der kører spillets egen sortering af tasker og bank. Højreklik på den i banken for at sortere kontobanken.",
	["Shows the challenges of one category."] = "Viser udfordringerne i én kategori.",
	["Shows the chat command that switches when spells cast, selected for copying. Paste it in chat and press Enter."] = "Viser chatkommandoen der skifter hvornår spells castes, markeret til kopiering. Indsæt den i chatten og tryk på Enter.",
	["Shows the chat command that turns soft interact on for mouse, keyboard and gamepad, selected for copying. Paste it in chat and press Enter."] = "Viser chatkommandoen der slår soft interact til for mus, tastatur og gamepad, markeret til kopiering. Indsæt den i chatten og tryk på Enter.",
	["Shows the Eldostar guide window."] = "Viser Eldostars guidevindue.",
	["Shows the Errors tab, or the log as text without the chat panel."] = "Viser fanen Fejl eller loggen som tekst uden chatpanelet.",
	["Shows the game's minimap large here, with your arrow and your group as the game draws them. The mouse wheel zooms. Out of combat."] = "Viser spillets minikort stort her, med din pil og din gruppe sådan som spillet tegner dem. Musehjulet zoomer. Uden for kamp.",
	["Shows the game's own map until you close the map. The Dungeon map button on it brings this view back."] = "Viser spillets eget kort indtil du lukker kortet. Knappen Dungeonkort på det henter denne visning tilbage.",
	["Shows the group only while you are in this stance or form. Any: in every one."] = "Viser kun gruppen mens du er i denne stance eller form. Alle: i hver eneste.",
	["Shows the guide window again after you closed it. /eui eldostar show does the same."] = "Viser guidevinduet igen efter du har lukket det. /eui eldostar show gør det samme.", -- l10n: keep
	["Shows the keyring's slots in the bag window, in their own section."] = "Viser nøgleringens pladser i taskevinduet, i deres eget afsnit.",
	["Shows the level-up trigger with sample values."] = "Viser udløseren for nyt level med eksempelværdier.",
	["Shows the month after."] = "Viser måneden efter.",
	["Shows the month before."] = "Viser måneden før.",
	["Shows the next page of characters."] = "Viser næste side med karakterer.",
	["Shows the planner window (also /eui legacy)."] = "Viser planlæggervinduet (også /eui legacy).",
	["Shows the previous page of characters."] = "Viser forrige side med karakterer.",
	["Shows the screen now (/eui afk test). Click to close."] = "Viser skærmen nu (/eui afk test). Klik for at lukke.",
	["Shows the seconds on each icon from this many seconds."] = "Viser sekunderne på hvert ikon fra dette antal sekunder.",
	["Shows the set you captured for this class and spec, ready to paste into Blizzard's Import box."] = "Viser det sæt du har indfanget for denne klasse og spec, klar til at indsætte i Blizzards importfelt.",
	["Shows the spell or item icon next to the line when the game names it."] = "Viser evnens eller genstandens ikon ved linjen når spillet nævner den.",
	["Shows the spell's tooltip and the timer type on mouse over. Off keeps the bar click-through."] = "Viser evnens tooltip og nedtællingstypen når du holder musen over. Fra: klik går gennem bjælken.",
	["Shows the step and its next goal on two lines."] = "Viser trinnet og dets næste mål på to linjer.",
	["Shows the whole step: its tip, every goal and the buttons."] = "Viser hele trinnet: dets tip, alle mål og knapperne.",
	["Shows this character's bags in the Bags module's own window."] = "Viser denne karakters tasker i Tasker-modulets eget vindue.",
	["Shows this entry's pulse now, with its sound and speech."] = "Viser denne posts puls nu med lyd og tale.",
	["Shows this floor of the dungeon."] = "Viser denne etage af dungeonet.",
	["Shows this scroll area. Its events show nowhere while it is off."] = "Viser dette rulleområde. Dets hændelser vises ingen steder mens det er slået fra.",
	["Shows whether aura alarms are running and how many spell IDs they watch."] = "Viser om auraalarmer kører og hvor mange evne-ID'er de overvåger.",
	["Shows while the game marks you Away (/afk, or after a few idle minutes). You stay Away until you move or type, as always."] = "Vises mens spillet markerer dig som AFK (/afk eller efter nogle minutter uden aktivitet). Du forbliver AFK til du bevæger dig eller skriver, som altid.",
	["Shows worn gear as a percentage or a red tint."] = "Viser slidt udstyr som procent eller som rød farvetone.",
	["Shows your killing blows, honorable kills and deaths in a battleground."] = "Viser dine dræbende slag, ærefulde drab og dødsfald i et battleground.",
	["Shows your spell's or item's icon in the middle of the screen when the game says it is ready again, with an optional sound and spoken line."] = "Viser ikonet for din evne eller genstand midt på skærmen når spillet melder den klar igen, med valgfri lyd og talt linje.",
	["Side by side"] = "Side om side",
	["Side by side or stacked, for the shared strip."] = "Side om side eller stablet, for den fælles stribe.",
	["Side panels"] = "Sidepaneler",
	["Silences every trigger's sound (texts and flashes still show). Also /eui fx mute."] = "Slår lyden fra for alle udløsere (tekster og blink vises stadig). Også /eui fx mute.",
	["Silent visual"] = "Silent visual",
	["Single mob"] = "Enkelt mob",
	["Sit by the fire"] = "Sæt dig ved bålet",
	["Sixes"] = "Seksere",
	["Size and layout"] = "Størrelse og layout",
	["Size and look"] = "Størrelse og udseende",
