	["Size of Blizzard's roll frames on EldoUI's roll spot."] = "Størrelsen på Blizzards rulrammer på EldoUI's rulplads.",
	["Size of Blizzard's start countdown on its EldoUI mover, in percent."] = "Størrelsen på Blizzards startnedtælling på dens EldoUI-flyttefelt, i procent.",
	["Size of critical hits and other sticky lines."] = "Størrelse på kritiske hits og andre faste linjer.",
	["Size of critical hits, in percent of normal."] = "Størrelse på kritiske hits i procent af normal.",
	["Size of each buff icon."] = "Størrelse på hvert buffikon.",
	["Size of each button."] = "Størrelse på hver knap.",
	["Size of each counter's icon."] = "Størrelsen på hver tællers ikon.",
	["Size of each debuff icon."] = "Størrelse på hvert debuffikon.",
	["Size of each dot."] = "Størrelse på hver prik.",
