	["Size of each slot in pixels."] = "Størrelsen på hver plads i pixels.",
	["Size of EldoUI's leave-vehicle button."] = "Størrelsen på EldoUI's knap til at forlade køretøjer.",
	["Size of names and values (Blizzard's text scale still applies on top)."] = "Størrelse på navne og værdier (Blizzards tekstskala gælder stadig oveni).",
	["Size of names and values."] = "Størrelse på navne og værdier.",
	["Size of normal lines in this area. General uses the general size."] = "Størrelse på normale linjer i dette område. Generelt bruger den generelle størrelse.",
	["Size of normal lines."] = "Størrelse på normale linjer.",
	["Size of plate numbers."] = "Størrelse på tal på nameplates.",
	["Size of sticky lines in this area. General uses the general size."] = "Størrelse på faste linjer i dette område. Generelt bruger den generelle størrelse.",
	["Size of the alert in percent (replaces Blizzard's Edit Mode size while Move is on)."] = "Advarslens størrelse i procent (erstatter Blizzards Edit Mode-størrelse mens Flyt er slået til).",
	["Size of the bag and bank windows, from 50 to 150 percent."] = "Størrelsen på taske- og bankvinduerne, fra 50 til 150 procent.",
	["Size of the big icon. 64 is the space the layouts keep for it."] = "Størrelsen på det store ikon. 64 er den plads layoutene holder til det.",
	["Size of the BoE and BoU text."] = "Størrelsen på BoE- og BoU-teksten.",
	["Size of the bubble text."] = "Størrelsen på teksten i taleboblerne.",
	["Size of the camp panel."] = "Lejrpanelets størrelse.",
	["Size of the Cast, Lure and Swap buttons."] = "Størrelsen på knapperne Kast, Agn og Skift.",
	["Size of the chat text (skin switch)."] = "Chattekstens størrelse (Skin-kontakt).",
	["Size of the controller action bar while it uses the EldoUI mover (Move switch of Gamepad HUD)."] = "Størrelsen på controllerens handlingslinje mens den bruger EldoUI-flyttefeltet (Flyt-kontakten for Gamepad-HUD).",
	["Size of the count text."] = "Størrelsen på tallets tekst.",
	["Size of the emoji in chat lines, in pixels. Auto follows the chat font size."] = "Størrelsen på emojis i chatlinjer, i pixels. Auto følger chattens skriftstørrelse.",
	["Size of the enchant icons."] = "Størrelse på enchant-ikonerne.",
	["Size of the feedback text."] = "Størrelse på feedbackteksten.",
	["Size of the goals; the step's title is one size larger."] = "Størrelsen på målene; trinnets titel er én størrelse større.",
	["Size of the icon that pops next to the text."] = "Størrelsen på ikonet der popper frem ved siden af teksten.",
	["Size of the icons on the bar. At most the thickness minus 4."] = "Størrelsen på ikonerne på bjælken. Højst tykkelsen minus 4.",
	["Size of the info text; the name is a little bigger."] = "Størrelsen på infoteksten; navnet er lidt større.",
	["Size of the item icons in the Quick Sell tab."] = "Størrelsen på genstandsikonerne i fanen Hurtigt salg.",
	["Size of the item level number."] = "Størrelsen på tallet for item level.",
	["Size of the item names in EldoUI's window."] = "Størrelsen på genstandsnavnene i EldoUI's vindue.",
	["Size of the large average item level number."] = "Størrelsen på det store tal for gennemsnitligt item level.",
	["Size of the mark."] = "Mærkets størrelse.",
	["Size of the name icons compared with the chat text."] = "Navneikonernes størrelse i forhold til chatteksten.",
	["Size of the name, time and count on every bar."] = "Størrelse på navn, tid og antal på alle bjælker.",
	["Size of the NPC's text and the choices. The name is a little larger."] = "Størrelsen på NPC'ens tekst og valgene. Navnet er lidt større.",
	["Size of the number of items in a stack."] = "Størrelsen på antallet af genstande i en stak.",
	["Size of the numbers and names."] = "Størrelsen på tal og navne.",
	["Size of the pack and boss markers."] = "Størrelsen på pack- og bossmarkørerne.",
	["Size of the part counter and the typing line."] = "Størrelse på deltælleren og skrivelinjen.",
	["Size of the pins."] = "Størrelse på nålene.",
	["Size of the possess buttons."] = "Størrelsen på kontrolknapperne.",
	["Size of the possess frame in percent."] = "Størrelsen på kontrolrammen i procent.",
	["Size of the seat indicator in percent while it uses the EldoUI mover."] = "Størrelsen på sædeindikatoren i procent mens den bruger EldoUI-flyttefeltet.",
	["Size of the spark relative to the bar height."] = "Gnistens størrelse i forhold til bjælkens højde.",
	["Size of the spell alerts around your character while they use the EldoUI mover (Move switch of Action button look). The Hide switch turns them off."] = "Størrelsen på evneadvarslerne omkring din karakter mens de bruger EldoUI-flyttefeltet (Flyt-kontakten for Handlingsknappernes udseende). Skjul-kontakten slår dem fra.",
	["Size of the stack count."] = "Størrelse på stakantallet.",
	["Size of the text you type."] = "Størrelsen på den tekst du skriver.",
	["Size of the time left."] = "Størrelse på den resterende tid.",
	["Size of the time."] = "Størrelse på tiden.",
	["Size of the timer texts."] = "Størrelse på nedtællingsteksterne.",
	["Size of the title and time."] = "Størrelse på titel og tid.",
	["Size of the totem bar in percent while it uses the EldoUI mover (Move switch of Totem bar)."] = "Størrelsen på totemlinjen i procent mens den bruger EldoUI-flyttefeltet (Flyt-kontakten for Totemlinje).",
	["Size of the whole bar in percent."] = "Størrelsen på hele linjen i procent.",
	["Size of the zone ability button in percent."] = "Størrelsen på zoneevnens knap i procent.",
	["Size of this event's text. Area uses the area's size."] = "Størrelse på teksten for denne hændelse. Område bruger områdets størrelse.",
	["Sizes the windows from the values below. Off: Details keeps its own size and the mover takes it over."] = "Sætter vinduernes størrelse ud fra værdierne nedenfor. Fra: Details beholder sin egen størrelse, og flyttefeltet overtager den.",
	["Skeletal horse"] = "Skelethest",
	["Skiff"] = "Jolle",
	["Skill"] = "Skill",
	["Skill filter"] = "Skillfilter",
	["Skill in every profession per character."] = "Skill i alle fag pr. karakter.",
	["Skill points you gain, from the game's chat line."] = "Skillpoints du får, fra spillets chatlinje.",
	["Skill ups"] = "Skillups",
	["Skill-ups"] = "Skillups",
	["Skill-ups, XP, honor and reputation"] = "Skillups, XP, ære og omdømme",
	["Skills"] = "Skills",
	["Skin any other panel the window shows."] = "Giv alle andre paneler i vinduet skin.",
	["Skin Blizzard's frames when Auto falls back"] = "Giv Blizzards rammer skin når Auto skifter over",
	["Skin flyouts"] = "Skin på flyouts",
	["Skin the currency panel."] = "Giv valutapanelet skin.",
	["Skin the PvP panel."] = "Giv PvP-panelet skin.",
	["Skin the reputation panel."] = "Giv omdømmepanelet skin.",
	["Skin the skills panel."] = "Giv skillpanelet skin.",
	["Skin the statistics panel."] = "Giv statistikpanelet skin.",
	["Skin the window tabs"] = "Skin på vinduets faner",
	["Skin tone"] = "Hudtone",
	["Skin tone of hands and people in the picker and autocomplete. The picker's tone buttons change it too. Emoji other players send keep their own tone."] = "Hudtone på hænder og personer i vælgeren og autofuldførelsen. Vælgerens toneknapper ændrer den også. Emojis som andre spillere sender, beholder deres egen hudtone.",
	["Skin, Move and Improve are the character window's switches on the Blizzard UI page; the settings here fine-tune each one."] = "Skin, Flyt og Forbedr er karaktervinduets kontakter på Blizzard-UI-siden; indstillingerne her finjusterer hver af dem.",
	["Skinned"] = "Med skin",
	["Skins and places Blizzard's Cooldown Manager, which keeps tracking every cooldown, and adds EldoUI's own rows that you can arrange into groups with their own looks."] = "Giver Blizzards Cooldown Manager skin og placering (den sporer stadig alle cooldowns) og tilføjer EldoUI's egne rækker som du kan samle i grupper med hver sit udseende.",
	["Skins and places Blizzard's own combat displays: damage meter, swing timer, loss of control, mirror and quest timers, death recap. Plus EldoUI's threat meter, combat timer and cursor ring."] = "Giver Blizzards egne kampvisninger skin og placering: skademåler, swingtimer, kontroltab, ånde- og udmattelsesbjælker, questnedtællinger, dødsoversigt. Plus EldoUI's aggromåler, kampur og markørring.",
	["Skipped (not in this DBM version): %s"] = "Sprunget over (findes ikke i denne DBM-version): %s",
	["Skips this step and remembers it as skipped. Undo takes it back."] = "Springer trinnet over og husker at det er sprunget over. Fortryd tager det tilbage.",
	["Skull, cross and the other markers on members."] = "Kranie, kryds og de andre markører på medlemmer.",
	["Slice and Dice on you"] = "Slice and Dice på dig",
	["Slide"] = "Glid",
	["Slide the carts until the kodo cart can leave the market."] = "Skub vognene, til kodovognen kan forlade markedet.",
	["Slide the coins and merge equal ones until one is worth 2048."] = "Skub mønterne, og flet ens mønter, til én er 2048 værd.",
	["Slide the pieces of a zone map back into place."] = "Skub brikkerne af et zonekort på plads igen.",
	["Sliding Map"] = "Skydepuslespil",
	["Slightly wide (5:4)"] = "Lidt bred (5:4)",
	["Slim"] = "Slim",
	["Sloop"] = "Slup",
	["Slot %d"] = "Plads %d",
	["Slot and type"] = "Plads og type",
	["Slot border"] = "Pladskant",
	["Slot border thickness"] = "Tykkelse på pladskant",
	["Slot free again"] = "Plads ledig igen",
	["Slot height"] = "Pladshøjde",
	["Slot size"] = "Pladsstørrelse",
	["Slots"] = "Pladser",
	["Slots next to the debuffs"] = "Pladser ved siden af debuffene",
	["Slots per row in the bag window."] = "Pladser pr. række i taskevinduet.",
	["Slots per row in the bank window."] = "Pladser pr. række i bankvinduet.",
	["Slow"] = "Langsom",
	["Slow camera turn"] = "Langsom kameradrejning",
	["Slow camera turn, darker world, tall panel."] = "Langsom kameradrejning, mørkere verden, højt panel.",
	["Small 24 px buttons close together."] = "Små knapper på 24 px tæt sammen.",
	["Small 24 px icons, close together."] = "Små 24 px ikoner tæt sammen.",
	["Small 26 px icons close together with the time on them."] = "Små ikoner på 26 px tæt sammen med tiden på dem.",
	["Small 26 px icons, 16 per row."] = "Små ikoner på 26 px, 16 pr. række.",
	["Small 36 px icons with 2 px gaps for a tight center."] = "Små 36 px ikoner med 2 px mellemrum til en tæt midte.",
	["Small buttons with the catch count."] = "Små knapper med fangsttælleren.",
	["Small colored dots, quieter on a busy map."] = "Små farvede prikker, mere afdæmpet på et travlt kort.",
	["Small field"] = "Lille mark",
	["Small icons under the item level: the enchant, each socketed gem, and a gray square per empty socket. Read from the item link."] = "Små ikoner under item level: enchanten, hver isat gem og en grå firkant pr. tom socket. Læses fra genstandslinket.",
	["Small icons without time left, sorted by order gained."] = "Små ikoner uden resterende tid, sorteret i den rækkefølge de kom.",
	["Small markers without counts and a thin line, for a calm map."] = "Små markører uden antal og en tynd linje giver et roligt kort.",
	["Small row without background or session gain."] = "Lille række uden baggrund eller gevinst i sessionen.",
	["Small rows and slim roll bars, fewer toasts."] = "Små rækker og smalle rulbjælker, færre pop op-beskeder.",
	["Small rows, more nodes on screen."] = "Små rækker, flere noder på skærmen.",
	["Small rows, no icons, see-through."] = "Små rækker, ingen ikoner, gennemsigtig baggrund.",
	["Small sections (categories or bags) share a row instead of starting a new one."] = "Små afsnit (kategorier eller tasker) deler en række i stedet for at starte en ny.",
	["Small slots in wide rows, for big bags."] = "Små pladser i brede rækker, til store tasker.",
	["Small sprites flying off the fill edge and drifting inside the bar. Off keeps colors, spark and flashes."] = "Små billeder der flyver ud fra fyldkanten og driver inde i bjælken. Fra beholder farver, gnist og blink.",
	["Small straight"] = "Lille straight",
	["Small text and tight boxes for busy cities."] = "Lille tekst og tætte bokse til travle byer.",
	["Small text, no tips and no goals along the way, in a see-through panel."] = "Lille tekst, ingen tips og ingen mål undervejs, i et gennemsigtigt panel.",
	["Small, out-of-the-way frames: thin class-colored bars with names and role icons, no buff icons, and a slim mana bar on healers in the party. Good for damage dealers."] = "Små, diskrete rammer: tynde bjælker i klassefarve med navne og rolleikoner, ingen buffikoner og en smal manabjælke på healere i gruppen. Godt til DPS'ere.",
	["Smaller gray line under the text. Same tokens."] = "Mindre grå linje under teksten. Samme tokens.",
	["Smallest change"] = "Mindste ændring",
	["Smoke puff"] = "Røgpust",
	["Smooth fill"] = "Glidende fyld",
	["Smooth movement"] = "Glidende bevægelse",
	["Snake"] = "Snake",
	["Snap distance"] = "Fastgørelsesafstand",
	["Snap EldoUI frames to"] = "Fastgør EldoUI-rammer til",
	["Social and money on the info bar, place and progress on a second bar."] = "Socialt og penge på infobjælken, sted og fremskridt på en anden bjælke.",
	["Soft chimes on the effects volume and no flash, for players who only want a nudge."] = "Bløde klokketoner på effektlydstyrken og intet blink, til spillere der kun vil have et lille puf.",
	["Soft fill"] = "Blød udfyldning",
	["Soft glow"] = "Blød glød",
	["Soft interact"] = "Soft interact",
	["Soft interact is off for mouse and keyboard, so the key misses the bobber. Only your own chat command can change this protected setting."] = "Soft interact er slået fra for mus og tastatur, så tasten rammer ikke flådet. Kun din egen chatkommando kan ændre denne beskyttede indstilling.",
	["Soft vignette"] = "Blød vignet",
	["Sold"] = "Solgt",
	["Solid"] = "Dækkende",
	["Solitaire"] = "Kabale",
	["someone in the group is offline"] = "nogen i gruppen er offline",
	["Someone is casting a resurrection on this member."] = "Nogen caster en genoplivning på dette medlem.",
	["someone is zoning into an instance"] = "nogen er på vej ind i en instans",
	["Soon"] = "Snart",
	["Sort button"] = "Sorteringsknap",
	["Sort by"] = "Sorter efter",
	["Sort direction"] = "Sorteringsretning",
	["Sorted"] = "Sorteret",
	["Sorting"] = "Sortering",
	["Sorts the trigger list."] = "Sorterer listen over udløsere.",
	["Soul Shard count"] = "Antal Soul Shards",
	["Soul Shards"] = "Soul Shards",
	["Sound alarms when you stand in harm, played by the game itself; EldoUI never reads the combat log. Off by default: turn it on under Modules."] = "Lydalarmer når du står i noget skadeligt, afspillet af spillet selv; EldoUI læser aldrig kamploggen. Slået fra som standard: slå det til under Moduler.",
	["Sound alarms when you stand in something harmful (spell list), run out of breath or fatigue, or are attacked while AFK."] = "Lydalarmer når du står i noget skadeligt (evneliste), løber tør for luft, bliver udmattet eller bliver angrebet mens du er AFK.",
	["Sound and speech"] = "Lyd og tale",
	["Sound at zero. Blizzard's countdown end by default."] = "Lyd ved nul. Blizzards slutlyd for nedtælling som standard.",
	["Sound effects and master volume while fishing mode is on."] = "Lydeffekter og samlet lydstyrke mens fisketilstand er slået til.",
	["Sound for each second. Blizzard's countdown tick by default."] = "Lyd for hvert sekund. Blizzards tiklyd for nedtælling som standard.",
	["Sound for my name"] = "Lyd ved mit navn",
	["Sound on a new enemy"] = "Lyd ved ny fjende",
	["Sound on a proc"] = "Lyd ved en proc",
	["sound on or off"] = "lyd til eller fra",
	["Sound per channel"] = "Lyd pr. kanal",
	["Sound played once when the warning starts. None plays nothing."] = "Lyd der afspilles én gang når advarslen starter. Ingen: der afspilles ingen lyd.",
	["Sound played when this event shows (when sounds are on, General tab)."] = "Lyd der afspilles når denne hændelse vises (når lyde er slået til på fanen Generelt).",
	["Sound to play. EldoUI's own, the game's, or any SharedMedia pack you have installed. Custom takes a file ID or an addon path."] = "Lyden der skal afspilles. EldoUI's egne, spillets eller enhver SharedMedia-pakke som du har installeret. Brugerdefineret: angiv et fil-id eller en addonsti.",
	["Sound when an aura ends"] = "Lyd når en aura slutter",
	["Sound when an aura starts"] = "Lyd når en aura starter",
	["Sound: %s"] = "Lyd: %s",
	["Sounds"] = "Lyde",
	["Sounds, big text, flashes and icon pops for moments in the game: \"When\", \"Only if\" and what to do. Off by default: turn it on under Modules."] = "Lyde, stor tekst, blink og ikoner der popper frem til øjeblikke i spillet: \"Når\", \"Kun hvis\" og hvad der skal ske. Slået fra som standard: slå det til under Moduler.",
	["Sounds, big text, screen flashes and icons for moments in the game: level up, epic loot, whispers, queue pops, boss kills and more. Fully customizable triggers."] = "Lyde, stor tekst, skærmblink og ikoner til øjeblikke i spillet: nyt level, epic loot, hvisk, køer der er klar, bossdrab og mere. Udløserne kan tilpasses fuldt ud.",
	["Source"] = "Kilde",
	["Sow stones round the board and fill your store before the Horde fills its own."] = "Så sten rundt på brættet og fyld dit lager før Horden fylder sit.",
	["SP"] = "SP",
	["Space"] = "Space",
	["Space around the buttons inside the backdrop."] = "Plads omkring knapperne inde i baggrunden.",
	["Space between bars."] = "Afstand mellem bjælker.",
	["Space between buttons."] = "Afstand mellem knapperne.",
	["Space between icons or bars."] = "Afstand mellem ikoner eller bjælker.",
	["Space between icons."] = "Afstand mellem ikoner.",
	["Space between rows"] = "Afstand mellem rækker",
	["Space between the bars of the block."] = "Afstand mellem blokkens bjælker.",
	["Space between the buttons and the edge of the backdrop."] = "Afstand mellem knapperne og baggrundens kant.",
	["Space between the text and the edge of the box."] = "Afstand mellem teksten og boksens kant.",
	["Space between the viewer and the chosen frame."] = "Afstand mellem visningen og den valgte ramme.",
	["Space first shows all of the text, then accepts, continues or completes the quest on the page. Off: Space jumps as usual."] = "Space viser først hele teksten og accepterer, fortsætter eller fuldfører derefter questen på siden. Fra: Space hopper som normalt.",
	["Space goes on"] = "Space går videre",
	["Space or a click: cast, then strike. P: pause."] = "Mellemrum eller et klik: kast og slå så til. P: pause.",
	["Space or a click: cast."] = "Mellemrum eller et klik: kast.",
	["Space or a click: roll. P: pause."] = "Mellemrum eller et klik: slå. P: pause.",
	["Space or click: all of the text"] = "Space eller klik: hele teksten",
	["Space to the essential row."] = "Afstand til den essentielle række.",
	["Space to the frame the meter is docked to."] = "Afstand til den ramme måleren er dokket til.",
	["Space, Enter or a click plays again."] = "Mellemrum, Enter eller et klik spiller igen.",
	["Space, Enter or a click starts. P pauses."] = "Mellemrum, Enter eller et klik starter. P sætter på pause.",
	["Space, Enter, P or a click plays on where you left off. New game starts over."] = "Mellemrum, Enter, P eller et klik spiller videre hvor du slap. Nyt spil starter forfra.",
	["Space, Enter, P or a click plays on."] = "Mellemrum, Enter, P eller et klik spiller videre.",
	["Space, Up or a click: flap. P: pause."] = "Mellemrum, op eller et klik: vingeslag. P: pause.",
	["Space, Up or a click: jump. Down or right-click: duck. P: pause."] = "Mellemrum, Op eller et klik: hop. Ned eller højreklik: duk dig. P: pause.",
	["Space: roll. 1 to 5 or a click: keep a die. Click a box to write the dice in it. P: pause."] = "Mellemrum: slå. 1 til 5 eller et klik: behold en terning. Klik på en rubrik for at skrive terningerne i den. P: pause.",
	["Spacer (empty gap)"] = "Mellemrum (tom plads)",
