	["Special"] = "Særlige",
	["Speed of this area in percent. General uses the general speed."] = "Områdets hastighed i procent. Generelt bruger den generelle hastighed.",
	["Speed, line limits and fonts of this area."] = "Hastighed, linjegrænser og skrifttyper for dette område.",
	["Spell"] = "Evne",
