	["Spell hit"] = "Spell hit",
	["Spell icons"] = "Evneikoner",
	["Spell ID or name whose range is checked. Empty uses your class's melee ability (Paladins and Shamans pick one, for example a melee strike)."] = "Evne-ID eller -navn hvis rækkevidde tjekkes. Tomt felt: din klasses nærkampsevne bruges (Paladins og Shamans vælger selv en, fx et nærkampsslag).",
	["Spell names"] = "Evnenavne",
	["Spell names or IDs for %s for the second row (defensives, interrupts, movement). A spell may also be in the main row."] = "Evnenavne eller -ID'er til %s til den anden række (defensive evner, afbrydelser, bevægelse). En evne kan også stå i hovedrækken.",
	["Spell names or IDs for %s, separated by commas, in the order they should show. Type a spell twice to show it twice."] = "Evnenavne eller -ID'er til %s adskilt af kommaer i den rækkefølge de skal vises. Skriv en evne to gange for at vise den to gange.",
	["Spell names or IDs for %s. Empty uses EldoUI's list for your class."] = "Evnenavne eller -ID'er til %s. Tomt felt: EldoUI's liste for din klasse bruges.",
	["Spell names or IDs, separated by commas, in the order they should show (up to 20). Shift-click a spell link into the box works too."] = "Evnenavne eller ID'er adskilt af kommaer, i den rækkefølge de skal vises (op til 20). Du kan også Shift-klikke et evnelink ind i feltet.",
	["Spell names, separated by commas, that are never upgraded, for example a low rank heal you keep for mana."] = "Navne på evner der aldrig opgraderes, adskilt med kommaer, for eksempel en heal i lav rang som du beholder for at spare mana.",
	["Spell pins"] = "Evnefastgørelser",
	["Spell power"] = "Spell power",
	["Spell rank upgraded: %s on %d buttons."] = { one = "Evnerang opgraderet: %s på %d knap.", other = "Evnerang opgraderet: %s på %d knapper." },
	["Spell ranks can be put back after combat."] = "Evnerang kan lægges tilbage efter kampen.",
	["Spell ranks can be upgraded after combat."] = "Evnerne kan opgraderes til højeste rang efter kampen.",
	["Spell schools"] = "Evneskoler",
	["Spell, key %s"] = "Evne, tast %s",
	["Spell, no key bound"] = "Evne, ingen tast tildelt",
	["Spell, not known yet"] = "Evne, ikke lært endnu",
	["Spells"] = "Evner",
	["Spells (IDs or names, separated by commas, up to six) whose cost gets a thin line on the bar, e.g. 1752, Eviscerate. The lines sit where the cost is on a full bar."] = "Evner (ID'er eller navne adskilt af kommaer, op til seks) hvis pris får en tynd streg på bjælken, fx 1752, Eviscerate. Stregerne sidder der hvor prisen ligger på en fuld bjælke.",
	["Spells and items"] = "Evner og genstande",
	["Spells cast when the key comes back up. This is a protected game setting: no addon can change it, but your own chat command can."] = "Spells castes når tasten slippes. Det er en beskyttet spilindstilling: ingen addon kan ændre den, men din egen chatkommando kan.",
	["Spells cast when the key goes down. This is a protected game setting: no addon can change it, but your own chat command can."] = "Spells castes når tasten trykkes ned. Det er en beskyttet spilindstilling: ingen addon kan ændre den, men din egen chatkommando kan.",
	["Spells with charges: gray while a charge comes back."] = "Evner med ladninger: grå mens en ladning kommer tilbage.",
	["Spells with charges: how visible the icon is while a charge comes back and at least one is left."] = "Evner med ladninger: hvor synligt ikonet er mens en ladning kommer tilbage og der er mindst én tilbage.",
	["Spi"] = "Spi",
	["Spin"] = "Rotation",
	["Spirit"] = "Spirit",
	["Splash"] = "Plask",
	["Split long messages"] = "Opdel lange beskeder",
