	["Spot on!"] = "Lige i plet!",
	["Spotlight"] = "Spotlight",
	["Spread"] = "Spredning",
	["Square 46 px essential icons, 36 px utility, centered rows, key text for spells on buttons you can't see."] = "Kvadratiske 46 px essentielle ikoner, 36 px Utility-ikoner, centrerede rækker, tastetekst for evner på knapper du ikke kan se.",
	["Square color"] = "Kvadratfarve",
