	["Square icon with a 1 px border and the theme font."] = "Kvadratisk ikon med en 1 px kant og temaskrifttypen.",
	["Square icons, 1 px borders, theme fonts and flat bars."] = "Kvadratiske ikoner, 1 px kanter, temaskrifttyper og flade bjælker.",
	["Squares are small colored indicators in the corner, like healer frames; the timer swipe stays."] = "Kvadrater er små farvede indikatorer i hjørnet, som på healerrammer; swipen for nedtællingen bevares.",
