	["Stacked meters: window 2 gets its own mover, above window 1 in every layout. Ungroup the windows in Details if it snapped them together."] = "Stablede målere: vindue 2 får sit eget flyttefelt over vindue 1 i alle layouts. Skil vinduerne ad i Details hvis den har fastgjort dem til hinanden.",
