	["Stacks of the same item show as one slot with the total count. A click, drag or split acts on one of the stacks, as on any slot, and the tooltip says how many stacks there are."] = "Stakke af samme genstand vises som én plads med det samlede antal. Et klik, træk eller en deling virker på én af stakkene, som på enhver plads, og tooltippet viser hvor mange stakke der er.",
