	["Standard view"] = "Standardvisning",
	["Standard: EldoUI's short label. No label: the value only. My own text: the text below. Icon: a small icon (where the datatext has one)."] = "Standard: EldoUI's korte etiket. Ingen etiket: kun værdien. Min egen tekst: teksten nedenfor. Ikon: et lille ikon (hvor datateksten har et).",
	["Standing in bad stuff"] = "Står i noget skadeligt",
	["Standing with each faction, in the game's groups."] = "Omdømme hos hver fraktion, grupperet som i spillet.",
	["Standing with every faction any of these characters has seen. Factions under a collapsed header keep their last value."] = "Omdømme hos alle fraktioner som en af disse karakterer har set. Fraktioner under en sammenklappet overskrift beholder deres seneste værdi.",
	["Stark"] = "Stark",
	["Start %s over from its first step? Your place in it is cleared."] = "Vil du starte %s forfra fra første trin? Din plads i den ryddes.",
