	["Switch back to my Details profile"] = "Skift tilbage til min Details-profil",
	["Switch back to my profile"] = "Skift tilbage til min profil",
	["Switch between the game's dungeon map and the schematic, where packs are placed by where they stand (approximate)."] = "Skift mellem spillets dungeonkort og det skematiske kort hvor packs er placeret efter hvor de står (omtrentligt).",
	["switch between your target (T) and your focus (F)"] = "skift mellem dit mål (T) og dit fokus (F)",
