	["take the bag out, drop a bag here to swap"] = "tag tasken ud, slip en taske her for at bytte",
	["Take the spells EldoUI last put on your bars off again, where a button still holds them. Same as /eui spells undo."] = "Tag de evner EldoUI sidst satte på dine linjer, af igen, hvor en knap stadig har dem. Det samme som /eui spells undo.",
	["Take the spells of the last fill off bars 4 and 5 again, where a button still holds them. Same as /eui fillbars undo."] = "Tag evnerne fra den sidste fyldning af linje 4 og 5 igen, hvor en knap stadig har dem. Det samme som /eui fillbars undo.",
	["Take the spells off bars 4 and 5"] = "Tag evnerne af linje 4 og 5",
