	["Talent Planner"] = "Talentplanlægger",
	["Talent plans (%d)"] = { one = "Talentplan (%d)", other = "Talentplaner (%d)" },
	["Talent plans saved on the account for the character's class. Hover a row for their names; right-click a name to open them in the Talent Planner."] = "Talentplaner gemt på kontoen for karakterens klasse. Hold musen over en række for at se navnene; højreklik på et navn for at åbne dem i Talentplanlæggeren.",
	["talents"] = "talenter",
	["Talk"] = "Talk",
	["Talk to %s"] = "Tal med %s",
	["Talking to an NPC"] = "Samtale med en NPC",
	["Tall"] = "Tall",
	["Tall (3:4)"] = "Høj (3:4)",
	["Tall bar with current and percent, wide pips."] = "Høj bjælke med nuværende værdi og procent, brede pips.",
	["Tall rows and big icons, easy to read."] = "Høje rækker og store ikoner, let at læse.",
	["Tall rows, big icons and larger text."] = "Høje rækker, store ikoner og større tekst.",
	["Taller bar with 16 pt text."] = "Højere bjælke med tekst i 16 pt.",
	["Tank bar color"] = "Farve på tankbjælke",
	["Tank color"] = "Tankfarve",
	["Tank role"] = "Tankrolle",
	["Tank, healer or damage icon."] = "Ikon for tank, healer eller DPS.",
	["target"] = "mål",
	["Target a player first."] = "Vælg en spiller som mål først.",
	["Target border"] = "Målkant",
	["Target dodge, parry, miss"] = "Mål: dodge, parry, miss",
	["Target Hits"] = "Hits på målet",
	["Targeted"] = "Målrettet",
	["Teal"] = "Blågrøn",
	["Tell me my part"] = "Fortæl mig min del",
	["Tell me when Auto switches to Blizzard's frames"] = "Giv besked når Auto skifter til Blizzards rammer",
	["Tell the group when I reset"] = "Fortæl gruppen når jeg resetter",
	["Tell the guild card"] = "Fortæl guilden-kort",
	["Tenths in the last second"] = "Tiendedele i sidste sekund",
	["test  show the AFK screen for a moment (click to close)"] = "test  vis AFK-skærmen et øjeblik (klik for at lukke)",
	["test <trigger> | list | mute  Fanfare triggers"] = "test <trigger> | list | mute  Fanfare-udløsere",
	["Test a line"] = "Test en linje",
	["Test bar: a base the Alliance is taking."] = "Testbjælke: en base som Alliance er ved at indtage.",
	["Test bar: a base the Horde is taking."] = "Testbjælke: en base som Horde er ved at indtage.",
	["Test bar: estimate from the current score."] = "Testbjælke: estimat ud fra den aktuelle stilling.",
	["Test bar: the game's estimated queue wait."] = "Testbjælke: spillets anslåede ventetid i køen.",
	["Test bar: time until the gates open."] = "Testbjælke: tid til portene åbner.",
	["Test bars"] = "Vis testbjælker",
	["Test casts wait until you leave combat."] = "Testcasts venter til du forlader kamp.",
	["Test danger"] = "Test fare",
	["Test fatigue"] = "Test udmattelse",
	["Test fights"] = "Testkampe",
	["Test flash"] = "Test blinket",
	["Test group size"] = "Størrelse på testgruppe",
	["Test stack"] = "Test stak",
	["Test text"] = "Test teksten",
	["Test this entry"] = "Test denne post",
	["Test timers"] = "Testnedtællinger",
	["Test: %s"] = "Test: %s",
	["Text align"] = "Tekstjustering",
	["Text badge"] = "Tekstmærke",
	["Text color of this event."] = "Tekstfarve for denne hændelse.",
	["Text of the note (empty: delete it):"] = "Notens tekst (tom: slet den):",
	["Text of the note:"] = "Notens tekst:",
	["Text on the bar"] = "Tekst på bjælken",
	["Text only"] = "Kun tekst",
	["Text only, no panel and no dim."] = "Kun tekst, intet panel og ingen nedtoning.",
	["Text only: no icons, kind labels or second line, see-through."] = "Kun tekst: ingen ikoner, typemærker eller anden linje, gennemsigtig.",
	["Text over your focus's frame."] = "Tekst over fokusrammen.",
	["Text over your own frame. Your scrolling combat text already shows these hits."] = "Tekst over din egen ramme. Din rullende kamptekst viser allerede disse hits.",
	["Text over your pet's frame."] = "Tekst over petrammen.",
	["Text over your target's frame."] = "Tekst over målrammen.",
	["Text shown big on screen. Fills in: %s"] = "Tekst der vises stort på skærmen. Tokens: %s",
	["Text size for this trigger. General uses the General tab's size."] = "Tekststørrelse for denne udløser. Generelt bruger størrelsen fra fanen Generelt.",
	["Text size in the box you type in (skin switch). Auto uses the chat text size."] = "Tekststørrelse i feltet du skriver i (Skin-kontakt). Auto bruger chattekstens størrelse.",
	["Text size in the feed."] = "Tekststørrelse i feedet.",
	["Text size in the list."] = "Tekststørrelse i listen.",
	["Text size in the lists."] = "Tekststørrelse i listerne.",
	["Text size in the stats pane."] = "Tekststørrelse i statsfeltet.",
	["Text size in this panel."] = "Tekststørrelse i dette panel.",
	["Text size of every datatext on this bar."] = "Tekststørrelse for alle datatekster på denne bjælke.",
	["Text size of macro names on this bar."] = "Tekststørrelse for makronavne på denne linje.",
	["Text size of the cooldown numbers at the normal base size (smaller on small buttons). The Size under Fonts and text > Cooldown numbers scales it: 16 keeps this size, 24 makes it half again as big."] = "Tekststørrelse for cooldowntallene ved den normale grundstørrelse (mindre på små knapper). Størrelse under Skrifttyper og tekst > Cooldowntal skalerer den: 16 bevarer denne størrelse, 24 gør den halvanden gang så stor.",
	["Text size of the count on this bar."] = "Tekststørrelse for antallet på denne linje.",
	["Text size of the count."] = "Tekststørrelse for antallet.",
	["Text size of the keybind on this bar."] = "Tekststørrelse for genvejstasten på denne linje.",
	["Text size of the keybind."] = "Tekststørrelse for genvejstasten.",
	["Text size of the macro name."] = "Tekststørrelse for makronavnet.",
	["Text size of the slot item levels."] = "Tekststørrelse for pladsernes item levels.",
	["Text size on the bars."] = "Tekststørrelse på bjælkerne.",
	["Text size on the tabs."] = "Tekststørrelse på fanerne.",
	["Text size. Some layouts cap it so it doesn't cover your frames (Cozy 52, Plates 44)."] = "Tekststørrelse. Nogle layouts begrænser den så den ikke dækker dine rammer (Cozy 52, Plates 44).",
	["Text speed"] = "Teksthastighed",
	["Text style"] = "Tekststil",
	["Text under the icon"] = "Tekst under ikonet",
	["Text: each slot shows its datatext as a short line. Dashboard: one row per value with an icon and a thin bar (durability, bag space, currencies), yellow then red when running low."] = "Tekst: hver plads viser sin datatekst som en kort linje. Dashboard: én række pr. værdi med et ikon og en tynd bjælke (holdbarhed, taskeplads, valutaer), først gul og så rød når den er ved at slippe op.",
	["Texts waiting"] = "Ventende tekster",
	["Texture"] = "Tekstur",
	["Texture of the bars."] = "Tekstur på bjælkerne.",
	["Texture of the bars. Theme texture follows the Textures page."] = "Bjælkernes tekstur. Tematekstur følger siden Teksturer.",
	["Texture of the buff bars."] = "Buffbjælkernes tekstur.",
	["Texture of the meter bars."] = "Tekstur på målerbjælkerne.",
	["Texture of the swing bars."] = "Tekstur på swingbjælkerne.",
	["Texture of the timer bars."] = "Tekstur på nedtællingsbjælkerne.",
	["That pull is full, or the route has as many pulls as it can keep."] = "Det pull er fuldt, eller ruten har så mange pulls som den kan rumme.",
	["The \"Main Hand\" / \"Off Hand\" / \"Ranged\" title. Off hides it; on follows Edit Mode."] = "Titlen \"Main Hand\" / \"Off Hand\" / \"Ranged\". Fra: skjult; til: følger Edit Mode.",
	["The 1-pixel line around the bubble box."] = "Linjen på 1 pixel rundt om boksen.",
	["the addon list"] = "addonlisten",
	["The Agenda's month view starts each week on Monday instead of Sunday."] = "Agendaens månedsvisning starter hver uge mandag i stedet for søndag.",
	["The Alerts tab can be opened after combat."] = "Alerts-fanen kan åbnes efter kampen.",
	["The Alerts tab opens with the first match"] = "Alerts-fanen åbnes ved første match",
	["The Alliance against the Horde: every rule of chess, four levels of computer."] = "Alliancen mod Horden: alle skakkens regler og fire sværhedsgrader.",
	["The Ammo datatext turns yellow at or below this many."] = "Datateksten for ammunition bliver gul ved dette antal eller færre.",
	["The ammo in your ammo slot, with how many you carry."] = "Ammoen på din ammoplads, og hvor meget du har på dig.",
	["The answer to EldoUI's own played-time request doesn't print in chat. A /played you type always prints."] = "Svaret på EldoUI's egen forespørgsel om spilletid skrives ikke i chatten. Et /played du selv skriver, vises altid.",
	["The auction house did not answer. Try again."] = "Auktionshuset svarede ikke. Prøv igen.",
	["The auction house is busy. Click Post again in a moment."] = "Auktionshuset har travlt. Klik på Læg op igen om lidt.",
	["The average level of your group."] = "Gruppens gennemsnitlige level.",
	["The bag window's search words work here too."] = "Taskevinduets søgeord virker også her.",
	["The bags tour runs in EldoUI's bag window: Blizzard UI > Bags (container windows) > Replace with EldoUI's frame."] = "Rundvisningen af taskerne kører i EldoUI's taskevindue: Blizzard-UI > Tasker (taskevinduer) > Erstat med EldoUI's ramme.",
	["the bank"] = "banken",
	["The bar is folded. Hover this tab to see it."] = "Bjælken er foldet sammen. Hold musen over denne fane for at se den.",
	["The bar is hidden: it shows on mouse over out of combat. Turn on Show on screen to use these settings."] = "Linjen er skjult: den vises med musen over uden for kamp. Slå Vis på skærmen til for at bruge disse indstillinger.",
	["The bar shows only while DBM, BigWigs or a pull countdown has a timer. It shows only what your boss mod publishes."] = "Bjælken vises kun mens DBM, BigWigs eller en pull-nedtælling har en nedtælling. Den viser kun det din bossmod udsender.",
	["The bar shows only while fishing mode is on."] = "Linjen vises kun mens fisketilstand er slået til.",
	["The bar sits in a panel that follows your art style: Blizzard border, Classic stone, Forever bronze."] = "Bjælken sidder i et panel der følger din grafikstil: Blizzard-kant, Classic-sten, Forever-bronze.",
	["The bar the rows below change."] = "Bjælken som rækkerne nedenfor ændrer.",
	["The bar whose settings show below."] = "Linjen hvis indstillinger vises nedenfor.",
	["The bar's background: a full panel in your art style, a see-through one, or none."] = "Linjens baggrund: et fuldt panel i din grafikstil, et gennemsigtigt panel eller ingen.",
	["The bar's color at the most stacks."] = "Bjælkens farve ved flest stakke.",
	["The bar's color from this stack count up."] = "Bjælkens farve fra dette antal stakke og op.",
	["The bar's fill color."] = "Bjælkens fyldfarve.",
	["The bar's length."] = "Bjælkens længde.",
	["The bar's own"] = "Bjælkens egen",
	["The bar's texture. Module texture uses the one on the Layout tab."] = "Bjælkens tekstur. Modultekstur bruger den på fanen Layout.",
	["The bar's thickness."] = "Bjælkens tykkelse.",
	["The bar's top and bottom edge light up as the cast fills."] = "Bjælkens øverste og nederste kant lyser op efterhånden som castet skrider frem.",
	["The bars the automatic upgrade may change. Every bar I use: bar 1 with its stance and form pages, the other bars that are on, and the gamepad bars. A lower rank you place yourself stays."] = "De linjer den automatiske opgradering må ændre. Alle linjer jeg bruger: linje 1 med dens stance- og formsider, de andre linjer der er slået til og gamepadlinjerne. En lavere rang du selv placerer, bliver stående.",
	["The best one your level can use"] = "Den bedste dit level kan bruge",
	["The blessing plan can be posted out of combat."] = "Velsignelsesplanen kan skrives i chatten uden for kamp.",
	["The blessing plan can be sent out of combat."] = "Velsignelsesplanen kan sendes uden for kamp.",
	["The blessing reminder's tooltip names your part of the plan (Reminders, paladins only)."] = "Velsignelsespåmindelsens tooltip nævner din del af planen (Påmindelser, kun Paladins).",
	["The Blizzard frames whose place EldoUI sets, hides or replaces. Click to show or hide the list."] = "Blizzard-rammerne som EldoUI placerer, skjuler eller erstatter. Klik for at vise eller skjule listen.",
	["The block only shows when your characters have at least this many together."] = "Blokken vises kun når dine karakterer tilsammen har mindst så mange.",
	["The block sits on its own mover (Tracking bars) wherever you drag it."] = "Blokken sidder på sit eget flyttefelt (Sporingsbjælker) der hvor du trækker den hen.",
	["The board is full: a draw."] = "Brættet er fuldt: uafgjort.",
	["The border color of this icon."] = "Kantfarven for dette ikon.",
	["The border takes the debuff type's color (magic, curse, disease, poison). The glow's style and color are set on the Glows page."] = "Kanten får debufftypens farve (magi, forbandelse, sygdom, gift). Glødens stil og farve indstilles på siden Glød.",
	["The box behind the bubble text, replacing Blizzard's parchment bubble and its pointer."] = "Boksen bag teksten i stedet for Blizzards pergamentboble og dens spids.",
	["The box goes away for this flight."] = "Boksen forsvinder for resten af denne flyvning.",
	["The box in the general art style, or in one of the other art styles."] = "Boksen i den generelle grafikstil eller i en af de andre grafikstile.",
	["The box in the WoW Forever bronze frame, whatever your general art style."] = "Boksen i WoW Forevers bronzeramme, uanset din generelle grafikstil.",
	["The box lets the game show through a little. How much: General > Panel opacity."] = "Boksen lader spillet skinne lidt igennem. Hvor meget: Generelt > Panelopacitet.",
	["The box shows when you land, once the flight timer knows the route."] = "Når flyvenedtællingen kender ruten, viser boksen hvornår du lander.",
	["The bright tip at the end of the bar."] = "Den lyse spids for enden af bjælken.",
	["The button holds this one from now on."] = "Knappen rummer denne fra nu af.",
	["The buttons in two rows. Buttons per row on the options page sets any other grid."] = "Knapperne i to rækker. Med \"Knapper pr. række\" på indstillingssiden kan du lave alle andre gitre.",
	["The camera slowly circles your character. Uses the camera API; off by default."] = "Kameraet kredser langsomt om din karakter. Bruger kamera-API'et; slået fra som standard.",
	["The camera zooms to your chosen distance when you talk to an NPC, fight, ride, go indoors or enter a city, and back again afterwards."] = "Kameraet zoomer til din valgte afstand når du taler med en NPC, kæmper, rider, går indendørs eller kommer ind i en by, og tilbage igen bagefter.",
	["The cancel and attack buttons while you control another unit. EldoUI frame: Blizzard's buttons in a movable EldoUI frame (needs the Replace switch of Vehicle bars)."] = "Annuller- og angrebsknapperne mens du styrer en anden enhed. EldoUI-ramme: Blizzards knapper i en flytbar EldoUI-ramme (kræver Erstat-kontakten for Køretøjslinjer).",
	["The catches of this session and catches per hour next to the buttons."] = "Denne sessions fangster og fangster pr. time ved siden af knapperne.",
	["The Categories view sorts items into sections; one that is off goes to Other. Your own categories come first and use the search syntax."] = "Visningen Kategorier sorterer genstande i afsnit; et afsnit der er slået fra, havner i Andet. Dine egne kategorier kommer først og bruger søgesyntaksen.",
	["The ceiling drops in %d shots"] = { one = "Loftet sænkes om %d skud", other = "Loftet sænkes om %d skud" },
	["The character sheet's average: a single spell can be resisted more, less or not at all."] = "Karakterarkets gennemsnit: en enkelt besværgelse kan blive modstået mere, mindre eller slet ikke.",
	["The character window is switched off on the Blizzard UI page, so it stays Blizzard's own. Type /eui blizz character-frame on to turn it on."] = "Karaktervinduet er slået fra på Blizzard-UI-siden, så det forbliver Blizzards eget. Skriv /eui blizz character-frame on for at slå det til.", -- l10n: keep
	["The character window lets the game show through a little. How much: General > Panel opacity."] = "Karaktervinduet lader spillet skinne en smule igennem. Hvor meget: Generelt > Panelopacitet.",
	["The character window, its slots and side panels in the EldoUI look."] = "Karaktervinduet, dets pladser og sidepaneler i EldoUI-udseendet.",
	["The chat window holds three panels."] = "Chatvinduet har plads til tre paneler.",
	["The chat window holds three: the second info bar and two panels."] = "Chatvinduet har plads til tre: den anden infobjælke og to paneler.",
	["The color for icons you can't cast."] = "Farven for ikoner du ikke kan caste.",
	["The color of the next note, arrow or line you add."] = "Farven på den næste note, pil eller linje du tilføjer.",
	["The color of the section's title and of its row here."] = "Farven på afsnittets titel og på dets række her.",
	["The color of the stacks above half in the folded style."] = "Farven på stakkene over halvdelen i den foldede stil.",
	["The color of the title on death cards and warnings."] = "Farven på titlen på dødskort og advarsler.",
	["The color when little time is left."] = "Farven når der er kort tid tilbage.",
	["The colors of the blocks, tiles and bricks. Color-blind safe keeps every color apart for all kinds of color blindness."] = "Farverne på blokke, fliser og mursten. Farveblind-sikker holder alle farver adskilt for alle slags farveblindhed.",
	["The Combat Text test runs out of combat only."] = "Testen af Kamptekst kører kun uden for kamp.",
	["The combo points on Blizzard's target frame."] = "Combopoints på Blizzards målramme.",
	["The corner of the item button the mark sits in. The upgrade arrow uses the top left."] = "Det hjørne af genstandsknappen som mærket sidder i. Opgraderingspilen sidder øverst til venstre.",
	["The CPU datatext turns red at this value."] = "CPU-datateksten bliver rød ved denne værdi.",
	["The CPU datatext turns yellow when all addons together take this long per frame."] = "CPU-datateksten bliver gul når alle addons tilsammen bruger så lang tid pr. billede.",
	["The currency the \"Custom currency %d\" datatext shows."] = "Den valuta som datateksten \"Brugerdefineret valuta %d\" viser.",
	["The dark cooldown swipe fills the square icon instead of Blizzard's rounded shape."] = "Den mørke cooldown-swipe fylder det kvadratiske ikon i stedet for Blizzards afrundede form.",
	["The dark part shows the time that has passed instead of the time left."] = "Den mørke del viser den tid der er gået, i stedet for den resterende tid.",
	["The datatext and the log; only the slot-free line in chat."] = "Datateksten og loggen; kun linjen om ledig plads i chatten.",
	["The datatext in slot %d of this panel."] = "Datateksten på plads %d i dette panel.",
	["The datatext shown in slot %d of the %s section."] = "Datateksten der vises på plads %d i afsnittet %s.",
	["The datatext whose label the next two rows change."] = "Datateksten hvis etiket de næste to rækker ændrer.",
	["The date format is on the Datatexts tab."] = "Datoformatet findes på fanen Datatekster.",
	["The death log window lets the game show through a little. How much: General > Panel opacity."] = "Dødslogvinduet lader spillet skinne lidt igennem. Hvor meget: Generelt > Panelopacitet.",
	["The default: flat strip, 28 px icons, a tick every 5 s, boss mod colors, the big icon with glow."] = "Standarden: flad strimmel, 28 px ikoner, en streg for hvert 5. sekund, bossmod-farver og det store ikon med glød.",
	["The direction the group grows from its mover."] = "Retningen gruppen vokser i fra sit flyttefelt.",
	["The draft costs %d of your %d points (%d left)."] = "Kladden koster %d af dine %d point (%d tilbage).",
	["The draft costs %d points."] = "Kladden koster %d point.",
	["The draft costs %d points: %d more than the %d you have now."] = "Kladden koster %d point: %d mere end de %d du har nu.",
	["The draft costs %d points: %d over the season cap of %d. It can't be made this season."] = "Kladden koster %d point: %d over sæsonloftet på %d. Den kan ikke laves i denne sæson.",
	["The draft is empty. Add ranks in the Legacy Planner first."] = "Kladden er tom. Tilføj først rangtrin i Legacy-planlæggeren.",
	["The dungeon list, the map with packs and the picked route."] = "Dungeonlisten, kortet med packs og den valgte rute.",
	["The dungeon list, the map with packs and the route picker. Inside a dungeon it opens that dungeon."] = "Dungeonlisten, kortet med packs og rutevælgeren. Inde i et dungeon åbner det på netop det dungeon.",
	["The Dungeons window lets the game show through a little. How much: General > Panel opacity."] = "Dungeonvinduet lader spillet skinne lidt igennem. Hvor meget: Generelt > Panelopacitet.",
	["The duration the Quick Sell tab starts with."] = "Den varighed fanen Hurtigt salg starter med.",
	["the Earth Mother"] = "Jordmoderen",
	["The editor closed for combat. Your route is saved."] = "Editoren blev lukket på grund af kamp. Din rute er gemt.",
	["The editor opens out of combat."] = "Editoren kan kun åbnes uden for kamp.",
	["The Eldostar tour shows while the guide window has a step open."] = "Eldostar-rundvisningen vises mens guidevinduet har et trin åbent.",
	["The EldoUI panel behind the windows lets the game show through a little. How much: General > Panel opacity."] = "EldoUI-panelet bag vinduerne lader spillet skinne en smule igennem. Hvor meget: Generelt > Panelopacitet.",
	["The EldoUI_Emoji folder is not installed. Put it next to the EldoUI folder in Interface\\AddOns."] = "Mappen EldoUI_Emoji er ikke installeret. Læg den ved siden af EldoUI-mappen i Interface\\AddOns.",
	["The equipped items with their item levels."] = "Det udstyr der er taget på, med item level.",
	["The error log: Lua errors are kept here instead of in chat."] = "Fejlloggen: Lua-fejl gemmes her i stedet for i chatten.",
	["The experience as a share of the level you had when you entered."] = "Erfaringen som andel af det level du havde da du gik ind.",
	["The extra mana bar on Blizzard's player frame."] = "Den ekstra manabjælke på Blizzards spillerramme.",
	["The fill takes the theme's color (or gradient). Casts that can't be interrupted keep the bar's gray."] = "Fyldet får temaets farve (eller gradient). Casts der ikke kan afbrydes, beholder bjælkens grå farve.",
	["The first column (or row) grows out from the middle of its edge, so a small group stays centered on the mover."] = "Den første kolonne (eller række) vokser ud fra midten af sin kant, så en lille gruppe forbliver centreret på flyttefeltet.",
	["The first section in the bag window."] = "Det første afsnit i taskevinduet.",
	["The flight master is overrun."] = "Flyvemesteren er løbet over ende.",
	["The flight master is safe!"] = "Flyvemesteren er i sikkerhed!",
	["The font of the chat windows and the edit box (skin switch). Theme font follows EldoUI's font; any EldoUI or SharedMedia font can be picked."] = "Skrifttypen i chatvinduerne og tekstfeltet (Skin-kontakt). Temaskrifttype følger EldoUI's skrifttype; alle EldoUI- og SharedMedia-skrifttyper kan vælges.",
	["The frame art of EldoUI's party and raid frames: the skin's material and a fine edge, never outside a frame, so raids keep their spacing. Positions, sizes and bars stay."] = "Rammegrafikken på EldoUI's gruppe- og raidrammer: skinnets materiale og en fin kant, aldrig uden for en ramme, så raids beholder deres afstand. Placeringer, størrelser og bjælker forbliver som de er.",
	["The frame is full: a draw."] = "Rammen er fuld: uafgjort.",
	["The full scan got no answer."] = "Den fulde scanning fik intet svar.",
	["The full scan isn't available right now."] = "Fuld scanning er ikke tilgængelig lige nu.",
	["The full scan returned no listings."] = "Den fulde scanning gav ingen opslag.",
	["The game announces Hardcore deaths as its own death alert setting allows (guild or all). Guild members who use EldoUI and click Tell the guild add their class and cause. Nothing here is sent anywhere."] = "Spillet annoncerer Hardcore-dødsfald som dets egen indstilling for dødsadvarsler tillader (guild eller alle). Guildmedlemmer som bruger EldoUI og klikker på Fortæl guilden, tilføjer deres klasse og årsag. Intet herfra sendes nogen steder hen.",
	["The game asks you to confirm this post."] = "Spillet beder dig bekræfte denne auktion.",
	["The game could not load EldoUI_GuideData."] = "Spillet kunne ikke indlæse EldoUI_GuideData.",
	["The game did not play %s (%s). Restart the game if EldoUI's sound files are new, and check the %s volume."] = "Spillet afspillede ikke %s (%s). Genstart spillet hvis EldoUI's lydfiler er nye, og tjek lydstyrken for %s.",
	["The game dims behind the open box; a click on the dimmed area closes it."] = "Spillet nedtones bag den åbne boks; et klik på det nedtonede område lukker den.",
	["The game does not show this name right now."] = "Spillet viser ikke dette navn lige nu.",
	["The game gives no position here"] = "Spillet oplyser ingen placering her",
	["The game gives no position here."] = "Spillet giver ingen placering her.",
	["The game has no Legacy trees here (Constants.LegacyConsts or C_Traits is missing). Type /eui legacy probe to see what it answers."] = "Spillet har ingen Legacy-træer her (Constants.LegacyConsts eller C_Traits mangler). Skriv /eui legacy probe for at se hvad det svarer.",
	["The game hides /roll results from addons in dungeons and raids."] = "Spillet skjuler /roll-resultater for addons i dungeons og raids.",
	["The game holds addon messages back right now. Try again later."] = "Spillet holder addonbeskeder tilbage lige nu. Prøv igen senere.",
	["The game itself writes the cooldown numbers and draws the swipe; EldoUI only picks the format and colors, so they work in combat too."] = "Spillet skriver selv cooldowntallene og tegner swipet; EldoUI vælger kun format og farver, så de også virker i kamp.",
	["the game leaves them closed"] = "spillet lader dem være lukket",
	["The game lists no challenges for this character yet."] = "Spillet viser ingen udfordringer for denne karakter endnu.",
	["the game opens them"] = "spillet åbner dem",
	["The game plays it when one of the group's auras comes on, also in combat. It counts the spell from anyone. Sound files only."] = "Spillet afspiller den når en af gruppens auraer kommer på, også i kamp. Evnen tæller fra alle. Kun lydfiler.",
	["The game plays it when one of the group's auras goes, also in combat. It counts the spell from anyone. Sound files only."] = "Spillet afspiller den når en af gruppens auraer forsvinder, også i kamp. Evnen tæller fra alle. Kun lydfiler.",
	["The game refused to load EldoUI_LootData. Check the addon list."] = "Spillet nægtede at indlæse EldoUI_LootData. Tjek addonlisten.",
	["The game reports this one, so it ticks by itself."] = "Spillet melder dette mål, så det får flueben af sig selv.",
	["The game sends these only while Blizzard's own floating combat text is on."] = "Spillet sender kun disse mens Blizzards egen svævende kamptekst er slået til.",
	["The game window opens on your last game as soon as the flight starts."] = "Spilvinduet åbner på dit seneste spil så snart flyvningen starter.",
	["The game would not play %s."] = "Spillet ville ikke afspille %s.",
	["The game's addon profiler is not available."] = "Spillets addonprofiler er ikke tilgængelig.",
	["The game's estimated wait for this queue."] = "Spillets anslåede ventetid for denne kø.",
	["The game's own error window is set on General > Lua errors."] = "Spillets eget fejlvindue indstilles under Generelt > Lua-fejl.",
	["The game's own setting: one combined bag or one window per bag. Game setting leaves it as it is. Needs the Bags switch on."] = "Spillets egen indstilling: én samlet taske eller ét vindue pr. taske. \"Spillets indstilling\" lader den være som den er. Kræver at kontakten Tasker er slået til.",
	["The game's own sort setting. Game setting leaves it as it is."] = "Spillets egen sorteringsindstilling. \"Spillets indstilling\" lader den være som den er.",
	["The game's quality color of the item, or one color for every item level."] = "Spillets kvalitetsfarve for genstanden, eller én farve til alle item levels.",
	["The game's reset lines are summed up in one. The leader's notice to other EldoUI users is an addon message, not group chat."] = "Spillets resetlinjer samles i én. Lederens besked til andre EldoUI-brugere er en addonbesked, ikke gruppechat.",
	["The game's short flash when a cooldown ends."] = "Spillets korte blink når en cooldown slutter.",
	["The Games box is off for every flight. Turn it back on in the Flight Games options; /eui games still opens the games."] = "Spil-boksen er slået fra for alle flyvninger. Slå den til igen under Flyvespil i indstillingerne; /eui games åbner stadig spillene.",
	["The games open once combat ends."] = "Spillene åbner når kampen er slut.",
	["The games use the game's own creature models (the gryphon in Gryphon Glide), and your character dances at a new best. Off: icons only."] = "Spillene bruger spillets egne væsenmodeller (griffinen i Griffinglid), og din karakter danser ved en ny rekord. Fra: kun ikoner.",
	["the gnomes"] = "gnomerne",
	["The gradient's color at the fill edge."] = "Gradientens farve ved fyldkanten.",
	["The group leader's crown and the raid assistant's mark."] = "Gruppelederens krone og raidassistentens mærke.",
	["The group of events listed below."] = "Gruppen af hændelser der vises nedenfor.",
	["The group pull countdown, as one icon."] = "Gruppens pull-nedtælling som ét ikon.",
	["The group the rows below change."] = "Gruppen som rækkerne nedenfor ændrer.",
	["The group the rows below change. Each group has its own mover named Aura group 1 to 6."] = "Den gruppe som rækkerne herunder ændrer. Hver gruppe har sit eget flyttefelt med navnet Auragruppe 1 til 6.",
	["The group's name in these settings."] = "Gruppens navn i disse indstillinger.",
	["The gryphons beside Blizzard's main bar (also with this module off; needs \"Let EldoUI change this\" on Main action bar) and, with Vanilla Original, beside EldoUI's bar 1."] = "Grifferne ved siden af Blizzards hovedlinje (også når dette modul er slået fra; kræver \"Lad EldoUI ændre dette\" for Hovedlinje) og, med Vanilla Original, ved siden af EldoUI's linje 1.",
	["The guide data could not be read. Install EldoUI again to repair it."] = "Guidedataene kunne ikke læses. Installer EldoUI igen for at reparere dem.",
	["The guide data is newer than this EldoUI. Update EldoUI to read it."] = "Guidedataene er nyere end denne EldoUI. Opdater EldoUI for at læse dem.",
	["The guide data is not installed. It comes with EldoUI as the EldoUI_GuideData folder; install EldoUI again to get it."] = "Guidedataene er ikke installeret. De følger med EldoUI som mappen EldoUI_GuideData; installer EldoUI igen for at få dem.",
	["The guide data is older than this EldoUI. Install EldoUI again to update it."] = "Guidedataene er ældre end denne EldoUI. Installer EldoUI igen for at opdatere dem.",
	["The guide in use. Right-click to start it over."] = "Guiden der er i brug. Højreklik for at starte den forfra.",
	["The guide list is in the Journal, under My Adventure. Turn My Adventure on to browse the guides."] = "Guidelisten ligger i journalen under My Adventure. Slå My Adventure til for at se guiderne.",
	["The guide list is in the Journal, under My Adventure: Guides. /eui eldostar guides does the same."] = "Guidelisten ligger i journalen under My Adventure: Guides. /eui eldostar guides gør det samme.",
	["The guide's tip for the step, under its title."] = "Guidens tip til trinnet, under dets titel.",
	["The guides are loaded."] = "Guiderne er indlæst.",
	["The guides load after combat."] = "Guiderne indlæses efter kampen.",
	["The guides load when Eldostar starts."] = "Guiderne indlæses når Eldostar starter.",
	["The health fills from the other side (right to left, or top to bottom)."] = "Livet fyldes fra den anden side (højre mod venstre eller oppefra og ned).",
	["The higher of both"] = "Den højeste af de to",
	["the Holy Light"] = "Det hellige lys",
	["The Horde fleet is sunk: you win!"] = "Hordens flåde er sænket: du vinder!",
	["The Horde got five in a row."] = "Horden fik fem på stribe.",
	["The Horde got four in a row."] = "Horden fik fire på stribe.",
	["The Horde has no move."] = "Horden har intet træk.",
	["The Horde is thinking..."] = "Horden tænker...",
	["The Horde sank your %s."] = "Horden sænkede din %s.",
	["The Horde takes aim..."] = "Horden sigter...",
	["The Horde wins."] = "Horden vinder.",
	["The hourly count is an estimate from your own entries on this ruleset."] = "Tællingen pr. time er et skøn ud fra dine egne besøg på dette regelsæt.",
	["The icon of each result on the left of its row."] = "Ikonet for hvert resultat i venstre side af rækken.",
	["The icon on the right of each bar, for a stack on the right side of the screen."] = "Ikonet til højre på hver bjælke, til en stak i højre side af skærmen.",
	["The icon that pops up in the middle of the screen when a spell or item on your Cooldown Pulse list is ready."] = "Ikonet der popper frem midt på skærmen når en evne eller genstand på din liste i Cooldown-puls er klar.",
	["The icon the rows below change. Clicking an icon's handle in move mode picks it too."] = "Ikonet som rækkerne nedenfor ændrer. Et klik på et ikons håndtag i flyttetilstand vælger det også.",
	["The icon's 1 px border: the theme color, an own color or none."] = "Ikonets kant på 1 px: temafarven, en egen farve eller ingen.",
	["The icon's border turns green for an upgrade (Upgrades module) and takes the accent color for an appearance you have not collected (Appearances module)."] = "Ikonets kant bliver grøn for en opgradering (modulet Opgraderinger) og får accentfarven for et udseende du ikke har samlet (modulet Udseender).",
	["The icon's own size. Group uses its group's size."] = "Ikonets egen størrelse. Gruppe bruger gruppens størrelse.",
	["The icon's shape; the art is cropped to fit."] = "Ikonets form; billedet beskæres så det passer.",
	["The icons in order, separated by commas: spell names or IDs, item:ID for items, slot:13 and slot:14 for your trinkets. Dragging icons in move mode changes this list too."] = "Ikonerne i rækkefølge, adskilt af kommaer: evnenavne eller ID'er, item:ID for genstande, slot:13 og slot:14 for dine trinkets. Når du trækker ikoner i flyttetilstand, ændres listen også.",
	["The item binds when you first wear it"] = "Genstanden bindes første gang du tager den på",
	["The item can be mailed to your other characters"] = "Genstanden kan sendes med posten til dine andre karakterer",
	["The item can be traded once"] = "Genstanden kan byttes én gang",
	["The item goes back to the section its search or type gives it."] = "Genstanden går tilbage til det afsnit dens søgning eller type giver den.",
	["The item is yours the moment you loot it"] = "Genstanden er din i det øjeblik du looter den",
	["The item level of each equipped item."] = "Item level for hver genstand du har på.",
	["The item level of weapons and armor in the top of the icon."] = "Item level på våben og rustning øverst i ikonet.",
	["The item level of weapons and armor, in gray beside the name."] = "Item level for våben og rustning, med grå skrift ved siden af navnet.",
	["The item moved. Pick it again."] = "Genstanden er flyttet. Vælg den igen.",
	["The items of every guild bank tab one of your characters opened."] = "Genstandene i alle guildbankfaner som en af dine karakterer har åbnet.",
	["The key of the action button that holds the spell. Only hidden buttons: just for spells on buttons you can't see, such as a bar that is off, shortened or shown only on mouse over."] = "Tasten på den handlingsknap der har evnen. Kun skjulte knapper: kun for evner på knapper du ikke kan se, fx en linje der er slået fra, afkortet eller kun vises ved mus over.",
	["The key that casts Fishing in fishing mode: click, then press the key. It keeps its normal job outside fishing mode. Clear: use the bar's Cast button."] = "Tasten der kaster snøren i fisketilstand: klik, og tryk så på tasten. Den beholder sin normale funktion uden for fisketilstand. Ryd: brug linjens Kast-knap.",
	["The key that opens and closes the Finder. Not bound by default."] = "Tasten der åbner og lukker Finder. Ingen tast som standard.",
	["The key to hold to drag a spell off a locked bar. Picking one changes the game's own \"Pick up action key\" setting."] = "Tasten du skal holde nede for at trække en evne af en låst linje. Når du vælger en, ændres spillets egen indstilling \"Pick up action key\".",
	["The keyword list (up to 50), with a sound per keyword and Pause. Also /eui chat alerts, and /eui chat alert <word> adds or removes one."] = "Listen over nøgleord (op til 50) med en lyd pr. nøgleord og Pause. Også /eui chat alerts, og /eui chat alert <word> tilføjer eller fjerner et.",
	["The last full scan stopped when the auction house closed. The prices read until then are saved."] = "Den seneste fulde scanning stoppede da auktionshuset lukkede. De priser der var læst indtil da, er gemt.",
	["The last lines of every chat tab come back after a reload or the next login, under a gray divider. Per character. Turning it off asks first, because it deletes the saved lines."] = "Hver chatfanes sidste linjer kommer tilbage efter en genindlæsning eller næste login under en grå skillelinje. Pr. karakter. Når du slår det fra, bliver du spurgt først fordi det sletter de gemte linjer.",
	["The last price seen on this realm and faction: from your searches in EldoUI's tabs or the game's Buy tab, and from full scans."] = "Den seneste pris set på denne realm og fraktion: fra dine søgninger i EldoUI's faner eller spillets Køb-fane og fra fulde scanninger.",
	["The level used by the button below."] = "Det level som knappen nedenfor bruger.",
	["The light on the fill edge."] = "Lyset på fyldkanten.",
	["The light that rides the fill edge."] = "Lyset der følger fyldkanten.",
	["The link box closes itself once you copied."] = "Linkfeltet lukker sig selv når du har kopieret.",
	["The list is full (%d guilds)."] = "Listen er fuld (%d guilds).",
	["The list is full (%d keywords)."] = "Listen er fuld (%d nøgleord).",
	["The list is full (%d mutes)."] = "Listen er fuld (%d dæmpede spillere).",
	["The list is full (%d phrases)."] = "Listen er fuld (%d fraser).",
	["The list is full. Remove one first."] = "Listen er fuld. Fjern en først.",
	["the Loa"] = "Loaerne",
	["The log is off."] = "Loggen er slået fra.",
	["The log of every run (also a click on the Instances datatext, or /eui instances)."] = "Loggen over alle runs (også et klik på Instanser-datateksten eller /eui instances).",
	["The log window lets the game show through a little. How much: General > Panel opacity."] = "Logvinduet lader spillet skinne lidt igennem. Hvor meget: Generelt > Panelopacitet.",
	["The loot window always opens on its mover; rolls stack upwards."] = "Lootvinduet åbner altid på sit flyttefelt; rul stables opad.",
	["The low ammo warning also for a warrior or rogue with a bow, gun or crossbow."] = "Advarslen om lav ammunition også for en warrior eller rogue med bue, gevær eller armbrøst.",
	["The lowest one first"] = "Den laveste først",
	["the mail"] = "posten",
	["The Mail block turns yellow when a letter on any of your characters runs out within this many days, and red under a day."] = "Post-blokken bliver gul når et brev på en af dine karakterer udløber inden for så mange dage, og rød under en dag.",
	["The match's time left as a bar, where the game shows a clock at the top of the screen."] = "Kampens resterende tid som bjælke i de battlegrounds hvor spillet viser et ur øverst på skærmen.",
	["The member is in another phase or war mode state."] = "Medlemmet er i en anden fase eller War Mode-tilstand.",
	["The member's class icon, or the role picked in the group finder."] = "Medlemmets klasseikon eller den rolle der er valgt i gruppesøgeren.",
	["The message could not be sent."] = "Beskeden kunne ikke sendes.",
	["The minimap holds two panels."] = "Minikortet har plads til to paneler.",
	["The minimap is in use elsewhere."] = "Minikortet bruges et andet sted.",
	["The minimap moves here after the fight."] = "Minikortet flytter herhen efter kampen.",
	["The moment that fires the trigger. Only things the game already tells you; combat data like enemy casts or health can't be used under the Midnight rules."] = "Øjeblikket der får udløseren til at gå af. Kun ting som spillet allerede fortæller dig; kampdata som fjenders casts eller liv kan ikke bruges under Midnight-reglerne.",
	["The most bars shown at once. Queue and start bars come first, then the ones with the least time left."] = "Det største antal bjælker der vises ad gangen. Kø- og startbjælker kommer først, derefter dem med mindst tid tilbage.",
	["The most players shown at once."] = "Højeste antal spillere der vises på én gang.",
	["The murloc rolled a 1: you win this duel!"] = "Murloccen slog 1: du vinder duellen!",
	["The murloc rolls..."] = "Murloccen slår ...",
	["The murloc's roll."] = "Murloccens slag.",
	["The name in its own bar over the health bar, the health text on the right of the health bar (the Boxed look)."] = "Navnet i sin egen bjælke over livsbjælken, livsteksten til højre på livsbjælken (Boxed-udseendet).",
	["The name of this theme in every list."] = "Temaets navn i alle lister.",
	["The name only, also for words below"] = "Kun navnet, også for ordene nedenfor",
	["The name shows on the tab, in the game's bank and in EldoUI's."] = "Navnet vises på fanen, både i spillets bank og i EldoUI's.",
	["the night elves"] = "natelverne",
	["The NPC's 3D model next to the text."] = "NPC'ens 3D-model ved siden af teksten.",
	["The number turns orange at this many seconds."] = "Tallet bliver orange ved dette antal sekunder.",
	["The number turns red at this many seconds. At most the warning time."] = "Tallet bliver rødt ved dette antal sekunder. Højst advarselstiden.",
	["The oldest entries go first when the log is full. The log is shared by all your characters."] = "De ældste poster fjernes først når loggen er fuld. Loggen deles af alle dine karakterer.",
	["The other end of the particles' color range."] = "Den anden ende af partiklernes farveområde.",
	["The packs come from the EldoUI_LootData folder that ships next to EldoUI. Install it beside EldoUI in Interface\\AddOns."] = "Packs kommer fra mappen EldoUI_LootData der følger med EldoUI. Installer den ved siden af EldoUI i Interface\\AddOns.",
	["The packs, patrols and bosses of the Classic dungeons on a dungeon map, with routes of numbered pulls. Keep your own routes and share them as a string."] = "Packs, patruljer og bosser i Classic-dungeons på et dungeonkort med ruter af nummererede pulls. Gem dine egne ruter, og del dem som en streng.",
	["The panel as a row of buff icons with timers."] = "Panelet som en række buffikoner med nedtællinger.",
	["The panel stays on screen, also away from camps."] = "Panelet bliver på skærmen, også væk fra lejre.",
	["The panel the rows below change."] = "Panelet som rækkerne nedenfor ændrer.",
	["The panel's look: the standard panel, a see-through page with the heading font, tighter spacing, the standard panel for large text, a bronze frame, or text with no panel."] = "Panelets udseende: standardpanelet, en gennemsigtig side med overskriftsskrifttypen, tættere afstand, standardpanelet til stor tekst, en bronzeramme eller tekst uden panel.",
	["The part counter on the edit box."] = "Deltælleren på chatfeltet.",
	["The part counter, and who in your party is typing (when they share it)."] = "Deltælleren og hvem i din gruppe der skriver (når de deler det).",
	["The particle's picture."] = "Partiklens billede.",
	["The per-element switches (skin, move, hide, replace, improve)."] = "Kontakterne pr. element (skin, flyt, skjul, erstat, forbedr).",
	["The percent the line shows below."] = "Den procentsats som linjen vises under.",
	["The picked area's style, played in a loop."] = "Det valgte områdes stil, afspillet i en løkke.",
	["The picked bar with sample spells, in its size, grid and texts."] = "Den valgte linje med eksempelevner, i dens størrelse, gitter og tekster.",
	["The picture: %s"] = "Billedet: %s",
	["The planner lets the game show through a little. How much: General > Panel opacity."] = "Planlæggeren lader spillet skinne lidt igennem. Hvor meget: Generelt > Panelopacitet.",
	["The player who gets the offer when \"Send to\" is a player. Name-Realm for another realm."] = "Spilleren der får tilbuddet når \"Send til\" er en spiller. Navn-Realm for en anden realm.",
	["The player who has aggro gets a fixed color."] = "Spilleren der har aggro, får en fast farve.",
	["The portrait gets its own bordered box as tall as the whole frame (the Boxed look)."] = "Portrættet får sin egen boks med kant, lige så høj som hele rammen (Boxed-udseendet).",
	["The portrait loses its color while the member is dead, a ghost or offline. Needs Dead and offline look on the Effects tab."] = "Portrættet mister sin farve mens medlemmet er dødt, en ånd eller offline. Kræver Udseende for døde og offline på fanen Effekter.",
	["The previous guide placement is waiting to be released safely."] = "Den tidligere guideplacering venter på at kunne frigives sikkert.",
	["The quest is not done yet."] = "Questen er ikke klaret endnu.",
	["The quest log at the last logout."] = "Questloggen ved seneste logout.",
	["The Quest Tracker module can also put Questie on its own mover. While it does, this integration stands back."] = "Modulet Questtracker kan også sætte Questie på sit eget flyttefelt. Så længe det gør det, træder denne integration til side.",
	["The raid's own main tank and main assist marks."] = "Raidets egne mærker for main tank og main assist.",
	["The rate shows after 2 minutes of play."] = "Tempoet vises efter 2 minutters spil.",
	["The ready check's time left."] = "Den resterende tid for klar-tjekket.",
	["The recap window stays hidden while the Hide switch is on."] = "Oversigtsvinduet forbliver skjult mens Skjul-kontakten er slået til.",
	["The remaining swing time. Off hides it; on follows Edit Mode."] = "Den resterende swingtid. Fra: skjult; til: følger Edit Mode.",
	["The rest are summed up in a \"+N more\" line."] = "Resten samles i en linje med \"+N flere\".",
	["The rest of the interface turns invisible while the screen shows, and comes back when you return."] = "Resten af brugerfladen bliver usynlig mens skærmen vises, og kommer tilbage når du vender tilbage.",
	["The RestedXP guide window goes to the layout's guide spot, and move mode places it like any EldoUI frame. Unchecked, RestedXP keeps its own spot."] = "RestedXP-guidevinduet flyttes til layoutets guideplads, og flyttetilstand placerer det som enhver anden EldoUI-ramme. Uden flueben beholder RestedXP sin egen plads.",
	["The ring fills while the global cooldown runs."] = "Ringen fyldes mens den globale cooldown kører.",
	["The role the timing follows. Automatic uses the group role the game gives you, and damage when you have none."] = "Den rolle timingen følger. Automatisk bruger den grupperolle spillet giver dig, og DPS når du ikke har nogen.",
	["The round is over: the next roll starts a new one."] = "Runden er slut: næste rul starter en ny.",
	["The route could not be sent."] = "Ruten kunne ikke sendes.",
	["the route has no pulls"] = "ruten har ingen pulls",
	["The route stands out: skipped packs are dimmed, patrols hidden."] = "Ruten træder frem: oversprungne packs er nedtonede, og patruljer er skjult.",
	["The row the settings below change. Each row has its own look."] = "Den række indstillingerne nedenfor ændrer. Hver række har sit eget udseende.",
	["The running session is cleared without saving it."] = "Den kørende session ryddes uden at blive gemt.",
	["The same choice for the bank window."] = "Det samme valg for bankvinduet.",
	["The same click also sends one addon message to the guild, so guild members' EldoUI logs your class, level, zone and cause."] = "Det samme klik sender også én addonbesked til guilden, så guildmedlemmernes EldoUI logger din klasse, dit level, din zone og årsagen.",
	["The same line when you enter a raid."] = "Samme linje når du går ind i et raid.",
	["The same position three times: a draw."] = "Samme stilling tre gange: remis.",
	["the scoreboard"] = "resultattavlen",
	["The scroll area the rows below change."] = "Rulleområdet som rækkerne nedenfor ændrer.",
	["The seal on you with the time it has left, so you see when to judge or cast it again. Each seal joins the group once you know it."] = "Seal på dig med tiden den har tilbage, så du kan se hvornår du skal judge eller caste den igen. Hver seal kommer med i gruppen når du kender den.",
	["The second count beside the bar at each tick mark, clear of the icons."] = "Sekundtallet ved siden af bjælken ud for hver streg, fri af ikonerne.",
	["The second info bar is not in the chat window now."] = "Den anden infobjælke er ikke i chatvinduet nu.",
	["The selected chat window as plain text."] = "Det valgte chatvindue som ren tekst.",
	["The selected window as plain text, ready to copy."] = "Det valgte vindue som ren tekst, klar til at kopiere.",
	["The sender's level as [42] before the name, in the game's difficulty color, for levels the game has shown you this session. Off by default."] = "Afsenderens level som [42] foran navnet i spillets sværhedsfarve, for levels spillet har vist dig i denne session. Slået fra som standard.",
	["The server says you entered too many instances: %s."] = "Serveren siger at du er gået ind i for mange instanser: %s.",
	["the session history"] = "sessionshistorikken",
	["The size of the game window."] = "Størrelsen på spilvinduet.",
	["The slot you can disenchant, prospect, mill or unlock while you hold the Bag Actions modifier."] = "Pladsen som du kan disenchante, prospecte, mille eller låse op mens du holder ændringstasten for Taskehandlinger nede.",
	["The smallest rows and icons: the most results on screen."] = "De mindste rækker og ikoner: flest resultater på skærmen.",
	["The social button with Quick Join toasts above the chat."] = "Den sociale knap med pop op-beskeder fra Quick Join over chatten.",
	["The sound for this entry. Module default uses the sound on the Pulse tab."] = "Lyden for denne post. Modulstandard bruger lyden på fanen Puls.",
	["The sound for this keyword. Choosing one plays it once."] = "Lyden for dette nøgleord. Når du vælger en, afspilles den én gang.",
	["The sound the flash plays."] = "Lyden som blinket afspiller.",
	["The sound with the low ammo warning. None for only the message."] = "Lyden ved advarslen om lav ammunition. \"Ingen\" giver kun beskeden.",
	["The speech-bubble button with the emote and language menus. /s, /p and right-clicking a tab still work."] = "Talebobbelknappen med emote- og sprogmenuerne. /s, /p og højreklik på en fane virker stadig.",
	["The spell book is not available here."] = "Besværgelsesbogen er ikke tilgængelig her.",
	["The spell icon in front of each buff bar."] = "Evneikonet foran hver buffbjælke.",
	["The spell or item the rows below change."] = "Evnen eller genstanden som rækkerne nedenfor ændrer.",
	["The spell or item tooltip when the mouse is over the icon."] = "Tooltippen for evnen eller genstanden når musen er over ikonet.",
	["The spell's name on the bar (not on vertical bars)."] = "Evnens navn på bjælken (ikke på lodrette bjælker).",
	["The spell's or item's name under the icon."] = "Evnens eller genstandens navn under ikonet.",
	["The square button saves the session."] = "Den firkantede knap gemmer sessionen.",
	["The stack count this color starts at."] = "Det antal stakke denne farve starter ved.",
	["The stack count, or charges as charges/most."] = "Antal stakke, eller ladninger som ladninger/maks.",
	["The standard view goes back to its own size."] = "Standardvisningen får sin egen størrelse igen.",
	["The step and its goals. A goal the game reports ticks by itself; click the others once they are done."] = "Trinnet og dets mål. Et mål som spillet melder, får flueben af sig selv; klik på de andre når de er klaret.",
	["The step and its next goal on two lines."] = "Trinnet og dets næste mål på to linjer.",
	["The step's next open goal. The arrows beside it move between steps."] = "Trinnets næste åbne mål. Pilene ved siden af skifter mellem trinnene.",
	["The suggested route clears the dungeon from boss to boss. Copy it to keep your own: name it, label and color pulls, and share it as a string. Planning only: nothing is pulled, targeted or marked for you."] = "Den foreslåede rute rydder dungeonet fra boss til boss. Kopier den for at få din egen: navngiv den, giv pulls etiketter og farver, og del den som en streng. Kun til planlægning: intet bliver pullet, valgt som mål eller markeret for dig.",
	["The sum of the item levels of your equipped gear (shirt and tabard left out), shown next to the average item level."] = "Summen af item levels for det udstyr du har på (Shirt og Tabard ikke medregnet), vist ved siden af det gennemsnitlige item level.",
	["The tab the window shows when you open it."] = "Den fane vinduet viser når du åbner det.",
	["The tab's text, for the whole guild."] = "Fanens tekst til hele guilden.",
	["The tabs along the window in the chosen tab style."] = "Fanerne langs vinduet i den valgte fanestil.",
	["The tabs and the side rail fade out while the mouse is not over the chat and come back when you point at it. Off by default."] = "Fanerne og sidebjælken toner ud mens musen ikke er over chatten, og kommer tilbage når du peger på den. Slået fra som standard.",
	["The tabs that don't fit the bar."] = "Fanerne der ikke er plads til på bjælken.",
	["The test timers run out of combat."] = "Testnedtællingerne kører uden for kamp.",
	["The text is selected: press Ctrl+C to copy it."] = "Teksten er markeret: tryk Ctrl+C for at kopiere den.",
	["The text of the Alts datatext: how many characters you have, or their total gold."] = "Teksten i Alts-datateksten: hvor mange karakterer du har, eller deres samlede guld.",
	["The texture of every bar that has no texture of its own."] = "Teksturen for alle bjælker der ikke har deres egen tekstur.",
	["The theme the rows below change. Built-in themes can be reset; copies can be renamed and deleted."] = "Det tema som rækkerne nedenfor ændrer. Indbyggede temaer kan nulstilles; kopier kan omdøbes og slettes.",
	["The theme the sample above and the test cast of your own bar use."] = "Det tema som prøven ovenfor og testcastet på din egen bjælke bruger.",
	["The theme this spell always gets. No pin lets EldoUI choose by school."] = "Det tema denne evne altid får. Ingen fastgørelse lader EldoUI vælge efter skole.",
	["The theme's spark"] = "Temaets gnist",
	["The thin button bar beside every chat window (scroll and minimize buttons)."] = "Den tynde knaplinje ved siden af hvert chatvindue (rulle- og minimeringsknapper).",
	["The time is in the accent color while the fight runs."] = "Tiden står i accentfarven mens kampen kører.",
	["The time left on the bar (not on vertical bars)."] = "Den resterende tid på bjælken (ikke på lodrette bjælker).",
	["The time text in the shared cooldown colors (Fonts and text > Cooldown numbers): changes color as the aura runs out. Applies to Text and Swipe and text."] = "Tidsteksten i de fælles cooldownfarver (Skrifttyper og tekst > Cooldowntal): skifter farve efterhånden som auraen løber ud. Gælder for Tekst og Swipe og tekst.",
	["The timer stops while you are marked away and goes on when you are back."] = "Tiden stopper mens du er markeret som væk, og fortsætter når du er tilbage.",
	["The timer turns red in the last quarter of the roll's time."] = "Tidsbjælken bliver rød i den sidste fjerdedel af rullets tid.",
	["The timer's name under the big icon, below the timeline's box."] = "Nedtællingens navn under det store ikon, under tidslinjens boks.",
	["the titans"] = "titanerne",
	["The title line with the mob's name and the target/focus switch."] = "Titellinjen med mobbens navn og knappen der skifter mellem mål og fokus.",
	["The toys the toy box lists. Your click or Enter on the result uses it."] = "De toys som toyboksen viser. Dit klik eller Enter på resultatet bruger det.",
	["the trade window"] = "byttevinduet",
	["The trigger to edit below. (off) marks switched-off ones."] = "Udløseren der skal redigeres nedenfor. (fra) markerer dem der er slået fra.",
	["the trolls"] = "troldene",
	["The vehicle seat picker. Mover needs the Move switch of Vehicle bars, Hidden the Hide switch."] = "Vælgeren af køretøjssæder. Flyttefelt kræver Flyt-kontakten for Køretøjslinjer, Skjult kræver Skjul-kontakten.",
	["the vendor"] = "købmanden",
	["The vertical bar has no place in the layouts. Drag it where you want it in move mode."] = "Den lodrette bjælke har ingen plads i layoutene. Træk den på plads i flyttetilstand.",
	["The viewers fade out of combat unless you have a hostile target or mouse over them."] = "Visningerne toner ud uden for kamp medmindre du har et fjendtligt mål eller holder musen over dem.",
	["the volume panel"] = "lydstyrkepanelet",
	["The waypoint arrow"] = "Waypoint-pilen",
	["The waypoint arrow points at the step's next goal: the place the guide gives, else the quest giver, the one you turn in to or the creature, from the Loot Guide's data."] = "Waypoint-pilen peger på trinnets næste mål: stedet guiden angiver, ellers questgiveren, den du afleverer til eller væsenet, ud fra Loot Guides data.",
	["The whole step in a see-through panel."] = "Hele trinnet i et gennemsigtigt panel.",
	["The whole step with its tip, goals and buttons, in a solid panel."] = "Hele trinnet med tip, mål og knapper i et fast panel.",
	["The window keeps its place and size: no dragging in move mode and no resize grip."] = "Vinduet beholder sin plads og størrelse: intet træk i flyttetilstand og intet greb til at ændre størrelsen.",
	["The windows open from the corner of their mover that faces the middle of the screen, so a bag mover on the left side grows to the right. Off: bags grow up and left, the bank down and right."] = "Vinduerne åbner fra det hjørne af deres flyttefelt der vender mod midten af skærmen, så et taskeflyttefelt i venstre side vokser mod højre. Når den er slået fra, vokser tasker op og mod venstre og banken ned og mod højre.",
	["The word was %s."] = "Ordet var %s.",
	["The world map is not available here."] = "Verdenskortet er ikke tilgængeligt her.",
	["Their items below this quality are not shown."] = "Gruppemedlemmers genstande under denne kvalitet vises ikke.",
	["Their targets"] = "Tankenes mål",
	["Their typed emotes and emote commands (/wave)."] = "Emotes de skriver, og emotekommandoer (/wave).",
	["Theme (Fonts and text page)"] = "Tema (siden Skrifttyper og tekst)",
	["Theme (General)"] = "Tema (Generelt)",
	["Theme color"] = "Temafarve",
	["Theme color and spark with a short flash; no particles, shine or glow. Lowest cost."] = "Temafarve og gnist med et kort blink; ingen partikler, glans eller glød. Laveste belastning.",
	["Theme editor"] = "Temaeditor",
	["Theme font and texture everywhere, class-colored meter, slim swing bars."] = "Temaskrifttype og -tekstur overalt, klassefarvet måler, slanke swingbjælker.",
	["Theme font, straight lines, quiet notifications."] = "Temaskrifttype, lige linjer, diskrete notifikationer.",
	["Theme for this spell"] = "Tema til denne evne",
	["Theme for your %s spells."] = "Tema til dine %s-evner.",
	["Theme for your spells that are in no school above (not in EldoUI's list and not pinned)."] = "Tema til dine evner der ikke hører til nogen skole ovenfor (ikke i EldoUI's liste og ikke fastgjort).",
	["Theme of every cast on the boss cast bars."] = "Tema for alle casts på bossernes castbars.",
	["Theme of every cast on the focus cast bar."] = "Tema for alle casts på fokuscastbaren.",
	["Theme of every cast on the pet cast bar."] = "Tema for alle casts på petcastbaren.",
	["Theme of every cast on the target cast bar."] = "Tema for alle casts på målcastbaren.",
	["Themed cast bars: a spell-school color, a spark with a light trail, a shine, particles and finish effects on EldoUI's cast bars, or on Blizzard's own when EldoUI's are off. Decoration only."] = "Castbars med tema: en farve efter evneskole, en gnist med et lysspor, en glans, partikler og afslutningseffekter på EldoUI's castbars, eller på Blizzards egne når EldoUI's er slået fra. Kun pynt.",
	["Themes"] = "Temaer",
	["Then"] = "Derefter",
	["There are no saved typed lines to clear."] = "Der er ingen gemte skrevne linjer at rydde.",
	["There is no automatic spell rank upgrade to undo."] = "Der er ingen automatisk opgradering af evnerang at fortryde.",
	["There is no earlier BigWigs profile to go back to."] = "Der er ingen tidligere BigWigs-profil at vende tilbage til.",
	["There is no route to send."] = "Der er ingen rute at sende.",
	["There is no saved chat history to clear."] = "Der er ingen gemt chathistorik at rydde.",
	["These blocks have no room on the bar right now."] = "Disse blokke har ikke plads på bjælken lige nu.",
	["These clicks on party and raid frames cast your spells now:"] = "Disse klik på gruppe- og raidrammer caster nu dine evner:",
	["They are added to your nodes. Nothing you have is removed."] = "Nodes tilføjes til dine egne. Intet af det du har, fjernes.",
	["Thick outline"] = "Tyk kontur",
	["Thickness of the bars, in pixels."] = "Bjælkernes tykkelse i pixels.",
	["Thickness of the route line in pixels."] = "Rutelinjens tykkelse i pixels.",
	["Thin 6 px bar, no text, small pips."] = "Tynd bjælke på 6 px, ingen tekst, små pips.",
	["Thin 6 px bars with the text above them."] = "Tynde bjælker på 6 px med teksten over.",
	["Thin health, power and GCD bars stacked under you, combo pips on top."] = "Tynde livs-, ressource- og GCD-bjælker stablet under dig, combopips øverst.",
	["Thin marks on the power bar at the values you choose for each power type."] = "Tynde streger på ressourcebjælken ved de værdier du vælger for hver ressourcetype.",
	["This ammo doesn't fit your ranged weapon."] = "Denne ammunition passer ikke til dit afstandsvåben.",
	["This BigWigs version has no profile API."] = "Denne BigWigs-version har ingen profil-API.",
	["This changes the profile \"%s\", which %d other characters use too."] = { one = "Dette ændrer profilen \"%s\", som %d anden karakter også bruger.", other = "Dette ændrer profilen \"%s\", som %d andre karakterer også bruger." },
	["This changes the profile \"%s\"."] = "Dette ændrer profilen \"%s\".",
	["This changes the setting for this character only."] = "Dette ændrer kun indstillingen for denne karakter.",
	["This character has not saved this part yet. It does at its next login (bank and mail at the next visit)."] = "Denne karakter har ikke gemt denne del endnu. Det sker ved næste login (bank og post ved næste besøg).",
	["This character is not on a Hardcore realm, so these options do nothing here."] = "Denne karakter er ikke på en Hardcore-realm, så disse indstillinger gør intet her.",
	["This character stops saving its Alts window info and leaves the Alts window, item counts and address book. Its bags and bank stay saved for itself. Kept per character."] = "Denne karakter holder op med at gemme sine oplysninger til Alts-vinduet og forsvinder fra Alts-vinduet, antal genstande og adressebogen. Dens tasker og bank forbliver gemt til den selv. Gemmes pr. karakter.",
	["This client can't make chat windows"] = "Denne klient kan ikke oprette chatvinduer",
	["This client does not report appearance collections, so there is nothing to show."] = "Denne klient oplyser ikke samlinger af udseender, så der er intet at vise.",
	["This client has no achievement API, so EldoUI can't list Legacy Challenges."] = "Denne klient har intet API til achievements, så EldoUI kan ikke vise Legacy-udfordringer.",
	["This client has no spellbook API to list."] = "Klienten har intet API til at vise evnebogen.",
	["This dungeon has no map in EldoUI's list."] = "Dette dungeon har intet kort i EldoUI's liste.",
	["This faction"] = "Denne fraktion",
	["This fight"] = "Denne kamp",
	["This game client has no aura slots, so aura bars can't show here (cooldown and charge bars still work)."] = "Denne spilklient har ingen aurapladser, så aurabjælker kan ikke vises her (cooldown- og ladningsbjælker virker stadig).",
	["This game client has no aura slots, so aura groups can't show here."] = "Denne spilklient har ingen aurapladser, så auragrupper kan ikke vises her.",
	["This group stands in for one of the fixed rows: its size, layout and position are the row's (Layout and Own rows tabs)."] = "Denne gruppe træder i stedet for en af de faste rækker: dens størrelse, layout og placering er rækkens (fanerne Layout og Egne rækker).",
	["This guide was updated. You are at step %d of the new version."] = "Guiden er opdateret. Du er ved trin %d i den nye version.",
	["This help shows once the healer role's click-casting is set up on this character."] = "Denne hjælp vises når healerrollens klikkast er sat op på denne karakter.",
	["This help shows while Blizzard's Edit Mode is open with EldoUI's panel beside it."] = "Denne hjælp vises mens Blizzards Edit Mode er åben med EldoUI's panel ved siden af.",
	["This help shows while EldoUI's cooldown rows stand in for Blizzard's and have no spells yet."] = "Denne hjælp vises mens EldoUI's cooldownrækker træder i stedet for Blizzards og endnu ikke har nogen evner.",
	["This help shows while fishing mode is on."] = "Denne hjælp vises mens fisketilstand er slået til.",
	["This help shows while the auction house is open with EldoUI's tabs."] = "Denne hjælp vises mens auktionshuset er åbent med EldoUI's faner.",
	["this hour"] = "denne time",
	["This hour (estimate)"] = "Denne time (skøn)",
	["this icon's look"] = "dette ikons udseende",
	["this icon's settings"] = "dette ikons indstillinger",
	["This level"] = "Dette level",
	["This panel sets how EldoUI's frames show in Edit Mode, and What EldoUI places lists the Blizzard frames EldoUI places, hides or replaces."] = "Dette panel bestemmer hvordan EldoUI's rammer vises i Edit Mode, og Hvad EldoUI placerer viser de Blizzard-rammer som EldoUI placerer, skjuler eller erstatter.",
	["This panel sets how they show in Edit Mode, and What EldoUI places lists the Blizzard frames EldoUI places, hides or replaces."] = "Dette panel bestemmer hvordan de vises i Edit Mode, og Hvad EldoUI placerer viser de Blizzard-rammer som EldoUI placerer, skjuler eller erstatter.",
	["This realm"] = "Denne realm",
	["This route can't be sent."] = "Ruten kan ikke sendes.",
	["This route can't be used: %s."] = "Ruten kan ikke bruges: %s.",
	["This route has no pulls yet."] = "Ruten har endnu ingen pulls.",
	["This route is too big to send to the group (too many lines). Export it as a string instead."] = "Ruten er for stor til at blive sendt til gruppen (for mange linjer). Eksporter den som en streng i stedet.",
	["This run can't be merged: the entry before it is another instance, more than an hour older, or the instances were reset in between."] = "Dette run kan ikke slås sammen: posten før det er en anden instans, er mere end en time ældre, eller instanserne blev resat ind imellem.",
	["This run doesn't count toward the hourly limit."] = "Dette run tæller ikke med i grænsen pr. time.",
	["this spec"] = "denne spec",
	["this target"] = "dette mål",
	["This trigger has no sound."] = "Denne udløser har ingen lyd.",
	["This week"] = "Denne uge",
	["Those addons show their own counts, so EldoUI hides its counts while one of them is loaded. Turn this on to show both."] = "Disse addons viser deres eget antal, så EldoUI skjuler sit antal mens en af dem er indlæst. Slå dette til for at vise begge.",
	["Threat %"] = "Aggro %",
	["Threat % is the share of the tank's threat, as Blizzard shows it on the target frame."] = "Aggro % er andelen af tankens aggro, ligesom Blizzard viser den på målrammen.",
	["Threat is hidden by the game here"] = "Spillet skjuler aggro her",
	["Threat meter"] = "Aggromåler",
	["Threat Meter"] = "Aggromåler",
	["Threat meter off (%s)."] = "Aggromåler slået fra (%s).",
	["Threat meter on (%s)."] = "Aggromåler slået til (%s).",
	["Threat source"] = "Aggrokilde",
	["Three alike"] = "Tre ens",
	["Three rolls a turn, fifteen boxes to fill; chase the highest total."] = "Tre slag i hver tur og femten rubrikker at udfylde; gå efter den højeste sum.",
	["Three sample bars on the roll spot for six seconds. Their buttons do nothing."] = "Tre eksempelbjælker på rulpladsen i seks sekunder. Knapperne på dem gør intet.",
	["Threes"] = "Treere",
	["Threshold lines"] = "Tærskellinjer",
	["Throwing knives"] = "Kastekniver",
	["Throws away your groups and free icons (of this talent group when it has its own layout) and makes the fixed rows into groups again."] = "Smider dine grupper og frie ikoner væk (for denne talentgruppe når den har sit eget layout) og gør de faste rækker til grupper igen.",
	["Thu Dec 31"] = "Thu Dec 31",
	["Tick \"Show as experience bar\" in the reputation list."] = "Sæt flueben i omdømmelisten for at vise en fraktion som erfaringsbjælke.",
	["Tick \"Show on backpack\" in the currency tab to show one here."] = "Vælg en valuta på valutafanen, og sæt flueben for at vise den på rygsækken; så vises den også her.",
	["Tick marks"] = "Skalastreger",
	["Tick numbers"] = "Stregtal",
	["Tick sound"] = "Tiklyd",
	["Tick step"] = "Stregafstand",
	["Tie"] = "Uafgjort",
	["Tie at %d"] = "Uafgjort på %d",
	["Tight"] = "Tight",
	["Time"] = "Tid",
	["Time %s"] = "Tid %s",
	["Time and date"] = "Tid og dato",
	["Time bar under icons"] = "Tidsbjælke under ikoner",
	["Time inside"] = "Tid inde",
	["Time is up. The answer was %s."] = "Tiden er gået. Svaret var %s.",
	["Time left as"] = "Resterende tid som",
	["Time left drains while the aura is up; stacks fills with the aura's stack count."] = "Tid tilbage tømmes mens auraen er aktiv; stakke fyldes med auraens antal stakke.",
	["Time left in the match"] = "Tid tilbage af kampen",
	["Time left in this match, as the game shows it."] = "Tid tilbage af kampen ifølge spillet.",
	["Time left on the box"] = "Tid tilbage på boksen",
	["Time left on the buff icons, drawn by the game in the shared EldoUI cooldown look."] = "Resterende tid på buffikonerne, tegnet af spillet i EldoUI's fælles cooldownstil.",
	["Time left on the debuff icons, drawn by the game in the shared EldoUI cooldown look (Fonts and text > Cooldown numbers)."] = "Resterende tid på debuffikonerne, tegnet af spillet i EldoUI's fælles cooldownstil (Skrifttyper og tekst > Cooldowntal).",
	["Time left on the defensive icon, drawn by the game in the shared EldoUI cooldown look."] = "Resterende tid på det defensive ikon, tegnet af spillet i EldoUI's fælles cooldownstil.",
	["Time left on the limit"] = "Tid tilbage på grænsen",
	["Time left to enter the battleground. Use Blizzard's pop-up to enter."] = "Tid tilbage til at gå ind i battlegroundet. Brug Blizzards pop op-vindue for at gå ind.",
	["Time left under Blizzard's buffs"] = "Resterende tid under Blizzards buffs",
	["Time played %s"] = "Spilletid %s",
	["Time since you entered combat; after the fight the last fight's length stays. The same timer as the Combat HUD's combat timer."] = "Tid siden du gik i kamp; efter kampen bliver den sidste kamps længde stående. Samme ur som kampuret i Combat HUD.",
	["Time text"] = "Tidstekst",
	["Time text size"] = "Størrelse på tidstekst",
	["Time to enter"] = "Tid til at gå ind",
	["Time until the flags return after a capture."] = "Tid til flagene vender tilbage efter en erobring.",
	["Time until the gates open."] = "Tid til portene åbner.",
	["Time: %s"] = "Tid: %s",
	["Timeline"] = "Tidslinje",
	["Timer"] = "Nedtælling",
	["Timers"] = "Nedtællinger",
	["Timers DBM or BigWigs shows for the encounter."] = "Nedtællinger som DBM eller BigWigs viser for kampen.",
	["Timers for battleground queues, the gates opening, base captures and the expected winner. Only shows what the game reports."] = "Nedtællinger for battleground-køer, portenes åbning, erobring af baser og den forventede vinder. Viser kun det spillet oplyser.",
	["Timers from"] = "Nedtællinger fra",
	["Timers from: %s"] = "Nedtællinger fra: %s",
	["Timestamp color"] = "Farve på tidsstempler",
	["Timestamps"] = "Tidsstempler",
	["Timing for my role"] = "Timing efter min rolle",
	["Tint for actions whose target is out of range."] = "Farvning af handlinger hvis mål er uden for rækkevidde.",
	["Tint for actions you can't use right now for another reason (wrong form, missing target type, and so on)."] = "Farvning af handlinger som du ikke kan bruge lige nu af en anden grund (forkert form, manglende måltype og så videre).",
