	["To zoom in on the NPC, use the Talking to an NPC distance in Camera Situations; this view never moves the camera itself."] = "Brug afstanden Samtale med en NPC i Kamerasituationer for at zoome ind på NPC'en; denne visning flytter aldrig selv kameraet.",
	["Toast cards"] = "Pop op-kort",
	["Toast cards slide in beside the right edge (mover \"Loot Toasts\"). The loot feed is a compact stack of rows in the look you pick (mover \"Loot Feed\")."] = "Pop op-kort glider ind langs højre kant (flyttefeltet \"Pop op-beskeder for loot\"). Lootfeedet er en kompakt stak af rækker i det udseende du vælger (flyttefeltet \"Lootfeed\").",
	["Toasts and feed"] = "Pop op-beskeder og feed",
