	["Try again after combat."] = "Prøv igen efter kampen.",
	["Try again in %s."] = "Prøv igen om %s.",
	["Try another filter or search word."] = "Prøv et andet filter eller søgeord.",
	["Try: %s"] = "Prøv: %s",
	["Turn %d of %d: roll the dice."] = "Tur %d af %d: slå med terningerne.",
	["Turn Battleground Timers on first (Modules page)."] = "Slå først Battleground-nedtællinger til (siden Moduler).",
	["Turn every bubble off in dungeons, raids and battlegrounds, and back on when you leave."] = "Slå alle talebobler fra i dungeons, raids og battlegrounds, og til igen når du forlader dem.",
	["Turn in %s"] = "Aflever %s",
	["Turn modules on or off, and run a typed /eui command."] = "Slå moduler til eller fra, og kør en kommando med /eui.",
	["Turn off \"%s\" first."] = "Slå \"%s\" fra først.",
	["Turn on \"%s\" on the General tab first."] = "Slå \"%s\" til på fanen Generelt først.",
	["Turn on \"Announce reset\" under Instances > Resets first."] = "Slå \"Meld reset\" til under Instanser > Resets først.",
	["Turn on \"Get routes your group sends\" (top right) to see routes people in your group send you."] = "Slå \"Modtag ruter fra din gruppe\" til (øverst til højre) for at se ruter som folk i din gruppe sender dig.",
	["Turn on \"Let EldoUI change this\" and Improve for the Legacy window under Blizzard UI"] = "Slå \"Lad EldoUI ændre dette\" og Forbedr til for Legacy-vinduet under Blizzard-UI",
	["Turn on \"Let EldoUI change this\" for the damage meter first (Combat HUD > Damage meter)."] = "Slå først \"Lad EldoUI ændre dette\" til for skademåleren (Combat HUD > Skademåler).",
	["Turn on \"Let EldoUI change this\" on the Blizzard combat text tab first."] = "Slå først \"Lad EldoUI ændre dette\" til på fanen Blizzards kamptekst.",
	["Turn on \"Share alt info with your guild\" in /eui > Alts first."] = "Slå først \"Del alt-info med din guild\" til under /eui > Alts.",
	["Turn on \"Share alt info with your guild\" in /eui > Alts, then click Ask the guild. Lists you import show here too."] = "Slå \"Del alt-info med din guild\" til under /eui > Alts, og klik derefter på Spørg guilden. Lister du importerer, vises også her.",
	["Turn on \"Share my recipes with the guild\" in /eui > Alts first."] = "Slå først \"Del mine opskrifter med guilden\" til under /eui > Alts.",
	["Turn on \"Share my recipes with the guild\" in /eui > Alts, then click Ask the guild. Lists guild members send show here."] = "Slå \"Del mine opskrifter med guilden\" til under /eui > Alts, og klik derefter på Spørg guilden. Lister som guildmedlemmer sender, vises her.",
	["Turn on \"Show what you loot\" to see the samples."] = "Slå \"Vis hvad du looter\" til for at se eksemplerne.",
	["Turn on Blizzard UI > Trade window > Improve first"] = "Slå først Blizzard-UI > Byttevindue > Forbedr til",
	["Turn on Camera Situations first."] = "Slå først Kamerasituationer til.",
	["Turn on Cooldown Pulse first."] = "Slå Cooldown-puls til først.",
	["Turn on EldoUI Loot Data in the addon list, then reload."] = "Slå EldoUI Loot Data til i addonlisten, og genindlæs derefter.",
	["Turn on Improve for the Legacy window here to dock the planner beside Blizzard's window."] = "Slå Forbedr til for Legacy-vinduet her for at docke planlæggeren ved siden af Blizzards vindue.",
	["Turn on Own groups on the Groups tab to give single icons their own look."] = "Slå Egne grupper til på fanen Grupper for at give enkelte ikoner deres eget udseende.",
	["Turn on the Alts module (Items and Economy) to list your characters here."] = "Slå modulet Alts til (Genstande og økonomi) for at vise dine karakterer her.",
	["Turn on the Alts module first"] = "Slå først Alts-modulet til",
	["Turn on the Instances module first (Group > Instances)."] = "Slå modulet Instanser til først (Gruppe > Instanser).",
	["Turn over"] = "Vend om",
	["Turn saved chat history off?\n\nThe %d saved chat lines of this character are deleted."] = "Slå gemt chathistorik fra?\n\nDenne karakters %d gemte chatlinjer slettes.",
	["Turn speed"] = "Drejehastighed",
	["Turn text smileys into emoji"] = "Lav tekstsmileys om til emojis",
	["Turn the Cooldown Manager on"] = "Slå Cooldown Manager til",
	["Turn the falling shapes and fill whole rows."] = "Drej de faldende figurer og fyld hele rækker.",
	["Turn the name icons off in single chat tabs."] = "Slå navneikonerne fra i enkelte chatfaner.",
	["Turn the name icons off in single numbered channels, for example a busy trade channel."] = "Slå navneikonerne fra i enkelte nummererede kanaler, fx en travl handelskanal.",
	["Turn the spell cues on. Off by default."] = "Slå spell cues til. Fra som standard.",
	["Turn this extra resource bar on."] = "Slå denne ekstra ressourcebjælke til.",
	["Turn two cards at a time and find every pair."] = "Vend to kort ad gangen og find alle par.",
	["Turn-in reminder"] = "Afleveringspåmindelse",
	["Turns music and ambience down while fishing, so the splash stands out."] = "Skruer ned for musik og baggrundslyde mens du fisker, så plasket træder tydeligt frem.",
	["Turns the box off for every flight. The Flight Games options turn it back on."] = "Slår boksen fra for alle flyvninger. Under Flyvespil i indstillingerne slår du den til igen.",
	["Turns the group on. Its mover appears in move mode while it is on."] = "Slår gruppen til. Dens flyttefelt vises i flyttetilstand mens den er slået til.",
	["Turns the right chat panel on. Move it with /eui move (EldoUI_ChatRight)."] = "Slår det højre chatpanel til. Flyt det med /eui move (EldoUI_ChatRight).",
	["Turns this bar on or off without deleting it."] = "Slår denne bjælke til eller fra uden at slette den.",
	["Turns your own groups off: EldoUI's own icons go back to the fixed rows (Main, Utility, Trinkets, Mobility, Items). Your groups are kept for later."] = "Slår dine egne grupper fra: EldoUI's egne ikoner vender tilbage til de faste rækker (Hoved, Utility, Trinkets, Mobilitet, Genstande). Dine grupper gemmes til senere.",
	["Two bars"] = "To bjælker",
	["Two Details windows stacked in the meter corner, each 440 x 200, with the EldoUI frame."] = "To Details-vinduer stablet i målerhjørnet, hver 440 x 200, med EldoUI-rammen.",
	["Two lanes"] = "To baner",
	["Two names and a count"] = "To navne og et antal",
	["Two pairs"] = "To par",
	["Twos"] = "Toere",
	["Type /eui in chat for the settings."] = "Skriv /eui i chatten for at åbne indstillingerne.",
	["Type a colon and two letters (such as :sm) to list matching emoji; Tab or a click puts one in. Without a colon, Tab works as before."] = "Skriv et kolon og to bogstaver (fx :sm) for at se emojis der passer; Tab eller et klik indsætter én. Uden kolon virker Tab som før.",
	["Type a guild name first."] = "Skriv først et guildnavn.",
	["Type a macro name or /macro text."] = "Skriv et makronavn eller /macro-tekst.",
	["Type a name, an item ID or bag search words."] = "Skriv et navn, et genstands-ID eller taskesøgeord.",
	["Type a name, or a filter: q:rare for rare items, ilvl>50 for item level above 50, t:cloth for a type, or junk, quest and new. Put - before a word to leave it out."] = "Skriv et navn eller et filter: q:rare for Rare-genstande, ilvl>50 for item level over 50, t:cloth for en type, eller junk, quest og new. Sæt - foran et ord for at udelade det.",
	["Type a search first."] = "Skriv en søgning først.",
	["Type a search term, or pick a shopping list."] = "Skriv et søgeord, eller vælg en indkøbsliste.",
	["Type a spell ID and press Enter to put that spell in the Spell row."] = "Skriv et evne-ID, og tryk på Enter for at sætte evnen i rækken Evne.",
	["Type a spell name or drag a spell here."] = "Skriv navnet på en evne, eller træk en evne hertil.",
	["Type a word and press Enter."] = "Skriv et ord og tryk Enter.",
	["Type a word or phrase first."] = "Skriv et ord eller en frase først.",
	["Type an item ID or name, or paste an item link, and press Enter."] = "Skriv et genstands-ID eller navn, eller indsæt et genstandslink, og tryk på Enter.",
	["Type letters, Enter guesses, Backspace erases; the keys below work with a click."] = "Skriv bogstaver, Enter gætter, Backspace sletter; tasterne nedenfor virker også med et klik.",
	["Type to search"] = "Skriv for at søge",
	["Type to search. Pinned and recent results show here."] = "Skriv for at søge. Fastgjorte og seneste resultater vises her.",
	["Type: %s"] = "Type: %s",
	["Typed lines"] = "Skrevne linjer",
	["Typed lines kept"] = "Gemte skrevne linjer",
	["Typing a sum (\"= 12*35+4\" or \"12*35+4\") shows the answer; a click opens it ready to copy."] = "Når du skriver et regnestykke (\"= 12*35+4\" eller \"12*35+4\"), vises svaret; et klik åbner det klar til at kopiere.",
	["U takes back your last move."] = "U fortryder dit sidste træk.",
	["U: back. R: again."] = "U: tilbage. R: forfra.",
	["Uncheck the last pull: it is next again."] = "Fjern det seneste flueben: det pull er det næste igen.",
	["Uncommon"] = "Uncommon",
	["uncommon"] = "Uncommon",
	["Uncommon (green)"] = "Uncommon (grøn)",
	["Uncommon+"] = "Uncommon+",
	["Under the cooldown rows"] = "Under cooldownrækkerne",
	["Under the cooldown rows: the block hangs under the main row, after the item row and before a cast bar placed there, and moves with them. Own mover: drag it in move mode."] = "Under cooldownrækkerne: blokken hænger under hovedrækken, efter genstandsrækken og før en castbar der er placeret dér, og flytter med dem. Eget flyttefelt: træk den i flyttetilstand.",
	["Under the cooldowns"] = "Under cooldownene",
	["under the guide"] = "under guiden",
	["Under the level line"] = "Under levellinjen",
	["Under the player frame"] = "Under spillerrammen",
	["Under the window"] = "Under vinduet",
	["Undercity lies under the ruins of which city?"] = "Under ruinerne af hvilken by ligger Undercity?",
	["Undercut"] = "Undercut",
