	["Undo last upgrade"] = "Fortryd sidste opgradering",
	["Undo on this page puts every value back as it was."] = "Fortryd på denne side sætter alle værdier tilbage som de var.",
	["Undo the step card change"] = "Fortryd ændringen af trinkortet",
	["Undo: Questie's own corner"] = "Fortryd: Questies eget hjørne",
	["Unicode character"] = "Unicode-tegn",
	["Unit price"] = "Stykpris",
	["Units per column"] = "Enheder pr. kolonne",
	["unknown"] = "ukendt",
	["Unknown option. Try /eui help legacy."] = "Ukendt valgmulighed. Prøv /eui help legacy.",
	["Unlock EldoUI frames to drag the class bar (mover \"Class Bar\")."] = "Lås EldoUI-rammer op for at trække klassebjælken (flyttefelt \"Klassebjælke\").",
	["Unlock EldoUI frames to drag the counters."] = "Lås EldoUI-rammer op for at trække tællerne.",
	["Unlock EldoUI frames to drag the list."] = "Lås EldoUI-rammer op for at trække listen.",
	["Unlock EldoUI frames to drag the panels (not attached ones)."] = "Lås EldoUI-rammerne op for at trække panelerne (ikke de dokkede).",
	["Unlocked"] = "Ulåst",
	["Unlocks only the scroll areas, each with sample lines in its own look and a bar where new lines start. Drag a box to move it, its corner to resize it; right-click turns it on or off."] = "Låser kun rulleområderne op, hver med prøvelinjer i sit eget udseende og en bjælke hvor nye linjer starter. Træk en boks for at flytte den og dens hjørne for at ændre størrelsen. Højreklik slår den til eller fra.",
	["Unlocks only this area, with sample lines and its start edge marked, so you can drag or resize it."] = "Låser kun dette område op, med prøvelinjer og startkanten markeret, så du kan trække det eller ændre størrelsen.",
	["Unlocks the combat frames so you can drag the timeline. The big icon and the bar move together."] = "Låser kamprammerne op, så du kan trække tidslinjen. Det store ikon og bjælken flytter sig sammen.",
	["Unmute in %s"] = "Fjern dæmpning i %s",
	["Unmute their guild <%s>"] = "Fjern dæmpning af deres guild <%s>",
	["Unspent points"] = "Ubrugte point",
	["Until setup is done, it waits under the player frame."] = "Indtil opsætningen er færdig, venter den under spillerrammen.",
	["Until then, the Cast button on the fishing bar casts."] = "Indtil da kaster knappen Kast på fiskelinjen snøren.",
	["Up (columns)"] = "Op (kolonner)",
	["Up (newest at the bottom)"] = "Op (nyeste nederst)",
	["Up next"] = "Næste",
	["Up to 16 characters in front of whispers you receive. Empty uses >."] = "Op til 16 tegn foran hvisk du modtager. Tomt bruger >.",
	["Up to 16 characters in front of whispers you send. Empty uses <."] = "Op til 16 tegn foran hvisk du sender. Tomt bruger <.",
	["Up to 90 days shows one bar per day; the year shows one bar per week."] = "Op til 90 dage viser én søjle pr. dag; året viser én søjle pr. uge.",
	["Up to eight datatext panels of your own, anywhere on screen with a mover, or docked in the chat window or on the minimap."] = "Op til otte egne datatekstpaneler med flyttefelt, frit placeret på skærmen eller dokket i chatvinduet eller på minikortet.",
	["Up to level"] = "Op til level",
	["Upgrade and new look border"] = "Kant for opgradering og nyt udseende",
	["Upgrade arrow"] = "Opgraderingspil",
	["Upgrade arrows"] = "Opgraderingspile",
	["Upward drift in pixels per second; negative values make particles fall."] = "Opdrift i pixels pr. sekund; negative værdier får partiklerne til at falde.",
	["Upward drift in pixels per second; negative values sink."] = "Opdrift i pixels pr. sekund; negative værdier får partiklerne til at synke.",
	["Urgent timer"] = "Travl tidsbjælke",
	["Usage: /eui alts [on | off | search <text> | agenda | log | size]"] = "Brug: /eui alts [on | off | search <text> | agenda | log | size]",
	["Usage: /eui chat %s <channel>; <name>, for example /eui chat mute Trade; Name-Realm"] = "Brug: /eui chat %s <channel>; <name>, fx /eui chat mute Trade; Navn-Realm",
	["Usage: /eui chat alert <word or phrase> (adds it, or removes it when it is on the list)"] = "Brug: /eui chat alert <word or phrase> (tilføjer det, eller fjerner det hvis det allerede er på listen)",
	["Usage: /eui chatguild %s <guild>"] = "Brug: /eui chatguild %s <guild>",
	["Usage: /eui crosshair [on|off]"] = "Brug: /eui crosshair [on|off]",
	["Usage: /eui cursor [on|off]"] = "Brug: /eui cursor [on|off]",
	["Usage: /eui find <name or filter>, e.g. /eui find linen or /eui find q:rare t:cloth"] = "Brug: /eui find <navn eller filter>, fx /eui find linen eller /eui find q:rare t:cloth",
	["Usage: /eui fish [mode | log | reset]"] = "Brug: /eui fish [mode | log | reset]",
	["Usage: /eui fx list | test <trigger> | mute"] = "Brug: /eui fx list | test <trigger> | mute",
	["Usage: /eui fx test <trigger>  (see /eui fx list)"] = "Brug: /eui fx test <trigger>  (se /eui fx list)",
	["Usage: /eui probe charges <spell name or ID>"] = "Brug: /eui probe charges <spell name or ID>",
	["Usage: /eui sound <id>  (see /eui media sound)"] = "Brug: /eui sound <id>  (se /eui media sound)",
	["Usage: /eui threat [on | off | focus | target]"] = "Brug: /eui threat [on | off | focus | target]",
	["Use %d as the limit"] = "Brug %d som grænse",
	["Use %s, %s or %s."] = "Brug %s, %s eller %s.",
	["Use /eui instances stats, or stats party, raid, group or guild."] = "Brug /eui instances stats eller stats party, raid, group eller guild.",
	["Use a different gap between rows than between columns."] = "Brug en anden afstand mellem rækker end mellem kolonner.",
	["Use Blizzard's Buy tab for this item."] = "Brug Blizzards købsfane til denne genstand.",
	["Use EldoUI's bindings"] = "Brug EldoUI's bindinger",
	["Use Masque"] = "Brug Masque",
	["Use the EldoUI Details profile"] = "Brug EldoUI's Details-profil",
	["use the Hearthstone"] = "brug Hearthstone",
	["Use the shared cooldown colors (Fonts and text > Cooldown numbers): one for minutes, one for seconds, red near the end."] = "Brug de fælles cooldownfarver (Skrifttyper og tekst > Cooldowntal): én til minutter, én til sekunder, rød nær slutningen.",
	["Use these settings once the raid is big enough; otherwise a smaller raid tab is used."] = "Brug disse indstillinger når raidet er stort nok; ellers bruges fanen for et mindre raid.",
	["use this price (minus your undercut)"] = "brug denne pris (minus dit undercut)",
	["Use this situation"] = "Brug denne situation",
	["Use this trigger"] = "Brug denne udløser",
	["Use your hearthstone"] = "Brug din Hearthstone",
	["Used when a theme above was deleted."] = "Bruges når et tema ovenfor er slettet.",
	["Used when the bar color is set to Custom color."] = "Bruges når bjælkefarven er sat til Brugerdefineret farve.",
	["Used when the color is Custom color."] = "Bruges når farven er Brugerdefineret farve.",
	["Used with Color per bar."] = "Bruges med Farve pr. bjælke.",
	["Used with Custom color."] = "Bruges med Brugerdefineret farve.",
	["Uses %s on your pole: one press."] = "Bruger %s på din fiskestang: ét tryk.",
	["Uses the game's equipment sets from the character window. Every swap happens out of combat; nothing is queued for later."] = "Bruger spillets udstyrssæt fra karaktervinduet. Alle skift sker uden for kamp; intet sættes i kø til senere.",
	["Uses the same font for the damage and healing numbers over targets. The game reads it when you log in, so it shows after a relog."] = "Bruger samme skrifttype til skade- og helingstallene over mål. Spillet indlæser den ved login, så den vises først efter et relog.",
	["utility"] = "værktøj",
	["Utility"] = "Utility",
	["Utility row"] = "Utility-række",
	["Value color"] = "Værdifarve",
	["Value where this color starts. Values at or past your maximum are skipped."] = "Værdien hvor denne farve begynder. Værdier på eller over dit maksimum springes over.",
	["Value/h"] = "Værdi/t",
	["Values are"] = "Værdier er",
	["Vehicle actions on bar 1"] = "Køretøjshandlinger på linje 1",
	["Vehicle bar"] = "Køretøjslinje",
	["Vehicle Exit"] = "Forlad køretøj",
	["Vehicle Seats"] = "Køretøjssæder",
	["Vehicles"] = "Køretøjer",
	["vendor"] = "købmand",
	["Vendor"] = "Købmand",
	["Vendor and auction house recipes get a color: green if one of your characters can learn it now, yellow if later, red if all of them know it."] = "Opskrifter hos købmænd og i auktionshuset får en farve: grøn hvis en af dine karakterer kan lære den nu, gul hvis senere, rød hvis alle kan den i forvejen.",
	["Vendor price"] = "Købmandspris",
	["Vendor price line"] = "Linje med købmandspris",
	["Vendor value of all copies"] = "Salgsværdi for alle eksemplarer",
	["Vertical"] = "Lodret",
	["Vertical bar only"] = "Kun lodret bjælke",
	["Vertical bar only: the timer's name beside each icon."] = "Kun lodret bjælke: nedtællingens navn ved siden af hvert ikon.",
	["Vertical list"] = "Lodret liste",
	["Vertical shift of the time text."] = "Lodret forskydning af tidsteksten.",
	["Vertical spacing"] = "Lodret afstand",
	["Very close at NPCs and indoors, wide in the world."] = "Meget tæt på ved NPC'er og indendørs, bredt ude i verden.",
	["Very wide (16:9)"] = "Meget bred (16:9)",
	["View"] = "Visning",
	["View another character's items, or forget one."] = "Se en anden karakters genstande, eller glem en.",
	["Visibility and text"] = "Synlighed og tekst",
	["Visibility macro"] = "Synlighedsmakro",
	["Visible for"] = "Synlig i",
	["Visit a vendor"] = "Besøg en købmand",
	["Visuals in combat"] = "Visuelle effekter i kamp",
	["Voice mute, deafen and text-to-speech buttons."] = "Knapper til mikrofon fra, lyd fra og tekst til tale.",
	["Voidwalker"] = "Voidwalker",
	["Vol"] = "Lyd",
	["Volume channel for the countdown. Default follows General > Sound channel."] = "Lydkanal for nedtællingen. Standard følger Generelt > Lydkanal.",
	["Volume channel for this sound."] = "Lydkanal til denne lyd.",
	["Volume channel for triggers set to Module default. Default follows the general sound channel."] = "Lydkanal til udløsere som er sat til Modulstandard. Standard følger den generelle lydkanal.",
	["Volume while fishing"] = "Lydstyrke mens du fisker",
	["Wait %d seconds before you send again."] = "Vent %d sekunder før du sender igen.",
	["Waiting for combat to end"] = "Venter på at kampen slutter",
	["Waiting for the auction house..."] = "Venter på auktionshuset...",
	["Waiting icons"] = "Ventende ikoner",
	["Walking out and back into the same instance doesn't count twice: entries with the same instance ID, read from the mobs you target, are merged."] = "Går du ud og ind i samme instans igen, tæller det ikke dobbelt: besøg med samme instans-ID, aflæst fra de mobs du har som mål, slås sammen.",
	["Ward of Spite"] = "Ward of Spite",
	["Warlocks: how many Soul Shards are in your bags, with the shard's icon, at the right end of the mana bar. It changes as soon as your bags do."] = "Warlocks: hvor mange Soul Shards du har i taskerne, med shardens ikon, i højre ende af manabjælken. Tallet opdateres så snart indholdet i dine tasker ændres.",
	["Warn about mail with fewer days left than this. The Mail and AH tab colors those mails yellow."] = "Advar om post med færre dage tilbage end dette. Fanen Post og AH farver de breve gule.",
	["Warn again when it stacks"] = "Advar igen ved ny stak",
	["Warn at"] = "Advar ved",
	["Warn before Camp Benefits ends"] = "Advar før Camp Benefits slutter",
	["Warn on a flagged target"] = "Advar ved et flagget mål",
	["Warn this many minutes before"] = "Advar så mange minutter før",
	["Warn when ammo runs low"] = "Advar når ammunitionen er ved at slippe op",
	["Warn when both place a frame"] = "Advar når begge placerer en ramme",
	["Warn when you get flagged"] = "Advar når du bliver flagget",
	["Warning at"] = "Advarsel ved",
	["Warning sound"] = "Advarselslyd",
	["Warning zones"] = "Advarselszoner",
	["Watch items, currencies and gold as small movable counters, with goals and the session gain."] = "Overvåg genstande, valutaer og guld som små flytbare tællere med mål og gevinst i sessionen.",
	["Watch the float..."] = "Hold øje med flåddet...",
	["Watch the runes..."] = "Se runerne...",
	["Watched"] = "Overvåget",
	["Watching %s (%d charges). Spend the charges; each one that comes back prints a line. /eui probe charges off stops."] = "Holder øje med %s (%d ladninger). Brug ladningerne; hver ladning der kommer tilbage, skriver en linje. /eui probe charges off stopper.",
	["Water drop"] = "Vanddråbe",
	["Water Elemental"] = "Water Elemental",
	["Wave %d"] = "Bølge %d",
	["Wave %d of %d"] = "Bølge %d af %d",
	["Wave %d reached"] = "Nåede bølge %d",
	["Wave %d, lives %d"] = "Bølge %d, liv %d",
	["Wave cleared!"] = "Bølgen er slået tilbage!",
	["Waypoint to the goal"] = "Waypoint til målet",
	["Weapon and profession skills going up."] = "Våben- og fagskills der stiger.",
	["Weapon enchants"] = "Våbenenchants",
	["Weapon Enchants"] = "Våbenenchants",
	["Weapons and armor"] = "Våben og rustning",
	["Weapons and armor show their item level in the corner, in the quality color."] = "Våben og rustning viser deres item level i hjørnet, i kvalitetsfarven.",
	["Weapons and armor."] = "Våben og rustning.",
	["Weapons back"] = "Våben tilbage",
	["Web addresses in chat become links. Click one, then press Ctrl+C to copy it. Shift+click puts it into an open chat edit box."] = "Webadresser i chatten bliver til links. Klik på et, og tryk så på Ctrl+C for at kopiere det. Shift+klik sætter det ind i et åbent chatfelt.",
	["Week starts on Monday"] = "Ugen starter mandag",
	["Week to %s"] = "Ugen frem til %s",
	["Well met!"] = "Hej med dig!",
	["Well played!"] = "Godt spillet!",
	["WELP"] = "WELP",
	["Whack-a-Gnoll"] = "Slå gnollen",
	["What a spell's place shows while its aura is not on the unit. The place never moves."] = "Hvad en evnes plads viser mens dens aura ikke er på enheden. Pladsen flytter sig aldrig.",
	["What a vendor pays for the looted stack, beside the name."] = "Hvad en købmand betaler for den lootede stak, ved siden af navnet.",
	["What a vendor pays for the whole stack, at the right of the row."] = "Hvad en købmand betaler for hele stakken, i højre side af rækken.",
	["What an item looks like when your bags hold none of it."] = "Hvordan en genstand ser ud når dine tasker ikke har nogen af den.",
	["What color is the name of an item of %s quality?"] = "Hvilken farve har navnet på en genstand med kvaliteten %s?",
	["What do the playable undead call themselves?"] = "Hvad kalder de spilbare udøde sig selv?",
	["What does a warlock gather with Drain Soul?"] = "Hvad samler en warlock med Drain Soul?",
	["What does Bind on Pickup mean?"] = "Hvad betyder Bind on Pickup?",
	["What EldoUI may change on Blizzard's own bars is set on the Blizzard UI page, bar by bar. A bar at Blizzard default stays exactly as it is."] = "Hvad EldoUI må ændre på Blizzards egne linjer, indstilles linje for linje på siden Blizzard-UI. En linje med Blizzards standard forbliver præcis som den er.",
	["What EldoUI may do with Blizzard's chat is set on the Blizzard UI page. These settings shape what each switch does."] = "Hvad EldoUI må gøre med Blizzards chat, indstilles på siden Blizzard-UI. Disse indstillinger bestemmer hvad hver kontakt gør.",
	["What EldoUI may do with bubbles is set on the Blizzard UI page. In instances the game locks them: only the font and which ones show apply."] = "Hvad EldoUI må gøre med talebobler, indstilles på Blizzard-UI-siden. I instanser låser spillet dem: kun skrifttypen og hvilke der vises, gælder.",
	["What EldoUI places"] = "Hvad EldoUI placerer",
	["What EldoUI sets in its DBM profile"] = "Hvad EldoUI sætter i sin DBM-profil",
	["What Herbalism skill do you need to pick %s?"] = "Hvilket Herbalism-skill skal du have for at plukke %s?",
	["What is read out. {name} becomes the spell's or item's name."] = "Det der læses op. {name} bliver til evnens eller genstandens navn.",
	["What is the highest level a character can reach?"] = "Hvad er det højeste level en karakter kan nå?",
	["What it searches"] = "Hvad den søger i",
	["What it shows"] = "Hvad den viser",
	["What kind of beast is Gahz'rilla?"] = "Hvilken slags dyr er Gahz'rilla?",
	["What kind of creature is Hogger of Elwynn Forest?"] = "Hvilken slags væsen er Hogger fra Elwynn Forest?",
	["What Mining skill is needed for %s?"] = "Hvilket Mining-skill skal der til for %s?",
	["What party and raid members loot, with their name in class colors. A loot line the game hides adds nothing."] = "Hvad medlemmer af din gruppe og dit raid looter, med deres navn i klassefarve. En lootlinje som spillet skjuler, tilføjer intet.",
	["What shows behind your character model."] = "Hvad der vises bag din karaktermodel.",
	["What sweeps over the filled part."] = "Det der fejer hen over den fyldte del.",
	["What the bar does when a cast completes: a short flash, and particles bursting from the edge."] = "Hvad bjælken gør når et cast fuldføres: et kort blink og partikler der springer ud fra kanten.",
	["What the bar does when a cast fails or is interrupted: a flash in the theme's fail color, and a short shake."] = "Hvad bjælken gør når et cast fejler eller afbrydes: et blink i temaets fejlfarve og en kort rystelse.",
	["What the bar shows. Combo points show as one bar that fills per point."] = "Hvad bjælken viser. Combopoints vises som én bjælke der fyldes for hvert point.",
	["What the picker puts into your line. Shortcode (:smile:) reads fine for everyone and is a picture for EldoUI users. Unicode sends the character; others may see boxes."] = "Det som vælgeren sætter ind i din linje. Kortkode (:smile:) kan læses af alle og vises som et billede for EldoUI-brugere. Unicode sender selve tegnet; andre ser måske firkanter.",
	["What the stack shows for your class."] = "Hvad stakken viser for din klasse.",
	["What they say and yell near you."] = "Det de siger og råber i nærheden af dig.",
	["What to warn about"] = "Hvad der skal advares om",
	["What was hidden from muted guilds in the last 15 minutes. Also /eui chatguild hidden."] = "Hvad der er skjult fra dæmpede guilds inden for de sidste 15 minutter. Også /eui chatguild hidden.",
	["What was hidden in the last 15 minutes."] = "Hvad der er skjult inden for de sidste 15 minutter.",
	["What you gain"] = "Hvad du får",
	["What you typed in the edit box comes back after a reload or the next login: Up and Down walk through it. Per character; secure commands are never saved. Off keeps them for this session only."] = "Det du har skrevet i tekstfeltet, kommer tilbage efter en genindlæsning eller næste login: op- og nedpil går igennem det. Pr. karakter; sikre kommandoer gemmes aldrig. Fra beholder dem kun i denne session.",
	["Wheel down"] = "Hjul ned",
	["Wheel up"] = "Hjul op",
	["When a plan arrives from your group, one chat line names the blessings you keep up and on which classes. Paladins only."] = "Når en plan ankommer fra din gruppe, nævner én chatlinje de velsignelser du holder oppe, og på hvilke klasser. Kun Paladins.",
	["When an icon can't show (spell not known, item not in your bags), the others move up. Off keeps its spot empty."] = "Når et ikon ikke kan vises (evnen er ikke lært, genstanden er ikke i dine tasker), rykker de andre op. Fra holder dets plads tom.",
	["When another addon provides LibDataBroker, its feeds can be picked as \"LDB: name\" in any slot. Turning this off takes effect after a reload."] = "Når en anden addon leverer LibDataBroker, kan dens feeds vælges som \"LDB: navn\" på en vilkårlig plads. Slår du dette fra, træder det i kraft efter en genindlæsning.",
	["When Blizzard's Cooldown Manager has no spells for your class, these rows stand in for its viewers. Always: they always show (hide Blizzard's viewers if both show)."] = "Når Blizzards Cooldown Manager ikke har evner til din klasse, træder disse rækker i stedet for dens visninger. Altid: de vises altid (skjul Blizzards visninger hvis begge vises).",
	["When Blizzard's is empty"] = "Når Blizzards er tom",
	["When Blizzard's is hidden"] = "Når Blizzards er skjult",
	["When chat lines fade out. Scrolling or hovering shows them again."] = "Hvornår chatlinjer toner ud. De vises igen når du ruller eller holder musen over.",
	["When durability turns red is set once for every module, on the General page (Clock and durability)."] = "Hvornår holdbarheden bliver rød, indstilles én gang for alle moduler på siden Generelt (Ur og holdbarhed).",
	["When durability turns yellow and red is set once for every module, on the General page (Clock and durability)."] = "Hvornår holdbarheden bliver gul og rød, indstilles én gang for alle moduler på siden Generelt (Ur og holdbarhed).",
	["When EldoUI's cast bar for a checked unit is off, decorate Blizzard's own cast bar for that unit instead."] = "Når EldoUI's castbar for en enhed med flueben er slået fra, pynter EldoUI i stedet Blizzards egen castbar for den enhed.",
	["When fishing mode starts: whenever a fishing pole is in your main hand (the Fishing mode key binding pauses it), or only after you press that key binding (Key Bindings > AddOns)."] = "Hvornår fisketilstand starter: hver gang du har en fiskestang i hovedhånden (genvejstasten til fisketilstand sætter den på pause), eller kun når du trykker på den genvejstast (Key Bindings > AddOns).",
	["When hovering a button shows its tooltip."] = "Hvornår en knap viser sin tooltip når du holder musen over den.",
	["When inactive"] = "Når inaktiv",
	["When missing"] = "Når den mangler",
	["When no situation applies, zoom back to the distance you had before."] = "Når ingen situation gælder, zoomer kameraet tilbage til den afstand du havde før.",
	["When none are left"] = "Når der ikke er flere tilbage",
	["When one of the spell IDs below lands on you."] = "Når et af evne-ID'erne nedenfor lander på dig.",
	["When one of your listed spells or items is ready again, its icon pops up in the middle of the screen. The global cooldown never counts."] = "Når en af dine evner eller genstande på listen er klar igen, popper dens ikon frem midt på skærmen. Den globale cooldown tæller aldrig med.",
	["When someone asks"] = "Når nogen spørger",
	["When someone in your group clicks Send to group, their route shows here."] = "Når nogen i din gruppe klikker på Send til gruppen, vises deres rute her.",
	["When the battleground is ready, a bar shows how long you have to enter. You still enter through Blizzard's pop-up."] = "Når battlegroundet er klar, viser en bjælke hvor lang tid du har til at gå ind. Du går stadig ind via Blizzards pop op-vindue.",
	["When the breath bar runs out under water."] = "Når åndedrætsbjælken løber tør under vand.",
	["When the character was last online."] = "Hvornår karakteren sidst var online.",
	["When the crosshair shows."] = "Hvornår sigtekorset vises.",
	["When the feed is full, the oldest row makes room."] = "Når feedet er fuldt, giver den ældste række plads.",
	["When the game lights up a spell (a proc, or a spell you can use now), its buttons flash once. The game's own glow stays as set on the Buttons tab."] = "Når spillet lyser en evne op (en proc eller en evne du kan bruge nu), blinker dens knapper én gang. Spillets egen glød følger indstillingen på fanen Knapper.",
	["When the game lights up one of your spells (the glow on the action button). In boss fights these move to the Incoming area so they don't cover boss warnings."] = "Når spillet får en af dine evner til at lyse op (gløden på handlingsknappen). I bosskampe flyttes de til området Indkommende så de ikke dækker bossadvarsler.",
	["When the game says you landed the killing blow. In boss fights these move to the Incoming area."] = "Når spillet siger at du landede det dræbende slag. I bosskampe flyttes de til området Indkommende.",
	["When the guide's spot is in the top half of the screen, its current step card opens under the guide, so the guide grows down from its spot. Lower on the screen RestedXP's own choice stays."] = "Når guidens plads er i skærmens øverste halvdel, åbner dens aktuelle trinkort under guiden, så guiden vokser nedad fra sin plads. Længere nede på skærmen gælder RestedXP's eget valg.",
	["When the Masque addon is loaded, let it skin EldoUI's buttons (one Masque group per bar). EldoUI's own button art steps aside."] = "Lad Masque-addonen give EldoUI's knapper skin når den er indlæst (én Masque-gruppe pr. linje). EldoUI's egen knapgrafik træder til side.",
	["When the ring shows."] = "Hvornår ringen vises.",
	["When the window is on screen."] = "Hvornår vinduet er på skærmen.",
	["When two categories' searches find the same item, the higher priority gets it."] = "Når to kategoriers søgninger finder den samme genstand, får den med højest prioritet den.",
	["When you are the master looter and click an item, a menu lists who can take it (by class in a raid) and Request roll. Items from Epic up ask before they are given."] = "Når du er master looter og klikker på en genstand, viser en menu hvem der kan få den (efter klasse i et raid) og Bed om rul. Genstande fra Epic og op spørger før de gives væk.",
	["When you leave, one line with what the run gave you: time, XP kills, experience, gold and reputation."] = "Når du går ud, én linje med hvad runnet gav dig: tid, XP-drab, erfaring, guld og omdømme.",
	["When you scrolled up and leave the chat alone this long, it jumps back to the newest line (not while the mouse is over it)."] = "Når du har rullet op og lader chatten være i så lang tid, hopper den tilbage til nyeste linje (ikke mens musen er over den).",
	["When you swim into deep water fatigue."] = "Når du svømmer så langt ud på dybt vand at du bliver udmattet.",
	["Where a new column (or row) starts once one is full."] = "Hvor en ny kolonne (eller række) starter når den forrige er fuld.",
	["Where a new line starts when a line is full."] = "Hvor en ny linje starter når en linje er fuld.",
	["Where a new row starts when one is full."] = "Hvor en ny række begynder når en række er fuld.",
	["Where blocked phrases and the Cyrillic filter look. All also covers guild, group and whispers."] = "Hvor blokerede fraser og det kyrilliske filter gælder. Alle dækker også guild, gruppe og hvisk.",
	["Where can you find %s?"] = "Hvor finder du %s?",
	["Where do you set your hearthstone's home?"] = "Hvor sætter du din Hearthstones hjem?",
	["Where does the boat from Booty Bay sail to?"] = "Hvor sejler båden fra Booty Bay hen?",
	["Where each button sits on the bar. Key bindings stay with their button."] = "Hvor hver knap sidder på linjen. Genvejstaster følger med deres knap.",
	["Where is %s?"] = "Hvor ligger %s?",
	["Where Is It?"] = "Hvor ligger det?",
	["Where is the %s?"] = "Hvor ligger %s?",
	["Where keywords are looked for."] = "Hvor der kigges efter nøgleord.",
	["Where Move puts Blizzard's totem timers. Own mover gives them their own box in move mode; With the totem bar keeps them next to the shaman totem bar. Other classes use the mover."] = "Hvor Flyt placerer Blizzards totemnedtællinger. Eget flyttefelt giver dem deres egen boks i flyttetilstand; Ved totemlinjen holder dem ved siden af Shaman-totemlinjen. Andre klasser bruger flyttefeltet.",
	["Where on the button the count sits on this bar."] = "Hvor på knappen antallet sidder på denne linje.",
	["Where on the button the count sits."] = "Hvor på knappen antallet sidder.",
	["Where on the button the keybind sits on this bar."] = "Hvor på knappen genvejstasten sidder på denne linje.",
	["Where on the button the keybind sits."] = "Hvor på knappen genvejstasten sidder.",
	["Where on the frame the text shows. Portrait falls back to the center when the frame has no portrait."] = "Hvor på rammen teksten vises. Portræt bruger midten når rammen ikke har noget portræt.",
	["Where the anchors sit."] = "Hvor ankerpunkterne sidder.",
	["Where the bars sit. Its own mover is Class Resources in move mode."] = "Hvor bjælkerne sidder. I flyttetilstand hedder deres eget flyttefelt Klasseressourcer.",
	["Where the character logged out."] = "Hvor karakteren loggede ud.",
	["Where the charge count (or the item count in the item row) sits on the icon."] = "Hvor antallet af ladninger (eller antallet af genstande i genstandsrækken) sidder på ikonet.",
	["Where the countdown sits on the icon."] = "Hvor nedtællingen sidder på ikonet.",
	["Where the extra text sits on the health bar."] = "Hvor den ekstra tekst sidder på livsbjælken.",
	["Where the hearthstone is set."] = "Hvor Hearthstone er bundet.",
	["Where the icon sits next to the text."] = "Hvor ikonet sidder i forhold til teksten.",
	["Where the icon sits on each bar, or no icon."] = "Hvor ikonet sidder på hver bjælke, eller intet ikon.",
	["Where the icon sits."] = "Hvor ikonet sidder.",
	["Where the next member goes."] = "Hvor det næste medlem placeres.",
	["Where the next row (or bar) goes."] = "Hvor den næste række (eller bjælke) placeres.",
	["Where the panel's Announce button posts its one line. It only posts when you click it."] = "Hvor panelets Annoncer-knap sender sin ene linje. Den sender kun når du klikker på den.",
	["Where the player with the most threat sits."] = "Hvor spilleren med mest aggro sidder.",
	["Where the private aura slots sit."] = "Hvor pladserne til private auraer sidder.",
	["Where the ready check, resurrection, summon and phase icons sit."] = "Hvor ikonerne for klar-tjek, genoplivning, summon og fase sidder.",
	["Where the set buttons sit."] = "Hvor sætknapperne sidder.",
	["Where the skull, cross and other markers sit."] = "Hvor kraniet, krydset og de andre markører sidder.",
	["Where the spell's icon sits."] = "Hvor evnens ikon sidder.",
	["Where the tabs and the Errors, Find and Copy buttons sit: above or under the messages (move switch). The right panel's title follows."] = "Hvor fanerne og knapperne Fejl, Søg og Kopier sidder: over eller under beskederne (Flyt-kontakt). Titlen på højre panel følger med.",
	["Where the time text sits: under or over the icon, or on it."] = "Hvor tidsteksten sidder: under eller over ikonet, eller på det.",
	["Where the timers come from. Automatic uses the boss mod EldoUI set up, so nothing shows twice. Both shows DBM and BigWigs and drops doubles."] = "Hvor nedtællingerne kommer fra. Automatisk bruger den bossmod EldoUI har sat op, så intet vises to gange. Begge viser DBM og BigWigs og fjerner dubletter.",
	["Where the tooltips of this panel's blocks open."] = "Hvor tooltips til dette panels blokke åbnes.",
	["Where this label sits on or around the icon."] = "Hvor denne etiket sidder på eller omkring ikonet.",
	["Whether bars empty or fill up while they count down."] = "Om bjælkerne tømmes eller fyldes op mens de tæller ned.",
	["Whether the Alerts tab is ready, or why matches are waiting."] = "Om Alerts-fanen er klar, eller hvorfor linjer med nøgleord venter.",
	["Whether the limit below is in seconds or in percent of the whole time."] = "Om grænsen nedenfor er i sekunder eller i procent af hele tiden.",
	["Whether the spell is looked for as a buff or a debuff."] = "Om evnen søges som buff eller debuff.",
	["Whether you have the item's appearance: collected, collected from another item, not collected, or not for your character."] = "Om du har genstandens udseende: i samlingen, i samlingen fra en anden genstand, ikke i samlingen eller ikke til din karakter.",
	["Which Alliance force fights in Arathi Basin?"] = "Hvilken Alliance-styrke kæmper i Arathi Basin?",
