	["Which bag holds a hunter's arrows?"] = "Hvilken taske bærer en hunters pile?",
	["Which bag holds a hunter's bullets?"] = "Hvilken taske bærer en hunters kugler?",
	["Which band of thieves operates in Alterac and Hillsbrad?"] = "Hvilken tyvebande hærger i Alterac og Hillsbrad?",
	["Which bars"] = "Hvilke linjer",
	["Which black dragon hides in Stormwind as Lady Katrana Prestor?"] = "Hvilken sort drage gemmer sig i Stormwind som Lady Katrana Prestor?",
	["Which blood god do the Zandalari want stopped in Zul'Gurub?"] = "Hvilken blodgud vil Zandalari have stoppet i Zul'Gurub?",
