	["Which bubbles show"] = "Hvilke talebobler der vises",
	["Which capital city is home to the %s race?"] = "Hvilken hovedstad er hjem for racen %s?",
	["Which characters the gold tooltip lists. Right-click the gold datatext to switch."] = "Hvilke karakterer guldtooltippen viser. Højreklik på datateksten for guld for at skifte.",
	["Which characters the window lists first. You can change it in the window's top bar too. On Forever, \"This realm\" means everyone on the same ruleset (PvE, PvP, RP or Hardcore)."] = "Hvilke karakterer vinduet viser først. Du kan også ændre det i vinduets øverste bjælke. På Forever betyder \"Denne realm\" alle på samme regelsæt (PvE, PvP, RP eller Hardcore).",
	["Which characters the window lists: this character, this realm (on Forever: everyone on the same ruleset), this faction, or all. Groups you made show here too."] = "Hvilke karakterer vinduet viser: denne karakter, denne realm (på Forever: alle på samme regelsæt), denne fraktion eller alle. Grupper du har lavet, vises også her.",
	["Which chat types the edit box stays on after you send a line, one tick each. The ticks start as the game has them: everything but yell. Needs the Blizzard UI switch Improve."] = "Hvilke chattyper tekstfeltet bliver på efter at du har sendt en linje, ét flueben for hver. Fluebenene starter som spillet har dem: alt undtagen råb. Kræver Blizzard-UI-kontakten Forbedr.",
	["Which class can learn %s?"] = "Hvilken klasse kan lære %s?",
	["Which creatures in the mines of Elwynn Forest are famous for guarding their candles?"] = "Hvilke væsner i minerne i Elwynn Forest er kendt for at vogte deres stearinlys?",
	["Which cult gathers in the Twilight camps of Silithus?"] = "Hvilken kult samles i Twilight-lejrene i Silithus?",
	["Which cult serves the Scourge in the Plaguelands?"] = "Hvilken kult tjener Scourge i Plaguelands?",
