	["Which demon lord roams the Blasted Lands as a world boss?"] = "Hvilken dæmonherre strejfer rundt i Blasted Lands som world boss?",
	["Which dreadlord leads the Scarlet Crusade in Stratholme in disguise?"] = "Hvilken dreadlord leder forklædt Scarlet Crusade i Stratholme?",
