	["Which faction asks you to douse the runes in the Molten Core?"] = "Hvilken fraktion beder dig slukke runerne i Molten Core?",
	["Which faction fights the Scourge from Light's Hope Chapel?"] = "Hvilken fraktion bekæmper Scourge fra Light's Hope Chapel?",
