	["Which faction keeps Cenarion Hold in Silithus?"] = "Hvilken fraktion holder Cenarion Hold i Silithus?",
	["Which faction serves the bronze dragons of the Caverns of Time?"] = "Hvilken fraktion tjener de bronzefarvede drager fra Caverns of Time?",
	["Which fishing contest is held in Stranglethorn Vale?"] = "Hvilken fiskekonkurrence holdes i Stranglethorn Vale?",
