	["Which goddess do the night elves worship?"] = "Hvilken gudinde tilbeder natelverne?",
	["Which guild the players you saw belong to, for the muted guilds list in Chat."] = "Hvilken guild hver spiller du har set, hører til. Bruges til listen over dæmpede guilds i Chat.",
	["Which Horde force fights in Arathi Basin?"] = "Hvilken Horde-styrke kæmper i Arathi Basin?",
	["Which Horde force fights in Warsong Gulch?"] = "Hvilken Horde-styrke kæmper i Warsong Gulch?",
	["Which human kingdom closed itself off behind the Greymane Wall?"] = "Hvilket menneskerige lukkede sig inde bag Greymane Wall?",
	["Which hunter pet family can learn %s?"] = "Hvilken petfamilie hos en hunter kan lære %s?",
	["Which item"] = "Hvilken genstand",
	["Which item a button holds when you have several: the highest one your level can use, or the lowest one so old food and potions get used up. Mounts and the Hearthstone always take the best."] = "Hvilken genstand en knap rummer når du har flere: den højeste dit level kan bruge, eller den laveste så gammel mad og gamle potions bliver brugt op. Mounts og Hearthstone tager altid den bedste.",
	["Which item takes you back to the inn you made your home?"] = "Hvilken genstand bringer dig tilbage til den kro du har gjort til dit hjem?",
	["Which kind of aura each spell is looked for as. Buffs and debuffs finds either."] = "Hvilken slags aura der søges efter for hver evne. Buffs og debuffs finder begge dele.",
	["Which land in the far north is the seat of the Lich King?"] = "Hvilket land langt mod nord er Lich Kings sæde?",
	["Which layer of the screen the windows sit on. Higher layers cover more of the other windows."] = "Hvilket lag af skærmen vinduerne ligger på. Højere lag dækker mere af de andre vinduer.",
	["Which layer the panel draws on: higher layers cover lower ones."] = "Hvilket lag panelet tegnes på: højere lag dækker lavere.",
	["Which Legacy Challenges the Challenges page lists when it opens; its filter chips change this too."] = "Hvilke Legacy-udfordringer siden Udfordringer viser når den åbner; dens filterknapper ændrer det også.",
	["Which legendary hammer is named after Ragnaros?"] = "Hvilken legendarisk hammer er opkaldt efter Ragnaros?",
	["Which legendary staff is made from splinters found in Naxxramas?"] = "Hvilken legendarisk stav laves af splinter fra Naxxramas?",
	["Which legendary sword is the Blessed Blade of the Windseeker?"] = "Hvilket legendarisk sværd er Blessed Blade of the Windseeker?",
	["Which leveling guide takes the layout's guide spot. Automatic: RestedXP when it is installed and on, else Eldostar. EldoUI never turns the other guide addon off: it only stops placing it."] = "Hvilken levelingguide der tager layoutets guideplads. Automatisk: RestedXP når den er installeret og slået til, ellers Eldostar. EldoUI slår aldrig den anden guideaddon fra: den holder kun op med at placere den.",
	["Which loot window you use. This sets the Loot window switches on the Blizzard UI page (Move, Hide and the rest live there too)."] = "Hvilket lootvindue du bruger. Det indstiller kontakterne for Lootvindue på Blizzard-UI-siden (Flyt, Skjul og resten findes også dér).",
	["Which mount carries Alliance travelers on flight paths in Kalimdor?"] = "Hvilken mount bærer Alliance-rejsende på flyveruter i Kalimdor?",
