	["Which side of the area the text lines up on."] = "Hvilken side af området teksten justeres efter.",
	["Which side of the chosen frame the viewer sits on."] = "Hvilken side af den valgte ramme visningen sidder på.",
	["Which side of the essential row the icons sit on."] = "Hvilken side af den essentielle række ikonerne sidder på.",
	["Which sound to play: EldoUI's sounds, the game's or a SharedMedia pack's."] = "Hvilken lyd der afspilles: EldoUI's lyde, spillets eller en SharedMedia-pakkes.",
	["Which Spell?"] = "Hvilken besværgelse?",
	["Which spirits do the trolls worship?"] = "Hvilke ånder tilbeder troldene?",
	["Which tab is shown when you talk to an auctioneer."] = "Hvilken fane der vises når du taler med en auktionarius.",
	["Which time the Time datatext shows; its tooltip lists both."] = "Hvilken tid datateksten for klokkeslæt viser; dens tooltip viser begge.",
	["Which tram runs between Stormwind and Ironforge?"] = "Hvilket tog kører mellem Stormwind og Ironforge?",
	["Which troll empire built Zul'Gurub?"] = "Hvilket troldeimperium byggede Zul'Gurub?",
	["Which troll faction wants Hakkar stopped?"] = "Hvilken troldefraktion vil have Hakkar stoppet?",
	["Which troll tribe holds Zul'Farrak?"] = "Hvilken troldestamme holder Zul'Farrak?",
	["Which troll tribe is part of the Horde?"] = "Hvilken troldestamme er en del af Horde?",
	["Which wall keeps Ahn'Qiraj sealed off from Silithus?"] = "Hvilken mur holder Ahn'Qiraj lukket af fra Silithus?",
	["Which warlock demon has %s?"] = "Hvilken warlock-dæmon har %s?",
	["Which was the first great human empire, born in the Arathi Highlands?"] = "Hvilket var det første store menneskeimperium med rod i Arathi Highlands?",
	["Which way lines move, or grow when stacked. Down starts new lines at the top of the box and up at the bottom, so this moves where text appears; Move this area shows the edge."] = "Hvilken vej linjerne bevæger sig, eller vokser når de stables. Ned starter nye linjer øverst i boksen og op nederst, så det flytter hvor teksten vises. Flyt dette område viser kanten.",
	["Which way more rolls stack from the roll spot (EldoUI's bars, and Blizzard's frames with the Move switch)."] = "Hvilken vej flere rul stables fra rulpladsen (EldoUI's bjælker og Blizzards rammer med kontakten Flyt).",
	["Which way spell flyouts (for example portals or pets) open from this bar."] = "Hvilken vej flyouts for evner (for eksempel portaler eller pets) åbner fra denne linje.",
	["Which way the feed grows from its mover."] = "Hvilken vej feedet vokser fra sit flyttefelt.",
	["Which way the icons line up from the group's mover."] = "Hvilken vej ikonerne stilles op fra gruppens flyttefelt.",
	["Which windows open your bags with them. A window only closes the bags it opened; bags you opened yourself stay open."] = "Hvilke vinduer der også åbner dine tasker. Et vindue lukker kun de tasker det selv åbnede; tasker som du selv åbnede, forbliver åbne.",
	["Which world did the orcs come from through the Dark Portal?"] = "Fra hvilken verden kom orkerne gennem Dark Portal?",
	["Which zealous order holds the Scarlet Monastery?"] = "Hvilken fanatisk orden holder Scarlet Monastery?",
	["While a pole is equipped"] = "Mens en fiskestang er taget på",
	["While a profession window is open, EldoUI notes which reagents each recipe needs. Used by the crafting cost line and the Crafting list in the Shopping List tab."] = "Mens et fagvindue er åbent, noterer EldoUI hvilke reagenser hver opskrift kræver. Bruges af linjen med craftingpris og listen Crafting i fanen Indkøbsliste.",
	["While a vendor, the Send Mail tab, the bank or a trade is open, every stack shows on its own slot, so you can pick the one you want."] = "Mens du er ved en købmand, på fanen Send post, i banken eller i et bytte, vises hver stak på sin egen plads, så du kan vælge den du vil have.",
	["While Alt is held the bar shows the actions of another bar."] = "Mens Alt holdes nede, viser linjen en anden linjes handlinger.",
	["While Ctrl is held the bar shows the actions of another bar."] = "Mens Ctrl holdes nede, viser linjen en anden linjes handlinger.",
	["While EldoUI is on, this key opens the Finder instead of: %s."] = "Mens EldoUI er slået til, åbner denne tast Finder i stedet for: %s.",
	["While holding Shift"] = "Mens du holder Shift nede",
	["While Shift is held the bar shows the actions of another bar. Off keeps its own."] = "Mens Shift holdes nede, viser linjen en anden linjes handlinger. Fra: linjen beholder sine egne.",
	["While the bar is out of sight: it shows when you point at it out of combat. Off: it never shows, and its keys keep working."] = "Mens linjen er ude af syne: den vises når du peger på den uden for kamp. Fra: den vises aldrig, og dens taster virker stadig.",
	["While the box is shown but you are not typing and the mouse is not over it, it fades to the opacity in the gear. Typing or pointing at it brings it back at once."] = "Når feltet er vist, men du ikke skriver, og musen ikke er over det, toner det ned til opaciteten i tandhjulet. Når du skriver eller peger på det, kommer det straks tilbage.",
	["While the spellbook is open"] = "Mens evnebogen er åben",
	["While you cast, the part of the bar the spell will cost is lit up, from the spell's own cost."] = "Mens du caster, lyser den del af bjælken op som evnen koster, ud fra evnens egen pris.",
	["While you type in party chat, your party members who use EldoUI see that you are typing. Sends one short addon message at most every 4 seconds, party only, never during chat lockdown. Off by default."] = "Mens du skriver i gruppechatten, kan dine gruppemedlemmer der bruger EldoUI, se at du skriver. Sender højst én kort addonbesked hvert 4. sekund, kun til gruppen og aldrig under chatlåsning. Slået fra som standard.",
	["While you were away"] = "Mens du var væk",
	["While your bobber is out the fishing key is Interact with target, so a press on a splash loots it. It needs the game's soft interact for mouse and keyboard."] = "Mens dit flåd er ude, interagerer fisketasten med målet, så et tryk på et plask looter det. Det kræver spillets soft interact for mus og tastatur.",
	["Whisper %s"] = "Hvisk til %s",
	["Whisper alert"] = "Advarsel ved hvisk",
	["Whisper markers"] = "Hviskemarkører",
	["Whisper pink"] = "Pink (hvisk)",
	["Whisper sound"] = "Hviskelyd",
	["Whisper your target"] = "Hvisk til dit mål",
	["Whispers one line with the place and tier of your camp. Nothing else is sent."] = "Hvisker én linje med placering og trin for din lejr. Intet andet sendes.",
	["Whispers that arrive while you are away, listed on the screen (time, sender, text). Cleared when you come back; they stay in chat as always."] = "Hviskebeskeder der kommer mens du er væk, vises som en liste på skærmen (tid, afsender, tekst). Listen ryddes når du kommer tilbage; beskederne bliver i chatten som altid.",
	["Who betrayed the gnomes and holds Gnomeregan?"] = "Hvem forrådte gnomerne og holder Gnomeregan?",
	["Who built the vaults of Uldaman?"] = "Hvem byggede hvælvingerne i Uldaman?",
	["Who gets the offer when you click a send button."] = "Hvem der får tilbuddet når du klikker på en sendeknap.",
	["Who gets your Ask and Share. A reply to someone who asked always goes to them alone."] = "Hvem dine Spørg og Del går til. Et svar til en der har spurgt, går altid kun til vedkommende.",
	["Who is listed"] = "Hvem der vises",
	["Who is the arch druid of Darnassus?"] = "Hvem er ærkedruide i Darnassus?",
	["Who is the boy king of Stormwind?"] = "Hvem er drengekongen i Stormwind?",
	["Who is the father of Onyxia and Nefarian?"] = "Hvem er far til Onyxia og Nefarian?",
	["Who is the Firelord that waits in the Molten Core?"] = "Hvem er ildherren der venter i Molten Core?",
	["Who is the headmaster of Scholomance?"] = "Hvem er rektor for Scholomance?",
	["Who is the king of the dwarves in Ironforge?"] = "Hvem er dværgenes konge i Ironforge?",
	["Who is the master of Blackwing Lair?"] = "Hvem er herre over Blackwing Lair?",
	["Who is the regent of Stormwind while its king is missing?"] = "Hvem er regent i Stormwind mens kongen er forsvundet?",
	["Who is the warchief of the Horde?"] = "Hvem er Hordens warchief?",
	["Who leads the Darkspear trolls?"] = "Hvem leder Darkspear-troldene?",
	["Who leads the Defias Brotherhood?"] = "Hvem leder Defias Brotherhood?",
	["Who leads the Forsaken?"] = "Hvem leder Forsaken?",
	["Who leads the Frostwolf Clan in Alterac Valley?"] = "Hvem leder Frostwolf Clan i Alterac Valley?",
	["Who leads the gnomes from their exile in Ironforge?"] = "Hvem leder gnomerne fra deres eksil i Ironforge?",
	["Who leads the night elves from Darnassus?"] = "Hvem leder natelverne fra Darnassus?",
	["Who leads the Scourge in the dead half of Stratholme?"] = "Hvem leder Scourge i den døde halvdel af Stratholme?",
	["Who leads the Stormpike Guard in Alterac Valley?"] = "Hvem leder Stormpike Guard i Alterac Valley?",
	["Who leads the tauren of Thunder Bluff?"] = "Hvem leder taurenerne i Thunder Bluff?",
	["Who put in and took out gold."] = "Hvem der har sat guld ind og hævet guld.",
	["Who put in and took out what, in this tab."] = "Hvem der har sat hvad ind og taget hvad ud i denne fane.",
	["Who rules Naxxramas for the Scourge?"] = "Hvem hersker over Naxxramas for Scourge?",
	["Who rules Theramore Isle?"] = "Hvem hersker over Theramore Isle?",
	["Who was Thrall's father?"] = "Hvem var Thralls far?",
	["Whole game"] = "Hele spillet",
	["Whole in %d moves"] = { one = "Helt med %d træk", other = "Helt med %d træk" },
	["Whole screen (faint)"] = "Hele skærmen (svagt)",
	["Whole words only"] = "Kun hele ord",
	["Whom do the tauren honor above all?"] = "Hvem ærer taurenerne over alt?",
	["Whose auras the group shows."] = "Hvis auraer gruppen viser.",
	["Whose auras to watch: you, your target, focus or pet."] = "Hvis auraer der holdes øje med: dig, dit mål, fokus eller pet.",
	["Whose coming online fires the trigger: people on your friend list (the default), members of your guild, or both. Read from the friend list and guild roster, never from the chat line."] = "Hvem der skal logge på for at udløseren går af: folk på din venneliste (standard), medlemmer af din guild eller begge. Læses fra vennelisten og guildlisten, aldrig fra chatlinjen.",
	["Whose deaths get a card. The log keeps every announced death either way."] = "Hvilke dødsfald der får et kort. Loggen gemmer under alle omstændigheder alle annoncerede dødsfald.",
	["Whose threat table is listed. The T/F button in the window header switches it too. A friendly target shows the threat on that friend's target."] = "Hvis aggrotabel der vises. Knappen T/F i vinduets overskrift skifter den også. Har du et venligsindet mål, vises aggroen på dets mål.",
	["Wide"] = "Wide",
	["Wide (4:3)"] = "Bred (4:3)",
	["Wide 240 px list with 14 pt text and up to 12 rows."] = "Bred liste på 240 px med 14 pt tekst og op til 12 rækker.",
	["Wide 280 px bars with 14 pt text for big screens."] = "Brede bjælker på 280 px med 14 pt tekst til store skærme.",
