	["Width of each timer bar, icon included."] = "Bredde på hver tidsbjælke, inklusive ikon.",
	["Width of each timer bar."] = "Bredde på hver tidsbjælke.",
	["Width of EldoUI's loot window."] = "Bredden på EldoUI's lootvindue.",
	["Width of every row. While Match the Cooldown Manager width is on, used only when that row is hidden."] = "Bredde på hver række. Mens Tilpas til Cooldown Managers bredde er slået til, bruges den kun når den række er skjult.",
	["Width of every swing bar (also EldoUI's own bars)."] = "Bredden på alle swingbjælker (også EldoUI's egne bjælker).",
	["Width of the \"Boss Timers\" mover (BigWigs and DBM). With BigWigs' \"copy width of custom anchor\" on, the bars take this width; DBM's timer bars always do."] = "Bredden på flyttefeltet \"Bosstimere\" (BigWigs og DBM). Når BigWigs kopierer bredden fra det brugerdefinerede ankerpunkt, får bjælkerne denne bredde; DBM's tidsbjælker gør det altid.",
	["Width of the \"Boss Timers: Soon\" mover, where BigWigs' emphasized and DBM's enlarged timers go."] = "Bredden på flyttefeltet \"Bosstimere: snart\" hvor BigWigs' fremhævede og DBM's forstørrede nedtællinger havner.",
	["Width of the \"Questie Tracker\" mover. Questie sizes the tracker itself; its corner sits at the mover's corner."] = "Bredden på flyttefeltet \"Questie-tracker\". Questie bestemmer selv trackerens størrelse; dens hjørne sidder i flyttefeltets hjørne.",
	["Width of the area box. Lines move inside it."] = "Bredden på områdets boks. Linjerne bevæger sig inden i den.",
