	["Width on its own position. Stack is as wide as the stack."] = "Bredde på egen placering. I stakken er den lige så bred som stakken.",
	["Width to height of the buttons. Wide shapes are lower than they are wide; the icon is cropped to fit, never stretched."] = "Forholdet mellem knappernes bredde og højde. Brede former er lavere end de er brede; ikonet beskæres så det passer, men strækkes aldrig.",
