	["Works on the game's chat edit box. Every part of a long message is sent by your own Enter press; EldoUI never sends a line by itself."] = "Virker i spillets chatfelt. Hver del af en lang besked sendes ved at du selv trykker på Enter; EldoUI sender aldrig en linje af sig selv.",
	["World"] = "Verden",
	["world map"] = "verdenskort",
	["WoW Trivia"] = "WoW-quiz",
	["Write a line in chat after an upgrade: how many buttons changed and to which rank."] = "Skriv en linje i chatten efter en opgradering: hvor mange knapper der blev ændret, og til hvilken rang.",
	["Write how many mobs stand in each pack on its marker."] = "Skriv antallet af mobs i hver pack på dens markør.",
	["Write keys short: S for Shift, C for Ctrl, A for Alt, M4 for mouse button 4, MwU for wheel up."] = "Skriv taster kort: S for Shift, C for Ctrl, A for Alt, M4 for museknap 4, MwU for hjul op.",
	["Write one line about your death in guild chat."] = "Skriv én linje om din død i guildchatten.",
	["Writes the free slots (or ammo left, on a quiver) on Blizzard's bag bar buttons of special bags."] = "Skriver de ledige pladser (eller resterende ammunition på et kogger) på knapperne for specialtasker i Blizzards taskelinje.",
	["Writes the settings below into the EldoUI DBM profile again, for example after you changed something in DBM's own options."] = "Skriver indstillingerne nedenfor ind i EldoUI's DBM-profil igen, fx når du har ændret noget i DBM's egne indstillinger.",
