	["You picked your own profile in DBM, so EldoUI leaves it alone. \"Set up\" switches back to EldoUI's."] = "Du har valgt din egen profil i DBM, så EldoUI lader den være. \"Opsæt\" skifter tilbage til EldoUI's.",
