	["Your bar turns red and a note shows when you get close to pulling aggro. Never while you are the tank."] = "Din bjælke bliver rød, og der vises en besked når du er tæt på at tage aggro. Aldrig mens du er tanken.",
	["Your bid"] = "Dit bud",
	["Your buffs (right-click to cancel), debuffs, weapon enchants and boss mechanic auras, plus Blizzard's buff frames."] = "Dine buffs (højreklik for at annullere), debuffs, våbenenchants og auraer fra bossmekanikker, plus Blizzards bufframmer.",
	["your build"] = "dit build",
	["Your camp buffs are active for 1 hour."] = "Dine lejrbuffs er aktive i 1 time.",
	["Your camp buffs ended. Sit by the fire to get them back."] = "Dine lejrbuffs er udløbet. Sæt dig ved bålet for at få dem igen.",
	["Your casts get their spell school's theme (pinned spells first, then your class theme). Other units get one fixed theme each."] = "Dine casts får temaet for deres evneskole (fastgjorte evner først, derefter dit klassetema). Andre enheder får hver ét fast tema.",
	["Your categories"] = "Dine kategorier",
	["your character can't collect it"] = "din karakter kan ikke samle den",
	["Your character large on screen, no camera turn."] = "Din karakter stor på skærmen, ingen kameradrejning.",
	["Your character on the right side of the screen."] = "Din karakter i højre side af skærmen.",
	["Your character's name counts as a keyword."] = "Din karakters navn tæller som et nøgleord.",
	["Your characters on quest tooltips"] = "Dine karakterer i questtooltips",
	["Your characters side by side: equipment, reputation, currencies, professions and lockouts."] = "Dine karakterer side om side: udstyr, omdømme, valutaer, fag og lockouts.",
	["Your class buffs, auras, armors, aspects or poisons: live with their time, faded while missing. Right-click one to pick the spell and rank; the reminders keep the same pick."] = "Dine klassebuffs, auraer, rustninger, aspects eller gifte: live med deres tid, tonet ud mens de mangler. Højreklik på et for at vælge evne og rang; påmindelserne bruger det samme valg.",
	["Your class's key cooldowns, with the game's cooldown swipe. A click casts the highest rank you know."] = "Din klasses vigtige cooldowns med spillets cooldown-swipe. Et klik caster den højeste rang du kender.",
	["Your class: %s"] = "Din klasse: %s",
	["Your click-cast bindings are kept too."] = "Dine klikkastbindinger bevares også.",
	["Your collected mounts. Your click or Enter on the result summons it."] = "Dine indsamlede mounts. Dit klik eller Enter på resultatet tilkalder den.",
	["Your combo points when they change."] = "Dine combopoints når de ændrer sig.",
	["Your computer's time"] = "Din computers tid",
	["Your computer's time and date."] = "Din computers klokkeslæt og dato.",
	["Your cooldown rows"] = "Dine cooldownrækker",
	["Your Corruption, Bane of Agony and Immolate on the enemy you target. Each joins the group once you know it."] = "Din Corruption, Bane of Agony og Immolate på den fjende du har som mål. Hver evne kommer med i gruppen så snart du kender den.",
	["Your current step"] = "Dit nuværende trin",
	["Your damage numbers over enemies"] = "Dine skadetal over fjender",
	["Your DBM profile comes back when the fight is over."] = "Din DBM-profil kommer tilbage når kampen er slut.",
	["Your dot: the game's position"] = "Din prik: spillets placering",
	["Your draft matches your build. Click a node to add a rank, or load a profile."] = "Din kladde matcher dit build. Klik på en node for at tilføje et rangtrin, eller indlæs en profil.",
	["Your dungeon data doesn't know this dungeon; the route is kept and shows once it does."] = "Dine dungeondata kender ikke dette dungeon; ruten gemmes og vises når de gør.",
	["Your effects on their button"] = "Dine effekter på deres knap",
	["Your EldoUI_LootData has no dungeon packs yet. Update it together with EldoUI."] = "Din EldoUI_LootData har endnu ingen dungeonpacks. Opdater den sammen med EldoUI.",
	["Your EldoUI_LootData lists no dungeon packs."] = "Din EldoUI_LootData indeholder ingen dungeonpacks.",
	["Your equipped trinkets, with their cooldowns."] = "De trinkets du har på, med deres cooldowns.",
	["Your fishing key: %s. While the bobber is out it loots the bobber."] = "Din fisketast: %s. Mens flådet er ude, looter den flådet.",
	["Your Flame Shock on the enemy you target, with the time it has left."] = "Din Flame Shock på den fjende du har som mål, med tiden den har tilbage.",
	["Your fleet"] = "Din flåde",
