	["Your Legacy trees aren't loaded yet"] = "Dine Legacy-træer er ikke indlæst endnu",
	["Your Legacy trees aren't loaded yet."] = "Dine Legacy-træer er ikke indlæst endnu.",
	["Your Legacy trees aren't loaded yet. Open Blizzard's Legacy window once, then try again."] = "Dine Legacy-træer er ikke indlæst endnu. Åbn Blizzards Legacy-vindue én gang, og prøv så igen.",
	["Your Legacy trees: ranks now and in your draft, with the changes marked."] = "Dine Legacy-træer: rangtrin nu og i din kladde, med ændringerne markeret.",
	["Your looks"] = "Dine udseender",
	["Your main cooldown row has no spells yet (Cooldown Manager > Own rows)."] = "Din hovedrække af cooldowns har ingen evner endnu (Cooldown Manager > Egne rækker).",
	["Your mana, rage or energy."] = "Din mana, rage eller energi.",
	["Your Moonfire, Insect Swarm and Faerie Fire on the enemy you target. Each joins the group once you know it."] = "Din Moonfire, Insect Swarm og Faerie Fire på den fjende du har som mål. Hver evne kommer med i gruppen så snart du kender den.",
	["Your move."] = "Dit træk.",
	["Your own bar in a fixed color."] = "Din egen bjælke i en fast farve.",
	["Your own cast bar. Your casts get the theme of their spell school."] = "Din egen castbar. Dine casts får temaet for deres evneskole.",
	["Your own categories and the section order as a string to share."] = "Dine egne kategorier og rækkefølgen af afsnittene som en streng du kan dele.",
	["Your own death"] = "Din egen død",
	["Your own deaths."] = "Dine egne dødsfald.",
	["Your own dungeon routes and the route picked per dungeon."] = "Dine egne dungeonruter og den valgte rute for hvert dungeon.",
	["Your own frame in the party frames."] = "Din egen ramme i grupperammerne.",
	["Your own health as a row in the stack."] = "Dit eget liv som en række i stakken.",
	["Your own list, separated by commas or spaces. Find an ID on Wowhead (the number in the link)."] = "Din egen liste, adskilt af kommaer eller mellemrum. Find et ID på Wowhead (tallet i linket).",
	["Your own numbers from Blizzard's damage meter (current fight)."] = "Dine egne tal fra Blizzards skademåler (nuværende kamp).",
	["Your own routes of every dungeon: open, rename, export and delete them."] = "Dine egne ruter i alle dungeons: åbn, omdøb, eksporter og slet dem.",
	["Your own rows of aura icons, each with its own mover: pick the spells, the unit and whether only yours count. The game shows each aura; EldoUI only places and dresses the icons."] = "Dine egne rækker af auraikoner, hver med sit eget flyttefelt: vælg evnerne, enheden og om kun dine egne tæller. Spillet viser hver aura; EldoUI placerer kun ikonerne og bestemmer deres udseende.",
	["Your own spells or items to watch, separated by commas or one per line. Spell names or IDs; items as item:ID, a shift-clicked item link or the item's name."] = "Dine egne evner eller genstande at holde øje med, adskilt af kommaer eller én pr. linje. Evnenavne eller ID'er; genstande som item:ID, et Shift-klikket genstandslink eller genstandens navn.",
	["Your panels"] = "Dine paneler",
	["Your part"] = "Din del",
	["Your pet's cast bar, in the pet theme."] = "Dit pets castbar i pettemaet.",
	["Your Polymorph on your target, with the time it has left, so you see when to cast it again."] = "Din Polymorph på dit mål med den resterende tid, så du kan se hvornår du skal caste den igen.",
	["Your quest log is empty."] = "Din questlog er tom.",
