	["Your recipe list went to your guild."] = "Din opskriftsliste er sendt til din guild.",
	["Your Rejuvenation and Regrowth on the friendly player you target, each with its time left."] = "Din Rejuvenation og Regrowth på den venlige spiller du har som mål, hver med sin resterende tid.",
	["Your Renew and Power Word: Shield on the friendly player you target, each with its time left."] = "Din Renew og Power Word: Shield på den venlige spiller du har som mål, hver med sin resterende tid.",
	["Your roll: Space or a click."] = "Dit slag: Mellemrum eller et klik.",
	["Your saved sessions per zone with gold, item value, XP, items and corpses looted per hour, and the totals. Also from the bar's right-click menu and the Farming info bar text."] = "Dine gemte sessioner pr. zone med guld, genstandsværdi, XP, genstande og lootede lig pr. time samt totalerne. Også fra bjælkens højreklikmenu og Farming-teksten på infobjælken.",
	["Your seal"] = "Din seal",
