	["Your Sunder Armor, Rend and Demoralizing Shout on the enemy you target. Each joins the group once you know it."] = "Din Sunder Armor, Rend og Demoralizing Shout på den fjende du har som mål. Hver kommer med i gruppen når du kender den.",
